window.__D("text/zohar-hebrew-translation/c007",{"p":[[9522011306,"<p>וְהִנֵּה ה' נִצָּב עָלָיו וְגוֹ'. כָּאן רָאָה יַעֲקֹב הַקֶּשֶׁר שֶׁל הָאֱמוּנָה כְּאֶחָד. נִצָּב עָלָיו, וְכָתוּב (מלכים א כב) וּמֶלֶךְ אֵין בֶּאֱדוֹם נִצָּב מֶלֶךְ. (נציב מלח) רָאָה, שֶׁכָּל הַדְּרָגוֹת עוֹמְדוֹת כֻּלָּן יַחַד עַל אוֹתוֹ הַסֻּלָּם לִקְשֹׁר הַכֹּל בְּקֶשֶׁר אֶחָד, מִשּׁוּם שֶׁאוֹתוֹ הַסֻּלָּם נִתָּן בֵּין שְׁנֵי צְדָדִים. זֶהוּ שֶׁכָּתוּב (בראשית כח) אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךְ וֵאלֹהֵי יִצְחָק הָאָרֶץ וְגוֹ'. אֵלּוּ הֵם שְׁנֵי צְדָדִים, בְּיָמִין וּבִשְׂמֹאל.</p>\n<p>דָּבָר אַחֵר וְהִנֵּה ה' נִצָּב עָלָיו (ויאמר) - עַל יַעֲקֹב, שֶׁהַכֹּל יִהְיֶה מֶרְכָּבָה קְדוֹשָׁה, יָמִין וּשְׂמֹאל, וְיַעֲקֹב בְּתוֹכָם, וּכְנֶסֶת יִשְׂרָאֵל לְהִקָּשֵׁר בֵּינֵיהֶם. זֶהוּ שֶׁכָּתוּב אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךְ וֵאלֹהֵי יִצְחָק. מִנַּיִן לָנוּ שֶׁיַּעֲקֹכ בָּאֶמְצַע? מַשְׁמָע שֶׁכָּתוּב אֱלֹהֵי אַבְרָהָם אָבִיךְ וֵאלֹהֵי יִצְחָק (הארץ), וְלֹא כָתוּב וֵאלֹהֵי יִצְחָק אָבִיךְ. שֶׁכֵּיוָן שֶׁנִּקְשָׁר עִם אַבְרָהָם, נִמְצָא שֶׁהוּא בָּאֶמְצַע. וְאַחַר כָּךְ, הָאָרֶץ אֲשֶׁר אַתָּה שֹׁכֵב עָלֶיהָ - הִנֵּה הַכֹּל מֶרְכָּבָה קְדוֹשָׁה אַחַת. וְכָאן הוּא רָאָה שֶׁיִּהְיֶה שְׁלֵמוּת הָאָבוֹת.</p>\n<p>בֹּא רְאֵה, אֱלֹהֵי אַבְרָהָם אָבִיךְ, שֶׁכֵּיוָן שֶׁאָמַר אַבְרָהָם אָבִיךְ, וַדַּאי שֶׁהוּא בָּאֶמְצַע. וֵאלֹהֵי יִצְחָק, כָּאן נִרְמָז שֶׁקָּשׁוּר לִשְׁנֵי צְדָדִים וְאוֹחֵז אוֹתָם. קָשׁוּר לְצַד אֶחָד - שֶׁכָּתוּב אַבְרָהָם אָבִיךְ. וְקָשׁוּר לְצַד אַחֵר - שֶׁכָּתוּב וֵאלֹהֵי יִצְחָק. תּוֹסֶפֶת וָא\"ו לְיִצְחָק, לְהַרְאוֹת שֶׁיַּעֲקֹב אָחוּז לִשְׁנֵי צְדָדִים.</p>\n<p>וְעַד שֶׁיַּעֲקֹב לֹא נִשָּׂא, לֹא נֶאֱמַר בְּגִלּוּי יוֹתֵר, וְנֶאֱמַר בְּגִלּוּי לְמִי שֶׁמַּכִּיר דַּרְכֵי הַתּוֹרָה. אַחַר שֶׁנִּשָּׂא וְהוֹלִיד, נֶאֱמַר לוֹ בְּגִלּוּי. זֶהוּ שֶׁכָּתוּב (בראשית לג) וַיַּצֶּב שָׁם מִזְבֵּחַ וַיִּקְרָא לוֹ אֵל אֱלֹהֵי יִשְׂרָאֵל. מִכָּאן לָמַדְנוּ, מִי שֶׁלֹּא נִשְׁלָם לְמַטָּה - לֹא נִשְׁלָם לְמַעְלָה. שׁוֹנֶה יַעֲקֹב, שֶׁנִּשְׁלַם לְמַעְלָה וּלְמַטָּה, אֲבָל לֹא בְּגִלּוּי.</p>\n<p>וְאִם תֹּאמַר שֶׁנִּשְׁלַם בְּאוֹתָהּ הַשָּׁעָה - לֹא. אֶלָּא רָאָה שֶׁיֻּשְׁלַם לְאַחַר זְמַן. וְאִם תֹּאמַר, הִנֵּה כָּתוּב וְהִנֵּה אָנֹכִי עִמָּךְ וּשְׁמַרְתִּיךְ בְּכֹל אֲשֶׁר תֵּלֵךְ? אֶלָּא הַשְׁגָּחַת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁמִירָתוֹ לֹא נֶעֶזְבָה מִיַּעֲקֹב לְעוֹלָמִים בְּכָל מַה שֶּׁהִצְטָרֵךְ לוֹ בָּעוֹלָם הַזֶּה, אֲבָל בָּעוֹלָם הָעֶלְיוֹן עַד שֶׁנִּשְׁלַם.</p>"],[9522011307,"<p>וַיִּיקַץ יַעֲקֹב מִשְּׁנָתוֹ וַיֹּאמֶר אָכֵן יֵשׁ ה' בַּמָּקוֹם הַזֶּה וְאָנֹכִי לֹא יָדָעְתִּי. וְכִי תְמִיהָה הוּא שֶׁלֹּא יָדַע? אֶלָּא מַה זֶּה וְאָנֹכִי לֹא יָדָעְתִּי? כְּמוֹ שֶׁנֶּאֱמַר (שמואל א יג) וּפְנֵי ה' לֹא חִלִּיתִי. אָמַר, וְכִי כָּל זֶה הִתְגַּלָּה לִי וְלֹא הִסְתַּכַּלְתִּי לָדַעַת אָנֹכִי, וּלְהִכָּנֵס תַּחַת כַּנְפֵי הַשְּׁכִינָה וְלִהְיוֹת שָׁלֵם?</p>\n<p>בֹּא רְאֵה, כָּתוּב (בראשית כה) וַתֹּאמֶר אִם כֵּן לָמָּה זֶה אָנֹכִי. כָּל יוֹם וָיוֹם רָאֲתָה רִבְקָה אֶת אוֹר הַשְּׁכִינָה, שֶׁהַשְּׁכִינָה הָיְתָה בְּמִשְׁכָּנָהּ, וְהִתְפַּלְלָה שָׁם. כֵּיוָן שֶׁרָאֲתָה צָרָתָהּ בְּמֵעֶיהָ, מַה כָּתוּב? וַתֵּלֶךְ לִדְרשׁ אֶת ה'. יָצְאָה מֵהַדַּרְגָּה הַזּוֹ לְדַרְגָּה אַחֶרֶת, שֶׁהִיא הוי\"ה. מִשּׁוּם כָּךְ אָמַר יַעֲקֹב, וְכִי כָּל כָּךְ רָאִיתִי וְאָנֹכִי לֹא יָדָעְתִּי? מִשּׁוּם שֶׁהָיָה לְבַדּוֹ וְלֹא נִכְנַס תַּחַת כַּנְפֵי הַשְּׁכִינָה.</p>\n<p>מִיָּד - וַיִּירָא וַיֹּאמַר מַה נּוֹרָא הַמָּקוֹם הַזֶּה. הַדָּבָר הַזֶּה הוּא לִשְׁנֵי הַצְּדָדִים. מַה נּוֹרָא הַמָּקוֹם הַזֶּה - אֶחָד עַל אוֹתוֹ הַמָּקוֹם שֶׁאָמַר בָּרִאשׁוֹנָה, וְאֶחָד עַל אוֹת הַבְּרִית הַקָּדוֹשׁ, שֶׁלֹּא צָרִיךְ לְהִבָּטֵל.</p>\n<p>וְאַף עַל גַּב שֶׁהֵם לִשְׁנֵי צְדָדִים - הוּא אֶחָד. אָמַר, אֵין זֶה כִּי אִם בֵּית אֱלֹהִים. אֵין זֶה לִהְיוֹת בָּטֵל, אֵין זֶה לְהִמָּצֵא לְבַדּוֹ, זֶה לֹא הָעֲמִידָה שֶׁלּוֹ, אֶלָּא בֵּית אֱלֹהִים, לְהִשְׁתַּמֵּשׁ בּוֹ וְלַעֲשׂוֹת בּוֹ פֵּרוֹת וּלְהָרִיק לוֹ בְּרָכוֹת מִכָּל אֵיבְרֵי הַגּוּף, שֶׁזֶּהוּ הַשַּׁעַר שֶׁל כָּל הַגּוּף. זֶהוּ שֶׁכָּתוּב וְזֶה שַׁעַר הַשָּׁמָיִם. זֶה הַשַּׁעַר שֶׁל הַגּוּף וַדַּאי, שַׁעַר הוּא לְהָרִיק בְּרָכוֹת לְמַטָּה, אָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה. אָחוּז לְמַעְלָה - שֶׁכָּתוּב וְזֶה שַׁעַר הַשָּׁמָיִם. (אחוז) לְמַטָּה - שֶׁכָּתוּב אֵין זֶה כִּי אִם בֵּית אֱלֹהִים. וְעַל זֶה, וַיִּירָא וַיֹּאמַר מַה נּוֹרָא הַמָּקוֹם הַזֶּה. וּבְנֵי אָדָם אֵינָם מַשְׁגִּיחִים בַּכָּבוֹד שֶׁבּוֹ לִהְיוֹת בּוֹ שָׁלֵם לְמַעְלָה וּלְמַטָּה. בָּא אָבִיו וּנְשָׁקוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, כְּשֶׁשָּׁמַעְתִּי אוֹתָם הַדְּבָרִים מִפִּיו, בָּכִיתִי וְאָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁלֹּא בִטֵּל מִן הָעוֹלָם הַחָכְמָה הָעֶלְיוֹנָה. הָלַכְתִּי עִמָּם עַד שָׁלֹשׁ פַּרְסָאוֹת עַד שֶׁנִּכְנַסְתִּי עִמָּהֶם לָעִיר. לֹא הִסְפִּיקוּ לְהִכָּנֵס, עַד שֶׁשִּׁדֵּךְ אוֹתוֹ הָאִישׁ אֶת בְּנוֹ, וְאָמְרוּ לוֹ, דְּבָרֶיךְ לֹא יִהְיוּ לְבַטָּלָה.</p>\n<p>אָמַרְתִּי, זֶה שֶׁאָמַר רַבִּי שִׁמְעוֹן, שֶׁהַדְּבָרִים הַלָּלוּ הֵם כֻּלָּם בְּסוֹד הַחָכְמָה וּלְהַרְאוֹת דְּבָרִים אֲחֵרִים. כְּשֶׁסִּדַּרְתִּי הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן, אָמַר לִי, אַל תֹּאמַר שֶׁהַדְּבָרִים הַלָּלוּ הֵם שֶׁל תִּינוֹק, אֶלָּא הֵם דְּבָרִים שֶׁל סוֹדוֹת עֶלְיוֹנִים, וְהַכֹּל רְשׁוּמִים בְּסוֹד הַחָכְמָה.</p>"],[9522011308,"<p>וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה. הַחֲלוֹם, הַמַּדְרֵגָה הַשִּׁשִּׁית מֵאוֹתָן שְׁתֵּי דַרְגוֹת הַנְּבוּאָה עַד אוֹתָהּ הַדַּרְגָּה, הֵן שֵׁשׁ דְּרָגוֹת, וְעַל כֵּן הַחֲלוֹם אֶחָד מִשִּׁשִּׁים דְּרָגוֹת שֶׁל נְבוּאָה. סֻלָּם, רָאָה אֶת בָּנָיו שֶׁעֲתִידִים לְקַבֵּל תּוֹרָה בְּהַר סִינַי. סֻלָּם זֶה סִינַי (בגימטריא), מִשּׁוּם שֶׁהוּא נָעוּץ בָּאָרֶץ וְחוֹשֵׁב בַּעֲלִיָּה לַשָּׁמַיִם, וְכָל הַמֶּרְכָּבוֹת (הקדושות) וְהַמַּחֲנוֹת הָעֶלְיוֹנִים, כֻּלָּם יוֹרְדִים (ירדו) לְשָׁם עִם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנָּתַן לָהֶם אֶת הַתּוֹרָה.</p>\n<p>וְהַסֹל רָאָה. רָאָה אֶת מטטרו\"ן זְקַן הַבַּיִת שֶׁשּׁוֹלֵט בְּכָל אֲשֶׁר לוֹ, שֶׁהוּא עוֹמֵד בְּשִׁלְטוֹן עַל הָעוֹלָם (הזה), בְּשִׁלְטוֹן שֶׁל שֵׁם שַׁדַּ\"י. וְעוֹלֶה לְמַעְלָה בַּעֲלִיַּת שֵׁם רִבּוֹנוֹ הוי\"ה, הַמָּקוֹם שֶׁיַּעֲקֹב הֻשְׁלַם בּוֹ לְאַחַר מִכֵּן. וְרֹאשׁוֹ שֶׁל שֵׁם שַׁדַּ\"י הוּא י', וְזֶה מַגִּיעַ הַשָּׁמָיְמָה. כֵּיוָן שֶׁהִגִּיעָה וְעָלְתָה הָאוֹת הַזּוֹ לַמָּקוֹם הַהוּא, הֻשְׁלַם וְנִקְרָא בְּאוֹתוֹ שֵׁם שֶׁל רִבּוֹנוֹ הוי\"ה.</p>\n<p>וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. אוֹתָם הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁקְּרוֹבִים לַמַּלְכוּת עוֹלִים, וְאוֹתָם הָאֲחֵרִים שֶׁאֵינָם קְרוֹבִים יוֹרְדִים.</p>\n<p>וְעוֹד, בּוֹ הֵם עוֹלִים וְיוֹרְדִים. כְּשֶׁהוּא עוֹלֶה, עוֹלִים עִמּוֹ. כְּשֶׁהוּא יוֹרֵד, יוֹרְדִים עִמּוֹ. מַלְאֲכֵי אֱלֹהִים - שְׁתֵּים עֶשְׂרֵה מַרְגָּלִיּוֹת טוֹבוֹת, וְהֵן: מיכא\"ל, קדמיא\"ל, פדא\"ל, גבריא\"ל, צדקיא\"ל, חסדיא\"ל, רפא\"ל, רזיא\"ל, סטורי\"ה, נוריא\"ל, יפיא\"ל, ענא\"ל. אַלְפֵי שִׁנְאָן, שִׁנְאָ\"ן - שׁוֹ\"ר נֶשֶׁ\"ר אַרְיֵ\"ה. ן' אָדָם, כּוֹלֵל זָכָר וּנְקֵבָה. וְהֵם עוֹלִים כְּשֶׁהוּא עוֹלֶה, וְאֵלּוּ יוֹרְדִים כְּשֶׁהוּא יוֹרֵד.</p>\n<p>וְעוֹד, כָּל אוֹתָם שֶׁשּׁוֹלְטִים בְּשִׁלְטוֹן הָעוֹלָם הַזֶּה עוֹלִים עַל יָדוֹ, וְכָל אוֹתָם שֶׁיּוֹרְדִים יוֹרְדִים עַל יָדוֹ, כֻּלָּם בַּסֻּלָּם הַזֶּה. הוי\"ה שׁוֹלֵט עַל הַכֹּל, שֶׁכָּתוּב וְהִנֵּה ה' נִצָּב עָלָיו. כְּשֶׁהִתְעוֹרֵר, כָּתוּב אֵין זֶה כִּי אִם בֵּית אֱלֹהִים וְזֶה שַׁעַר הַשָּׁמָיִם. בֵּית אֱלֹהִים וַדַּאי, וְהוּא הַשַּׁעַר לְהִכָּנֵס פְּנִימָה, שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבוֹא בָם אוֹדֶה יָהּ זֶה הַשַּׁעַר לַה'. זֶה שַׁעַר הַשָּׁמַיִם הַכֹּל אֶחָד.</p>"],[9522011309,"<p>וַיִּדַּר יַעֲקֹב נֶדֶר לֵאמֹר אִם יִהְיֶה אֱלֹהִים עִמָּדִי וְגוֹ'. אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁכָּל זֶה הִבְטִיחַ לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, לָמָּה לֹא הֶאֱמִין, שֶׁאָמַר אִם יִהְיֶה אֱלֹהִים עִמָּדִי וְגוֹ'? אֶלָּא, אָמַר יַעֲקֹב, חֲלוֹם חָלַמְתִּי, וְהַחֲלוֹמוֹת - מֵהֶם אֱמֶת וּמֵהֶם לֹא אֱמֶת, וְאִם יִתְקַיֵּם, הֲרֵי יָדַעְתִּי שֶׁהוּא חֲלוֹם אֱמֶת. וְעַל כֵּן אָמַר אִם יִהְיֶה אֱלֹהִים עִמָּדִי וְגוֹ', כְּמוֹ שֶׁחָלַמְתִּי, וְהָיָה ה' לִי לֵאלֹהִים. אֲנִי אֶהְיֶה מוֹשֵׁךְ בְּרָכוֹת מֵהַמַּעְיָן שֶׁל הַנַּחַל שֶׁל הַכֹּל לַמָּקוֹם הַזֶּה שֶׁנִּקְרָא אֱלֹהִים.</p>\n<p>בֹּא רְאֵה, יִשְׂרָאֵל שֶׁהוּא בָּאֶמְצַע, הַכֹּל הוּא נוֹטֵל בָּרִאשׁוֹנָה מֵהַמָּקוֹר שֶׁל הַכֹּל, וְאַחַר שֶׁיַּגִּיעַ אֵלָיו, מִמֶּנּוּ שׁוֹפֵעַ וּמַמְשִׁיךְ לַמָּקוֹם הַזֶּה, מַשְׁמָע שֶׁכָּתוּב וְהָיָה ה' לִי - בָּרִאשׁוֹנָה, וְאַחַר הַכֹּל - לֵאלֹהִים. כְּמוֹ שֶׁאֱלֹהִים יִהְיֶה שׁוֹמֵר וְעוֹשֶׂה לִי כָּל אוֹתָן הַטּוֹבוֹת, אַף אֲנִי אֶהְיֶה מוֹשֵׁךְ לוֹ מֵהַמָּקוֹם שֶׁלִּי כָּל אוֹתָן הַבְּרָכוֹת, וְיִתְחַבֵּר בּוֹ הַקֶּשֶׁר שֶׁל הַכֹּל. מָתַי? וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי, כְּשֶׁאֶהְיֶה יוֹשֵׁב בַּדַּרְגָּה שֶׁלִּי, וְאֶהְיֶה יוֹשֵׁב בַּדַּרְגָּה שֶׁל שָׁלוֹם לְתַקֵּן אֶת בֵּית אָבִי, וְשַׁבְתִּי בְשָׁלוֹם דַּוְקָא, אָז וְהָיָה ה' לִי לֵאלֹהִים.</p>\n<p>דָּבָר אַחֵר וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי, שֶׁשָּׁם הִיא הָאָרֶץ הַקְּדוֹשָׁה, שָׁם אֶשְׁתַּלֵּם. וְהָיָה ה' לִי לֵאלֹהִים. בַּמָּקוֹם הַזֶּה אֶעֱלֶה (נתעלה) מִדַּרְגָּה זוֹ לְדַרְגָּה אַחֶרֶת כָּרָאוּי, וְשָׁם אֶעֱבֹד עֲבוֹדָתוֹ.</p>\n<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, דִּבְרֵי עֲונוֹת גָּבְרוּ מֶנִּי פְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם. הַפָּסוּק הַזֶּה קָשֶׁה, שֶׁאֵין סוֹפוֹ רֹאשׁוֹ וְאֵין רֹאשׁוֹ סוֹפוֹ. אֶלָּא דָּוִד בִּקֵּשׁ עַל עַצְמוֹ, וְאַחַר כָּךְ בִּקֵּשׁ עַל הַכֹּל (תהלים סה) דִּבְרֵי עֲונוֹת גָּבְרוּ מֶנִּי. אָמַר דָּוִד, אֲנִי יָדַעְתִּי בְּעַצְמִי שֶׁחָטָאתִי, אֲבָל כַּמָּה רְשָׁעִים הֵם בָּעוֹלָם שֶׁהִתְגַּבְּרוּ חֲטָאֵיהֶם עֲלֵיהֶם יוֹתֵר מִמֶּנִּי. הוֹאִיל וְכֵן, לִי וְלָהֶם, פְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁרַבִּים הָרְשָׁעִים בָּעוֹלָם, הֵם עוֹלִים עַד אוֹתוֹ מָקוֹם שֶׁסִּפְרֵי הָרְשָׁעִים נִפְתְּחוּ, כְּמוֹ שֶׁנֶּאֱמַר הַ (בית) דִּין יוֹשֵׁב וּסְפָרִים נִפְתָּחִים, וְאוֹתוֹ סֵפֶר (הדין עומד עליה), (למעלה מראשו של דוד הוא) משום כך דברי עונות גברו מני, ועל כן פשעינו אתה תכפרם.</p>\n<p>יַעָקֹב כְּמוֹ כֵן מִשּׁוּם כָּךְ לֹא הֶאֱמִין. אִם תֹּאמַר שֶׁלֹּא הֶאֱמִין בַּקָּדוֹשׁ-בָּרוּךְ-הוּא - לֹא. אֶלָּא שֶׁלֹּא הֶאֱמִין בְּעַצְמוֹ. אוּלַי יֶחֱטָא, וְאוֹתוֹ הַחֵטְא יִמְנַע אוֹתוֹ שֶׁלֹּא יָשׁוּב בְּשָׁלוֹם וְתִסְתַּלֵּק מִמֶּנּוּ הַשְּׁמִירָה, וּמִשּׁוּם כָּךְ לֹא הֶאֱמִין בְּעַצְמוֹ. וְהָיָה ה' לִי לֵאלֹהִים אֲפִלּוּ רַחֲמִים, כְּשֶׁאָשׁוּב בְּשָׁלוֹם, אָשִׂים כְּנֶגְדִּי אֶת הַדִּין, מִשּׁוּם (שהרי) שֶׁאֲנִי עוֹבֵד לְפָנָיו תָּמִיד.</p>\n<p>אָמַר רַבִּי אָחָא, אָמַר יַעֲקֹב, כָּעֵת אֵינִי צָרִיךְ אֶת הַדִּין. כְּשֶׁאָשׁוּב לְבֵית אָבִי אֶתְכַּלֵּל בַּדִּין וְאֶתְקַשֵּׁר בּוֹ. אָמַר רַבִּי יוֹסֵי, לֹא כָּךְ, אֶלָּא אָמַר, עַכְשָׁו אִם יִהְיֶה אֱלֹהִים עִמָּדִי, אֲנִי צָרִיךְ שֶׁהַדִּין יִשְׁמֹר אוֹתִי עַד שֶׁאָשׁוּב בְּשָׁלוֹם אֶל בֵּית אָבִי. אֲבָל כֵּיוָן שֶׁאָשׁוּב בְּשָׁלוֹם, אַכְלִיל אֶת הָרַחֲמִים בַּדִּין, וְאֶתְקַשֵּׁר בְּקֶשֶׁר נֶאֱמָן לְהַכְלִיל הַכֹּל יַחַד. וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים, שֶׁהֲרֵי אָז הַכֹּל יִהְיֶה קֶשֶׁר אֶחָד, וְהָאֶבֶן הַזּוֹ מִתְבָּרֶכֶת מִיָּמִין וּמִשְּׂמֹאל, מִתְבָּרֶכֶת מִמַּעְלָה וּמִמַּטָּה, מִשּׁוּם (זה) שֶׁאֶתֵּן מַעֲשֵׂר מִכֹּל.</p>\n<p>אָמַר רַבִּי אַבָּא, הִנֵּה כָּתוּב וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. וְאִם תֹּאמַר שֶׁהָאֶבֶן הַזּוֹ עֶלְיוֹנָה (על) כַּמָּה אֲבָנִים לִמְקוֹם מוֹשָׁבָהּ לִשְׁרוֹת עֲלֵיהֶם, (זהו שכתוב) וַהֲרֵי כָּתוּב וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה - (עליונה היה צריך להיות,) מִשּׁוּם (כיון) שֶׁאָמַר אֵין זֶה כִּי אִם בֵּית אֱלֹהִים, כָּאן הֵרִים אוֹתָהּ מַצֵּבָה עֶלְיוֹנָה, מִשּׁוּם שֶׁתָּלָה בָּהּ כָּל הַשֶּׁבַח שֶׁל זֶה, שֶׁאֵין זֶה לְקַיֵּם (למטה) כִּי אִם בֵּית אֱלֹהִים, וְיָפֶה. וְעַל כֵּן אֲשֶׁר שַׂמְתִּי מַצֵּבָה.</p>\n<p>יִהְיְהִ בֵּית אֱלֹהִים, לְעוֹלָמִים. בֵּית אֱלֹהִים? בֵּית ה' הָיָה צָרִיךְ לִהְיוֹת, כְּמוֹ שֶׁנֶּאֱמַר לְכוֹנֵן אֶת בֵּית ה', וְכֵן (תהלים קכב) בֵּית ה' נֵלֵךְ. אֶלָּא מְקוֹם בֵּית הַדִּין הוּא מִשְּׁנֵי צְדָדִים עֶלְיוֹנִים - מִצַּד הַיּוֹבֵל שֶׁהוּא אֱלֹהִים חַיִּים, וּמֵהַצַּד שֶׁל יִצְחָק אֱלֹהִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הַיּוֹבֵל, אַף עַל גַּב שֶׁהַדִּינִים (יוצאים) מִתְעוֹרְרִים מִמֶּנָּה וְכֻלָּם רַחֲמִים (ודינים), כָּל הַשְּׂמָחוֹת יוֹצְאוֹת מִמֶּנָּה, וְהוּא שִׂמְחַת (והוא חרות) הַכֹּל. אֶלָּא בֵּית אֱלֹהִים - הַצַּד שֶׁל הַדִּין הַקָּשֶׁה. אִם לְטוֹב, בְּצַד (היובל) הַשְּׂמֹאל מִתְעוֹרֶרֶת בּוֹ אַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. אִם לְרַע, בְּצַד הַשְּׂמֹאל מִתְעוֹרֵר בּוֹ דִּין קָשֶׁה, כְּמוֹ שֶׁנֶּאֱמַר מִצָּפוֹן תִּפָּתַח הָרָעָה עַל כָּל יֹשְׁבֵי הָאָרֶץ. וַדַּאי בֵּית אֱלֹהִים. רַבִּי שִׁמְעוֹן אָמַר, בֵּית אֱלֹהִים, הַיְנוּ שֶׁכָּתוּב קִרְיַת מֶלֶךְ רָב. יֵשׁ מֶלֶךְ סְתָם וְיֵשׁ מֶלֶךְ רַב. וַדַּאי שֶׁהָעוֹלָם הָעֶלְיוֹן הוּא מֶלֶךְ רַב, וְזוֹהִי קִרְיַת מֶלֶךְ רָב.</p>"],[9522011310,"<p>רַבִּי חִיָּיא וְרַבִּי חִזְקִיָּה הָיוּ יוֹשְׁבִים תַּחַת הָאִילָנוֹת שֶׁל שְׂדֵה אוֹנוֹ. נִרְדַּם רַבִּי חִיָּיא, וְרָאָה אֶת אֵלִיָּהוּ. אָמַר, מֵהוֹכָחַת הַדֶּרֶךְ שֶׁל מַר מֵאִיר הַשָּׂדֶה. אָמַר, כָּעֵת בָּאתִי לְהוֹדִיעַ שֶׁקְּרוֹבָה יְרוּשָׁלַיִם לְהֵחָרֵב, וְכָל אוֹתָן קִרְיוֹת הַחֲכָמִים, מִשּׁוּם שֶׁיְּרוּשָׁלַיִם הִיא דִין, וְעַל דִּין עוֹמֶדֶת וְעַל דִּין תֵּחָרֵב, וְהִנֵּה נִתְּנָה רְשׁוּת לְסמא\"ל עָלֶיהָ וְעַל גִּבּוֹרֵי הָעוֹלָם, וּבָאתִי לְהוֹדִיעַ לַחֲכָמִים אוּלַי יַאֲרִיכוּ אֶת שְׁנוֹת יְרוּשָׁלַיִם, שֶׁהֲרֵי כָּל זְמַן שֶׁנִּמְצֵאת בָּהּ תּוֹרָה - הִיא עוֹמֶדֶת, מִשּׁוּם שֶׁהַתּוֹרָה עֵץ הַחַיִּים הָעוֹמֵד עָלֶיהָ. כָּל זְמַן שֶׁהַתּוֹרָה מִתְעוֹרֶרֶת לְמַטָּה - עֵץ הַחַיִּים לֹא זָז לְמַעְלָה. פָּסְקָה הַתּוֹרָה לְמַטָּה - עֵץ הַחַיִּים מִסְתַּלֵּק (ממנה) מִן הָעוֹלָם.</p>\n<p>וְעַל כֵּן, כָּל זְמַן שֶׁהַחֲכָמִים יִשְׂמְחוּ בַּתּוֹרָה, לֹא יוּכַל עֲלֵיהֶם סמא\"ל, שֶׁהֲרֵי כָּתוּב הַקֹּל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו. זוֹ הַתּוֹרָה הָעֶלְיוֹנָה שֶׁנִּקְרֵאת קוֹל יַעֲקֹב. בְּעוֹד שֶׁאוֹתוֹ קוֹל לֹא פוֹסֵק, הַדִּבּוּר שׁוֹלֵט וְיָכוֹל, וְעַל כֵּן לֹא צָרִיךְ לְהַפְסִיק בַּתּוֹרָה. וְהִתְעוֹרֵר רַבִּי חִיָּיא, וְהָלְכוּ וְאָמְרוּ אֶת הַדָּבָר הַזֶּה לַחֲכָמִים.</p>\n<p>אָמַר רַבִּי יֵיסָא, הַכֹּל יוֹדְעִים אֶת זֶה, וְכָךְ הוּא, שֶׁכָּתוּב אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. אֵלּוּ הֵם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, הַקִּרְיָה הַקְּדוֹשָׁה עוֹמֶדֶת עֲלֵיהֶם, וְלֹא עַל הַגְּבָרִים הַגִּבּוֹרִים שֶׁל הָעוֹלָם, הַיְנוּ שֶׁכָּתוּב אִם ה' לֹא יִשְׁמָר עִיר וְגוֹ'.</p>"],[9522011311,"<p>וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְגוֹ'. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים ג) מִזְמוֹר לְדָוִד בְּבָרְחוֹ מִפְּנֵי אַבְשָׁלוֹם בְּנוֹ. בַּפָּסוּק הַזֶּה הִתְעוֹרְרוּ הַחֲבֵרִים, אֲבָל מִזְמוֹר לְדָוִד, לָמָּה אָמַר שִׁירָה? אִם מִשּׁוּם שֶׁבְּנוֹ הוּא שֶׁקָּם עָלָיו, יוֹתֵר קִינָה הָיָה צָרִיךְ לִהְיוֹת, שֶׁהֲרֵי הֵרַע עָלָיו עַל הָאָדָם קְצָת מִקְּרוֹבָיו מִשֶּׁאַחֵר הַרְבֵּה. אֶלָּא מִזְמוֹר לְדָוִד, אָמַר שִׁירָה, וְכָךְ בִּקֵּשׁ דָּוִד, שֶׁחָשַׁב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא סִלֵּק אֶת חֶטְאוֹ לָעוֹלָם הַהוּא. כֵּיוָן שֶׁרָאָה שֶׁכָּאן בָּעוֹלָם הַזֶּה רוֹצֶה לִגְבּוֹת מִמֶּנּוּ, שָׂמַח.</p>\n<p>עוֹד, שֶׁרָאָה שֶׁעֶלְיוֹנִים מִמֶּנּוּ הָיוּ בָּעוֹלָם שֶׁבָּרְחוּ, וְכֻלָּם לְבַדָּם. יַעֲקֹב בָּרַח, שֶׁכָּתוּב (הושע יב) וַיִּבְרַח יַעֲקֹב שְׂדֵה אֲרָם, וּבָרַח לְבַדּוֹ. מֹשֶׁה בָּרַח, שֶׁכָּתוּב (שמות כ) וַיִּבְרַח מֹשֶׁה מִפְּנֵי פַרְעֹה, וּבָרַח לְבַדּוֹ. וְדָוִד בָּרַח, כָּל אוֹתָם שַׁלִּיטֵי הָאָרֶץ וְכָל אוֹתָם גִּבּוֹרֵי הָאָרֶץ וְרָאשֵׁי יִשְׂרָאֵל, כֻּלָּם בָּרְחוּ עִמּוֹ, וְסוֹבְבִים מִימִינוֹ וּמִשְּׂמֹאלוֹ לִשְׁמֹר אוֹתוֹ מִכָּל הַצְּדָדִים. כֵּיוָן שֶׁרָאָה הַשֶּׁבַח הַזֶּה, אָמַר שִׁירָה.</p>\n<p>וְאָמַר רַבִּי יְהוּדָה, כֻּלָּם פָּגְשׁוּ אֶת הַבְּאֵר הַזּוֹ. וְלָמָּה דָּוִד לֹא פָגַשׁ בָּהּ? אֶלָּא דָּוִד בַּעַל שִׂנְאָה הָיָה כְּנֶגְדּוֹ (של הבאר) בְּאוֹתוֹ הַזְּמַן, וּמִשּׁוּם כָּךְ לֹא פָגַשׁ בָּהּ. אֶת יַעֲקֹב וּמֹשֶׁה קִבְּלָה אוֹתָם הַבְּאֵר בְּשִׂמְחָה וְרָצְתָה לְהִתְקָרֵב עִמָּם. וְעַל כֵּן, כֵּיוָן שֶׁרָאֲתָה אוֹתָם הַבְּאֵר הַזּוֹ, עָלוּ הַמַּיִם אֵלֶיהָ כְּאִשָּׁה שֶׁשְּׂמֵחָה עִם בַּעְלָהּ.</p>\n<p>וְאִם תֹּאמַר, הִנֵּה אֵלִיָּהוּ בָּרַח וְלֹא פָגַשׁ בָּהּ, לָמָּה? אֶלָּא אֵלִיָּהוּ הוּא לְמַטָּה מִן הַבְּאֵר, וְלֹא לְמַעְלָה, כְּמוֹ שֶׁהָיוּ מֹשֶׁה וְיַעֲקֹב, וּמִשּׁוּם כָּךְ הוּא מַלְאָךְ וְעוֹשֶׂה שְׁלִיחוּת. וּמִשּׁוּם שֶׁיַּעֲקֹב וּמֹשֶׁה הֵם לְמַעְלָה מִן הַבְּאֵר, הַבְּאֵר שְׂמֵחָה אֲלֵיהֶם וְעָלְתָה לְקַבֵּל אוֹתָם כְּאִשָּׁה שֶׁשְּׂמֵחָה לְבַעְלָהּ וּמְקַבֶּלֶת אוֹתוֹ.</p>\n<p>וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה. סוֹד הוּא שֶׁרָאָה אֶת הַבְּאֵר הַזּוֹ לְמַעְלָה, זֶה כְּמוֹ זֶה. כָּתוּב שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ. אִם הֵם שְׁלֹשָׁה, לָמָּה כָּתוּב וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים? אֶלָּא הֵם שְׁלֹשׁה: דָּרוֹם, מִזְרָח, צָפוֹן. דָּרוֹם מִן הַצַּד הַזֶּה, וְצָפוֹן מֵהַצַּד הַזֶּה, וּמִזְרָח בֵּינֵיהֶם. וְאֵלּוּ עוֹמְדִים עַל הַבְּאֵר הַזּוֹ וְאוֹחֲזִים אוֹתָהּ וּמְמַלְּאִים אוֹתָהּ. מָה הַטַּעַם מִשּׁוּם כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים. הַיְנוּ שֶׁכָּתוּב יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי.</p>\n<p>וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים, הַיְנוּ שֶׁכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶת הַיָּם. וְגָלֲלוּ אֶת הָאֶבֶן - מַעֲבִירִים מִמֶּנָּה אֶת תֹּקֶף הַדִּין הַקָּשֶׁה, אוֹתוֹ שֶׁקָּפָא וְנִקְרַשׁ, (מים זכרים) שֶׁאָז נִקְרָא אֶבֶן, וְלֹא יוֹצְאִים מִמֶּנָּה מַיִם הַחוּצָה. וּכְשֶׁאוֹתָם הַנְּחָלִים בָּאִים, מִתְחַזֵּק הַדָּרוֹם, שֶׁהוּא הַיָּמִין, וְלֹא יָכוֹל הַצָּפוֹן לְהַקְרִישׁ אֶת הַמַּיִם, כַּנָּהָר הַזֶּה, כְּשֶׁמֵּימָיו רַבִּים, לֹא קוֹפְאִים וְנִקְרָשִׁים הַמַּיִם, כְּמוֹ נָהָר שֶׁמֵּימָיו מוּעָטִים.</p>\n<p>וְעַל כֵּן, כְּשֶׁאוֹתָם נְחָלִים בָּאִים, מִתְחַזֵּק הַדָּרוֹם, שֶׁהוּא הַיָּמִין, וְהַמַּיִם מַפְשִׁירִים וְשׁוֹפְעִים וּמַשְׁקִים אֶת הָעֲדָרִים, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי. וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר, לִמְקוֹמָהּ, מִשּׁוּם שֶׁהָעוֹלָם צָרִיךְ אֶת הַדִּין שֶׁלָּהּ, שֶׁתִּהְיֶה בְּדִין, לְהוֹכִיחַ אֶת הָרְשָׁעִים בָּהּ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁיַּעֲקֹב הָיָה יוֹשֵׁב עַל הַבְּאֵר וְרָאָה הַמַּיִם עוֹלִים אֵלָיו, יָדַע שֶׁשָּׁם תִּזְדַּמֵּן לוֹ אִשְׁתּוֹ. וְכֵן בְּמֹשֶׁה, כְּשֶׁיָּשַׁב עַל הַבְּאֵר, כֵּיוָן שֶׁרָאָה שֶׁהַמַּיִם עוֹלִים אֵלָיו, יָדַע שֶׁאִשְׁתּוֹ תִּזְדַּמֵּן לוֹ לְשָׁם. וְכָךְ הָיָה לְיַעֲקֹב, שֶׁשָּׁם הִזְדַּמְּנָה לוֹ אִשְׁתּוֹ, כְּמוֹ שֶׁכָּתוּב עוֹדֶנּוּ מְדַבֵּר עִמָּם וְרָחֵל בָּאָה עִם הַצֹּאן. וַיְהִי כַּאֲשֶׁר רָאָה יַעֲקֹב אֶת רָחֵל וְגוֹ'. מֹשֶׁה, שֶׁכָּתוּב (שמות ב) וַיָּבֹאוּ הָרֹעִים וַיְגָרֲשׁוּם וְגוֹ', וְשָׁם הִזְדַּמְּנָה לוֹ צִפּוֹרָה, מִשּׁוּם שֶׁאוֹתָהּ הַבְּאֵר גָּרְמָה לָהֶם.</p>\n<p>בֹּא רְאֵה, הַבְּאֵר הַזוֹ כְּתוּבָה שֶׁבַע פְּעָמִים בַּפָּרָשָׁה הַזּוֹ, מִשּׁוּם שֶׁהִיא רֶמֶז לְשֶׁבַע. וְכָךְ נִקְרֵאת בְּאֵר שֶׁבַע. (ומשום) הַבְּאֵר הַזּוֹ נִזְכֶּרֶת שֶׁבַע פְּעָמִים בַּפָּרָשָׁה הַזּוֹ, שֶׁכָּתוּב וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה. כִּי מִן הַבְּאֵר הַהִיא. וְהָאֶבֶן גְּדֹלָה עַל פִּי הַבְּאֵר. וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים וְגוֹ' מֵעַל פִּי הַבְּאֵר. וְהִשְׁקוּ אֶת הַצּאן וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר. וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר. וַיָּגֶל אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר. הֲרֵי שִׁבְעָה, וּבְוַדַּאי שֶׁכָּךְ זֶה.</p>\n<p>בְּמֹשֶׁה לֹא כָתוּב אֶלָּא פַּעַם אַחַת, שֶׁכָּתוּב וַיֵּשֶׁב בְּאֶרֶץ מִדְיָן וַיֵּשֶׁב עַל הַבְּאֵר. מִשּׁוּם שֶׁמֹּשֶׁה נִפְרַד מִכֹּל וָכֹל מֵהַבַּיִת שֶׁלְּמַטָּה, וְיַעֲקֹב לֹא נִפְרַד כְּלָל. בְּמֹשֶׁה אֶחָד, כַּכָּתוּב (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי. אַחַת הִיא לְאִמָּהּ. וּמִשּׁוּם כָּךְ מֹשֶׁה הָיָה בַּעַל הַבַּיִת וְהִתְעַלָּה לְמַעְלָה. בְּמֹשֶׁה כָּתוּב וַיֵּשֶׁב עַל הַבְּאֵר. בְּיַעֲקֹב - וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה, וְלֹא כָתוּב וַיֵּשֶׁב עַל הַבְּאֵר.</p>\n<p>וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְהִנֵּה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ. בְּאֵר - הַדַּרְגָּה שֶׁל אֲדוֹן כָּל הָאָרֶץ. בַּשָּׂדֶה - שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. שְׁלֹשָׁה עֶדְרֵי צֹאן - שָׁלֹשׁ דְּרָגוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת מְתֻקָּנוֹת עַל אוֹתָהּ הַבְּאֵר, וְהֵן נֶצַ\"ח וְהוֹ\"ד וְהַיְסוֹד שֶׁל הָעוֹלָם. וְאֵלּוּ מוֹשְׁכוֹת מַיִם מִלְמַעְלָה וּמְמַלְּאִים אֶת הַבְּאֵר הַ את.</p>\n<p>מִשּׁוּם שֶׁהַמָּקוֹר הַהוּא, יְסוֹד הָעוֹלָם, כְּשֶׁשּׁוֹרֶה בַּבְּאֵר הַזּוֹ, הוּא עוֹשֶׂה פֵּרוֹת וְנוֹבֵעַ תָּמִיד, וְאוֹתָהּ הַבְּאֵר מִתְמַלֵּאת מִמֶּנּוּ. כֵּיוָן שֶׁהִתְמַלְּאָה, וַדַּאי כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים, אֵלּוּ הֵם כָּל הָאוּכְלוּסִים וְהַמַּחֲנוֹת הַקְּדוֹשִׁים, שֶׁכֻּלָּם מֻשְׁקִים וְשׁוֹתִים מֵהַבְּאֵר הַהִיא, וְכָל אֶחָד וְאֶחָד כָּרָאוּי לוֹ.</p>\n<p>וְהָאֶבֶן גְּדֹלָה עַל פִּי הַבְּאֵר - זוֹ הָאֶבֶן שֶׁמִּמֶּנָּה כּוֹשְׁלִים בְּנֵי הָעוֹלָם, אֶבֶן נֶגֶף וְצוּר מִכְשׁוֹל, שֶׁעוֹמֶדֶת תָּמִיד עַל פִּי הַבְּאֵר הַזּוֹ, עַל פְּקֻדָּתָהּ לִתְבֹּעַ הַדִּין שֶׁל כָּל הָעוֹלָם שֶׁלֹּא יֵרֵד מָזוֹן וְטוֹב לָעוֹלָם.</p>\n<p>וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים. לֹא כָתוּב וְנֶאֶסְפוּ שָׁמָּה הָעֲדָרִים, אֶלָּא כָּל הָעֲדָרִים. הַמַּחֲנוֹת הַקְּדוֹשִׁים לְמַעְלָה וְהַמַּחֲנוֹת הַקְּדוֹשִׁים לְמַטָּה. אֵלּוּ בְּשִׁירִים וְתִשְׁבָּחוֹת לְמַעְלָה, וְאֵלּוּ בִּתְפִלּוֹת וּבַקָּשׁוֹת לְמַטָּה. אֵלּוּ וְאֵלּוּ מִיָּד וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר. מְגַלְגְּלִים אוֹתָהּ וּמַעֲבִירִים אוֹתָהּ מִן הַקֹּדֶשׁ וּמִסְתַּלֶּקֶת מִן הַדִּין. מִיָּד וְהִשְׁקוּ אֶת הַצּאן. נוֹסְעִים מַלְאָכִים עֶלְיוֹנִים לְמַעְלָה, וְנוֹסְעִים יִשְׂרָאֵל לְמַטָּה.</p>\n<p>אַחַר כָּךְ וְהֵשִׁיבוּ אֶת הָאֶבֶן, עַל פְּקֻדַּת הַבְּאֵר הַזּוֹ, שֶׁתִּהְיֶה מְעֻטֶּרֶת (מזמנת) לְפָנָיו וְלִתְבֹּעַ הַדִּין שֶׁל הָעוֹלָם, לְהַנְהִיג הָעוֹלָם בְּדִין, וְכָךְ צָרִיךְ, שֶׁהֲרֵי אֵין הָעוֹלָם יָכוֹל לַעֲמֹד אֶלָּא עַל דִּין, שֶׁהַכֹּל יִהְיֶה בֶּאֱמֶת וּזְכוּת.</p>\n<p>כֵּיוָן שֶׁנִּשְׁלַם יַעֲקֹב, לֹא הִצְטָרֵךְ לָאֶבֶן הַזּוֹ סִיּוּעַ אַחֵר. מַה כָּתוּב? וַיִּגַּשׁ יַעֲקֹב וַיָּגֶל אֶת הָאֶבֶן. וַיָּגֶל וְגָלֲלוּ, וְלֹא כָתוּב וַיָּסֵר וְהֵסִירוּ, אֶלָּא (ויגל) וְגָלֲלוּ, הַיְנוּ הָעִרְבּוּב שֶׁל הַשָּׂטָן שֶׁמְּעַרְבְּבִים אוֹתוֹ שֶׁלֹּא יוּכַל לְקַטְרֵג.</p>\n<p>וְיַעֲקֹב לְבַדּוֹ, לֹא הִצְטָרֵךְ לְסִיּוּעַ אַחֵר, אֶלָּא הוּא לְבַדּוֹ. שֶׁהֲרֵי יַעֲקֹב הָיָה בְּחִיר הָאָבוֹת. שֶׁכֵּיוָן שֶׁיָּכֹל לְעֵשָׂו בָּעוֹלָם הַזֶּה, יָכוֹל לְמַעְלָה, וּבַכֹּל צָרִיךְ מַעֲשֶׂה.</p>\n<p>שְׁנֵי עוֹלָמוֹת יָרַשׁ יַעֲקֹב - אֶחָד הָעוֹלָם שֶׁנִּגְלָה, וְאֶחָד הָעוֹלָם שֶׁהִתְכַּסָּה, כְּמוֹ שֶׁהֵם מַמָּשׁ. מֵאֶחָד יָצְאוּ שִׁשָּׁה שְׁבָטִים, וּמֵאֶחָד יָצְאוּ שְׁנֵי שְׁבָטִים. הָעוֹלָם הַמְכֻסֶּה הוֹצִיא שִׁשָּׁה צְדָדִים, וְהָעוֹלָם הַמְגֻלֶּה הוֹצִיא שְׁנַיִם, וְאוֹתָם שְׁנֵי הַכְּרוּבִים שֶׁתַּחְתֶּיהָ. וְיַעֲקֹב נִמְצָא בֵּין שְׁנֵי עוֹלָמוֹת, בִּדְמוּתָם מַמָּשׁ, וּמִשּׁוּם כָּךְ כָּל דִּבְרֵי לֵאָה הָיוּ בְּנִכְסֶה, וְשֶׁל רָחֵל בְּהִתְגַּלּוּת.</p>\n<p>וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה. רַבִּי אֶלְעָזָר אָמַר, כָּתוּב (ישעיה נא) שִׁמְעוּ אֵלַי רֹדְפֵי צֶדֶק. אוֹתָם הַמְבַקְשִׁים סוֹד הָאֱמוּנָה, אוֹתָם שֶׁנִּדְבְּקוּ בְּקֶשֶׁר הָאֱמוּנָה, אוֹתָם שֶׁיּוֹדְעִים דַּרְכֵי הַמֶּלֶךְ הָעֶלְיוֹן (קרבו שמעו).</p>\n<p>כְּשֶׁעוֹלִים שְׁנַיִם וְיָצְאוּ לִקְרַאת אֶחָד - מְקַבְּלִים אוֹתוֹ בֵּין שְׁתֵּי זְרוֹעוֹת. שְׁנַיִם יוֹרְדִים לְמַטָּה, שְׁנַיִם הֵם, אֶחָד בֵּינֵיהֶם. שְׁנֵי אֵלֶּה מוֹשַׁב הַנְּבִיאִים, הַמָּקוֹם שֶׁיּוֹנְקִים בּוֹ, אֶחָד בֵּינֵיהֶם, שֶׁהוּא מִתְחַבֵּר בַּכֹּל, הוּא נוֹטֵל הַכֹּל.</p>\n<p>אוֹתָהּ בְּאֵר קְדוֹשָׁה עוֹמֶדֶת תַּחְתֵּיהֶם, הִיא שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. מֵהַבְּאֵר הַזּוֹ מֻשְׁקִים הָעֲדָרִים, כָּל אוֹתָן הַמֶּרְכָּבוֹת, כָּל אוֹתָם בַּעֲלֵי כְנָפַיִם. שְׁלֹשָׁה קַיָּמִים רוֹבְצִים (עומדים) עַל הַבְּאֵר הַזּוֹ. הַבְּאֵר הַזּוֹ מִתְמַלֵּאת מֵהֶם. זֶהוּ שֶׁכָּתוּב כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים וְגוֹ'. זֶה נִקְרָא אדנ\"י, וְעַל זֶה כָּתוּב אֲדֹנָי אֱלֹהִים אַתָּה הַחִלּוֹתָ, וְכָתוּב וְהָאֵר פָּנֶיךְ עַל מִקְדָּשְׁךְ הַשָּׁמֵם לְמַעַן אֲדנָ\"י. אֲדוֹן כָּל הָאָרֶץ. זֶהוּ שֶׁכָּתוּב הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. ע\"כ התוספתא.</p>"],[9522011312,"<p>דָּבָר אַחֵר וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה - רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים קו) אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט עֹשֵׂה צְדָקָה בְכָל עֵת. אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרַת אֱמֶת לְהִשְׁתַּדֵּל בָּהּ יָמִים וְלֵילוֹת, שֶׁהֲרֵי כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, יֵשׁ לוֹ חֵרוּת מֵהַכֹּל, חֵרוּת מִן הַמָּוֶת, שֶׁלֹּא יָכוֹל לִשְׁלֹט עָלָיו, וַהֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְנֶאֱחָז בָּהּ, נֶאֱחָז בְּעֵץ הַחַיִּים. וְאִם מַרְפֶּה אֶת עַצְמוֹ מֵעֵץ הַחַיִּים, הִנֵּה עֵץ הַמָּוֶת שׁוֹרֶה עָלָיו וְנֶאֱחָז בּוֹ. זֶהוּ שֶׁכָּתוּב (משלי כד) הִתְרַפִּיתָ בְּיוֹם צָרָה צַר כֹּחֶכָה. הִתְרַפִּיתָ - אִם מַרְפֶּה יָדָיו מִן הַתּוֹרָה.</p>\n<p>בְּיוֹם צָרָה צַר כֹּחֶכָה, מַה זֶּה צַר כֹּחֶכָה? צַר כֹּחַ כֹּה. שֶׁהֲרֵי הִיא תָּמִיד לְיָמִין, וּשְׁמִירָתָהּ תָּמִיד עַל בֶּן אָדָם כַּאֲשֶׁר הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, וְאָז דּוֹחֶה אֶת הָרַע הַחוּצָה שֶׁלֹּא יִקְרַב לְבֶן הָאָדָם וְלֹא יוּכַל לְקַטְרֵג לוֹ. וּכְשֶׁאָדָם סוֹטֶה מִדַּרְכֵי הַתּוֹרָה וּמִתְרַפֶּה מִמֶּנָּה, אֲזַי צַר כֹּחַ כֹּה, מִשּׁוּם שֶׁאוֹתוֹ הָרָע, שֶׁהוּא הַשְּׂמֹאל, שׁוֹלֵט עַל הָאָדָם, וְדוֹחֶה אֶת הַ\"כֹּה\" הַזּוֹ הַחוּצָה, עַד שֶׁדּוֹחֵק אוֹתוֹ מָקוֹם בְּצָרָה.</p>\n<p>דָּבָר אַחֵר צַר כֹּחֶכָה - שֶׁכַּאֲשֶׁר בֶּן אָדָם אוֹחֵז בְּדַרְכֵי הַתּוֹרָה, נֶאֱהָב לְמַעְלָה וְנֶאֱהָב לְמַטָּה, וְהוּא אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב יב) וַה' אֲהֵבוֹ, שֶׁהָיָה אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאוֹהֵב אוֹתוֹ. וּכְשֶׁאָדָם סוֹטֶה מִדַּרְכֵי הַתּוֹרָה, אֲזַי צַר כֹּחַ כֹּה, צַר שֶׁלּוֹ וּבַעַל שִׂנְאָה הוּא אֵלָיו, וְשׁוֹלֵט עָלָיו אוֹתוֹ שֶׁנִּקְרָא רַע, עַד שֶׁמְּקַטְרֵג בּוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, הָרָע הַזֶּה, שֶׁהוּא יֵצֶר הָרָע, שׁוֹלֵט עַל הָעוֹלָם בְּכַמָּה צְדָדִים, וְכַמָּה שִׁלְטוֹן יֵשׁ לוֹ בָּעוֹלָם, וְהוּא נָחָשׁ תַּקִּיף שֶׁחָטָא בּוֹ אָדָם, וְנִכְשָׁלִים בּוֹ בְּנֵי הָעוֹלָם וּמוֹשְׁכִים אוֹתוֹ עֲלֵיהֶם, עַד שֶׁמּוֹצִיא לָהֶם אֶת נִשְׁמוֹתֵיהֶם.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁהוּא שׁוֹלֵט, שׁוֹלֵט עַל הַגּוּף. וְכֵיוָן שֶׁשּׁוֹלֵט עַל הַגּוּף, יוֹצֵאת מִמֶּנּוּ הַנְּשָׁמָה, מִשּׁוּם שֶׁהַגּוּף נִטְמָא, וְהַנְּשָׁמָה עוֹלָה, וְאֵין שׁוֹלֵט עָלָיו עַד שֶׁנּוֹטֵל רְשׁוּת. וְכַמָּה הֵם שֶׁבָּאִים מִצִּדּוֹ וְשׁוֹלְטִים עַל הָעוֹלָם, וַהֲרֵי שָׁנִינוּ שֶׁכָּל מַעֲשֵׂי הָעוֹלָם שֶׁנַּעֲשִׂים וְשׁוֹלְטִים בָּהֶם, וְיֵשׁ לוֹ מְמֻנִּים וְשַׁמָּשִׁים, כֻּלָּם שַׁמָּשִׁים בְּמַעֲשֵׂי הָעוֹלָם.</p>\n<p>וְעַל כֵּן הוּא קֵץ שֶׁל הַשְּׂמֹאל, וַהֲרֵי פֵּרְשׁוּהָ שֶׁיֵּשׁ קֵץ לְיָמִין וְיֵשׁ קֵץ לִשְׂמֹאל, וְהַקֵּץ שֶׁל הַשְּׂמֹאל הַזֶּה הוּא קֵץ כָּל בָּשָׂר. נִקְרָא קֵץ כָּל בָּשָׂר, לֹא נִקְרָא קֵץ כָּל רוּחַ, וְסוֹד הַדָּבָר - זֶהוּ קֵץ (כל בשר) וְזֶהוּ קֵץ. זֶה קֵץ עַל בָּשָׂר, וְזֶה עַל רוּחַ. מִשּׁוּם כָּךְ זֶה פְּנִימִי וְזֶה חִיצוֹנִי, זֶה יָמִין וְזֶה שְׂמֹאל, זֶה קָדוֹשׁ וְזֶה טָמֵא, וְהִנֵּה פֵּרְשׁוּהָ.</p>\n<p>וּבֹא וּרְאֵה סוֹד עֶלְיוֹן קָדוֹשׁ שֶׁל הָאֱמוּנָה, הַסּוֹד שֶׁל עוֹלַם הַזָּכָר וְעוֹלַם הַנְּקֵבָה, וְכָל קֹדֶשׁ הַקְּדָשִׁים בּוֹ, וְכָל סוֹדוֹת הָאֱמוּנָה מִכָּאן יָצְאוּ, וְכָל הַחַיִּים וְכָל הַחֵרוּת, וְכָל הַטּוֹבוֹת וְכָל הָאוֹרוֹת הֵם מִכָּאן, וְכָל הַבְּרָכוֹת וְטַלְלֵי נְדָבוֹת, וְכָל הָאַהֲבָה שֶׁל הָאֲהָבוֹת הַכֹּל מֵהַצַּד הַזֶּה, סוֹד הַדָּרוֹם.</p>\n<p>מִצַד הַצָּפוֹן מִתְפַּשְּׁטוֹת דְּרָגוֹת עַד שֶׁמַּגִּיעָה לְמַטָּה פְּסֹלֶת הַזָּהָב, בְּצַד הַטֻּמְאָה, לִכְלוּךְ טָמֵא, וְאוֹחֵז אֶת זֶה לְמַעְלָה, וְאוֹחֵז אֶת זֶה לְמַטָּה. וְכָאן מִזְדַּוְּגִים זָכָר וּנְקֵבָה יַחַד, וְהֵם רוֹכֵב נָחָשׁ, הַסּוֹד שֶׁל זָכָר וּנְקֵבָה, וְזֶה סוֹד עֲזָאזֵ \"ל.</p>\n<p>וּמִכָּאן נִפְרָדוֹת הַדְּרָגוֹת וְיוֹצְאִים כַּמָּה צְדָדִים לָעוֹלָם, שֶׁמִּתְפַּשְּׁטִים מִכָּאן וְשׁוֹלְטִים עַל הָעוֹלָם, וְכֻלָּם צִדְדֵי הַטֻּמְאָה, וּמְמֻנִּים שָׂרִים לְתוֹךְ הָעוֹלָם. בֹּא רְאֵה, כְּשֶׁיָּצָא עֵשָׂו לָעוֹלָם, כֻּלּוֹ אָדם כַּשּׁוֹשַׁנָּה בַּשֵּׂעָר כְּמוֹ הַשָּׂעִיר, וּמִשָּׁם אַלּוּפִים, מָגִנִּים מְמֻנִּים (שנים עשר) שֶׁשּׁוֹלְטִים בָּעוֹלָם, וְהִנֵּה פֵּרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט - שֶׁשּׁוֹמְרִים הָאֱמוּנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מִשְׁפָּט, וְצָרִיךְ לָאָדָם לִשְׁמֹר שֶׁלֹּא יִסְטֶה לְדֶרֶךְ אַחֶרֶת, אֶלָּא שֶׁיִּהְיֶה שׁוֹמֵר מִשְׁפָּט, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מִשְׁפָּט, שֶׁכָּל דְּרָכָיו מִשְׁפָּט.</p>\n<p>עֹשֵׂה צְדָקָה בְכָל עֵת - וְכִי בְכָל עֵת יָכוֹל אָדָם לַעֲשׂוֹת צְדָקָה? אֶלָּא מִי שֶׁמִּשְׁתַּדֵּל בְּדַרְכֵי הַתּוֹרָה וְעוֹשֶׂה צְדָקָה עִם אוֹתָם שֶׁצְּרִיכִים אוֹתָהּ. שֶׁכָּל מִי שֶׁעוֹשֶׂה צְדָקָה עִם הֶעָנִי, מַרְבֶּה אוֹתָהּ צְדָקָה לְמַעְלָה וּלְמַטָּה.</p>\n<p>בֹּא רְאֵה, מִי שֶׁמִּשְׁתַּדֵּל בִּצְדָקָה, אוֹתָהּ צְדָקָה שֶׁעוֹשֶׂה עוֹלָה לְמַעְלָה וּמַגִּיעָה לְמַעְלָה לְאוֹתוֹ הַמָּקוֹם שֶׁל יַעֲקֹב, שֶׁהוּא מֶרְכָּבָה עֶלְיוֹנָה, וּמַמְשִׁיךְ בְּרָכוֹת לַמָּקוֹם הַהוּא מִן הַמַּעְיָן שֶׁל כָּל הַמַּעְיָנוֹת. וּמֵאוֹתָהּ הַצְּדָקָה מַמְשִׁיךְ וּמַרְבֶּה בְּרָכוֹת לְכָל אוֹתָם הַתַּחְתּוֹנִים וּלְכָל הַמֶּרְכָּבוֹת וּלְכָל הַחֲיָלוֹת, וְכֻלָּם מִתְבָּרְכִים, וְנוֹסָפִים אוֹרוֹת כָּרָאוּי, מִשּׁוּם שֶׁכֻּלָּם נִקְרְאוּ עֵת, וְזֶהוּ שֶׁכָּתוּב עֹשֵׂה צְדָקָה בְכָל עֵת.</p>\n<p>בֹּא רְאֵה, בִּזְמַן שֶׁהָיוּ יִשְׂרָאֵל בָּאָרֶץ הַקְּדוֹשָׁה, הֵם הָיוּ מוֹשְׁכִים בְּרָכוֹת מִמַּעְלָה לְמַטָּה. וּכְשֶׁיָּצְאוּ יִשְׂרָאֵל מִן הָאָרֶץ הַקְּדוֹשָׁה, נִכְנְסוּ תַּחַת רְשׁוּת אַחֶרֶת, וְנִמְנְעוּ הַבְּרָכוֹת מִן הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, יַעֲקֹב הָיָה תַּחַת רְשׁוּת קְדוֹשָׁה. כֵּיוָן שֶׁיָּצָא מִן הָאָרֶץ, נִכְנַס לִרְשׁוּת אַחֶרֶת. וְטֶרֶם שֶׁנִּכְנַס תַּחַת רְשׁוּת אַחֶרֶת, הִתְגַּלָּה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲלוֹם וְרָאָה כָּל מַה שֶּׁרָאָה, וְהָלְכוּ עִמּוֹ מַלְאָכִים קְדוֹשִׁים, עַד שֶׁיָּשַׁב עַל הַבְּאֵר. וְכֵיוָן שֶׁיָּשַׁב עַל הַבְּאֵר עָלוּ אֵלָיו הַמַּיִם, וְכֵן הָיָה מֹשֶׁה, שֶׁמִּשָּׁם הִזְדַּמְּנָה לוֹ אִשְׁתּוֹ. סוֹד הַדָּבָר - הַבְּאֵר לֹא עוֹלָה אֶלָּא כְּשֶׁרוֹאָה אֶת הַקֶּשֶׁר שֶׁלָּהּ לְהִתְחַבֵּר עִמּוֹ.</p>\n<p>וְאָמַר רַבִּי אַבָּא, כָּל הַפְּסוּקִים הַלָּלוּ קָשִׁים זֶה עַל זֶה. בָּרִאשׁוֹנָה כָּתוּב וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה. וְלָבָן הָיָה יוֹשֵׁב בְּחָרָן. לָמָּה נָסַע מִשָּׁם? שֶׁכָּתוּב וַיִּשָּׂא יַעֲקֹב רַגְלָיו וַיֵּלֶךְ אַרְצָה בְּנֵי קֶדֶם. וּמִנַּיִן לָנוּ שֶׁבְּחָרָן הָיָה דִיּוּרוֹ שֶׁל לָבָן? שֶׁכָּתוּב וַיֹּאמֶר לָהֶם יַעֲקֹב אַחַי מֵאַיִן אַתֶּם וַיֹּאמְרוּ מֵחָרָן אֲנָחְנוּ. וַיֹּאמֶר הַיְדַעְתֶּם אֶת לָבָן בֶּן נָחוֹר וַיֹּאמְרוּ יָדָעְנוּ. מַשְׁמָע שֶׁדִּיּוּרוֹ שֶׁל לָבָן הָיָה בְחָרָן.</p>\n<p>אֶלָּא יַעֲקֹב אָמַר, אֲנִי רוֹצֶה לְהִכָּנֵס בַּשְּׁכִינָה מִשּׁוּם שֶׁאֲנִי רוֹצֶה לְהִתְחַתֵּן. כְּשֶׁאַבָּא נִשָּׂא וְשָׁלַח אֶת הָעֶבֶד, מָצָא עֵין הַמַּיִם, וְאָז הִזְדַּמְּנָה לְאַבָּא אִשָּׁה, וְהִנֵּה בַּמָּקוֹם הַזֶּה לֹא מָצָאתִי לֹא עַיִן וְלֹא בְּאֵר וְלֹא מַיִם, וּמִיָּד - וַיִּשָּׂא יַעֲקֹב רַגְלָיו וַיֵּלֶךְ אַרְצָה בְּנֵי קֶדֶם, וְשָׁם הִזְדַּמְּנָה לוֹ בְּאֵר, כְּמוֹ שֶׁאָמַרְנוּ, וְהִזְדַּמְּנָה לוֹ אִשְׁתּוֹ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, חָרָן, שָׁם הָיָה וַדַּאי, וְהַבְּאֵר הַזּוֹ הָיְתָה בַּשָּׂדֶה. שֶׁאִם לֹא כָּךְ, לָמָּה כָּתוּב וַתָּרָץ וַתַּגֵּד לְאָבִיהָ? אֶלָּא מִשּׁוּם שֶׁהָיָה סָמוּךְ לָעִיר.</p>\n<p>וְאָמַר רַבִּי אֶלְעָזָר, יַעֲקֹב שֶׁהִזְדַּמְּנָה לוֹ אִשָּׁה עַל הַבְּאֵר, לָמָּה לֹא הִזְדַּמְּנָה לוֹ לֵאָה, שֶׁהֲרֵי הֶעֱמִידָה לוֹ לְיַעֲקֹב כָּל אוֹתָם הַשְּׁבָטִים? אֶלָּא שֶׁאֶת לֵאָה לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְזַוְּגָהּ עִם יַעֲקֹב בְּגָלוּי, שֶׁכָּתוּב וַיְהִי בַבֹּקֶר וְהִנֵּה הִיא לֵאָה. (מכלל) שֶׁהֲרֵי קֹדֶם לֹא הִתְגַּלָּה הַדָּבָר.</p>\n<p>וְעוֹד, כְּדֵי לִמְשֹׁךְ אֶת עֵינוֹ וְלִבּוֹ שֶׁל יַעֲקֹב בַּיֹּפִי שֶׁל רָחֵל, לַעֲשׂוֹת שָׁם אֶת דִּיּוּרוֹ, וּבִשְׁבִילָהּ הִזְדַּוְּגָה לוֹ לֵאָה וְהֵקִימָה אֶת כָּל אוֹתָם הַשְּׁבָטִים. בַּמֶּה יָדַע יַעֲקֹב מִי הִיא רָחֵל? אֶלָּא שֶׁאוֹתָם הָרוֹעִים אָמְרוּ לוֹ, שֶׁכָּתוּב וְהִנֵּה רָחֵל בִּתּוֹ בָּאָה עִם הַצֹּאן.</p>"],[9522011313,"<p>בֹּא רְאֵה מַה כָּתוּב, וַיֹּאמֶר אֶעֱבָדְךְ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךְ הַקְּטַנָּה. וְכִי מַה דַּעְתּוֹ שֶׁל יַעֲקֹב שֶׁלֹּא אָמַר עֲשָׂרָה יְרָחִים אוֹ שָׁנָה אַחַת, אֶלָּא שֶׁבַע שָׁנִים לָמָּה? אֶלָּא יַעֲקֹב עָשָׂה בְּחָכְמָה, כְּדֵי שֶׁלֹּא יֹאמְרוּ שֶׁבִּשְׁבִיל הַתְּשׁוּקָה שֶׁל יָפְיָהּ שֶׁל רָחֵל עָשָׂה, אֶלָּא בִּשְׁבִיל הַחָכְמָה, שֶׁהַלְּבָנָה בַּת שֶׁבַע שָׁנִים הִיא, וְכָל שֶׁבַע הַשָּׁנִים הָעֶלְיוֹנוֹת שׁוֹרוֹת הָיוּ עַל יַעֲקֹב טֶרֶם נָשָׂא אֶת רָחֵל לָשֶׁבֶת עִמָּהּ כָּרָאוּי, שֶׁהֲרֵי יַעֲקֹב נָטַל אֶת כֻּלָּם בָּרִאשׁוֹנָה, וְאַחַר כָּךְ בָּא אֵלֶיהָ, כְּדֵי לְהִמָּצֵא הוּא שָׁמַיִם וְהִיא אֶרֶץ.</p>\n<p>וְסוֹד הַדָּבָר - וַיִּהְיוּ בְעֵינָיו כְּיָמִים אֲחָדִים. מַה זֶה כְּיָמִים אֲחָדִים? אֶלָּא כָּל שֶׁבַע הַשָּׁנִים שָׁקַל אוֹתָם בְּעֵינָיו כְּאוֹתָם עֶלְיוֹנִים, שֶׁהֵם אֲחָדִים וְלֹא נִפְרָדִים, וְכֻלָּם אֶחָד, שֶׁנִּקְשָׁרִים זֶה עִם זֶה. בְּאַהֲבָתוֹ אֹתָהּ, לִהְיוֹת כַּדֻּגְמָה הָעֶלְיוֹנָה.</p>\n<p>בֹּא רְאֵה שֶׁאֲפִלּוּ לָבָן רָמַז לוֹ בְּאוֹתָם הַשֶּׁבַע וְלֹא יָדַע מָה אָמַר. שֶׁפָּתַח וְאָמַר טוֹב, שֶׁכָּתוּב טוֹב תִּתִּי וְגוֹ'. אָמַר רַבִּי אַבָּא, כָּךְ זֶה וַדַּאי, עָבַד שֶׁבַע שָׁנִים לְהִזְדַּוֵּג עִם שְׁמִטָּה. אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, בְּכָל מָקוֹם הַיּוֹבֵל סָתוּם, שֶׁלֹּא הִתְגַּלָּה, וְהַשְּׁמִטָּה הִתְגַּלְּתָה.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁיַּעֲקֹב עָבַד שֶׁבַע שָׁנִים רִאשׁוֹנוֹת, יָצָא קוֹל וְאָמַר: יַעֲקֹב, כָּתוּב מִן הָעוֹלָם וְעַד הָעוֹלָם. הָעוֹלָם הַנִּסְתָּר שֶׁלְּמַעְלָה הַיּוֹבֵל, מִשָּׁם הָרֵאשִׁית. שֶׁאֵלּוּ שֶׁהֵם נִסְתָּרִים, שֶׁלֹּא הִתְגַּלָּה לָהֶם, הֵם מִן הַיּוֹבֵל. מִשּׁוּם כָּךְ נִסְתְּמוּ מִיַּעֲקֹב שֶׁלֹּא יָדַע, שֶׁחָשַׁב שֶׁהֲרֵי הֵם מִן הַשְּׁמִטָּה, וּכְדֵי שֶׁיַּעֲשֶׂה רֵאשִׁית מִן הָעוֹלָם שֶׁלְּמַעְלָה הִתְכַּסּוּ מִמֶּנּוּ, מִשּׁוּם שֶׁהַיּוֹבֵל הוּא נִסְתָּר. וְאַחַר שֶׁעָבְרוּ שְׁנֵי הַיּוֹבֵל הַמְכֻסִּים, עָשָׂה שְׁנֵי שְׁמִטָּה הַנִּגְלִים, וְהִתְעַטֵּר בִּשְׁנֵי עוֹלָמוֹת וְאָחַז אוֹתָם.</p>"],[9522011314,"<p>בֹּא רְאֵה, לֵאָה הוֹלִידָה שִׁשָּׁה בָנִים וּבַת אַחַת, וְכָךְ רָאוּי, שֶׁהֲרֵי שִׁשָּׁה צְדָדִים עוֹמְדִים עָלֶיהָ, וְאֵלּוּ שִׁשָּׁה וּבַת אַחַת בְּסוֹד עֶלְיוֹן יָצְאָה.</p>\n<p>רָחֵל הוֹלִידָה שְׁנֵי צַדִּיקִים, וְכָךְ רָאוּי, הִנֵּה שְׁמִטָּה, שֶׁבֵּין שְׁנֵי צַדִּיקִים יוֹשֶׁבֶת לְעוֹלָמִים, שֶׁכָּתוּב צַדִּיקִים יִירְשׁוּ אָרֶץ. צַדִּיק לְמַעְלָה וְצַדִּיק לְמַטָּה. הַצַּדִּיק לְמַעְלָה, מִמֶּנּוּ שׁוֹפְעִים מַיִם עֶלְיוֹנִים. הַצַּדִּיק לְמַטָּה, מִמֶּנּוּ נוֹבַעַת הַנְּקֵבָה מַיִם לַזָּכָר בִּתְשׁוּקָה שְׁלֵמָה. צַדִּיק מִצַּד זֶה, וְצַדִּיק מִצַּד זֶה. כְּמוֹ שֶׁהַזָּכָר לְמַעְלָה יוֹשֵׁב בֵּין שְׁתֵּי נְקֵבוֹת, כָּךְ גַּם הַנְּקֵבָה לְמַטָּה יוֹשֶׁבֶת בֵּין שְׁנֵי צַדִּיקִים.</p>\n<p>וְעַל כֵּן יוֹסֵף וּבִנְיָמִין הֵם שְׁנֵי צַדִּיקִים. יוֹסֵף זָכָה לִהְיוֹת צַדִּיק לְמַעְלָה, מִשּׁוּם שֶׁשָּׁמַר אֶת הַבְּרִית, וּבִנְיָמִין הוּא צַדִּיק לְמַטָּה, לְעַטֵּר אֶת הַשְּׁמִטָּה בֵּין שְׁנֵי צַדִּיקִים - יוֹסֵף הַצַּדִּיק וּבִנְיָמִין הַצַּדִּיק.</p>\n<p>וְכִי בִּנְיָמִין הָיָה צַדִּיק? כֵּן, שֶׁכָּל יָמָיו לֹא חָטָא בְּאוֹת הַבְּרִית הַזּוֹ. וְאַף עַל גַּב שֶׁלֹּא הִזְדַּמֵּן לוֹ מַעֲשֶׂה כְּמוֹ יוֹסֵף, אִם כֵּן לָמָּה נִקְרָא צַדִּיק? אֶלָּא כָּל יְמֵי יַעֲקֹב, כְּשֶׁהָיָה בְּאֵבֶל שֶׁל יוֹסֵף, לֹא שִׁמֵּשׁ מִטָּתוֹ. וְאִם תֹּאמַר, שֶׁכְּשֶׁנִּטַּל יוֹסֵף מִיַּעֲקֹב, עֶלֶם הָיָה וְלֹא נָשׂוּי, וְאַתָּה אוֹמֵר שֶׁלֹּא שִׁמֵּשׁ מִטָּתוֹ? אֶלָּא אַף עַל גַּב שֶׁהִתְחַתֵּן לְאַחַר מִכֵּן, לֹא רָצָה לְשַׁמֵּשׁ מִטָּתוֹ.</p>\n<p>וְאָנוּ כָּךְ שָׁנִינוּ, בְּשָׁעָה שֶׁשָּׁאַל יוֹסֵף אֶת בִּנְיָמִין, אָמַר לוֹ: יֵשׁ לְךְ אִשָּׁה? אָמַר לוֹ: כֵּן. אָמַר לוֹ: יֵשׁ לְךְ בָּנִים? אָמַר לוֹ: כֵּן. וְאֵיךְ נִקְרָאִים? אָמַר לוֹ: עַל שֵׁם אָחִי וְכוּ', (אמר לו, יש לך בנים? אמר לו, עתידים לי, והיאך תקראם? אמר לו, על שם אחי וגו') גֵּרָא וְנַעֲמָן וְגוֹ', שֶׁכָּתוּב וּבְנֵי בִנְיָמִין בֶּלַע וָבֶכֶר וְגוֹ', וְאַתָּה אָמַרְתָּ שֶׁלֹּא שִׁמֵּשׁ? (אלא באותה שעה).</p>\n<p>אָמַר לוֹ, כֵּן, שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה לֹא הָיוּ לוֹ. (לאחר שיצא מבית האסורים היו לו) וְאִם תֹּאמַר, וּבְנֵי בִנְיָמִין בֶּלַע וָבֶכֶר, כְּשֶׁנִּכְנְסוּ לְמִצְרַיִם, כָּךְ זֶה וַדַּאי. שֶׁכָּל זְמַן שֶׁהִתְאַבֵּל יַעֲקֹב עַל יוֹסֵף, לֹא שִׁמֵּשׁ מִטָּתוֹ וְהוֹלִיד בָּנִים. וְאָמַר בִּנְיָמִין: הִנֵּה יוֹסֵף אָחִי, אוֹת הַבְּרִית שֶׁל אַבָּא הָיָה, שֶׁהֲרֵי הַבְּרִית הִיא סִיּוּם הַגּוּף. כֵּיוָן שֶׁהוּא נֶאֱבָד, אֲנִי אֶהְיֶה שׁוֹמֵר מְקוֹמוֹ שֶׁל אָחִי.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי בְּאוֹתוֹ זְמַן שֶׁנֶּאֱבַד לֹא הָיָה צַדִּיק, שֶׁצַּדִּיק הוּא לֹא הָיָה עַד שֶׁקָּרָה הַמַּעֲשֶׂה הַזֶּה בּוֹ - אֶלָּא כֻּלָּם הָיוּ יוֹדְעִים מִיַּעֲקֹב, שֶׁיַּעֲקֹב הָיָה יוֹדֵעַ שֶׁהַמָּקוֹם הַזֶּה יָרַשׁ יוֹסֵף, וּמִשּׁוּם כָּךְ הֶאֱרִיךְ אֵצֶל לָבָן כָּל כָּךְ, עַד שֶׁיִּסְתַּיֵּם הַגּוּף, וּמִי הוּא סִיּוּם הַגּוּף? הַבְּרִית, וְעַל כֵּן כָּתוּב וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגוֹ'. שֶׁהֲרֵי וַדַּאי כָּעֵת הִשְׁתַּלֵּם הַגּוּף. כֵּיוָן שֶׁהִשְׁתַּלֵּם הַגּוּף, אֲנִי רוֹצֶה לָלֶכֶת. וּמִשּׁוּם כָּךְ בִּנְיָמִין יָדַע וְשָׁמַר אֶת דֶּרֶךְ אָחִיו.</p>\n<p>כֵּיוָן שֶׁבָּא לְיוֹסֵף וְנִמְצָא, בִּנְיָמִין חָזַר לְבֵיתוֹ וְשִׁמֵּשׁ מִטָּתוֹ (והלכו ונכנסו) וְהוֹלִיד בָּנִים. וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתוֹ צַדִּיק לְמַטָּה, וְיוֹסֵף צַדִּיק לְמַעְלָה, וּמִשּׁוּם כָּךְ רָחֵל הוֹלִידָה שְׁנֵי בָנִים, וְלֵאָה שִׁשָּׁה בָנִים וּבַת.</p>\n<p>וְעַל זֶה אוֹתָן שֶׁבַע הַשָּׁנִים הָרִאשׁוֹנוֹת מְכֻסּוֹת, שֶׁלֹּא יָדַע בָּהֶן יַעֲקֹב, מִשּׁוּם שֶׁהָיוּ שֶׁל הַיּוֹבֵל. וְאוֹתָן שֶׁל שְׁמִטָּה הִתְגַּלּוּ, וּבַשְּׁמִטָּה הַגְּלוּיָה עָבַד אֶת הַיּוֹבֵל שֶׁהִתְכַּסָּה, שֶׁכָּתוּב וַיַּעֲבֹד יַעֲקֹב בְּרָחֵל שֶׁבַע שָׁנִים. שֶׁבַע שָׁנִים סְתָם. בְּרָחֵל עָבַד שֶׁבַע שָׁנִים עֶלְיוֹנוֹת, וְנֶאֱחַז בָּהֶן בִּשְׁנֵי עוֹלָמוֹת. מִכָּאן לָמַדְנוּ, מִתּוֹךְ הַנִּגְלֶה בָּא הָאָדָם לַנִּסְתָּר.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ שֶׁהַשָּׁנִים הָרִאשׁוֹנוֹת הֵן מֵהַיּוֹבֵל, הֲרֵי בַּיּוֹבֵל כָּתוּב שֶׁבַע שָׁנִים שֶׁבַע פְּעָמִים. שֶׁבַע שָׁנִים מְצוּיוֹת, שֶׁבַע פְּעָמִים (לא מצויות) אֵיפֹה הֵן? אֶלָּא אוֹתָם שִׁבְעָה יָמִים שֶׁשָּׁמַר בַּחֲתֻנָּה שֶׁל לֵאָה הִשְׁלִימוּ אֶת הַחֶשְׁבּוֹן, שֶׁהֲרֵי כָּל יוֹם (פעם אחת ושבע אחת) (שבע) נִקְרָא פַּעַם אַחַת, שֶׁכָּתוּב (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ עַל מִשְׁפְּטֵי צִדְקֶךְ. וְכָל שִׁבְעָה מִשְׁתַּלֵּם בְּשִׁבְעָה יָמִים, ז' בְּכָל יוֹם, שֶׁנִּקְרָא פַּעַם אַחַת.</p>\n<p>וּבְרָחֵל לֹא הָיָה כֵן, שֶׁלֹּא שָׁמַר שִׁבְעָה יָמִים, אֶלָּא שֶׁבַע שָׁנִים שֶׁעָבַד אַחַר כָּךְ. וְאִם תֹּאמַר, אִם כָּךְ, שָׁנִים שֶׁל שְׁמִטָּה הָיָה לוֹ לַעֲבֹד קֹדֶם וְאַחַר כָּךְ לְהִזְדַּוֵּג עִם הַשְּׁמִטָּה? אֶלָּא כֵּיוָן שֶׁקִּבֵּל עָלָיו לַעֲבֹד, כְּאִלּוּ עָבַד אוֹתָם. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר, בָּרוּךְ הָרַחֲמָן שֶׁזָּכִיתִי לַפָּסוּק הַזֶּה, עַל אוֹתוֹ הַמָּקוֹם כָּתוּב (ישעיה מט) ה' חָפֵץ לְמַעַן צִדְקוֹ יַגְדִּיל תּוֹרָה וְיַאְדִּיר.</p>"],[9522011315,"<p>עוֹד אָמַר רַבִּי אֶלְעָזָר, זֶה שֶׁנֶּאֱמַר לֵאָה הוֹלִידָה שִׁשָּׁה בָנִים וּבַת אַחַת - כָּךְ זֶה וַדַּאי. רָחֵל שְׁנֵי בָנִים וַדַּאי, בְּנֵי הַשְּׁפָחוֹת אַרְבָּעָה. תִּקּוּנָם אֵיךְ עוֹמְדִים? אֶלָּא אוֹתָם אַרְבָּעָה קְשָׁרִים שֶׁנִּקְרָאִים אֲחוֹרַיִם, שֶׁכָּתוּב וְכָל אֲחֹרֵיהֶם בָּיְתָה.</p>\n<p>שֶׁהֲרֵי בִּזְרוֹעַ יָמִין שְׁלֹשָׁה קְשָׁרִים, אֲבָל קֶשֶׁר אֶחָד בָּאֶמְצַע שֶׁהוּא גָדוֹל וְהוּא אָחוֹר, שֶׁנִּשְׁאַר בַּחוּץ. וְכֵן אֶחָד בִּזְרוֹעַ שְׂמֹאל, וְכֵן אֶחָד בְּיֶרֶךְ יָמִין, וְכֵן אֶחָד בְּיֶרֶךְ שְׂמֹאל. וּכְשֶׁהַכֹּל נִתְקַן, נִמְצְאוּ כֻלָּם בַּיְתָה, לְקַיֵּם אֶת הַפָּסוּק שֶׁכָּתוּב וְכָל אֲחֹרֵיהֶם בָּיְתָה.</p>\n<p>כָּל שְׁאָר הַקְּשָׁרִים, כֻּלָּם נִרְאִים בְּיֹשֶׁר, וְאֵלּוּ יוֹצְאִים מִחוּץ לַזְּרוֹעוֹת וּמִחוּץ לַיְרֵכַיִם לְהֵרָאוֹת בִּפְנֵי הַשְּׁפָחוֹת. שֶׁאַף עַל גַּב שֶׁהֵם בַּמִּנְיָן, אֵינָם חֲשׁוּבִים כִּבְנֵי רָחֵל וְלֵאָה, וּמִשּׁוּם כָּךְ יָצְאוּ בַּחוּץ.</p>\n<p>דָּבָר אַחֵר, אֵלּוּ הֵם הָאַרְבָּעָה שֶׁכָּל שְׁאָר הַקְּשָׁרִים נוֹטְלִים בִּשְׁבִילָם, וְאֵלּוּ נוֹטְלִים אוֹתָם. אָמַר רַבִּי אַבָּא, כָּךְ זֶה וַדַּאי, (אמר רבי אבא, זה לא זה) וְעַל כֵּן הַכֹּל נִתְקָן יַחַד.</p>"],[9522011316,"<p>וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (תהלים קיג) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת אֵם הַבָּנִים שְׂמֵחָה הַלְלוּיָהּ. מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת - זוֹ רָחֵל, שֶׁהִיא עִקַּר הַבַּיִת. אֵם הַבָּנִים שְׂמֵחָה - זוֹ לֵאָה.</p>\n<p>דָּבָר אַחֵר מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת - זוֹ שְׁמִטָּה, שֶׁהִיא עִקַּר הָעוֹלָם הַזֶּה, עָלָיו הוּא מֻנְהָג. אֵם הַבָּנִים שְׂמֵחָה - זֶה הַיּוֹבֵל, שֶׁכָּל שִׂמְחָה וְכָל חֶדְוָה שֶׁל כָּל הָעוֹלָמוֹת תְּלוּיִים בּוֹ, וְהַפָּסוּק הַזֶּה הוּא הַכְּלָל שֶׁל הַכֹּל, מִשּׁוּם שֶׁזֶּה כּוֹלֵל הַכֹּל בְּסוֹד קָדוֹשׁ, וְעַל זֶה סִיּוּם הַפָּסוּק הַלְלוּיָהּ.</p>\n<p>וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה. וְכִי לָמָּה הִיא שְׂנוּאָה, וַהֲרֵי בְּנֵי הַשְּׂנוּאָה אֵינָם בָּנִים מְעֻלִּים, וְרָאִינוּ שֶׁכָּל אוֹתָם בָּנִים מְעֻלִּים יָצְאוּ מִלֵּאָה, וְאַתָּה אוֹמֵר שֶׁלֵּאָה שְׂנוּאָה? אֶלָּא וַדַּאי הַיּוֹבֵל הוּא תָּמִיד עוֹלָם הַנִּסְתָּר, וְכָל דְּבָרָיו אֵינָם (בני) בְּנִגְלֶה, וּמִשּׁוּם כָּךְ נִסְתְּרוּ מִיַּעֲקֹב כָּל מַעֲשָׂיו.</p>\n<p>בֹּא רְאֵה, הָעוֹלָם הַתַּחְתּוֹן הוּא בְּנִגְלֶה, וְהוּא רֵאשִׁית הַכֹּל לַעֲלוֹת בְּדַרְגוֹתָיו. כְּמוֹ שֶׁהַחָכְמָה הָעֶלְיוֹנָה הִיא רֵאשִׁית הַכֹּל, כָּךְ גַּם הָעוֹלָם הַתַּחְתּוֹן הוּא חָכְמָה, וְהִיא רֵאשִׁית הַכֹּל, וּמִשּׁוּם כָּךְ קוֹרְאִים אַתָּה, מִשּׁוּם שֶׁהוּא שְׁמִטָּה, וּבְגָלוּי.</p>\n<p>וְהָעוֹלָם הָעֶלְיוֹן, שֶׁהוּא הַיּוֹבֵל, קוֹרְאִים הוּא, שֶׁכָּל דְּבָרָיו הֵם בְּנִסְתָּר, וְסוֹד הַדָּבָר שֶׁל לֵאָה, שֶׁכָּתוּב וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא, וְעַל זֶה כָּתוּב (במדבר יח) וְעָבַד הַלֵּוִי הוּא, כְּדֵי לִמְשֹׁךְ מִמֶּנּוּ בְּרָכוֹת לַכֹּל. הוּא - הָעוֹלָם הָעֶלְיוֹן שֶׁנִּסְתָּר תָּמִיד. וְיַעֲקֹב בְּמַה שֶּׁנִּסְתָּר לֹא נִדְבַּק בִּרְצוֹנוֹ, אֶלָּא בְּמַה שֶּׁנִּגְלֶה, וְזֶה סוֹד הַכָּתוּב וְדָבַק בְּאִשְׁתּוֹ.</p>\n<p>וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה. מִכָּאן שֶׁשּׂוֹנֵא אָדָם עֶרְוַת אִמּוֹ (ואחותו), וְיִתְיַחֵד אָדָם עִם אִמּוֹ בְּכָל מָקוֹם וְלֹא יַחְשֹׁשׁ, וַהֲרֵי הֵעִירוּ, בֵּן מִתְיַחֵד עִם אִמּוֹ. וְהַכֹּל הִתְכַּסָּה מִיַּעֲקֹב, שֶׁהָעוֹלָם הָעֶלְיוֹן לֹא הִתְגַּלָּה כְּלָל.</p>"],[9522011317,"<p>בֹּא רְאֵה, בִּשְׁבִיל יַעֲקֹב הִתְקַיֵּם הָעוֹלָם. וְאִם תֹּאמַר, הִנֵּה בִּשְׁבִילוֹ שֶׁל אַבְרָהָם, כְּמוֹ שֶׁנֶּאֱמַר בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם - אֶלָּא מִשּׁוּם יַעֲקֹב הִתְקַיֵּם אַבְרָהָם, שֶׁכָּתוּב (ישעיה כט) כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם. וּמִקֹּדֶם לָכֵן הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָם. כֵּיוָן שֶׁבָּא יַעֲקֹב, הִשְׁתַּכְלְלוּ מִמֶּנּוּ הָעוֹלָמוֹת וְלֹא נֶחְרְבוּ כְּבָרִאשׁוֹנָה. זֶהוּ שֶׁכָּתוּב כֹּה אָמַר ה' בֹּרַאֲךְ יַעֲקֹב וְיֹצֶרְךְ יִשְׂרָאֵל וְגוֹ'.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וְכָתוּב שַׁלַּח אֶת בְּנִי וְיַעַבְדֵנִי. יִשְׂרָאֵל נִקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא מִשּׁוּם שֶׁנִּדְבָּק בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר מַה שְּׁמוֹ וּמַה שֵּׁם בְּנוֹ כִּי תֵדָע.</p>\n<p>כְּשֶׁלֵּאָה הוֹלִידָה אֶת רְאוּבֵן, מַה כָּתוּב? וַתִּקְרָא אֶת שְׁמוֹ רְאוּבֵן. רְאוּבֵן סְתָם, מִשּׁוּם שֶׁנִּכְלָל בִּשְׁלֹשָׁה צְדָדִים מְחֻבָּרִים יַחַד - שִׁמְעוֹן וְלֵוִי. מָה הַטַּעַם לֵוִי? כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ז) לֹיוֹת, הַחִבּוּר שֶׁל כָּל הַצְּדָדִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מִכָּאן שֶׁכָּתוּב יֶתֶר שְׂאֵת וְיֶתֶר עָז, כְּתַרְגּוּמוֹ בְּכוֹרָה, כְּהֻנָּה וּמַלְכוּת. וְהַמַּלְכוּת הִיא בְּצַד הַגְּבוּרָה, וְעַל כֵּן רְאוּבֵן סְתָם.</p>\n<p>אָמַר רַבִּי אַבָּא, רְאוּ בֵן סְתָם, שֶׁנִּכְלָל בְּשִׁמְעוֹן וְלֵוִי. כָּךְ הָיְתָה דַעְתָּהּ (רצונה) שֶׁל לֵאָה, שֶׁכָּתוּב הַפַּעַם יִלָּוֶה אִישִׁי אֵלַי כִּי יָלַדְתִּי לוֹ שְׁלֹשָׁה בָנִים. מִשּׁוּם שֶׁהָיוּ שְׁלֹשָׁה שֶׁמִּתְחַבְּרִים יַחַד.</p>\n<p>וּבֹא וּרְאֵה שֶׁכָּאן הוּא, שֶׁהֲרֵי הַמֶּרְכָּבָה הָעֶלְיוֹנָה - הָאָבוֹת, וְדָוִד הַמֶּלֶךְ שֶׁהִתְחַבֵּר עִמָּם, וְכָל הָאַרְבַּע הֵם מֶרְכָּבוֹת עֶלְיוֹנוֹת, הַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ. וְעַל כֵּן רְאוּבֵן שִׁמְעוֹן וְלֵוִי, אַחַר כָּךְ יְהוּדָה שֶׁיָּרַשׁ מַלְכוּת, וְעַל כֵּן כֻּלָּם בַּמָּקוֹם הַזֶּה.</p>\n<p>וְכָתוּב (זה אחר זה שכתוב) (בראשית כט) הַפַּעַם אוֹדֶה אֶת ה' וְגוֹ' וַתַּעֲמֹד מִלֶּדֶת. מִשּׁוּם שֶׁכָּאן נִשְׁלְמוּ אַרְבָּעָה עַמּוּדִים. הַפַּעַם אוֹדֶה אֶת ה', מָה הַטַּעַם אָמְרָה בְּזֶה אוֹדֶה אֶת ה', וְלֹא בְכֻלָּם? אֶלָּא מִכָּאן, שֶׁכָּל זְמַן שֶׁכְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת, הַשֵּׁם הַקָּדוֹשׁ אֵינוֹ שָׁלֵם. בֹּא רְאֵה, אַף עַל גַּב שֶׁשְּׁלֹשָׁה בָנִים הָיוּ עַד שֶׁהוֹלִידָה אֶת יְהוּדָה, הַכִּסֵּא לֹא הַשָּׁלֵם, וּמִשּׁוּם כָּךְ הַפַּעַם אוֹדֶה אֶת ה', וְלֹא בְכֻלָּם. וְעַל כֵּן וַתַּעֲמֹד מִלֶּדֶת. מַה זֶּה וַתַּעֲמֹד? שֶׁעָמַד הַכִּסֵּא עַל תּוֹמְכָיו.</p>\n<p>(ותעמד עד כאן) וַתַּעֲמֹד, שֶׁהִנֵּה עַד כָּאן וַתַּעֲמֹד, בְּיִחוּד אֶחָד. מִכָּאן וּלְמַטָּה הוּא עוֹלַם הַפֵּרוּד. וְאִם תֹּאמַר, אוֹתָם שְׁנֵי הַבָּנִים שֶׁהוֹלִידָה אַחַר כָּךְ כְּמוֹ זֶה? לֹא שֶׁהֲרֵי אוֹתָם הַשְּׁנַיִם הִתְחַבְּרוּ עִם אֵלּוּ, מִשּׁוּם שֶׁשֵּׁשֶׁת הַצְּדָדִים שֶׁל הָעוֹלָם הֵם יַחַד.</p>\n<p>וּבֹא וּרְאֵה, כָּל שְׁנֵים עָשָׂר הַשְּׁבָטִים הֵם תִּקּוּנֶיהָ שֶׁל כְּנֶסֶת יִשְׂרָאֵל בָּעוֹלָם הַזֶּה, לְתַקֵּן הָאוֹר הָעֶלְיוֹן הַשָּׁחֹר כְּמוֹ שֶׁרָאוּי, וּלְהָשִׁיב אֶת עִקַּר הַכֹּל לִמְקוֹמוֹ. כָּל הָעוֹלָמוֹת כְּמוֹ אֶחָד עוֹמְדִים, וּבָזֶה נִשְׁלָם הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ שֶׁהָעוֹלָם שֶׁלְּמַעְלָה.</p>\n<p>יִשָּׂשכָר זְבֻלוּן, כָּאן נִשְׁלְמוּ שִׁשָּׁה בָנִים, שֵׁשֶׁת הַצְּדָדִים שֶׁל הָעוֹלָם. כְּמוֹ כֵן בְּנֵי הַשְּׁפָחוֹת הֵם אַרְבַּע, וְהִתְחַבְּרוּ עִם אֵלּוּ, וְאֵלּוּ אַרְבַּעַת הַקְּשָׁרִים שֶׁמִּתְחַבְּרִים בָּהֶם, וּבֵאֲרוּהָ. וְעַל כֵּן כָּתוּב (מלכים א ז) וְכָל אֲחֹרֵיהֶם בָּיְתָה. אַף עַל גַּב שֶׁבְּנֵי שְׁפָחוֹת הֵם - בָּיְתָה.</p>\n<p>רַבִּי חִזְקִיָּה אָמַר, אִם כָּךְ, הֲרֵי נֶאֱמַר, כָּל מַה שֶּׁהוֹלִיד הָעוֹלָם הַתַּחְתּוֹן הוּא פֵּרוּד, שֶׁהֲרֵי כָּתוּב וּמִשָּׁם יִפָּרֵד. מַה תֹּאמַר בְּיוֹסֵף וּבִנְיָמִין? אִם תֹּאמַר שֶׁעוֹלָם אֶחָד בְּאֵלֶּה - זֶה אֵינוֹ, שֶׁהֲרֵי לֹא יָצְאוּ מִן הָעוֹלָם הָעֶלְיוֹן, וְהָעוֹלָם הַתַּחְתּוֹן - מַה שֶּׁהוֹלִיד, הוֹלִיד לְמַטָּה וְלֹא לְמַעְלָה, וְאִם כָּךְ הוּא פֵּרוּד.</p>\n<p>בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר לוֹ, דָּבָר זֶה הוּא נִסְתָּר, שֶׁהֲרֵי הָעוֹלָם הָעֶלְיוֹן הִתְתַּקֵּן בִּשְׁנֵים עָשָׂר שֶׁל אוֹתָם מִשֶּׁלּוֹ. אֲבָל בֹּא רְאֵה סוֹד הַדָּבָר, בְּכָל זְמַן הַצַּדִּיק מֵהָעוֹלָם הַתַּחְתּוֹן יוֹצֵא וְנִכְנָס, בּוֹ נִכְנָס וּמִמֶּנּוּ יוֹצֵא, וּמִשּׁוּם כָּךְ נִבְנֶה בַּמָּקוֹם הַזֶּה, וְהָעִקָּר הוּא לְמַעְלָה, וְהָעִקָּר הוּא לְמַטָּה, (צדיק, בו נכנס בו יוצא) וְהוּא תָּמִיד בָּעוֹלָם הַתַּחְתּוֹן לְעוֹלָם, כָּתוּב וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה.</p>\n<p>בֹּא רְאֵה, בָּעוֹלָם הַתַּחְתּוֹן הַזֶּה, הַצַּדִּיק נִכְנָס בּוֹ וּמִמֶּנּוּ יוֹצֵא. כְּשֶׁנִּכְנָס הוּא בְּסוֹד שֶׁל יוֹסֵף הַצַּדִּיק, וּכְשֶׁיּוֹצֵא הוּא בְּסוֹד שֶׁל בִּנְיָמִין. זֶהוּ שֶׁכָּתוּב וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה. מִי נַפְשָׁהּ? זֶה הַצַּדִּיק שֶׁיּוֹצֵא מִמֶּנָּה.</p>\n<p>וְזְהִ בִּנְיָמִין, נִקְרָא בֶּן אוֹנִי, שֶׁחָשְׁבָה שֶׁהוֹלִידָה לְמַטָּה בְּעוֹלַם הַפֵּרוּד, וְנִשְׁאֲרוּ אַחַד עָשָׂר בְּאוֹתָם לְמַעְלָה. מַה כָּתוּב? וְאָבִיו קָרָא לוֹ בִּנְיָמִין, בֶּן יָמִין. שֶׁהֲרֵי הִתְעַלָּה לְמַעְלָה בָּעוֹלָם הָעֶלְיוֹן. שֶׁכַּאֲשֶׁר נֶאֱבַד יוֹסֵף, בִּנְיָמִין הִשְׁלִים אֶת מְקוֹמוֹ. וְעַל כֵּן הַצַּדִּיק נִכְנָס וְיוֹצֵא בָּעוֹלָם הַתַּחְתּוֹן. מִשּׁוּם כָּךְ יוֹסֵף וּבִנְיָמִין וְכָל הַשְּׁנֵים עָשָׂר, כְּמוֹ שֶׁלְּמַעְלָה בְּיִחוּד אֶחָד.</p>"],[9522011318,"<p>הַפַּעַם אוֹדֶה אֶת ה'. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהלים קיא) אוֹדֶה ה' בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה. בְּכָל לֵבָב? בְּכָל לֵב הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא דָּוִד בְּסוֹד עֶלְיוֹן שֶׁל הַשֵּׁם הַקָּדוֹשׁ רָצָה לְהוֹדוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא. אוֹדֶה ה' בְּכָל לֵבָב - בְּיֵצֶר טוֹב וּבְיֵצֶר רַע, וְאֵלּוּ שְׁנֵי הַצְּדָדִים, אֶחָד יָמִין וְאֶחָד שְׂמֹאל.</p>\n<p>בְּסוֹד יְשָׁרִים וְעֵדָה - אֵלּוּ הֵם שְׁאָר הַצְּדָדִים שֶׁל הָעוֹלָם הַזֶּה, שֶׁהֲרֵי לֵבָב כְּמוֹ צָפוֹן וְדָרוֹם. בְּסוֹד יְשָׁרִים - אֵלּוּ הֵם שְׁאָר צִדְדֵי הָעוֹלָם, שֶׁהֵם שִׁשָּׁה כְּמוֹ שֶׁלְּמַעְלָה. וְעֵדָה - זֶהוּ הַמָּקוֹם שֶׁל יְהוּדָה, וְכָתוּב (תהלים קלב) וְעֵדתִי זוֹ אֲלַמְּדֵם.</p>\n<p>וְכָתוּב (הושע יב) וִיהוּדָה עֹד רָד עִם אֵל וְגוֹ'. כְּתִיב (תהלים קלח) אוֹדְךְ בְכָל לִבִּי נֶגֶד אֱלֹהִים אֲזַמְּרֶךָּ. כָּאן בְּמָקוֹם אֶחָד נֶאֱמַר, שֶׁכָּתוּב נֶגֶד אֱלֹהִים אֲזַמְּרֶךָּ, שֶׁהֲרֵי לַדַּרְגָּה הַזּוֹ אָמַר שִׁירָה, לְחַבֵּר אוֹתָהּ לְיָמִין.</p>\n<p>בֹּא רְאֵה, יְהוּדָה אָחוּז בְּכָל הַצְּדָדִים. אָחוּז בַּדָּרוֹם, אָחוּז בַּמִּזְרָח. שֶׁהֲרֵי הוּא בָּא מִצַּד הַשְּׂמֹאל, וְרֵאשִׁיתוֹ בַּצָּפוֹן, וְאָחוּז בַּדָּרוֹם, מִשּׁוּם שֶׁהוּא הוֹלֵךְ לְיָמִין וְנֶאֱחָז בַּגּוּף. מִשּׁוּם כָּךְ, הַפַּעַם אוֹדֶה אֶת ה'. וַתַּעֲמֹד מִלֶּדֶת. וַתַּעֲמֹד, שֶׁעָמְדָה בַּקִּיּוּם שֶׁל הַבְּרִית כָּרָאוּי, שֶׁהֲרֵי הַכֹּל נִתְקַן מֶרְכָּבָה קְדוֹשָׁה.</p>\n<p>רַבִּי שִׁמְעוֹן יָצָא לַקִּרְיָה. הִזְדַּמֵּן לוֹ רַבִּי אַבָּא וְרַבִּי חִיָּיא וְרַבִּי יוֹסֵי. כֵּיוָן שֶׁרָאָה אוֹתָם, אָמַר, הִתְחַדְּשׁוּת שֶׁל הַתּוֹרָה צָרִיךְ כָּאן. יָשְׁבוּ שְׁלֹשֶׁת אֵלֶּה (ימים). כְּשֶׁרָצָה לָלֶכֶת, פָּתַח כָּל אֶחָד מֵהֶם בְּפָסוּק.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, וַה' אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ, שָׂא נָא עֵינֶיךְ וּרְאֵה וְגוֹ'. וְכִי לְפִי הָרְאִיָּה שֶׁל אַבְרָהָם יוֹרֵשׁ אֶת הָאָרֶץ, וְלֹא יוֹתֵר? עַד כַּמָּה רוֹאֶה בֶּן אָדָם? שָׁלֹשׁ פַּרְסָאוֹת, אוֹ אַרְבַּע אוֹ חָמֵשׁ פַּרְסָאוֹת, וְהוּא אוֹמֵר כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה וְגוֹ'?!</p>\n<p>אֶלָּא, כֵּיון שֶׁאַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם רוֹאֶה, אֶת כָּל הָאָרֶץ רוֹאֶה. שֶׁהֲרֵי אַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם הֵם כְּלָלוֹ שֶׁל כָּל הָעלָם. עוֹד, הֵרִים אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אֶרֶץ יִשְׂרָאֵל וְהֶרְאָה לוֹ שֶׁהִיא קְשׁוּרָה בִּצִדְדֵי הָעוֹלָם, וְהָיָה רוֹאֶה אֶת הַכֹּל. כְּמוֹ כֵן, מִי שֶׁרוֹאֶה אֶת רַבִּי שִׁמְעוֹן, רוֹאֶה אֶת כָּל הָעוֹלָם, הַשִּׂמְחָה שֶׁל מַעְלָה וּמַטָּה.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, הָאָרֶץ אֲשֶׁר אַתָּה שֹׁכֵב עָלֶיהָ לְךְ אֶתְּנֶנָּה וּלְזַרְעֶךְ, וְכִי אוֹתוֹ הַמָּקוֹם לְבַדּוֹ הִבְטִיחַ לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי אַרְבַּע אַמּוֹת אוֹ חָמֵשׁ הָיוּ וְלֹא יוֹתֵר? אֶלָּא בְּאוֹתוֹ זְמַן, בְּאוֹתָם אַרְבַּע אַמּוֹת קִפֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אֶרֶץ יִשְׂרָאֵל. נִמְצָא שֶׁאוֹתוֹ מָקוֹם הוּא הַכְּלָל שֶׁל כָּל הָאָרֶץ. וּמָה אוֹתוֹ הַמָּקוֹם הוּא הַכְּלָל שֶׁל כָּל הָאָרֶץ - רַבִּי שִׁמְעוֹן שֶׁהוּא הַמָּאוֹר שֶׁל כָּל הָאָרֶץ, עַל אַחַת כַּמָּה וְכַמָּה שֶׁשָּׁקוּל כְּכָל הָעוֹלָם.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, הַפַּעַם אוֹדֶה אֶת ה', וְכִי בְּכָל מַה שֶּׁהוֹלִידָה לֹא רָאוּי לְהוֹדוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶלָּא בָּזֶה? אֶלָּא יְהוּדָה הוּא הַבֵּן הָרְבִיעִי לַכִּסֵּא, וְהוּא מַשְׁלִים אֶת הַכִּסֵּא. וּמִשּׁוּם כָּךְ יְהוּדָה לְבַדּוֹ תִּקּוּן הַכִּסֵּא וְתוֹמֵךְ שֶׁל כָּל הַתּוֹמְכִים. (שהיו שלשה, אברהם ויצחק ויעקב, ואז בא דוד מיהודה והשלים הכסא, ועל כך נקרא יהודה, שהוא השם הקדוש, והדל\"ת (ארבע רגליו) מרגלות הכסא) רַבִּי שִׁמְעוֹן שֶׁמֵּאִיר אֶת כָּל הָעוֹלָם בַּתּוֹרָה וְכַמָּה מְאוֹרוֹת מְאִירִים בִּשְׁבִילוֹ, עַל אַחַת כַּמָּה וְכַמָּה.</p>"],[9522011319,"<p>מִשְׁנָה, בְּנֵי עֶלְיוֹן, קְדוֹשִׁים עֶלְיוֹנִים, בְּרוּכֵי (נבחרי) הָעוֹלָם, מֹחַ הָאֱגוֹז, הִתְכַּנְּסוּ לָדַעַת. הִנֵּה צִפּוֹר יוֹרֶדֶת בְּכָל יוֹם, מִתְעוֹרֶרֶת בַּגַּן. שַׁלְהֶבֶת אֵשׁ בִּכְנָפֶיהָ, בְּיָדֶיהָ שָׁלֹשׁ מַגְרֵפוֹת שְׁנוּנוֹת כַּחֶרֶב, מַפְתְּחוֹת שֶׁל גְּנָזִים בְּיַד יָמִין.</p>\n<p>קוֹרֵא בְחַיִל וְאוֹמֵר: מִי מִכֶּם שֶׁפָּנָיו מְאִירוֹת, שֶׁנִּכְנַס וְיָצָא וְהֶחֱזִיק בְּעֵץ הַחַיִּים, הִגִּיעַ לַעֲנָפָיו, אָחַז בְּשָׁרָשָׁיו, אָכַל מִפִּרְיוֹ הַמָּתוֹק מִדְּבַשׁ, נוֹתֵן חַיִּים לַנֶּפֶשׁ וּרְפוּאָה לְעַצְמוֹ?</p>\n<p>הִשָּׁמֵר מֵהִרְהוּר רַע, מֵהִרְהוּר שֶׁמְּשַׁקֵּר בְּעֵץ הַחַיִּים, מְטַמֵּא הַנָּהָר וְהַנַּחַל הַמָּקוֹר שֶׁל יִשְׂרָאֵל, שֶׁנּוֹתֵן מָוֶת לַנֶּפֶשׁ וְשֶׁבֶר לְעַצְמוֹ, אֵין לוֹ כְּלָל קִיּוּם.</p>\n<p>הַהִרְהוּר שֶׁמְּטַמֵּא אוֹתוֹ הַמָּקוֹר שֶׁלּוֹ, עוֹשֶׂה עֵץ שֶׁל שֶׁקֶר, מִשּׁוּם שֶׁאוֹתוֹ הַהִרְהוּר עוֹלֶה וּמַחֲלִיף נֶפֶשׁ תַּחַת נֶפֶשׁ. עֵץ הַחַיִּים מִסְתַּלֵּק, וְעֵץ הַמָּוֶת מַחֲזִיק בּוֹ, מוֹשֵׁךְ מִשָּׁם הַנֶּפֶשׁ.</p>\n<p>אוֹי לוֹ שֶׁנֶּעֱקַר בַּהִרְהוּר הַהוּא מִתּוֹךְ עֵץ הַחַיִּים וְנִדְבַּק בְּעֵץ הַמָּוֶת, אֵין בּוֹ עֲנָפִים, לֹא רוֹאֶה טוֹב לְעוֹלָמִים, הוּא יָבֵשׁ בְּלִי לַחוּת כְּלָל, פִּרְיוֹ מַר כַּלַּעֲנָה, עָלָיו נֶאֱמַר (ירמיה יז) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא יִרְאֶה כִּי יָבוֹא טוֹב וְגוֹ'.</p>\n<p>מִשּׁוּם שֶׁהִרְהוּר טוֹב עוֹלֶה לְמַעְלָה, אוֹחֵז בְּעֵץ הַחַיִּים, מַחֲזִיק בַּעֲנָפָיו, אוֹכֵל מִפִּרְיוֹ, כָּל הַקְּדֻשּׁוֹת וְכָל הַבְּרָכוֹת יוֹצְאוֹת מִמֶּנּוּ, מוֹרִישׁ חַיִּים לַנֶּפֶשׁ וּרְפוּאָה לְעַצְמוֹ, עָלָיו נֶאֱמַר (שם) וְהָיָה כְּעֵץ שָׁתוּל עַל מַיִם וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו וְלֹא יִרְאֶה כִּי יָבֹא חֹם וְגוֹ'.</p>\n<p>כָּל דִּבְרֵי הָעוֹלָם הוֹלְכִים אַחַר הַמַּחֲשָׁבָה וְהַהִרְהוּר, וְעַל כֵּן (ויקרא יא) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים, מִשּׁוּם שֶׁכָּל הַקְּדֻשּׁוֹת שֶׁל הָעוֹלָם מוֹצִיא וּמוֹשֵׁךְ בְּהִרְהוּר טוֹב.</p>\n<p>מִי שֶׁנִּטְמָא בְּהִרְהוּר רַע, כְּשֶׁבָּא לְהִזְדַּוֵּג עִם אִשְׁתּוֹ וְשָׂם רְצוֹנוֹ וְהִרְהוּרוֹ בְּאִשָּׁה אַחֶרֶת, וְזוֹרֵעַ זֶרַע בְּהִרְהוּר אַחֵר, זֶהוּ שֶׁמַּחֲלִיף אֶת הַדְּרָגוֹת הָעֶלְיוֹנִים שֶׁלְּמַעְלָה, הַדַּרְגָּה שֶׁל קֹדֶשׁ בַּעֲבוּר הַדַּרְגָּה שֶׁל הַטֻּמְאָה. כְּמוֹ שֶׁהַהִרְהוּר שֶׁלּוֹ עוֹשֶׂה חִלּוּפִים לְמַטָּה, אַף כָּךְ עוֹשֶׂה חִלּוּפִים לְמַעְלָה.</p>\n<p>כְּמוֹ שֶׁגּוּפוֹ שֶׁל אוֹתוֹ בֵּן שֶׁיּוֹלִיד נִקְרָא בֶּן תְּמוּרָה, כָּךְ גַּם בַּנֶּפֶשׁ נִקְרָא בֶּן תְּמוּרָה, שֶׁהֲרֵי לֹא מוֹשֵׁךְ מְשִׁיכָה קְדוֹשָׁה בַּהִרְהוּר הַהוּא, וְנַפִשׁוֹ מִתְחַלֶּפֶת בְּדַרְגָּה אַחֶרֶת.</p>\n<p>יַעָקֹב הַשָּׁלֵם שֶׁל הַכֹּל, גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכָּל דְּרָכָיו הָיוּ בֶּאֱמֶת, וְהִרְהוּר שֶׁל אֱמֶת הִרְהֵר תָּמִיד בַּכֹּל, בְּאוֹתוֹ הַלַּיְלָה שֶׁשִּׁמֵּשׁ עִם אִשְׁתּוֹ לֵאָה, הַהִרְהוּר שֶׁלּוֹ הָיָה בְּרָחֵל. מְשַׁמֵּשׁ עִם לֵאָה וְחוֹשֵׁב עַל רָחֵל. וְהַמָּקוֹר שֶׁלּוֹ הָלַךְ בַּהִרְהוּר הַהוּא שֶׁלּוֹ.</p>\n<p>וְלֹא לְדַעַת, שֶׁהֲרֵי לֹא הָיָה יוֹדֵעַ, מִשּׁוּם כָּךְ לֹא עָלָה רְאוּבֵן בַּשֵּׁם. הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיָה יוֹדֵעַ, הֶרְאָה לוֹ וְאָמַר, רְאוּ בֵן שֶׁנּוֹלָד בָּעוֹלָם. וְעַל כֵּן כָּתוּב (ירמיה כג) אִם יִסָּתֵר אִישׁ בְּמִסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ. אַל תִּקְרֵי אֶרְאֶנּוּ אֶלָּא אַרְאֶנּוּ, שֶׁיִּסְתַּכְּלוּ בוֹ. וּמִשּׁוּם שֶׁהִתְגַּלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֲרֵי זֶה הָיָה לֹא לְדַעְתּוֹ וּבְדֶרֶךְ אֱמֶת הִרְהֵר בִּרְצוֹנוֹ יַעֲקֹב, לֹא נִפְסַל מִתּוֹךְ הַשְּׁבָטִים הַקְּדוֹשִׁים, שֶׁאִם לֹא כָּךְ - הָיָה נִפְסָל.</p>\n<p>וּמִשּׁוּם שֶׁהַהִרְהוּר הוּא עִקָּר וְעוֹשֶׂה מַעֲשֶׂה, הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיָה יוֹדֵעַ אוֹתוֹ הַהִרְהוּר בַּמָּקוֹם שֶׁנִּדְבַּק, בְּאוֹתָהּ הַטִּפָּה הָרִאשׁוֹנָה נִשְׁמְרָה לוֹ הַבְּכוֹרָה, שֶׁכָּתוּב (ד\"ה א ב) כִּי הוּא הַבְּכוֹר וְגוֹ'. נִתְּנָה בְּכוֹרָתוֹ לְיוֹסֵף. בְּאוֹתוֹ מָקוֹם שֶׁהַהִרְהוּר הָלַךְ וְנִדְבַּק בַּטִּפָּה הַהִיא, שָׁם נִדְבַּק וְנִמְסְרָה אוֹתָהּ הַבְּכוֹרָה, וְנִטְּלָה הַבְּכוֹרָה מֵרְאוּבֵן, וְנִמְסְרָה לַמָּקוֹם שֶׁהַהִרְהוּר נִדְבַּק בָּהּ. בְּרָחֵל הִרְהֵר וְנִדְבַּק הָרָצוֹן - בְּרָחֵל נִדְבְּקָה הַבְּכוֹרָה, וְהַכֹּל חָזַר אַחַר הַהִרְהוּר וְהַמַּחֲשָׁבָה.</p>\n<p>כְּמוֹ כֵן הַהִרְהוּר וְהַמַּחֲשָׁבָה עוֹשִׂים מַעֲשֶׂה, וְנִמְשֶׁכֶת מְשִׁיכָה בְּכָל מַה שֶּׁנִּדְבַּק אָדָם בַּסֵּתֶר, שֶׁכָּתוּב (דברים כה) לֹא תִהְיֶה אֵשֶׁת הַמֵּת הַחוּצָה לְאִישׁ זָר יְבָמָהּ יָבֹא עָלֶיהָ. וְכָאן צָרִיךְ הִרְהוּר וְרָצוֹן לְהִתְדַּבֵּק, וּבְאוֹתוֹ הָרָצוֹן וּמַחֲשָׁבָה מוֹשֵׁךְ מְשִׁיכָה וְעוֹשֶׂה הַמַּעֲשֶׂה שֶׁצָּרִיךְ, וְלֹא יִכְלֶה שֵׁם הַמֵּת מִן הָעוֹלָם.</p>\n<p>וְסֵתֶר זֶה, (איוב לד) אִם יָשִׂים אֵלָיו לִבּוֹ רוּחוֹ וְנִשְׁמָתוֹ אֵלָיו יֶאֱסֹף. שֶׁהֲרֵי וַדַּאי הָרָצוֹן וְהַמַּחֲשָׁבָה מוֹשְׁכִים מְשִׁיכָה וְעוֹשִׂים מַעֲשֶׂה בְּכָל מַה שֶּׁצָּרִיךְ. וְעַל כֵּן בַּתְּפִלָּה צָרִיךְ רָצוֹן וְהִרְהוּר לְכַוֵּן, וְכֵן בְּכָל אוֹתָן הָעֲבוֹדוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - הַהִרְהוּר וְהַמַּחֲשָׁבָה עוֹשִׂים מַעֲשֶׂה, וּמוֹשְׁכִים מְשִׁיכָה בְּכָל מַה שֶּׁצָּרִיךְ.</p>"],[9522011320,"<p>וַיֵּלֶךָ רְאוּבֵן בִּימֵי קְצִיר חִטִּים וַיִּמְצָא דוּדָאִים בַּשָּׂדֶה. רַבִּי יִצְחָק פָּתַח וְאָמַר, (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךְ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ בְּכַמָּה מְקוֹמוֹת. אֶלָּא מִי יָכוֹל לִמְנוֹת אֶת מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִנֵּה כַּמָּה צְבָאוֹת וּמַחֲנוֹת מְשֻׁנִּים זֶה מִזֶּה שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְכֻלָּם בְּפַעַם אַחַת, כְּמוֹ פַּטִּישׁ שֶׁמּוֹצִיא זִיקִים לְכָל הַצְּדָדִים בְּפַעַם אַחַת, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא כַּמָּה מִינִים וּמַחֲנוֹת מְשֻׁנִּים זֶה מִזֶּה שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְכֻלָּם בְּפַעַם אַחַת.</p>\n<p>בֹּא רְאֵה, בְּדִבּוּר וּבְרוּחַ יַחַד נַעֲשָׂה הָעוֹלָם, שֶׁכָּתוּב בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ וּבְרוּחַ פִּיו כָּל צְבָאָם. בִּדְבַר ה' - זֶה הַדִּבּוּר. וּבְרוּחַ פִּיו - זוֹ הָרוּחַ. זֶה בְּלִי זֶה לֹא הוֹלֵךְ, וְנִכְלָלִים זֶה עִם זֶה וְיוֹצְאִים מֵהֶם כַּמָּה צְבָאוֹת לַצְּבָאוֹת, וּמַחֲנוֹת לַמַּחֲנוֹת, וְהַכֹּל בְּפַעַם אַחַת.</p>\n<p>בֹּא רְאֵה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָמוֹת, הוֹצִיא אוֹר נִסְתָּר אֶחָד, שֶׁמֵּהָאוֹר הַהוּא יוֹצְאִים וּמְאִירִים כָּל אוֹתָם הָאוֹרוֹת שֶׁהִתְגַּלּוּ, וּמֵאוֹתוֹ הָאוֹר יוֹצְאִים וְהִתְפַּשְּׁטוּ וְנַעֲשׂוּ שְׁאָר הָאוֹרוֹת, וְהוּא הָעוֹלָם הָעֶלְיוֹן.</p>\n<p>וְעוֹד, הָאוֹר הָעֶלְיוֹן הַזֶּה הִתְפַּשֵּׁט וְעָשָׂה אֻמָּן, אוֹר שֶׁאֵינוֹ מֵאִיר, וְעָשָׂה אֶת הָעוֹלָם הַתַּחְתּוֹן. וּמִשּׁוּם שֶׁהוּא אוֹר שֶׁלֹּא מֵאִיר, רוֹצֶה לְהִתְקַשֵּׁר לְמַעְלָה, רוֹצֶה לְהִתְקַשֵּׁר לְמַטָּה. וּבַקֶּשֶׁר שֶׁלְּמַטָּה נִקְשָׁר לְהָאִיר בַּקֶּשֶׁר שֶׁלְּמַעְלָה.</p>\n<p>וְהָאוֹר הַזֶּה שֶׁאֵינוֹ מֵאִיר בַּקֶּשֶׁר שֶׁלְּמַעְלָה, מוֹצִיא אֶת כָּל הַחֲיָלוֹת וְהַמַּחֲנוֹת לְמִינִים רַבִּים. זֶהוּ שֶׁכָּתוּב מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ וְגוֹ'.</p>\n<p>וְכָל מַה שֶּׁבָּאָרֶץ כָּךְ גַּם לְמַעְלָה, וְאֵין לְךְ דָּבָר קָטָן בָּעוֹלָם הַזֶּה שֶׁלֹּא תָלוּי בְּדָבָר אַחֵר עֶלְיוֹן שֶׁהִתְמַנָּה עָלָיו לְמַעְלָה. מִשּׁוּם שֶׁכְּשֶׁמִּתְעוֹרֵר זֶה שֶׁלְּמַטָּה, מִתְעוֹרֵר אוֹתוֹ שֶׁהִתְמַנָּה עָלָיו לְמַעְלָה, שֶׁהַכֹּל נֶאֱחָז זֶה עִם זֶה.</p>\n<p>בֹּא רְאֵה, כָּתוּב תְּנִי נָא לִי מִדּוּדָאֵי בְּנֵךְ. לֹא הַדּוּדָאִים הֵם שֶׁיִּלְּדוּ אֶת רָחֵל, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלְגֵּל אֶת הַדָּבָר עַל יְדֵי אוֹתָם דּוּדָאִים כְּדֵי שֶׁיֵּצֵא יִשָּׂשכָר, שֶׁאוֹחֵז בַּתּוֹרָה יוֹתֵר מִכָּל הַשְּׁבָטִים, מִשּׁוּם שֶׁהֲרֵי רָחֵל הָאֲחוּזָה בְּיַעֲקֹב לֹא הִשְׁאִירָה אוֹתוֹ לְלֵאָה. זֶהוּ שֶׁכָּתוּב הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, וְכָתוּב לָכֵן יִשְׁכַּב עִמָּךְ הַלַּיְלָה תַּחַת דּוּדָאֵי בְנֵךְ.</p>\n<p>הֵם גָּרְמוּ שֶׁיֵּצֵא יִשָּׂשכָר לָעוֹלָם מִשּׁוּם שֶׁמַּעֲלֶה הָרֵיחַ שֶׁל הַתּוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב הַדּוּדָאִים נָתְנוּ רֵיחַ וְכוּ', וְכָתוּב וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא, הוּא וַדַּאי, וַהֲרֵי פֵּרְשׁוּהָ שֶׁהָעוֹלָם הָעֶלְיוֹן הוּא שֶׁנִּסְתָּר וְלֹא נִגְלֶה, מִשּׁוּם שֶׁהֲרֵי הַתּוֹרָה יוֹצֵאת מֵהָעוֹלָם הָעֶלְיוֹן.</p>\n<p>וּבְכָל מָקוֹם הָעוֹלָם הָעֶלְיוֹן הוּא שֶׁלֹּא הִתְגַּלָּה, וַהֲרֵי נֶאֱמַר וְעָבַד הַלֵּוִי הוּא, כְּדֵי לְהַמְשִׁיךְ מִמֶּנּוּ בְּרָכוֹת לַכֹּל, וְיִשָּׂשכָר נֶאֱחָז בּוֹ, וְעַל כָּךְ קוֹרְאִים עֵץ הַחַיִּים, הָעֵץ שֶׁלְּאוֹתָם הַחַיִּים הָעֶלְיוֹנִים שֶׁנִּקְרָא הוּא וְלֹא אַתָּה.</p>\n<p>וְאִם תֹּאמַר שֶׁהַדּוּדָאִים הַלָּלוּ פָּתְחוּ אֶת מֵעֶיהָ שֶׁל רָחֵל - לֹא, שֶׁהִנֵּה כָּתוּב וַיִּשְׁמַע אֵלֶיהָ אֱלֹהִים וַיִּפְתַּח אֶת רַחְמָהּ. הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא דָבָר אַחֵר. מִשּׁוּם שֶׁאוֹתָם הַדּוּדָאִים, אַף עַל פִּי שֶׁכֹּחָם לְמַעְלָה, בְּאוֹתוֹ הַכֹּחַ שֶׁלָּהֶם לֹא מִתְמַנֶּה פְּקִידַת הַבָּנִים, שֶׁהֲרֵי הַבָּנִים תְּלוּיִים בְּמַזָּל, וְלֹא בְּדָבָר אַחֵר.</p>\n<p>וְאִם תֹּאמַר שֶׁהִנֵּה הֵם נִבְרְאוּ לְחִנָּם - לֹא, שֶׁהֲרֵי אֲפִלּוּ לַדָּבָר הַזֶּה הֵם סִיּוּעַ לְאוֹתָם שֶׁמִּתְעַכְּבִים, וְאֵינָם עֲקָרוֹת, וְלֹא נִגְזָר עֲלֵיהֶם אֶלָּא בְּמַזָּל.</p>\n<p>וַיֵּלֶךָ רְאוּבֵן בִּימֵי קְצִיר חִטִּים וַיִּמְצָא דוּדָאִים בַּשָּׂדֶה וְגוֹ'. שָׁנִינוּ, כּוֹס שֶׁל בְּרָכָה אֵין מִתְבָּרֶכֶת אֶלָּא בְּצַד יָמִין, וּמִשּׁוּם כָּךְ, בְּעוֹד שֶׁמִּתְעוֹרֵר הַיָּמִין לְכוֹס שֶׁל בְּרָכָה, הַשְּׂמֹאל לֹא תְסַיַּע לְשָׁם, שֶׁהֲרֵי הַיָּמִין מוֹצֵא עִלָּה בַּכּוֹס הַהִיא לְעוֹרֵר כְּלַפֵּי הָעוֹלָם הָעֶלְיוֹן.</p>\n<p>וְהַסֵּתֶר הַזֶּה, וַיֵּלֶךְ רְאוּבֵן, זֶה צַד הַדָּרוֹם, מִשּׁוּם כָּךְ דִּגְלוֹ בַּדָּרוֹם, שֶׁהוּא רֹאשׁ לִשְׁנֵים עָשָׂר הַתְּחוּמִים, וּתְשׁוּקָתוֹ שֶׁל צַד הַדָּרוֹם לִמְצֹא עִלָּה וְתִקְרֹבֶת לַגְּבִירָה לְבָרֵךְ אוֹתָהּ.</p>\n<p>מַה כָּתוּב? וַיִּמְצָא דוּדָאִים בַּשָּׂדֶה. הָלַךְ לְחַפֵּשׂ בְּכָל אוֹתָם הַגְּנָזִים שֶׁלָּהּ, וּמָצָא בַּשָּׂדֶה הַזּוֹ אוֹתָם הַדּוּדָאִים, וַעֲלֵיהֶם נֶאֱמַר הַדּוּדָאִים נָתְנוּ רֵיחַ, וְאוֹתָם שְׁנֵי כְרוּבִים שֶׁהֵם הַתִּקּוּנִים שֶׁלָּהּ, לְהָעִיר הִתְעוֹרְרוּת לְמַעְלָה, שֶׁהֲרֵי בְּכָל אוֹתָם הַתִּקּוּנִים שֶׁל הַשָּׂדֶה הַזּוֹ אֵין תִּקּוּן שֶׁיְּעוֹרֵר כְּלַפֵּי מַעְלָה, רַק הַכְּרוּבִים.</p>\n<p>מָתַי צַד הַדָּרוֹם מִתְעוֹרֵר אֵלֶיהָ לִמְצֹא עִלָּה לְבָרֵךְ אוֹתָהּ? בִּימֵי קְצִיר חִטִּים, בִּזְמַן שֶׁמְּחַלֶּקֶת חֵלֶק שָׁלָל לְאוּכְלוּסֶיהָ, וְכָל קוֹצְרֵי הַשָּׂדֶה. מִיָּד - וַיָּבֵא אֹתָם אֶל לֵאָה אִמּוֹ. מַעֲלֶה רֵיחַ וְהִתְעוֹרְרוּתָם לָעוֹלָם הָעֶלְיוֹן, הָעוֹלָם הַנִּכְסֶה, מִשּׁוּם שֶׁמֵּעִיר (שיעורר) בְּרָכוֹת לָעוֹלָם הַתַּחְתּוֹן.</p>\n<p>וְכַאֲשֶׁר מִתְבָּרֶכֶת, אוֹתָם הַדּוּדָאִים לוֹקְחִים וְנוֹתְנִים לְכָל הָעוֹלָמוֹת, שֶׁכָּתוּב הַדּוּדָאִים נָתְנוּ רֵיחַ וְעַל פְּתָחֵינוּ כָּל מְגָדִים. כַּאֲשֶׁר הֵם נָתְנוּ רֵיחַ, אוֹתוֹ הָרֵיחַ לוֹקֵחַ אוֹתוֹ צַד הַדָּרוֹם לְהִתְעוֹרֵר לָעוֹלָם הָעֶלְיוֹן. מִיָּד - עַל פְּתָחֵינוּ כָּל מְגָדִים, וְכָל טוּב לֹא חָסֵר (הכל) מֵהָעוֹלָם.</p>\n<p>הָעוֹלָם הַתַּחְתּוֹן לֹא מִתְעוֹרֵר לָעוֹלָם הָעֶלְיוֹן, אֶלָּא כְּשֶׁאוֹתָם דּוּדָאִים נוֹתְנִים רֵיחַ לַיָּמִין. כֵּיוָן שֶׁהֵם נוֹתְנִים רֵיחַ לַיָּמִין, וְהַיָּמִין מִתְעוֹרֵר לָעוֹלָם הָעֶלְיוֹן, מִיָּד הָעוֹלָם הַתַּחְתּוֹן מִתְעוֹרֵר לִשְׁאֹל מַה שֶּׁצָּרִיךְ. מַה כָּתוּב? וַתֹּאמֶר רָחֵל אֶל לֵאָה תְּנִי נָא לִי מִדּוּדָאֵי בְּנֵךְ. תֵּן לִי בְּרָכוֹת מֵאוֹתָהּ הַהִתְעוֹרְרוּת שֶׁל אוֹתָם דּוּדָאִים שֶׁמִּתְעוֹרֵר לְצַד הַיָּמִין.</p>\n<p>אָז הָעוֹלָם הָעֶלְיוֹן בְּשִׂמְחָה, בְּשַׁעֲשׁוּעַ, מֵשִׁיב אֵלֶיהָ, וְאוֹמֶרֶת הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, כְּאֵם אֶל בִּתָּהּ. וְאִם כָּךְ, בַּעְלָהּ שֶׁל הָעוֹלָם הָעֶלְיוֹן הוּא יַעֲקֹב? לֹא כָּךְ, אֶלָּא תְּשׁוּקַת הָאָב תָּמִיד אֵינָהּ אֶלָּא כְּלַפֵּי הַבַּת הַזּוֹ, (שהיא) שֶׁהַבַּת הַזּוֹ אַהֲבָתוֹ אֵלֶיהָ תָּמִיד, מִשּׁוּם שֶׁהִיא בַּת יְחִידָה בֵּין שִׁשָּׁה בָנִים, וּלְכָל אוֹתָם שֵׁשֶׁת הַבָּנִים חִלֵּק לָהֶם חֲלָקִים וְאוֹצָרוֹת וּמַתָּנוֹת, וְלָהּ לֹא חִלֵּק, וְאֵין לָהּ יְרֻשָּׁה כְּלוּם, וְעַל כָּל זֶה הוּא מַשְׁגִּיחַ בָּהּ בִּתְשׁוּקָה וְאַהֲבָה יוֹתֵר מִן הַכֹּל.</p>\n<p>בָּאַהֲבָה שֶׁלּוֹ הוּא קוֹרֵא לָהּ בַּת. לֹא הִסְפִּיק לוֹ זֶה, וְקָרָא לָהּ אָחוֹת. לֹא הִסְפִּיק לוֹ זֶה, קָרָא לָהּ אֵם בְּשֵׁם אִמּוֹ. לֹא הִסְפִּיק לוֹ זֶה, קָרָא לָהּ בִּשְׁמוֹ, שֶׁכָּתוּב וְהַחָכְמָה מֵאַיִן תִּמָּצֵא, חָכְמָה וַדַּאי. וְעַל כֵּן הָעוֹלָם הָעֶלְיוֹן אוֹמֶרֶת לָהּ, הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, שֶׁכָּל אַהֲבָתוֹ נִמְשְׁכָה לָךְ אֵלַיִךְ וְעַל זֶה, בְּשַׁעֲשׁוּעַ וְאַהֲבָה הָאֵם אֶל הַבַּת.</p>\n<p>מַה הִיא מְשִׁיבָה? לָכֵן יִשְׁכַּב עִמָּךְ הַלַּיְלָה. בְּכָל מָקוֹם לָכֵן הִיא שְׁבוּעָה. יִשְׁכַּב, מַה זֶּה יִשְׁכַּב? אֶלָּא שְׁכִיבָה בְּכָל מָקוֹם הִיא תִקּוּן הַנְּקֵבָה לַזָּכָר לְהַכְנִיס בָּהּ צִיּוּר שֶׁל כָּל הָאוֹתִיּוֹת. וְזֶהוּ יִשְׁכַּב, י\"ש כ\"ב. י\"ש זֶהוּ הָעוֹלָם הָעֶלְיוֹן, (כ\"ב סוד) הַסּוֹד שֶׁל הַתּוֹרָה, נְקֻדָּה טְמִירָה שֶׁמִּתְעוֹרְרִים אֵלֶיהָ כ\"ב אוֹתִיּוֹת. וְזֶהוּ יִשְׁכַּ\"ב. י\"ש - הָעוֹלָם הַבָּא, שֶׁכָּתוּב (משלי א) לְהַנְחִיל אוֹהֲבַי יֵשׁ. כ\"ב - נְקֻדָּה עֶלְיוֹנָה שֶׁמַּכְנִיסָה כָּל כ\"ב הָאוֹתִיּוֹת, הַסּוֹד שֶׁל כָּל הַתּוֹרָה.</p>\n<p>וְזֶהוּ יִשְׁכַּב. לֹא כָתוּב יִשְׁכַּב עִמָּךְ יַעֲקֹב, אֶלָּא יִשְׁכַּב עִמָּךְ, אוֹתוֹ הַטָּמִיר שֶׁרָאוּי לְהִתְעוֹרֵר אֵלַיִךְ, וְהַכֹּל בַּהִתְעוֹרְרוּת שֶׁל אוֹתָם (שכלם) דּוּדָאִים, וְהַכֹּל כָּתוּב בְּאַהֲבָה.</p>\n<p>וַיָּבֹא יַעֲקֹב מִן הַשָּׂדֶה בָּעֶרֶב. וַיָּבֹא יַעֲקֹב - זוֹ תִּפְאֶרֶת הַקְּדוֹשָׁה, מֵאוֹתָהּ הַשָּׂדֶה שֶׁלּוֹקַחַת אֶת כָּל הַבְּרָכוֹת, שֶׁכָּתוּב בּוֹ אֲשֶׁר בֵּרֲכוֹ ה'. בָּעֶרֶב, לָמָּה בָּעֶרֶב? אֶלָּא בָּעֶרֶב שֶׁכָּתוּב (בראשית כד) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עָרֶב. בִּזְמַן שֶׁהִתְעוֹרֵר יִצְחָק אָבִיו לַשָּׂדֶה הַזּוֹ וְלָקַח אוֹתוֹ, שֶׁהֲרֵי יִצְחָק לֹא מִתְעוֹרֵר לַשָּׂדֶה הַזּוֹ. כֵּיוָן שֶׁהִסְתַּלֵּק יַעֲקֹב מִשָּׁם בָּעֶרֶב, הִשְׁאִיר אֶת הַשָּׂדֶה הַזּוֹ לְיִצְחָק אָבִיו, וְהוּא עָלָה בְּאוֹתוֹ הַזְּמַן לְמַעְלָה.</p>\n<p>מַה כָּתוּב? וַתֵּצֵא לֵאָה לִקְרָאתוֹ. הָאֵם הָעֶלְיוֹנָה, לַבֵּן הַיָּחִיד. וַתֹּאמֶר אֵלַי תָּבוֹא, תַּחַת כְּנָפַי, לְבָרֵךְ אוֹתְךְ וּלְהַרְווֹת אוֹתְךְ בְּתַפְנוּקִים וְעִדּוּנִים עֶלְיוֹנִים. הִנֵּה עֵת רָצוֹן וְעֹנֶג לָתֵת לְךְ נַחַת רוּחַ עֶלְיוֹנָה לְאוֹתָהּ הַשָּׂדֶה טֶרֶם שֶׁיִּשָּׂרֵף בַּחֹזֶק שֶׁל יִצְחָק.</p>\n<p>כֵּיוָן שֶׁלָּקְחָה אֶת יַעֲקֹב תַּחַת כְּנָפֶיהָ, אָז וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא. הוּא - שֶׁנִּסְתָּר מִן הַכֹּל. הוּא - שֶׁכָּל הַבְּרָכוֹת וְכָל הַקְּדֻשּׁוֹת יוֹצְאוֹת מִשָּׁם. לֹא כָתוּב יַעֲקֹב, אֶלָּא הוּא, מִי שֶׁרָאוּי לְהִתְעוֹרֵר אֵלֶיהָ.</p>\n<p>וְטֶרֶם מְזֻמָּן אֵלֶיהָ תַּחַת כְּנָפֶיהָ, מִי שֶׁלּוֹקֵחַ אוֹתָם הַקְּדוֹשִׁים (הקדשות) וְהַבְּרָכוֹת, לֹא מִתְמַלֵּא מֵהַנְּקֻדָּה הַטְּמִירָה, הָעוֹלָם הָעֶלְיוֹן הַהוּא. וְעַל כֵּן הַדּוּדָאִים מְעוֹרְרִים הַכֹּל, וְהַכֹּל כְּמוֹ שֶׁסּוֹד עֶלְיוֹן. רְאוּבֵן, מַה זֶּה רְאוּבֵן? הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם שֵׁמוֹת בָּאָרֶץ, שֶׁכָּתוּב (תהלים מו) לְכוּ חֲזוּ מִפְעֲלוֹת ה' אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ.</p>\n<p>וַתֵּצֵא לֵאָה לִקְרָאתוֹ וַתֹּאמֶר אֵלַי תָּבוֹא וְגוֹ'. הַדָּבָר הַזֶּה הוּא חֻצְפָּה? אֵינוֹ כָּךְ, אֶלָּא מִכָּאן לָמַדְנוּ עַנְוְתָנוּתָהּ שֶׁל לֵאָה, שֶׁלֹּא אָמְרָה דָּבָר לִפְנֵי אֲחוֹתָהּ, וְהִיא הִקְדִּימָה לַדֶּרֶךְ וְאָמְרָה לוֹ בַּחֲשַׁאי וְהוֹדִיעָה לוֹ, שֶׁהֲרֵי זֶה הָיָה בִּרְשׁוּת רָחֵל, שֶׁכָּתוּב כִּי שָׂכֹר שְׂכַרְתִּיךְ. מֵרָחֵל נָטְלָה רְשׁוּת. וּכְדֵי שֶׁלֹּא יֵרַע בְּעֵינֵי רָחֵל, אָמְרָה לוֹ בַּחוּץ, וְלֹא בַּבַּיִת.</p>\n<p>וְלֹא עוֹד, אֶלָּא בַּפֶּתַח שֶׁל מִשְׁכַּן לֵאָה (לחוץ) יָצְאָה הַחוּצָה, וְהִכְנִיסָה אֶת יַעֲקֹב בַּפֶּתַח שֶׁבַּחוּץ טֶרֶם שֶׁיִּכָּנֵס לְמִשְׁכַּן רָחֵל. מָה הַטַּעַם? כְּדֵי שֶׁלֹּא תֹאמַר דָּבָר לִפְנֵי רָחֵל, וְלֹא תִתְחַצֵּף לִפְנֵי אֲחוֹתָהּ. וְלֹא עוֹד, אֶלָּא אָמְרָה לֵאָה, אִם יִכָּנֵס יַעֲקֹב לְמִשְׁכַּן רָחֵל, אֵינוֹ דִין לְהוֹצִיאוֹ מִשָּׁם, מִשּׁוּם כָּךְ הִקְדִּימָה לוֹ בַּחוּץ.</p>\n<p>וְכָל זֶה לָמָּה? אֶלָּא שֶׁרוּחַ הַקֹּדֶשׁ הִתְעוֹרְרָה בְּלֵאָה, וְיָדְעָה שֶׁכָּל הַשְּׁבָטִים הָעֶלְיוֹנִים הַלָּלוּ, כֻּלָּם קְדוֹשִׁים, יֵצְאוּ מִמֶּנָּה, וְדָחֲקָה הַשָּׁעָה בַּחֲבִיבוּת לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וּמִשּׁוּם כָּךְ קָרְאָה לָהֶם שֵׁמוֹת בְּסוֹד הַחָכְמָה.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, בְּכָל פַּעַם (שאנו) הוֹלְכִים בַּדֶּרֶךְ וְעוֹסְקִים בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַרְחִישׁ לָנוּ נִסִּים, וְכָעֵת הַדֶּרֶךְ הַזּוֹ אֲרֻכָּה לָנוּ, נִתְעַסֵּק בַּתּוֹרָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְחַבֵּר עִמָּנוּ.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (שמות יב) בָּרִאשּן בְּאַרְבָּעָה עָשָׂר יוֹם לַחֹדֶשׁ בָּעֶרֶב תֹּאכְלוּ מַצּת, וְכָתוּב (דברים טז) שִׁבְעַת יָמִים תֹּאכַל עָלָיו מַצּוֹת לֶחֶם עֹנִי. לֶחֶם עָנִי כָּתוּב. בַּדָּבָר הַזֶּה הִתְעוֹרְרוּ בוֹ הַחֲבֵרִים. אֲבָל בּא רְאֵה, כְּשֶׁהָיוּ יִשְׂרָאֵל בְּמִצְרַיִם, הָיוּ בִּרְשׁוּת אַחֶרֶת. כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְקָרֵב אוֹתָם אֵלָיו, נָתַן לָהֶם מָקוֹם שֶׁל לֶחֶם עֹנִי, לֶחֶם עָנִי. מִי הֶעָנִי? זֶה דָּוִד הַמֶּלֶךְ, שֶׁכָּתוּב בּוֹ (תהלים פז) כִּי עָנִי וְאֶבְיוֹן אָנִי.</p>\n<p>וְלֶחֶם עֹנִי הַזֶּה נִקְרָא מַצָּה, נְקֵבָה בְּלִי זָכָר הִיא עֹנִי. הִתְקָרְבוּ לַמַּצָּה בַּהַתְחָלָה. כֵּיוָן שֶׁקֵּרְבוּ אוֹתָם יוֹתֵר, הִכְנִיס אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בִּדְרָגוֹת אֲחֵרוֹת, וְהִתְחַבֵּר זָכָר עִם נְקֵבָה. וְאָז, כְּשֶׁמַּצָּה מִתְחַבֶּרֶת בַּזָּכָר, נִקְרָא מִצְוָה, בְּתוֹסֶפֶת וָא\"ו. זֶהוּ שֶׁכָּתוּב (דברים ל) כִּי הַמִּצְוָה הַ את. מִשּׁוּם כָּךְ מַצָּה בָּרִאשׁוֹנָה, וְאַחַר כָּךְ מִצְוָה.</p>\n<p>בְּעוֹדָם הוֹלְכִים שָׁמְעוּ קוֹל אֶחָד שֶׁאוֹמֵר: גְּדוּד שֶׁל רוֹצְחִים אוֹרְבִים בַּדֶּרֶךְ, סְטוּ לְמַעְלָה, אַל תֵּרְדוּ לַטִּירָה חַסְרַת הַגַּג שֶׁלְּמַטָּה. אָמַר רַבִּי יוֹסֵי, מִזֶּה נִשְׁמָע שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לִשְׁמֹר אֶת דְּרָכֵינוּ. עָלוּ לְמַעְלָה וְנִכְנְסוּ לְהַר אֶחָד, בֵּין סְלָעִים חֲזָקִים. אָמְרוּ, הוֹאִיל וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בַּדֶּרֶךְ הַזּוֹ, נִרְאֶה דָבָר, אוֹ יִתְרַחֵשׁ לָנוּ נֵס.</p>\n<p>הָלְכוּ, יָשְׁבוּ עַל בְּקִיעֵי הַסֶּלַע. עָלָה לָהֶם אִישׁ אֶחָד. תָּמְהוּ. אָמַר רַבִּי יוֹסֵי, מִי אַתָּה? אָמַר, אֲנִי מֵאַנְשֵׁי אַרְקָא. אָמַר לוֹ, וְשָׁם יֵשׁ בְּנֵי אָדָם? אָמַר, כֵּן, וְזוֹרְעִים וְקוֹצְרִים, מֵהֶם בְּמַרְאֶה אַחֵר מְשֻׁנִּים מִמֶּנִּי, וְעָלִיתִי אֲלֵיכֶם לְהַכִּיר מִכֶּם, מַה שְּׁמָהּ שֶׁל הָאָרֶץ שֶׁאַתֶּם בָּהּ?</p>\n<p>אָמַר לוֹ, אֶרֶץ, מִשּׁוּם שֶׁכָּאן שׁוֹרָה אֶרֶץ הַחַיִּים, שֶׁכָּתוּב (איוב כח) אֶרֶץ מִמֶּנָּה יֵצֵא לָחֶם. מִזּוֹ יֵצֵא לָחֶם? בִּשְׁאָר הָאָרֶץ לֹא יֵצֵא לֶחֶם, וְאִם יוֹצֵא, לֹא מִשִּׁבְעַת הַמִּינִים. בֵּינְתַיִם נִכְנַס לִמְקוֹמוֹ. תָּמְהוּ. אָמְרוּ, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְעוֹרֵר אוֹתָנוּ בְּאֵיזֶה דָבָר.</p>\n<p>אָמַר רַבִּי חִיָּיא, וַדַּאי עַל הַפָּסוּק הַזֶּה שֶׁאָמַרְתָּ, זָכַרְתִּי שֶׁלָּמַדְתִּי מִסָּבִי דָּבָר אֶחָד עֶלְיוֹן בְּפֶסַח, שֶׁנָּתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל הַלֶּחֶם הַזֶּה מֵאֶרֶץ הַחַיִּים, וְאַחַר כָּךְ לֶחֶם מִן הַשָּׁמַיִם, הַלֶּחֶם הַזֶּה, וְהִנֵּה בֵּאַרְנוּ אֶת הַדָּבָר.</p>\n<p>עוֹד הָיָה אוֹמֵר, שֶׁאָדָם, כְּשֶׁיּוֹצֵא לָעוֹלָם הַזֶּה, לֹא יוֹדֵעַ דָּבָר עַד שֶׁטּוֹעֵם לֶחֶם. כֵּיוָן שֶׁאוֹכֵל לֶחֶם, מִתְעוֹרֵר לָדַעַת וּלְהַכִּיר. כָּךְ כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, לֹא הָיוּ יוֹדְעִים דָּבָר, עַד שֶׁהִטְעִים לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לֶחֶם מִן הָאָרֶץ הַזּוֹ, שֶׁכָּתוּב אֶרֶץ מִמֶּנָּה יֵצֵא לָחֶם, וְאָז נִכְנְסוּ יִשְׂרָאֵל לָדַעַת וּלְהַכִּיר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְתִינוֹק לֹא יוֹדֵעַ וְלֹא מַכִּיר עַד שֶׁטּוֹעֵם לֶחֶם שֶׁל הָעוֹלָם הַזֶּה.</p>\n<p>יִשְׂרָאֵל לֹא יָדְעוּ וְלֹא הִכִּירוּ בַּדְּבָרִים שֶׁלְּמַעְלָה עַד שֶׁאָכְלוּ לֶחֶם עֶלְיוֹן, וְאָז יָדְעוּ וְהִכִּירוּ אֶת אוֹתוֹ מָקוֹם, וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּשְׂרָאֵל יֵדְעוּ יוֹתֵר בְּאוֹתוֹ מָקוֹם שֶׁרָאוּי לָאָרֶץ הַזּוֹ, וְלֹא יָכְלוּ, עַד שֶׁטָּעֲמוּ לֶחֶם מֵאוֹתוֹ הַמָּקוֹם, וּמִי הוּא? שָׁמַיִם, שֶׁכָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם, וְאָז יָדְעוּ וְהִסְתַּכְּלוּ לְאוֹתוֹ מָקוֹם. וְעַד שֶׁאָכְלוּ לֶחֶם מֵאוֹתוֹ מָקוֹם, (ועד שלא אכלו לחם באלו המקומות) לֹא יָדְעוּ דָבָר וְלֹא הִכִּירוּ.</p>\n<p>בָּא רַבִּי יוֹסֵי וּנְשָׁקוֹ. אָמַר, וַדַּאי עַל זֶה הֵעִיר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּזֶה, וְעַל כֵּן הָרֵאשִׁית שֶׁל יִשְׂרָאֵל לָדַעַת הָיָה הַלֶּחֶם. קָמוּ וְהָלְכוּ. בְּעוֹדָם הוֹלְכִים רָאוּ שְׁנֵי פֵּרוֹת, אֶחָד זָכָר וְאֶחָד נְקֵבָה. אָמַר רַבִּי יוֹסֵי, אֵין לָנוּ דָּבָר בָּעוֹלָם שֶׁאֵינוֹ זָכָר וּנְקֵבָה, וְכָל מַה שֶּׁבָּאָרֶץ - כָּךְ גַּם בַּיָּם.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, וַיָּבֹא יַעֲקֹב מִן הַשָּׂדֶה בָּעֶרֶב וַתֵּצֵא לֵאָה לִקְרָאתוֹ וְגוֹ'. וַתֵּצֵא לֵאָה לִקְרָאתוֹ, מִנַּיִן יָדְעָה? הֲרֵי אָמְרוּ שֶׁגָּעָה הַחֲמוֹר, וְלֵאָה יָדְעָה וְיָצְאָה אֵלָיו, וְגָרַם לוֹ שֶׁיֵּצֵא מִמֶּנָּה יִשָּׂשכָר. זֶהוּ שֶׁכָּתוּב יִשָּׂשכָר חֲמוֹר גָּרֶם, אַל תִּקְרֵי גָּרֶם אֶלָּא גָרַם, שֶׁהַחֲמוֹר גָּרַם לוֹ. אָמְרָה לֵאָה: וַדַּאי יָדַעתִּי שֶׁאִם יִכָּנֵס יַעֲקֹב לְמִשְׁכַּן רָחֵל, אֵין לִי לְהוֹצִיא אוֹתוֹ, אֶלָּא אֲחַכֶּה לוֹ כָּאן וְיִכָּנֵס לְמִשְׁכָּנִי.</p>\n<p>כִּי שָׂכֹר שְׂכַרְתִּיךְ בְּדוּדָאֵי בְּנִי, מַה זֶּה בְּדוּדָאֵי בְּנִי? מִשּׁוּם שֶׁנּוֹחַ לְיַעֲקֹב עַל זֶה, שֶׁאֵלּוּ מְסַיְּעִים לְהוֹלִיד. וְיַעֲקֹב הָיָה יוֹדֵעַ שֶׁהַדָּבָר לֹא עוֹמֵד בַּדּוּדָאִים, אֶלָּא לְמַעְלָה.</p>\n<p>פָּתַח וְאָמַר, מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת אֵם הַבָּנִים שְׂמֵחָה הַלְלוּיָהּ. אָמַר רַבִּי חִיָּיא, רוּחַ הַקֹּדֶשׁ אוֹמֶרֶת: מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת - זוֹ רָחֵל. אֵם הַבָּנִים שְׂמֵחָה - זוֹ לֵאָה. מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת - זֶה הָעוֹלָם הַתַּחְתּוֹן. אֵם הַבָּנִים שְׂמֵחָה (הללויה) - זֶה הָעוֹלָם הָעֶלְיוֹן. מִשּׁוּם כָּךְ הַלְלוּיָהּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּל הַשְּׁבָטִים הַלָּלוּ הֵם תִּקּוּנִים שֶׁלְּמַטָּה, וְכֻלָּם כְּמוֹ שֶׁלְּמַעְלָה. בּא רְאֵה, כִּי שָׂכֹר שְׂכַרְתִּיךְ - לָקַחַת מִמֶּנּוּ הַגּוּף, וּמִי הוּא? תּוֹרָה. שָׂכֹר שְׂכַרְתִּיךְ - לְךְ, לְגוּפְךְ מַמָּשׁ. שָׂכֹר שְׂכַרְתִּיךְ - לְהוֹלִיד אֶת דְּמוּתְךְ.</p>\n<p>מִכָּאן מִי שֶׁעוֹסֵק בַּתּוֹרָה, יוֹרֵשׁ אֶת הָעוֹלָם הַבָּא וְיוֹרֵשׁ אֶת נַחֲלַת יַעֲקֹב. יוֹרֵשׁ הָעוֹלָם הַבָּא, שֶׁכָּתוּב יִשָּׂשכָר, יֵשׁ שָׂכָר, (ירמיה לא) כִּי יֵשׁ שָׂכָר לִפְעֻלָּתֵךְ, וְכָתוּב (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאֹצְרֹתֵיהֶם אֲמַלֵּא.</p>\n<p>כִּי יָלַדְתִּי לוֹ שִׁשָּׁה בָנִים. אָמַר רַבִּי חִזְקִיָּה, אֵלּוּ מַעְלָה וּמַטָּה וְאַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם. וּמִי שֶׁמַּאֲרִיךְ בְּאֶחָד, צָרִיךְ לוֹ לְהַמְלִיךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה וּלְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְהַיְינוּ אֶחָד.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, כָּתוּב (שיר ב) עַל הָרֵי בָתֶר, וְכָתוּב (שם ח) עַל הָרֵי בְשָׂמִים. מִי הֵם הָרֵי בְשָׂמִים? אֵלּוּ שֵׁשֶׁת הַבָּנִים שֶׁל לֵאָה שֶׁכּוֹלְלִים שִׁשָּׁה אֲחֵרִים, וְהֵם שְׁנֵים עָשָׂר, וְהֵם שִׁשָּׁה, מִשּׁוּם שֶׁכָּל אֶחָד כָּלוּל בַּחֲבֵרוֹ, וְלֵאָה עֲלֵיהֶם, לְקַיֵּם (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה הַלְלוּיָהּ.</p>\n<p>וְעַל כֵּן כָּתוּב לֹא תִקַּח הָאֵם עַל הַבָּנִים, מִשּׁוּם שֶׁהוּא הָעוֹלָם הַנִּסְתָּר וְלֹא הַנִּגְלֶה, וְעַל כֵּן שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם וְאֶת הַבָּנִים תִּקַּח לָךְ, מִשּׁוּם שֶׁהוּא הָעוֹלָם שֶׁנִּסְתָּר וְלֹא הִתְגַּלָּה כְּלָל.</p>\n<p>וְאֶת הַבָּנִים תִּקַּח לָךְ, הַיְנוּ שֶׁכָּתוּב כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים וְגוֹ' וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם. וְכָל אֵלּוּ נִקְרָאִים הָרֵי בְשָׂמִים. מִכָּאן וּלְמַטָּה נִקְרְאוּ הָרֵי בָתֶר, שֶׁכָּתוּב וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים, הֶהָרִים שֶׁל הַפֵּרוּד.</p>\n<p>אָמַר רַבִּי יֵיסָא, בְּנֵי הַשְּׁפָחוֹת קָשְׁרוּ קְשָׁרִים, אַרְבָּעָה קְשָׁרִים שֶׁהִצְטָרְכוּ לְתִקּוּן. וְאָמַר רַבִּי אֶלְעָזָר, שֶׁמִּשּׁוּם כָּךְ יוֹצְאִים הַחוּצָה אוֹתָם הַקְּשָׁרִים. וְאַף עַל גַּב שֶׁכֻּלָּם אֶחָד, וּמִכָּאן וָהָלְאָה כֻּלָּם אֶחָד, בְּדֶרֶךְ יְשָׁרָה, וְעַל כֵּן כָּל הַשְּׁבָטִים עוֹלִים בְּעֵדוּת לְמַעְלָה. זֶהוּ שֶׁכָּתוּב (תהלים קכב) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם ה'.</p>"],[9522011321,"<p>וְאָמַר רַבִּי אֶלְעָזָר, כָּתוּב וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגוֹ'. מָה רָאָה יַעֲקֹב לָלֶכֶת לְדַרְכּוֹ כְּשֶׁנּוֹלַד יוֹסֵף, וְטֶרֶם שֶׁנּוֹלַד יוֹסֵף לֹא רָצָה לָלֶכֶת לְדַרְכּוֹ? אֶלָּא הִנֵּה פֵּרְשׁוּהָ, שֶׁרָאָה שֶׁנּוֹלַד שְׂטָנוֹ שֶׁל עֵשָׂו.</p>\n<p>וּבֹא וּרְאֵה, יוֹסֵף הִשְׁלִים אֶת מְקוֹמוֹ אַחֲרָיו וְיוֹסֵף זָכָה לוֹ, שֶׁנִּקְרָא צַדִּיק, וְכָאן סִיּוּם הַגּוּף. כֵּיוָן שֶׁרָאָה יַעֲקֹב שֶׁנִּשְׁלַם הַגּוּף, רָצָה הַגּוּף לָלֶכֶת לְדַרְכּוֹ, וְסִיּוּם הַגּוּף הוּא הַבְּרִית, וְעִם כָּל זֶה בִּנְיָמִין הִשְׁלִים אֶת הַחֶשְׁבּוֹן, שֶׁבּוֹ נִשְׁלְמוּ שְׁנֵים עָשָׂר.</p>\n<p>וְאִם תֹּאמַר, וְכִי לֹא הָיָה יוֹדֵעַ יַעֲקֹב שֶׁעַד עַכְשָׁו לֹא הִשְׁתַּלְּמוּ הַשְּׁבָטִים, אַף עַל גַּב שֶׁנּוֹלַד יוֹסֵף, מָה הַטַּעַם לֹא חִכָּה עַד שֶׁנּוֹלַד בִּנְיָמִין וְיִשְׁתַּלְּמוּ הַשְּׁבָטִים? אֶלָּא יַעֲקֹב עָשָׂה בְּחָכְמָה וְיָדַע הַדָּבָר. אָמַר, וַדַּאי אִם יִשְׁתַּלְּמוּ כָּאן כָּל הַשְּׁבָטִים, הִנֵּה יָדַעְתִּי שֶׁהַתִּקּוּן שֶׁל מַעְלָה שָׁרוּי עֲלֵיהֶם כָּרָאוּי, וּבָאָרֶץ הַזּוֹ לֹא צְרִיכִים שֶׁיִּשְׁתַּלְּמוּ, אֶלָּא בָּאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁכָּל שְׁנֵים עָשָׂר הַשְּׁבָטִים הֵם הַתִּקּוּן שֶׁל הָעוֹלָם הַתַּחְתּוֹן, וְכֵיוָן שֶׁנּוֹלַד בִּנְיָמִין, מֵתָה רָחֵל, וְלָקְחָה אֶת הַמָּקוֹם הָעוֹלָם הַתַּחְתּוֹן הַזֶּה לְהִתְתַּקֵּן בָּהֶם, וְעַל כֵּן לֹא נוֹלַד בִּנְיָמִין אֶלָּא בָּאָרֶץ הַקְּדוֹשָׁה. זֶהוּ שֶׁכָּתוּב וַאֲנִי בְּבֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל בְּאֶרֶץ כְּנַעַן בַּדֶּרֶךְ, וְשָׁם מֵתָה רָחֵל וְנָטְלָה אֶת הַמָּקוֹם, הָעוֹלָם הַתַּחְתּוֹן הַזֶּה, לְהִתְיַשֵּׁב בְּבַיִת שָׁלֵם. וְכָל זְמַן שֶׁרָחֵל קַיֶּמֶת, הָעוֹלָם הַתַּחְתּוֹן אֵינוֹ נִתְקָן בָּהֶם. מֵתָה רָחֵל - נָטְלָה (למעלה) הַבַּיִת בִּשְׁלֵמוּתוֹ.</p>\n<p>וְאִם תֹּאמַר, לָמָּה לֹא מֵתָה לֵאָה בְּאוֹתוֹ הַזְּמַן? אֶלָּא מִשּׁוּם שֶׁהַבַּיִת הוּא בָּעוֹלָם הַתַּחְתּוֹן (העליון), וְהַכֹּל הָיוּ מִמֶּנּוּ לְהִתְתַּקֵּן, וְלֹא מִן הָעוֹלָם הָעֶלְיוֹן (התחתון), וּמִשּׁוּם כָּךְ לֹא מֵתָה בְּאוֹתָהּ שָׁעָה. וְכָל מַעֲשֵׂי לֵאָה הֵם בְּנִסְתָּר, מִשּׁוּם שֶׁהָעוֹלָם הָעֶלְיוֹן הוּא בְּנִסְתָּר וְלֹא בְּנִגְלֶה, וּמִשּׁוּם כָּךְ לֹא נִזְכְּרָה מִיתָתָהּ שֶׁל לֵאָה כְּמִיתָתָהּ שֶׁל רָחֵל.</p>\n<p>וּבֹא וּרְאֵה שֶׁכָּךְ זֶה וַדַּאי, מִשּׁוּם שֶׁהָעוֹלָם הָעֶלְיוֹן כָּל דְּבָרָיו בְּנִסְתָּר, וְהָעוֹלָם (העליון) הַתַּחְתּוֹן כָּל דְּבָרָיו בְּנִגְלֶה, מִשּׁוּם כָּךְ נִתְכַּסְּתָה לֵאָה בִּמְעָרַת הַמַּכְפֵּלָה, וְרָחֵל בַּדֶּרֶךְ הַגְּלוּיָה. זוֹ בְּנִסְתָּר, וְזוֹ בְּגָלוּי. וּבַנִּסְתָּר הָעוֹלָם הָעֶלְיוֹן נִרְשַׁם, שֶׁכָּתוּב וַתֹּאמֶר לֵאָה בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָנוֹת, וּמִשּׁוּם כָּךְ קָרְאָה שְׁמוֹ אָשֵׁר. (משום כך כל הברכות של שני העולמות בנגלה ובנסתר, ועם כל זה).</p>\n<p>וּמִשּׁוּם כָּךְ הַכֹּל אֶחָד, שֶׁהֲרֵי הַכֹּל הוּא מִן הָעוֹלָם הָעֶלְיוֹן. כָּךְ גַּם, וּבְכָל מָקוֹם, שְׁנֵי עוֹלָמוֹת, זֶה בְּנִגְלֶה וְזֶה בְּנִסְתָּר, וְאָנוּ לֹא מְבָרְכִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא בִּשְׁנֵי עוֹלָמוֹת, שֶׁכָּתוּב בָּרוּךְ ה' אֱלֹהֵי יִשְׂרָאֵל מִן הָעוֹלָם וְעַד הָעוֹלָם. מִשּׁוּם כָּךְ לָעוֹלָם הָעֶלְיוֹן קוֹרְאִים הוּ\"א, וְלָעוֹלָם הַתַּחְתּוֹן קוֹרְאִים אַתָּ\"ה, מִשּׁוּם שֶׁהוּא בָּרוּךְ מִן הָעוֹלָם הָעֶלְיוֹן עַל יְדֵי הַצַּדִּיק. זֶהוּ שֶׁכָּתוּב בָּרוּךְ ה' מִצִּיּוֹן שֹׁכֵן יְרוּשָׁלם וְגוֹ'. וַדַּאי מִצִּיּוֹן הוּא בָּרוּךְ.</p>\n<p>בֹּא רְאֵה, כְּמוֹ כֵן ה' ה' שְׁנֵי עוֹלָמוֹת הֵם, זֶה בְּנִגְלֶה וְזֶה בְּנִסְתָּר, וְעַל כֵּן מַפְסִיק הַטַּעַם בְּתוֹכָם, וּמֵהָעוֹלָם הַזֶּה וְעַד הָעוֹלָם הַזֶּה הַכֹּל אֶחָד.</p>\n<p>וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגוֹ'. אָמַר רַבִּי יְהוּדָה, בּא רְאֵה הַשְּׁלֵמוּת שֶׁל יַעֲקֹב, שֶׁלֹּא רָצָה לָלֶכֶת אֶלָּא בִּרְשׁוּת לָבָן. וְאִם תֹּאמַר, לָמָּה לֹא הָלַךְ פַּעַם אַחֶרֶת בִּרְשׁוּתוֹ? אֶלָּא מִשּׁוּם שֶׁפָּחַד יַעֲקֹב שֶׁלֹּא יַעֲזֹב אוֹתוֹ וְיִשְׁתַּלְּמוּ שְׁנֵים עָשָׂר שְׁבָטִים בְּאֶרֶץ אַחֶרֶת, וְעַל כֵּן, כֵּיון שֶׁרָאָה שֶׁהִגִּיעָה שְׁעָתוֹ שֶׁל בִּנְיָמִין, בָּרַח, כְּמוֹ שֶׁנֶּאֱמַר וַיִּבְרַח הוּא וְכָל אֲשֶׁר לוֹ.</p>\n<p>שֶׁכֵּיוָן שֶׁנּוֹלַד בִּנְיָמִין, נִקְשְׁרָה הַשְּׁכִינָה בְּכָל הַשְּׁבָטִים וְנָטְלָה הַבַּיִת עִם כֻּלָּם. וְיַעֲקֹב הָיָה יוֹדֵעַ בְּסוֹד הַחָכְמָה, שֶׁכַּאֲשֶׁר יִשְׁתַּלְּמוּ שְׁנֵים עָשָׂר שְׁבָטִים, שֶׁהַשְּׁכִינָה תִּתְקַשֵּׁט וְתִתְקַשֵּׁר עִמָּם וְרָחֵל תָּמוּת, וְהִיא נוֹטֶלֶת אֶת הַבַּיִת.</p>\n<p>בֹּא רְאֵה, כָּךְ לָמַדְנוּ, הָעוֹלָם הַתַּחְתּוֹן נִרְאָה לְיַעֲקֹב כְּמוֹ שֶׁנִּרְאָה לְמֹשֶׁה, אֶלָּא שֶׁלֹּא יָכְלָה עַד שֶׁהָיוּ שְׁנֵים עָשָׂר שְׁבָטִים בַּבַּיִת לְהִתְקַשֵּׁר עִמָּם, וְאָז נִטְהֲרָה (נדחתה) רָחֵל, וְהִיא נָטְלָה אֶת הַבַּיִת בְּכָל הַשְּׁבָטִים וְהָיְתָה עִקַּר הַבַּיִת, וְאָז וַדַּאי מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת.</p>\n<p>אָמַר יַעֲקֹב, הִנֵּה הִגִּיעַ הַזְּמַן שֶׁנִּשְׁלְמוּ שְׁנֵים עָשָׂר הַשְּׁבָטִים, וַדַּאי יֵרֵד הָעוֹלָם שֶׁלְּמַעְלָה לַבַּיִת לְהִתְקַשֵּׁר עִמָּם, וְהַמִּסְכֵּנָה הַ את נִדְחֵית לְפָנָיו. אִם תָּמוּת כָּאן, לֹא אֵצֵא מִכָּאן לְעוֹלָמִים. וְלֹא עוֹד, אֶלָּא בָּאָרֶץ הַזּוֹ לֹא רָאוּי לְהַשְׁלִים אֶת הַבַּיִת. מִשּׁוּם כָּךְ וַיְהִי כַּאֲשֶׁר יָלְדָה וְגוֹ', טֶרֶם יִשְׁתַּלְּמוּ הַשְּׁבָטִים.</p>\n<p>שָׁמַע רַבִּי שִׁמְעוֹן וְאָמַר, וַדַּאי יָפִים הֵם כָּל דִּבְרֵי רַבִּי יְהוּדָה, וְזֶה עוֹלֶה עַל הַכֹּל. וְאִם תֹּאמַר, לָמָּה לֹא הָלַךְ לוֹ לְדַרְכּוֹ מִיָּד? אֶלָּא כָּל זְמַן שֶׁרָחֵל לֹא הִתְעַבְּרָה מִבִּנְיָמִין, הִתְעַכֵּב שָׁם. כֵּיוָן שֶׁהִגִּיעַ הַזְּמַן שֶׁל בִּנְיָמִין, בָּרַח וְלֹא בִקֵּשׁ רְשׁוּת, כְּדֵי שֶׁלֹּא יִתְעַכֵּב שָׁם, וְיִתְחַבֵּר יַעֲקֹב בְּכָל הַשְּׁבָטִים בְּמָקוֹם (שלא) שֶׁצָּרִיךְ.</p>\n<p>רַבִּי אַבָּא פָּתַח, וַיֵּלֶךְ מֹשֶׁה וַיָּשָׁב אֶל יֶתֶר חֹתְנוֹ וְגוֹ'. בּא רְאֵה, מֹשֶׁה הָיָה רוֹעֶה אֶת צֹאן חוֹתְנוֹ, וְדִיּוּרוֹ הָיָה עִמּוֹ. וּכְשֶׁרָצָה לָלֶכֶת, לֹא הָלַךְ אֶלָּא בִּרְשׁוּתוֹ. וְיַעֲקֹב, שֶׁהָיָה שָׁלֵם, וְדִיּוּרוֹ תָּמִיד הָיָה עִם לָבָן, לָמָּה לֹא בִקֵּשׁ מִמֶּנּוּ רְשׁוּת? אֶלָּא הֲרֵי נִתְבָּאֵר שֶׁלֹּא יְגַלְגֵּל לָבָן עִמּוֹ גִּלְגּוּלִים וְיִשָּׁאֵר שָׁם, שֶׁהֲרֵי בָּרִאשׁוֹנָה אָמַר לוֹ, וּמִיָּד גִּלְגֵּל עָלָיו גִּלְגּוּלִים וְנִשְׁאַר שָׁם, וְכָעֵת פָּחַד מִמֶּנּוּ.</p>\n<p>אֲבָל יִתְרוֹ לֹא הָיָה כָּךְ כְּלַפֵּי מֹשֶׁה, מִשּׁוּם שֶׁלָּבָן הָיָה מְכַשֵּׁף, וּבְכִשּׁוּף הָיָה כָּל מַעֲשֵׂהוּ כְּלַפֵּי יַעֲקֹב, וְכָעֵת לֹא רָצָה יַעֲקֹב לְהִתְעַכֵּב שָׁם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ שׁוּב אֶל אֶרֶץ אֲבֹתֶיךְ וְגוֹ', וְעַל כֵּן</p>"],[9522011322,"<p>לֹא רָצָה לְהִתְעַכֵּב וְלַעֲזֹב אֶת מִצְוַת רִבּוֹנוֹ. בֹּא רְאֵה, כָּתוּב וַיִּזְכֹּר אֱלֹהִים אֶל רָחֵל וְגוֹ'. פָּתַח וְאָמַר, (תהלים מו) לַמְנַצֵּחַ לִבְנֵי קֹרַח עַל עֲלָמוֹת שִׁיר. בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל שֶׁהוּא סוֹד שֶׁל חָכְמָה, וְכָל הַשִּׁירִים וְהַתִּשְׁבָּחוֹת הַלָּלוּ שֶׁהָיוּ אוֹמְרִים בְּנֵי קֹרַח, כֻּלָּם מְחַדְּשִׁים הֵם אוֹתָם שִׁירִים וְתִשְׁבָּחוֹת שֶׁהָיוּ מִלְּפָנִים, וְכֵן כָּל אוֹתָם שִׁירוֹת וְתִשְׁבָּחוֹת שֶׁאָמַר דָּוִד וְכָל אוֹתָם שֶׁהָיוּ עִמּוֹ, כֻּלָּם הָיוּ בְּסוֹד עֶלְיוֹן, בְּסוֹד הַחָכְמָה.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ הָעוֹלָם הָעֶלְיוֹן, וְכָל אוֹתָם הַסְּדָרִים שֶׁסִּדְּרוּ דָּוִד וּשְׁלֹמֹה בְּנוֹ וְכָל אוֹתָם נְבִיאֵי הָאֱמֶת - כֻּלָּם סִדְּרוּ כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בֹּא רְאֵה, כְּמוֹ שֶׁיֵּשׁ מִשְׁמָרוֹת בָּאָרֶץ - כָּךְ גַּם בָּרָקִיעַ שֶׁמְּזַמְּרִים לְרִבּוֹנָם וְאוֹמְרִים תָּמִיד שִׁירָה, וְכֻלָּם עוֹמְדִים אֵלּוּ כְּנֶגֶד אֵלּוּ, וְהַכֹּל בִּסְדָרִים שֶׁל שִׁירוֹת וְתִשְׁבָּחוֹת, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>עָלָמוֹת שִׁיר, מַה זֶּה עֲלָמוֹת שִׁיר? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) שִׁשִּׁים הֵמָּה מְלָכוֹת וּשְׁמֹנִים פִּילַגְשִׁים וַעֲלָמוֹת אֵין מִסְפָּר. מַה זֶּה וַעֲלָמוֹת אֵין מִסְפָּר? כְּמוֹ שֶׁנֶּאֱמַר הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. וּמִשּׁוּם שֶׁאֵין לָהֶם חֶשְׁבּוֹן, כָּתוּב וַעֲלָמוֹת אֵין מִסְפָּר.</p>\n<p>וְכֻלָּם שׁוּרוֹת שׁוּרוֹת, מַקִּיפִים סְדָרִים, אֵלּוּ כְּנֶגֶד אֵלּוּ, לְזַמֵּר וּלְשַׁבֵּחַ אֶת רִבּוֹנָם, וְאֵלּוּ הֵם עֲלָמוֹת שִׁיר. וּמִשּׁוּם שֶׁיֵּשׁ עֲלָמוֹת שֶׁאֵין מְזַמְּרוֹת כְּמוֹ אֵלּוּ, אֵלּוּ נִקְרָאוֹת עֲלָמוֹת שִׁיר.</p>"],[9522011323,"<p>שְׁלשָה סְדָרִים נִפְרָדִים לְכָל צַד לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וּבְכָל סֵדֶר וְסֵדֶר, שֶׁהוּא לְכָל צַד, שְׁלֹשָׁה סְדָרִים אֲחֵרִים. סֵדֶר רִאשׁוֹן שֶׁלְּצַד מִזְרָח - שְׁלֹשָׁה סְדָרִים הֵם, וְהֵם תִּשְׁעָה סְדָרִים, מִשּׁוּם שֶׁכָּל סֵדֶר מֵהַשְּׁלֹשָׁה הַלָּלוּ יֵשׁ לוֹ שְׁלֹשָׁה סְדָרִים, וְנִמְצְאוּ שֶׁהֵם תִּשְׁעָה, וְכַמָּה אֲלָפִים וּרְבָבוֹת תַּחְתֵּיהֶם.</p>\n<p>תִּשְׁעַת הַסְּדָרִים הַלָּלוּ, כֻּלָּם מִתְנַהֲגִים בְּאוֹתִיּוֹת רְשׁוּמוֹת, וְכָל סֵדֶר מִסְתַּכֵּל לְאוֹתָן אוֹתִיּוֹת רְשׁוּמוֹת, (והרי בארוה וכן לכל סדר וסדר, וכלם נוסעים באותיות רשומות, ואלו עליונים מאלו, ועומדים אלו על אלו) וְכֻלָּן מִתְחַבְּרוֹת וְאוֹמְרוֹת שִׁירָה. וּכְשֶׁאוֹתָן הָאוֹתִיּוֹת פּוֹרְחוֹת לְתוֹךְ הָאֲוִיר שֶׁל הָרוּחַ (ההיא) הַמְמֻנָּה עַל הַכֹּל, אָז הֵם נוֹסְעִים, וְהַשִּׁירָה נִמְתֶּקֶת, וְאוֹת אַחַת מֻכָּה מִלְּמַטָּה, וְאוֹתָהּ אוֹת עוֹלָה וְיוֹרֶדֶת, וּשְׁתֵּי אוֹתִיּוֹת פּוֹרְחוֹת עֲלֵיהֶן. וְהָאוֹת הַזּוֹ מִלְּמַטָּה מַעֲלָה סֵדֶר מִמַּטָּה לְמַעְלָה וּמִתְחַבֶּרֶת עִמָּם, וְנַעֲשׂוֹת שָׁלֹשׁ אוֹתִיּוֹת, כֻּלָּם לְפִי הָאוֹתִיּוֹת יה\"ו, שֶׁהֵן שָׁלֹשׁ בְּתוֹךְ הָאַסְפַּקְלַרְיָה הַמְּאִירָה. מֵאֵלּוּ נִפְרָדִים שְׁלֹשָׁה סְדָרִים וְאוֹתָן שְׁתֵּי הָאוֹתִיּוֹת, וְאוֹתָהּ הָאוֹת שֶׁעוֹלָה מִתְחַבֶּרֶת עִמָּהֶן, וְהֵן שָׁלֹשׁ.</p>\n<p>בֹּא רְאֵה, אוֹתָן שְׁתֵּי אוֹתִיּוֹת עֶלְיוֹנוֹת שֶׁעוֹלוֹת בָּאֲוִיר, הֵן כְּלוּלוֹת זוֹ בְּזוֹ, רַחֲמִים בְּדִין, וּמִשּׁוּם כָּךְ הֵן שְׁתַּיִם, וְהֵן מִן הָעוֹלָם הָעֶלְיוֹן, בְּסוֹד שֶׁל זָכָר. וְזוֹ שֶׁעוֹלָה וּמִתְחַבֶּרֶת עִמָּהֶן הִיא נְקֵבָה, וְנִכְלֶלֶת בִּשְׁתֵּיהֶן. כְּמוֹ שֶׁהַנְּקֵבָה נִכְלֶלֶת בִּשְׁנֵי צְדָדִים, בְּיָמִין וּבִשְׂמֹאל, וּמִתְחַבֶּרֶת עִמָּהֶם, כָּךְ גַּם הָאוֹת הַנְּקֵבָה הַזּוֹ שֶׁמִּתְחַבֶּרֶת עִם שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת, וְהֵן בִּשְׁנֵי צְדָדִים אֵלּוּ הָעֶלְיוֹנִים, וְזֶה לְמַטָּה, וְהַכֹּל הוּא אֶחָד, זָכָר וּנְקֵבָה. (חוץ) שֶׁכַּאֲשֶׁר נִבְרָא הָעוֹלָם, שֶׁאוֹתָם הָאוֹתִיּוֹת הֵן מִן הָעוֹלָם הָעֶלְיוֹן, שֶׁהֵם הוֹלִידוּ אֶת כָּל הַמַּעֲשִׂים לְמַטָּה כְּמוֹ שֶׁלָּהֶם מַמָּשׁ. וּמִשּׁוּם כָּךְ, מִי שֶׁיּוֹדֵעַ אוֹתָן וְנִזְהָר בָּהֶן, אָהוּב הוּא לְמַעְלָה וְאָהוּב לְמַטָּה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, כָּל הָאוֹתִיּוֹת הַלָּלוּ, זָכָר וּנְקֵבָה, לְהִכָּלֵל יַחַד בְּסוֹד הַמַּיִם הָעֶלְיוֹנִים וְהַמַּיִם הַתַּחְתּוֹנִים, וְהַכֹּל אֶחָד, וְזֶהוּ הַיִּחוּד הַשָּׁלֵם. וּמִשּׁוּם כָּךְ, מִי שֶׁמַּכִּיר אוֹתָם וְנִזְהָר בָּהֶם, אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהוּא עִקַּר הַיִּחוּד הַשָּׁלֵם כָּרָאוּי, שָׁלֹשׁ שָׁלֹשׁ מִצַּד זֶה וּמִצַּד זֶה, בְּיִחוּד אֶחָד בִּשְׁלֵמוּת הַכֹּל, וְכֻלָּם הַסּוֹד שֶׁל הַסֵּדֶר הָעֶלְיוֹן כָּרָאוּי כְּמוֹ שֶׁלְּמַעְלָה, שֶׁאוֹתוֹ סֵדֶר שְׁלֹשָׁה שְׁלֹשָׁה בְּסוֹד אֶחָד.</p>\n<p>סֵדֶר שֵׁנִי שֶׁלְּצַד הַדָּרוֹם, שְׁלֹשָׁה סְדָרִים הֵם לְאוֹתוֹ הַצַּד, וְכָל סֵדֶר וְסֵדֶר שְׁלֹשָׁה שְׁלֹשָׁה, וְהֵם תִּשְׁעָה, כְּמוֹ שֶׁנֶּאֱמַר, וְכָךְ נֶחֱלָקוֹת הָאוֹתִיּוֹת לְכָל צַד לְהִתְחַבֵּר הַכֹּל יַחַד. מִשּׁוּם שֶׁיֵּשׁ אוֹתִיּוֹת בְּסוֹד שֶׁל נְקֵבָה, וְאוֹתִיּוֹת בְּסוֹד שֶׁל זָכָר, וְכֻלָּן הִתְחַבְּרוּ יַחַד, וְהֵן אַחַת בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ הַשָּׁלֵם, וַאֲלֵיהֶם סְדָרִים מְמֻנִּים שְׁלֹשָׁה שְׁלֹשָׁה, כְּמוֹ שֶׁנִּתְבָּאֵר, וְהַכֹּל יוֹצֵא מֵהַסֵּדֶר שֶׁל הָאָבוֹת שֶׁלְּמַעְלָה, כַּסֵּדֶר שֶׁנִּתְקְנוּ אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ יה\"ו, כְּמוֹ שֶׁנִּתְבָּאֵר. כָּל הַסְּדָרִים הַלָּלוּ מִתְנַהֲגִים בָּאוֹתִיּוֹת הַיְדוּעוֹת הַלָּלוּ וְנוֹסְעִים בָּהֶן, וְכַמָּה צְבָאוֹת וּרְבָבוֹת כֻּלָּם לְמַטָּה שֶׁנּוֹסְעִים וּמִתְנַהֲגִים בַּסֵּדֶר הַזֶּה.</p>\n<p>סֵדֶר שְׁלִישִׁי שֶׁלְּצַד צָפוֹן, בִּשְׁלֹשָׁה סְדָרִים הֵם לְאוֹתוֹ הַצַּד, וְהֵם תִּשְׁעָה, וּבִשְׁלֹשָׁה צְדָדִים שְׁלֹשָׁה שְׁלֹשָׁה לְכָל צַד הֵם תִּשְׁעָה, וְאוֹתָם סְדָרִים מִשְּׁלֹשֶׁת הַצְּדָדִים, כְּמוֹ שֶׁנִּתְבָּאֵר. שִׁבְעָה וְעֶשְׂרִים, בְּסוֹד הָאוֹתִיּוֹת שֶׁהֵן שֶׁבַע וְעֶשְׂרִים. וְאַף עַל גַּב שֶׁהֵן עֶשְׂרִים וּשְׁתַּיִם, שְׁלֵמוּת הָאוֹתִיּוֹת הֵן עֶשְׂרִים וָשֶׁבַע. וְכָךְ הַסִּדּוּר שֶׁל הַסְּדָרוֹת הַלָּלוּ.</p>\n<p>שִׁבְעָה וְעֶשְׂרִים, לִשְׁלֹשָׁה שְׁלֹשָׁה סְדָרִים לְכָל צַד. וְנִמְצְאוּ שְׁלֹשָׁה אֵלֶּה מִצַּד זֶה שֶׁהֵם תִּשְׁעָה, וּשְׁלֹשָׁה הַלָּלוּ מֵהַצַּד הַזֶּה שֶׁהֵם תִּשְׁעָה, וּשְׁלֹשָׁה הַלָּלוּ מֵהַצַּד הַזֶּה שֶׁהֵם תִּשְׁעָה, נִמְצְאוּ כֻלָּם שִׁבְעָה וְעֶשְׂרִים.</p>\n<p>וְהַסּוֹד שֶׁל הַשִּׁבְעָה וְעֶשְׂרִים הַלָּלוּ הֵן תֵּשַׁע אוֹתִיּוֹת (הן) שֶׁהֵן בְּסוֹד הַנְּקֵבוֹת, לְחַבֵּר עִמָּהֶם נְקֵבָה עִם אוֹתָם שְׁמוֹנָה עָשָׂר צְדָדִים אֲחֵרִים בַּסּוֹד שֶׁנִּתְבָּאֵר (של הזכר), וְהַכֹּל הוּא כָּרָאוּי.</p>\n<p>בֹּא רְאֵה, כְּמוֹ שֶׁאוֹתָן אוֹתִיּוֹת עֶלְיוֹנוֹת שֶׁל הָעוֹלָם הָעֶלְיוֹן, כָּךְ גַּם הָאוֹתִיּוֹת הָאֲחֵרוֹת לְמַטָּה, אוֹתִיּוֹת עֶלְיוֹנוֹת גְּדוֹלוֹת, וְאוֹתִיּוֹת תַּחְתּוֹנוֹת קְטַנּוֹת, וְהַכֹּל זֶה כְּמוֹ זֶה. וְכָל הַסּוֹדוֹת הַלָּלוּ הֵם בְּסוֹד שֶׁל זָכָר וּנְקֵבָה, הַכֹּל אֶחָד בִּשְׁלֵמוּת.</p>"],[9522011324,"<p>וַיִּזְכֹּר אֱלֹהִים אֶל רָחֵל, שֶׁהֲרֵי בְּמַזָּל זֶה תָלוּי, וּמִשּׁוּם כָּךְ כָּתוּב בָּהּ זְכִירָה. וַה' פָּקַד אֶת שָׂרָה - זֶה לֹא הָיָה מֵהַמַּזָּל. וְאִם תֹּאמַר שֶׁהֲרֵי הַבָּנִים תְּלוּיִים בְּמַזָּל וְלֹא לְמַטָּה - כָּאן בְּשָׂרָה זֶה לֹא הָיָה בְּמַזָּל, אֶלָּא כָּתוּב וַה', הַכֹּל יַחַד.</p>\n<p>אִם כָּךְ, לָמָּה כָּתוּב פְּקִידָה? אֶלָּא וַדַּאי הַזְּכִירָה (הזו) הָיְתָה מִקֹּדֶם לָכֵן, וְהַמַּפְתֵּחַ הַזֶּה נִמְסַר לְמַטָּה, כְּמוֹ שֶׁכָּתוּב (בראשית יז) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק אֲשֶׁר תֵּלֵד לְךְ שָׂרָה לַמּוֹעֵד הַזֶּה וְגוֹ'. אַחֲרֵי כֵן כְּמוֹ זֶה - כֵּיוָן שֶׁנִּזְכַּר בַּסּוֹד שֶׁלְּמַעְלָה, אַחַר כָּךְ נֶאֱמַר בַּסּוֹד שֶׁל הַנְּקֵבָה פְּקִידָה, שֶׁיִּהְיֶה הַכְּלָל שֶׁל הַכֹּל יַחַד.</p>\n<p>וַיִּזְכֹּר אֱלֹהִים אֶל רָחֵל. רַבִּי חִיָּיא פָּתַח וְאָמַר, (שמות ו) וְגַם אֲנִי שָׁמַעְתִּי אֶת נַאֲקַת בְּנֵי יִשְׂרָאֵל אֲשֶׁר מִצְרַיִם מַעֲבִידִים אֹתם וָאֶזְכֹּר אֶת בְּרִיתִי. וָאֶזְכֹּר - הֲרֵי זְכִירָה, מִשּׁוּם שֶׁהִיא לְמַעְלָה, שֶׁהַמַּזָּל הַזֶּה הוּא לְמַעְלָה בַּזָּכָר, בָּא עַל פְּקִידָה שֶׁהִיא בַּגָּלוּת לְמַטָּה בַּנְּקֵבָה. כְּמוֹ כֵן וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל, כְּמוֹ שֶׁנֶּאֱמַר וָאֶזְכֹּר אֶת בְּרִיתִי.</p>\n<p>בֹּא רְאֵה, כָּתוּב פָּקֹד פָּקַדְתִּי אֶתְכֶם. וְכִי פָּקֹד פָּקַדְתִּי? וַהֲרֵי הַפְּקִידָה עוֹמֶדֶת בַּנְּקֵבָה, וּבְאוֹתוֹ הַזְּמַן הָיְתָה בַּגָּלוּת, וְהִיא אוֹמֶרֶת פָּקֹד פָּקַדְתִּי? אֶלָּא שֶׁכָּאן יֵשׁ לְהִסְתַּכֵּל, וְכָאן סוֹד שֶׁל הַחָכְמָה, וְהִיא בַּגָּלוּת, אֵיךְ נִרְאֶה לְמֹשֶׁה כָּאן וְאֵיךְ אָמְרָה פָּקֹד פָּקַדְתִּי.</p>\n<p>אֶלָּא כָּךְ לָמַדְנוּ, כְּשֶׁהַשֶּׁמֶשׁ מֵאִיר - הוּא בַּשָּׁמַיִם, וְתָקְפּוֹ וְכֹחוֹ עַל הָאָרֶץ בְּכָל מָקוֹם. כְּמוֹ כֵן מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. בִּזְמַן שֶׁהַמִּקְדָּשׁ עָמַד - מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, זוֹ הָאָרֶץ הַקְּדוֹשָׁה, וְכָעֵת שֶׁיִּשְׂרָאֵל בַּגָּלוּת - הִיא לְמַעְלָה, וְהַתֹּקֶף מַקִּיף אֶת יִשְׂרָאֵל לְהָגֵן עֲלֵיהֶם, וְאַף עַל גַּב שֶׁהֵם בְּאֶרֶץ אַחֶרֶת.</p>\n<p>וּבֹא תִרְאֶה, שְׁכִינָה לְמַטָּה וּשְׁכִינָה לְמַעְלָה. שְׁכִינָה לְמַעְלָה בִּשְׁנֵים עָשָׂר תְּחוּמִים מֶרְכָּבוֹת קְדוֹשׁוֹת וּשְׁתֵּים עֶשְׂרֵה חַיּוֹת עֶלְיוֹנוֹת. שְׁכִינָה לְמַטָּה בִּשְׁנֵים עָשָׂר שְׁבָטִים קְדוֹשִׁים. וְאָז נִכְלֶלֶת הַשְּׁכִינָה לְמַעְלָה וּלְמַטָּה, וְהַכֹּל בְּפַעַם אַחַת יַחַד. וְאַף עַל גַּב שֶׁבִּזְמַן שֶׁיִּשְׂרָאֵל בַּגָּלוּת לְמַטָּה לֹא נִתְקֶנֶת לְמַעְלָה, כָּךְ גַּם לֹא נִתְקֶנֶת מִשּׁוּם שֶׁלְּמַטָּה לֹא נִתְקֶנֶת, וְזֶהוּ בַּגָּלוּת עִם יִשְׂרָאֵל, שֶׁהִיא בַּגָּלוּת עִמָּהֶם.</p>\n<p>בַּמֶּה נִתְקֶנֶת? לְמֶלֶךְ שֶׁמֵּת בְּנוֹ, מֶה עָשָׂה? כָּפָה אֶת מִטָּתוֹ עַל אֵבֶל בְּנוֹ, וְלֹא הִתְקִין לוֹ אֶת מִטָּתוֹ, אֶלָּא נָטַל קוֹצִים וְדַרְדָּרִים וְהִטִּיל תַּחַת מִטָּתוֹ וְשָׁכַב עָלֶיהָ. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, כֵּיוָן שֶׁגָּלוּ יִשְׂרָאֵל וְנֶחֱרַב הַמִּקְדָּשׁ, לָקַח קוֹצִים וְדַרְדָּרִים וְשָׂם תַּחְתָּיו. זֶהוּ שֶׁכָּתוּב וַיֵּרָא אֵלָיו מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה, מִשּׁוּם שֶׁיִּשְׂרָאֵל הָיוּ בַּגָּלוּת.</p>\n<p>פָּקֹד פָּקַדְתִּי אֶתְכֶם. מִי שֶׁלֹּא עוֹמֵד בִּרְשׁוּתוֹ, מַה מְצַוֶּה וּמָה עוֹשֶׂה? אֶלָּא פָּקֹד מִלְמַעְלָה, פָּקַדְתִּי מִלְּמַטָּה. מָה הַטַּעַם? מִשּׁוּם שֶׁהַזְּכִירָה הַזּוֹ הָיְתָה עָלֶיהָ מִקֹּדֶם לָכֵן, שֶׁכָּתוּב וָאֶזְכֹּר אֶת בְּרִיתִי. כֵּיוָן שֶׁכָּתוּב וָאֶזְכֹּר - הִנֵּה זְכִירָה הִתְמַנְּתָה עָלֶיהָ, וּמִשּׁוּם כָּךְ אָמְרָה אַחַר כָּךְ פָּקֹד פָּקַדְתִּי, שֶׁהֲרֵי סִימָן לָקְחָה מִקֹּדֶם לָכֵן. כְּמוֹ כֵן שָׂרָה, שֶׁכָּתוּב וַה' פָּקַד אֶת שָׂרָה. אֲבָל כָּאן רָחֵל, שֶׁלֹּא נִזְכְּרָה מִקֹּדֶם לָכֵן, לֹא נֶאֱמַר בָּהּ פְּקִידָה, אֶלָּא זְכִירָה, וְהַכֹּל הוּא בִּזְכִירָה, בַּסּוֹד שֶׁל הַמַּזָּל.</p>\n<p>רַבִּי יְהוּדָה וְרַבִּי חִזְקִיָּה הָיוּ הוֹלְכִים מִקַּפּוֹטְקִיָּא לְלוֹד, וְרַבִּי יְהוּדָה הָיָה רוֹכֵב, וְרַבִּי חִזְקִיָּה עַל רַגְלָיו. בֵּינְתַיִם יָרַד רַבִּי יְהוּדָה. אָמַר, מִכָּאן וָהָלְאָה נִתְעַסֵּק בַּתּוֹרָה, כַּכָּתוּב (דברים לב) הָבוּ גֹדֶל לֵא לֹהֵינוּ.</p>\n<p>אָמַר לוֹ, אִלּוּ הָיִינוּ שְׁלֹשָׁה - יָפֶה הוּא, שֶׁאֶחָד יֹאמַר - וּשְׁנַיִם יָשִׁיבוּ לוֹ. אָמַר לוֹ, הַדְּבָרִים הַלָּלוּ שֶׁל הַבְּרָכוֹת, מִשּׁוּם שֶׁאֶחָד מַזְכִּיר שֵׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּשְׁנַיִם יָשִׁיבוּ לוֹ. זֶהוּ שֶׁכָּתוּב כִּי שֵׁם ה' אֶקְרָא הָבוּ גֹדֶל לֵאלֹהֵינוּ. כִּי שֵׁם ה' אֶקְרָא - זֶה אֶחָד שֶׁמְּבָרֵךְ. הָבוּ גֹדֶל לֵאלֹהֵינוּ - אֵלּוּ שְׁנַיִם אֲחֵרִים. אֲבָל בַּתּוֹרָה, אֲפִלּוּ שְׁנַיִם יוֹשְׁבִים וְנוֹתְנִים גֹּדֶל וְחֹזֶק שֶׁל שֶׁבַח הַתּוֹרָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>אָמַר לוֹ רַבִּי חִזְקִיָּה, כְּלַפֵּי הַבְּרָכוֹת לָמָּה שְׁלֹשָׁה? אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ וְנִתְבָּאֵר, שֶׁכָּתוּב הָבוּ גֹדֶל לֵאלֹהֵינוּ. אֲבָל סוֹד הַדָּבָר כָּאן, שֶׁהֲרֵי כָּל הַסּוֹדוֹת שֶׁל הַבְּרָכוֹת הוּא כָּךְ - אֶחָד לְבָרֵךְ וּשְׁנַיִם לְהָשִׁיב, כְּדֵי שֶׁיַּעֲלֶה הַשֶּׁבַח שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּסוֹד שֶׁל שְׁלֹשָׁה, אֶחָד מְבָרֵךְ וּשְׁנַיִם (אומרים אמן) שֶׁמּוֹדִים, וְזֶהוּ קִיּוּם הַבְּרָכוֹת, וּבְסוֹד עֶלְיוֹן כָּרָאוּי, וּבַסּוֹד שֶׁל שְׁלֹשָׁה, כְּמוֹ שֶׁבֵּאֲרוּהוּ.</p>\n<p>בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי יְהוּדָה, שָׁנִינוּ, יֵשׁ זְכִירָה לְטוֹב וְיֵשׁ זְכִירָה לְרַע, יֵשׁ פְּקִידָה לְטוֹב וְיֵשׁ פְּקִידָה לְרַע. יֵשׁ זְכִירָה לְטוֹב - כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (ויקרא כו) וְזָכַרְתִּי לָהֶם בְּרִית רִאשֹׁנִים וְגוֹ', (בראשית ח) וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ, (שמות ב) וַיִּזְכֹּר אֱלֹהִים אֶת בְּרִיתוֹ. וְיֵשׁ זְכִירָה לְרַע - שֶׁכָּתוּב (תהלים עח) וַיִּזְכֹּר כִּי בָשָׂר הֵמָּה רוּחַ הֹלֵךְ וְלֹא יָשׁוּב. פְּקִידָה לְטוֹב - שֶׁכָּתוּב (שמות ג) פָּקֹד פָּקַדְתִּי אֶתְכֶם. פְּקִידָה לְרַע - שֶׁכָּתוּב (תהלים פט) וּפָקַדְתִּי בְשֵׁבֶט פִּשְׁעָם וּבִנְגָעִים עֲונָם. וְכֻלָּם סוֹדוֹת עֶלְיוֹנִים.</p>\n<p>כָּל אֵלּוּ - זְכִירָה וּפְקִידָה - לְטוֹב, אֵלּוּ הֵן דְּרָגוֹת יְדוּעוֹת, סוֹד הָאֱמוּנָה, זָכָר וּנְקֵבָה, סוֹד אֶחָד, זְכִירָה וּפְקִידָה, אֵלּוּ הֵם לְטוֹב. זְכִירָה וּפְקִידָה לְרַע אֵלּוּ הֵם הַסּוֹד שֶׁל הַצַּד הָאַחֵר שֶׁעוֹמֵד בְּסוֹד שֶׁל אֱלֹהִים אֲחֵרִים. זָכָר וּנְקֵבָה יַחַד, זְכִירָה בָּזֶה וּפְקִידָה בָּזֶה, וְאֵלּוּ הֵם שֶׁתָּמִיד עוֹמְדִים לְרַע וְאֵלּוּ כְּנֶגֶד אֵלּוּ. מִכָּאן יוֹצְאִים כָּל סוֹדוֹת הָאֱמוּנָה וְכָל הַקְּדֻשּׁוֹת הָעֶלְיוֹנוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ, וּמִכָּאן יוֹצְאִים כָּל הַמִּינִים הָרָעִים וְכָל מָוֶת וְכָל הַצְּדָדִים וְהַמִּינִים הָרָעִים בָּעוֹלָם, וּבֵאֲרוּהָ, וְזֶה בְּהִפּוּךְ מִזֶּה.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, כָּךְ זֶה וַדַּאי. אַשְׁרֵי הוּא מִי שֶׁחֶלְקוֹ מִתְקַיֵּם בַּצַּד הַטּוֹב וְלֹא יַרְכִּין עַצְמוֹ לְצַד אַחֵר וְיִנָּצֵל מֵהֶם. אָמַר לוֹ רַבִּי יְהוּדָה, כָּךְ זֶה וַדַּאי, וְאַשְׁרֵי מִי שֶׁיָּכוֹל לְהִנָּצֵל מִמֶּנּוּ מֵהַצַּד הַהוּא, וְאַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיְּכוֹלִים לְהִנָּצֵל מֵהֶם וּלְהִלָּחֵם קְרָב עִם אוֹתוֹ הַצַּד. אָמַר רַבִּי חִזְקִיָּה, בַּמֶּה? פָּתַח וְאָמַר, (משלי כד) כִּי בְתַחְבֻּלוֹת תַּעֲשֶׂה לְּךְ מִלְחָמָה. מִי הַמִּלְחָמָה? זוֹ הַמִּלְחָמָה שֶׁל אוֹתוֹ הַצַּד הָרָע שֶׁצָּרִיךְ אָדָם לְהִלָּחֵם בּוֹ קְרָב וְלִשְׁלֹט עָלָיו וּלְהִנָּצֵל מִמֶּנּוּ.</p>\n<p>בֹּא רְאֵה שֶׁיַּעֲקֹב כָּךְ הִשְׁתַּדֵּל אֵצֶל עֵשָׂו מִשּׁוּם אוֹתוֹ הַצַּד שֶׁלּוֹ, לְהִתְחַכֵּם עָלָיו וְלָלֶכֶת עִמּוֹ בְּעַקְמוּמִיּוֹת בְּכָל מַה שֶּׁצָּרִיךְ כְּדֵי לִשְׁלֹט עָלָיו בָּרֹאשׁ וּבַסּוֹף, וְהַכֹּל כָּרָאוּי, וְהָרֹאשׁ וְהַסּוֹף יַחַד זֶה כְּמוֹ זֶה, כַּכָּתוּב בְּכֹרָתִי, וְאַחַר כָּךְ בִּרְכָתִי. הָרֵאשִׁית וְהַסּוֹף יַחַד זֶה כְּמוֹ זֶה, כְּדֵי לִשְׁלֹט עָלָיו בְּדֶרֶךְ יְשָׁרָה כָּרָאוּי לוֹ, וּמִשּׁוּם כָּךְ צַדִּיק הוּא מִי שֶׁנִּצָּל מֵהֶם וְיָכוֹל לִשְׁלֹט עֲלֵיהֶם.</p>\n<p>בֹּא רְאֵה, זְכִירָה וּפְקִידָה לְטוֹב הֵם כְּאֶחָד בְּסוֹד הָאֱמוּנָה, וְאַשְׁרֵי הוּא מִי שֶׁמִּשְׁתַּדֵּל אַחַר הָאֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר (הושע יא) אַחֲרֵי ה' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג וְגוֹ'. אָמַר רַבִּי חִזְקִיָּה, כָּךְ הוּא וַדַּאי.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁאָדָם מִתְפַּלֵּל תְּפִלָּתוֹ, אַל יֹאמַר עָלֶיהָ זָכְרֵנִי וּפָקְדֵנִי, מִשׁוּם שֶׁיֵּשׁ זְכִירָה וּפְקִידָה לְטוֹב, וּזְכִירָה וּפְקִידָה לְרַע, וַעֲתִידִים לִטֹּל אֶת הַדִּבּוּר מִפִּיו, וּבָאִים לְהַזְכִּיר חֲטָאֵי הָאָדָם וּלְהַעֲנִישׁוֹ. פְּרָט אִם הוּא צַדִּיק שָׁלֵם, שֶׁכַּאֲשֶׁר בּוֹדְקִים אֶת חֲטָאָיו, אוֹתָהּ זְכִירָה וּפְקִידָה לְרַע לֹא יִמְצְאוּ אוֹתָם, כְּמוֹ עֶזְרָא שֶׁאָמַר זָכְרָה לִי אֱלֹהַי לְטוֹבָה.</p>\n<p>שֶׁהִנֵּה בְּכָל מָקוֹם שֶׁאָדָם מִתְפַּלֵּל תְּפִלָּתוֹ, יִכְלֹל אֶת עַצְמוֹ בֵּין רַבִּים, בַּכְּלָל שֶׁל הָרַבִּים. וּבֹא וּרְאֵה, הַשּׁוּנַמִּית, כַּאֲשֶׁר אָמַר לָהּ אֱלִישָׁע (מלכים ב ד) הֲיֵשׁ לְדַבֶּר לָךְ אֶל הַמֶּלֶךְ אוֹ אֶל שַׂר הַצָּבָא, הֲיֵשׁ לְדַבֶּר לָךְ אֶל הַמֶּלֶךְ - אוֹתוֹ הַיּוֹם הָיָה יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה, וְאוֹתוֹ הַיּוֹם שֶׁשּׁוֹלֶטֶת מַלְכוּת הָרָקִיעַ לָדוּן אֶת הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא הַמֶּלֶךְ הַמִּשְׁפָּט בְּאוֹתוֹ הַזְּמַן, וּמִשּׁוּם כָּךְ אָמַר לָהּ הֲיֵשׁ לְדַבֶּר לָךְ אֶל הַמֶּלֶךְ.</p>\n<p>מַה כָּתוּב? וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת. מָה אָמְרָה? לֹא רוֹצָה לִהְיוֹת רְשׁוּמָה לְמַעְלָה, אֶלָּא לְהַכְנִיס אֶת רֹאשִׁי בֵּין רַבִּים, וְלֹא לָצֵאת מֵהַכְּלָל שֶׁלָּהֶם. וְכָךְ צָרִיךְ לְאָדָם לְהִכָּלֵל בִּכְלָל שֶׁל רַבִּים וְלֹא לְהִתְיַחֵד לְבַדּוֹ, כְּדֵי שֶׁלֹּא יַשְׁגִּיחוּ עָלָיו לְהַזְכִּיר חֲטָאָיו, כְּמוֹ שֶׁאָמַ רְנוּ.</p>"],[9522011325,"<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, (איוב לח) הֲנִגְלוּ לְךְ שַׁעֲרֵי מָוֶת וְשַׁעֲרֵי צַלְמָוֶת תִּרְאֶה. הַפָּסוּק הַזֶּה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאִיּוֹב כְּשֶׁרָאָה שֶׁאִיּוֹב דּוֹחֵק עַצְמוֹ עַל דִּין הַקָּדוֹשׁ בָּרוּךְ הוּא. בֹּא רְאֵה, אִיּוֹב אָמַר הֵן יִקְטְלֵנִי לוֹ אֲיַחֵל. כָּתוּב לֹא בְּאָלֶ\"ף, וְקוֹרְאִים לוֹ בְּוָא\"ו, וְהַכֹּל הוּא.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי אֲנִי הוֹרֵג בְּנֵי אָדָם!? הֲנִגְלוּ לְךְ שַׁעֲרֵי מָוֶת וְשַׁעֲרֵי צַלְמָוֶת תִּרְאֶה!? כַּמָּה שְׁעָרִים פְּתוּחִים בְּאוֹתוֹ הַצַּד, וְהַמָּוֶת שׁוֹלֵט עֲלֵיהֶם, וְכֻלָּם סְתוּמִים מִבְּנֵי אָדָם, (ולא יכולים להשמר מהם משום שהם סתומים מבני אדם) שֶׁלֹּא מַכִּירִים אֶת אוֹתָם הַשְּׁעָרִים.</p>\n<p>וְשַׁעָרֵי צַלְמָוֶת תִּרְאֶה. מִי הֵם שַׁעֲרֵי מָוֶת וּמִי הֵם שַׁעֲרֵי צַלְמָוֶת? אֶלָּא מָוֶת וְצַלְמָוֶת הֵם יַחַד, וְהֵם זִוּוּג אֶחָד. מָוֶת - הֲרֵי נִתְבָּאֵר, זֶה מַלְאַךְ הַמָּוֶת, וַהֲרֵי פֵּרְשׁוּהָ. צַלְמָוֶת - צֵל מָוֶת, זֶהוּ מִי שֶׁרוֹכֵב עָלָיו, וְהוּא הַצֵּל שֶׁלּוֹ וְהַכֹּחַ שֶׁלּוֹ לְהִזְדַּוֵּג יַחַד בְּקֶשֶׁר אֶחָד, וְהֵם אֶחָד.</p>\n<p>וְכָל אוֹתָם הַדְּרָגוֹת שֶׁיּוֹצְאוֹת מֵהֶם וְנִקְשָׁרוֹת בָּהֶם הֵם הַשְּׁעָרִים שֶׁלָּהֶם, כְּמוֹ שֶׁלְּמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כד) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. וְאֵלּוּ (אותם שערים) נִקְרָאִים נְהָרוֹת וּנְחָלִים. שֵׁשֶׁת הַצְּדָדִים שֶׁל הָעוֹלָם, אַף כָּךְ הֵם שַׁעֲרֵי מָוֶת, וְשַׁעֲרֵי צַלְמָוֶת מֵהַצַּד הָאַחֵר, דְּרָגוֹת יְדוּעוֹת שֶׁשּׁוֹלְטוֹת בָּעוֹלָם. שַׁעֲרֵי מָוֶת וְשַׁעֲרֵי צַלְמָוֶת - זֶה נְקֵבָה וְזֶה זָכָר, וּשְׁנֵיהֶם יַחַד.</p>\n<p>וְעַל זֶה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאִיּוֹב בִּשְׁבִיל כָּל אוֹתָם דְּבָרִים שֶׁהוּא אָמַר, (איוב ז) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לֹא יַעֲלֶה, וְכָל אוֹתָם שְׁאָר דְּבָרִים. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲנִגְלוּ לְךְ שַׁעֲרֵי מָוֶת, לָדַעַת שֶׁהֲרֵי הַכֹּל בִּרְשׁוּתִי, וְכֻלָּם עֲתִידִים לְהִתְבַּעֵר מִן הָעוֹלָם, שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'.</p>"],[9522011326,"<p>בֹּא רְאֵה, וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל וַיִּשְׁמַע אֵלֶיהָ אֱלֹהִים וַיִּפְתַּח אֶת רַחְמָהּ. פַּעֲמַיִם אֱלֹהִים אֱלֹהִים, לָמָּה? אֶלָּא אֶחָד מֵעוֹלַם הַזָּכָר, וְאֶחָד מֵעוֹלַם הַנְּקֵבָה, מִשּׁוּם שֶׁהַדָּבָר תָּלוּי בְּמַזָּל.</p>\n<p>וּכְשֶׁמִּתְעוֹרֶרֶת רָחֵל בַּשֵּׁם הַזֶּה, שֶׁכָּתוּב יֹסֵף ה' לִי בֵּן אַחֵר, יָדַע יַעֲקֹב שֶׁהִיא רְאוּיָה לְהַשְׁלִים אֶת כָּל הַשְּׁבָטִים וְלֹא תִתְקַיֵּם בָּעוֹלָם, מִשּׁוּם כָּךְ רָצָה לָלֶכֶת וְלֹא יָכֹל, וּכְשֶׁהִגִּיעַ זְמַנּוֹ שֶׁל בִּנְיָמִין, בָּרַח וְהָלַךְ לוֹ, כְּדֵי שֶׁהַבַּיִת לֹא יִשְׁתַּלֵּם בְּאֶרֶץ אַחֶרֶת, לְהִתְקַשֵּׁר בּוֹ הָעוֹלָם הַקָּדוֹשׁ.</p>\n<p>וְהַיְנוּ שֶׁכָּתוּב (בראשית לא) וַיֹּאמֶר ה' אֶל יַעֲקֹב שׁוּב אֶל אֶרֶץ אֲבוֹתֶיךְ וּלְמוֹלַדְתֶּךְ וְאֶהְיֶה עִמָּךְ. מַה זֶּה וְאֶהְיֶה עִמָּךְ? אֶלָּא אָמַר לוֹ, עַד כָּאן רָחֵל הָיְתָה עִמְּךְ עִקַּר הַבַּיִת, מִכָּאן וָהָלְאָה אֲנִי אֶהְיֶה עִמְּךְ וְאֶטֹּל אֶת הַבַּיִת עִמְּךְ עִם שְׁנֵים עָשָׂר הַשְּׁבָטִים. וְהַיְנוּ שֶׁכָּתוּב וַאֲנִי בְּבֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל. עָלַי הָיָה זֶה, וּבִגְלָלִי הָיָה הַדָּבָר שֶׁהִיא נִדְחֲתָה, וּבָאָה דַיֶּרֶת אַחֶרֶת וְנָטְלָה אֶת הַבַּיִת בִּשְׁבִילִי לָדוּר עִמִּי.</p>"],[9522011327,"<p>וַיֹּאמַר נָקְבָה שְׂכָרְךְ עָלַי וְאֶתֵּנָה. מַה זֶּה נָקְבָה? אָמַר רַבִּי יִצְחָק, אוֹתוֹ רָשָׁע אָמַר, אֲנִי רוֹאֶה שֶׁיַּעֲקֹב לֹא מִסְתַּכֵּל אֶלָּא בִּנְקֵבוֹת, וּמִשּׁוּם זֶה יַעֲבֹד אוֹתִי. אָמַר נָקְבָה שְׂכָרְךְ, הִנֵּה נְקֵבָה, שֶׁהִיא שְׂכָרְךְ, כְּבָרִאשׁוֹנָה. וְאֶתֵּנָה, אֱמֹר בְּאֵיזוֹ נְקֵבָה הִסְתַּכַּלְתָּ וְאֶתֵּנָה, וַעֲבֹד אוֹתִי בִּשְׁבִילָהּ.</p>\n<p>וַיֹּאמֶר יַעֲקֹב לֹא תִתֵּן לִי מְאוּמָה. אָמַר יַעֲקֹב, חָלִילָה, שֶׁהֲרֵי אֲנִי כָּל מַה שֶּׁעָשִׂיתִי, לְשֵׁם כְּבוֹד הַמֶּלֶךְ הַקָּדוֹשׁ עָשִׂיתִי, וְעַל כֵּן לֹא תִתֵּן לִי מְאוּמָה, שֶׁהֲרֵי אֵין דַּעְתִּי בָּזֶה, אֶלָּא אִם תַּעֲשֶׂה לִי (את) הַדָּבָר הַזֶּה וְגוֹ'.</p>\n<p>וַיָּסַר בַּיּוֹם הַהוּא אֶת הַתְּיָשִׁים. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים טו) ה' מִי יָגוּר בְּאָהֳלֶךְ וְגוֹ'. הֲרֵי בֵּאַרְנוּ וּבֵאֲרוּ הַחֲבֵרִים, הוֹלֵךְ תָּמִים - זֶה אַבְרָהָם, שֶׁכַּאֲשֶׁר נִמּוֹל נִקְרָא תָמִים. וּפֹעֵל צֶדֶק - זֶה יִצְחָק. וְדבֵר אֱמֶת - זֶה יַעֲקֹב. וַדַּאי שֶׁיַּעֲקֹב נִדְבַּק בָּאֱמֶת. אִם הוּא בָּאֱמֶת נִדְבַּק, מָה הַטַּעַם עָשָׂה עִם לָבָן בַּצּוּרָה הַזּוֹ?</p>\n<p>אֶלָּא יַעֲקֹב הִבְחִין אֶת שְׁעַת הַמַּזָּל שֶׁלּוֹ שֶׁהָיְתָה, שֶׁמֻּתָּר לָאָדָם לִבְחֹן אֶת שְׁעָתוֹ טֶרֶם יָשׁוּב לְאַרְצוֹ, וְאִם מַזָּלוֹ עוֹמֵד בְּמַה שֶּׁעוֹשֶׂה - יָפֶה, וְאִם לֹא - אַל יוֹשִׁיט רַגְלוֹ עַד שֶׁיַּעֲלֶה (שיעמד במה שעשה) אֵלָיו.</p>\n<p>בֹּא רְאֵה, כָּתוּב וְעָנְתָה בִּי צִדְקָתִי בְּיוֹם מָחָר וְגוֹ'. שֶׁהֲרֵי הוּא לֹא עָשָׂה כְּדֵי שֶׁיִּטֹּל מִשֶּׁלּוֹ לְחִנָּם, אֶלָּא הַכֹּל בֶּאֱמֶת וּשְׁלֵמוּת הָרָצוֹן, וְלֹא עוֹד, אֶלָּא שֶׁהוּא נָטַל רְשׁוּת מִלָּבָן, וְעַל כֵּן כָּתוּב נִחַשְׁתִּי וַיְבָרֲכֵנִי ה' בִּגְלָלֶךְ. כַּמָּה כְשָׁפִים וּמִינִים עָשָׂה לָבָן וּבָחַן אֶת מַזָּלוֹ מִשּׁוּם יַעֲקֹב, וְהָיָה מוֹצֵא בִּגְלַל יַעֲקֹב מֵאָה צֹאן כָּל חֹדֶשׁ, וּמֵאָה כְבָשִׁים וּמֵאָה עִזִּים יוֹתֵר עַל צֹאנוֹ.</p>\n<p>רַבִּי אַבָּא אָמַר, אֶלֶף צֹאן וְאֶלֶף כְּבָשִׂים וְאֶלֶף עִזִּים הָיָה מֵבִיא לוֹ יַעֲקֹב יוֹתֵר בְּכָל חֹדֶשׁ וְחֹדֶשׁ. זֶהוּ שֶׁכָּתוּב כִּי מְעַט אֲשֶׁר הָיָה לְךְ לְפָנַי וַיִּפְרֹץ לָרֹב וַיְבָרֶךְ ה' אֹתְךְ לְרַגְלִי. וְהַבְּרָכָה שֶׁלְּמַעְלָה אֵינָהּ פָּחוֹת מֵאֶלֶף מִכָּל מִין וּמִין. נִמְצָא אֶלֶף מֵהַצּאן, מֵהַכְּבָשִׂים נִמְצְאוּ אֶלֶף, מֵהָעִזִּים נִמְצְאוּ אֶלֶף, עַל כָּל מַה שֶּׁשּׁוֹרָה הַבְּרָכָה שֶׁלְּמַעְלָה לֹא פָחוֹת מֵאֶלֶף, עַד שֶׁבִּשְׁבִיל יַעֲקֹב הִתְעַלָּה לָבָן לְעֹשֶׁר רַב.</p>\n<p>וּכְשֶׁרָצָה יַעֲקֹב לִטֹּל שְׂכָרוֹ, לֹא מָצָא אֶלָּא עֲשָׂרָה מִכָּל מִין וּמִין, וְיַעֲקֹב חָשַׁב אוֹתוֹ לְעֹשֶׁר רַב. רָאָה כַּמָּה נָטַל מִשֶּׁלּוֹ מִמַּה שֶּׁהָיָה נוֹתֵן הוּא בִּזְכוּתוֹ לְלָבָן. וְכָל זֶה שֶׁעָלָה בּוֹ בְּיַעֲקֹב, לֹא הָיָה אֶלָּא בַּזְּרוֹעַ שֶׁל אוֹתָם מַקְלוֹת שֶׁשָּׂם אֵצֶל הַצֹּאן.</p>\n<p>בֹּא רְאֵה כַּמָּה טָרַח אוֹתוֹ יַעֲקֹב הַשָּׁלֵם אַחֲרֵי לָבָן. כָּתוּב וַיָּשֶׂם דֶּרֶךְ שְׁלֹשֶׁת יָמִים וְגוֹ', וְהֵבִיא לוֹ כָּל הָעֹשֶׁר הַזֶּה, וְעִם כָּל זֶה לֹא רָצָה לָבָן שֶׁיִּהְיֶה כָּךְ שְׂכָרוֹ שֶׁל יַעֲקֹב, אֶלָּא נָטַל עֲשָׂרָה מִזֶּה וַעֲשָׂרָה מִזֶּה, וְנָתַן (בידי בניו) לוֹ וְאָמַר לוֹ: טֹל אֶת אֵלֶּה, וְאִם יוֹלִידוּ כְּמוֹ שֶׁאָמַרְתָּ - בַּצּוּרָה הַזּוֹ יִהְיֶה שְׂכָרְךְ. זֶהוּ שֶׁכָּתוּב וַתַּחֲלֵף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מֹנִים. (ובאלו) עֲשָׂרָה מִזֶּה וַעֲשָׂרָה מִזֶּה, וְכָתוּב וַאֲבִיכֶן הֵתֶל בִּי וְהֶחֱלִף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מֹנִים. (ובאלו העשרה) הִשְׁתַּדֵּל אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבֵרְכוֹ. וּמִכָּל מַה שֶּׁהִתְנָה לָבָן עִם יַעֲקֹב - חָזַר בְּדִבּוּרוֹ וְנָטַל מִיַּעֲקֹב הַכֹּל, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו וְנָטַל מִשֶּׁלּוֹ בִּזְרוֹעַ.</p>"],[9522011328,"<p>אָמַר רַבִּי אֶלְעָזָר, כָּל הַפְּסוּקִים הַלָּלוּ בָּאוּ לְהַרְאוֹת הַחָכְמָה, שֶׁשָּׁנִינוּ שֶׁדְּבָרִים שֶׁלְּמַעְלָה, מֵהֶם תְּלוּיִים בְּמַעֲשֶׂה, וּמֵהֶם בְּדִבּוּר, וּמֵהֶם בִּרְצוֹן הַלֵּב, וּמִי שֶׁרוֹצֶה לִמְשֹׁךְ בְּרָכוֹת בִּתְפִלָּה, בְּדִבּוּר וְרָצוֹן. וּמֵהֶם שֶׁלֹּא בִּתְפִלָּה, אֶלָּא תְּלוּיִים בְּמַעֲשֶׂה.</p>\n<p>בֹּא רְאֵה, יַעֲקֹב הַשָּׁלֵם, כָּל מַה שֶּׁעָשָׂה, עָשָׂה בְּחָכְמָה. כָּתוּב וַיַּצֵּג אֶת הַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים בְּשִׁקֲתוֹת הַמָּיִם. הַכֹּל בְּחָכְמָה, לִמְשֹׁךְ בְּרָכוֹת מֵהַמַּעְיָן שֶׁל הַכֹּל לְכָל הַדְּרָגוֹת הָעֶלְיוֹנוֹת שֶׁהֵן חֶלְקוֹ וְגוֹרָלוֹ.</p>\n<p>אֶת הַמַּקְלוֹת - אֵיזֶה מַקְלוֹת? אֵלּוּ הַדְּרָגוֹת שֶׁהֵן בֵּית הַדִּין. אֲשֶׁר פִּצֵּל - שֶׁהֶעֱבִיר מֵהֶן אֶת הַדִּין. בָּרְהָטִים - הַיְנוּ שֶׁכָּתוּב (שיר ז) מֶלֶךְ אָסוּר בָּרְהָטִים, שֶׁזֶּה מֵהַמֶּלֶךְ הַהוּא בָּאוֹת בְּרָכוֹת לְכָל הָעוֹלָמוֹת.</p>\n<p>דָּבָר אַחֵר מֶלֶךְ אָסוּר בָּרְהָטִים - מֶלֶךְ זֶה אָסוּר וְקָשׁוּר בְּאוֹתָם הָרְהָטִים הָעֶלְיוֹנִים שֶׁמֵּהֶם מַשְׁקִים אֶת הַכֹּל (נמשכות ברכות לכל) מִן הַמֶּלֶךְ הָעֶלְיוֹן. בְּשִׁקְתוֹת הַמָּיִם - (ומשם משקים כל שקתות המים) אֵלּוּ הֵם הַנְּחָלִים שֶׁיּוֹצְאִים וּבָאִים עַד שֶׁמַּגִּיעִים לְמָקוֹם שֶׁשָּׁם מִתְכַּנְּסִים. אֲשֶׁר תָּבֹאןָ הַצֹּאן לִשְׁתּוֹת - כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם. וּבְאוֹתוֹ הַמָּקוֹם שֶׁשָּׁם מִתְכַּנְּסִים הַמַּיִם, כֻּלָּם בָּאִים לְהַשְׁקוֹת מִמֶּנּוּ.</p>\n<p>וַיֵּחַמְנָה - מַה זֶּה וַיֵּחַמְנָה? בֹּא רְאֵה, בְּשָׁעָה שֶׁרוּחַ צָפוֹן נוֹשֶׁבֶת, הַמַּיִם קוֹפְאִים וְלֹא נִמְשָׁכִים לַחוּץ וְלֹא מַשְׁקִים, מִשּׁוּם שֶׁהַדִּין תָּלוּי, וְקֹר הַצָּפוֹן מַקְפִּיא אֶת הַמַּיִם. וּכְשֶׁמִּתְעוֹרֶרֶת רוּחַ הַדָּרוֹם, מִתְחַמְּמִים הַמַּיִם וְהַקִּפָּאוֹן שֶׁלָּהֶם עוֹבֵר וְשׁוֹפְעִים. אָז הַכֹּל מֻשְׁקִים, מִשּׁוּם שֶׁהַחֹם שֶׁל הַדָּרוֹם מַפְשִׁירִים הַמַּיִם, וְכֻלָּם מִתְחַמְּמִים וּשְׂמֵחִים לִשְׁתּוֹת מֵאוֹתוֹ הַקֹּר שֶׁל הַצָּפוֹן שֶׁהָיָה לָהֶם בָּרִאשׁוֹנָה. זֶהוּ שֶׁכָּתוּב וַיֵּחַמְנָה. וַיֵּחַמְנָה, וַהֲרֵי (ולא) כָתוּב וַיֶּחֱמוּ. אֶלָּא שֶׁהֵם כֻּלָּם נְקֵבוֹת.</p>"],[9522011329,"<p>וְעַל זֶה הִתְכַּוֵּן יַעֲקֹב לַעֲשׂוֹת מַעֲשֶׂה בְּחָכְמָה, וְזֶהוּ שֶׁכָּתוּב וַיִּקַּח לוֹ יַעֲקֹב מַקַּל לִבְנֶה לַח וְגוֹ'. פָּתַח (רבי אלעזר) וְאָמַר, כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ. בּא רְאֵה, כִּי יַעֲקֹב בָּחַר לוֹ יָהּ, עַד כָּאן לֹא יָדַעְנוּ מִי בָחַר אֶת מִי - אִם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּחַר אֶת יַעֲקֹב, אִם יַעֲקֹב בָּחַר לוֹ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶלָּא מִמַּה שֶּׁגִּלָּה הַכָּתוּב יָדַעְנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל אֶת יַעֲקֹב לְגוֹרָלוֹ, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>בֹּא רְאֵה, כָּךְ גַּם יַעֲקֹב בָּחַר אֶת יְרֻשָּׁתוֹ וְגוֹרָלוֹ לְחֶלְקוֹ, וְעָלָה לְמַעְלָה מִכָּל הַדְּרָגוֹת וְנָטַל אוֹתוֹ לְגוֹרָלוֹ. מַקַּל לִבְנֶה לַח - הַיְנוּ הַדַּרְגָּה הַלְּבָנָה שֶׁל צַד הַיָּמִין. וְלוּז וְעַרְמוֹן - הַיְנוּ הַדַּרְגָּה הָאֲדֻמָּה שֶׁל צַד שְׂמֹאל.</p>\n<p>וַיְפַצֵל בָּהֶם פְּצָלוֹת לְבָנוֹת - שֶׁהֶעֱבִיר מִזֶּה אֶת הַדִּין וְחִבֵּר אוֹתוֹ לַיָּמִין, וְהוּא נִכְנַס בֵּינֵיהֶם וְנָטַל אוֹתָם יַחַד וְנַעֲשָׂה הַכֹּל אֶחָד בִּשְׁנֵי גְוָנִים. וְעִם כָּל זֶה מַחְשּף הַלָּבָן, שֶׁיִּתְגַּלֶּה הַלָּבָן עַל הָאָדם. וְכָל זֶה לָמָּה? לִמְשֹׁךְ אֶת הַדַּרְגָּה הַזּוֹ שֶׁל גּוֹרָלוֹ בְּרָכוֹת מִן הַמַּעְיָן שֶׁל הַכֹּל (של הנחל), וְלָשִׂים אֶת הַדַּרְגָּה הַזּוֹ שֶׁהִיא שָׁלֹשׁ כְּאַחַת.</p>\n<p>בָּרְהָטִים בְּשִׁקֲתוֹת הַמָּיִם - כְּמוֹ שֶׁבֵּאַרְנוּ, וְאָז בַּמַּעֲשֶׂה הַזֶּה שֶׁל חָכְמָה שׁוֹפְעוֹת הַבְּרָכוֹת לְמַטָּה וּמֻשְׁקִים (ומתברכים) כָּל הָעוֹלָמוֹת וְשׁוֹרוֹת עֲלֵיהֶם הַבְּרָכוֹת, כְּמוֹ שֶׁפֵּרְשׁוּהָ (בראשית מט) שֶׁכָּתוּב בַּבֹּקֶר יֹאכַל עַד וְגוֹ', וְאַחַר מִכָּאן - וְלָעֶרֶב יְחַלֵּק שָׁלָל, שֶׁיִּתְבָּרְכוּ כָּל הָעוֹלָמוֹת לְמַטָּה. וְיַעֲקֹב נָטַל חֶלְקוֹ מֵאוֹתָן הַבְּרָכוֹת שֶׁשּׁוֹרוֹת עָלָיו לְמַטָּה, מִשּׁוּם שֶׁהוּא חֶלְקוֹ וְגוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וַיִּקַּח לוֹ מַקַּל לִבְנֶה וְגוֹ'. מִשְׁנָה. הָרָצוֹן שֶׁל הַמַּעֲשֶׂה, קִשְׁרֵי הָאֱמוּנָה, קוֹל הַקּוֹל שֶׁל הַקּוֹלוֹת, מִתְעוֹרֵר מִמַּעְלָה לְמַטָּה. אָנוּ הָיִינוּ פְּתוּחֵי עֵינַיִם. הַגַּלְגַּל סוֹבֵב מִמַּעְלָה לְכַמָּה צְדָדִים, קוֹל שֶׁל נְעִימוּת הִתְעוֹרֵר. הִתְעוֹרְרוּ יְשֵׁנִים נִרְדָּמִים שֶׁשֵּׁנָה בִּנְחִירֵיהֶם, וְלֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים וְלֹא רוֹאִים, אֲטוּמֵי אָזְנַיִם, כִּבְדֵי לֵב, יְשֵׁנִים וְאֵין יוֹדְעִים, הַתּוֹרָה עוֹמֶדֶת לִפְנֵיהֶם וְלֹא מַשְׁגִּיחִים וְלֹא יוֹדְעִים בַּמֶּה מִסְתַּכְּלִים, רוֹאִים וְלֹא רוֹאִים. הַתּוֹרָה מְרִימָה קוֹלוֹת: הִסְתַּכְּלוּ טִפְּשִׁים, יִפָּתְחוּ הָעֵינַיִם וְתֵדְעוּ. אֵין מִי שֶׁיַּשְׁגִּיחַ, אֵין מִי שֶׁיַּרְכִּין אָזְנוֹ. עַד מָתַי תִּהְיוּ בְּתוֹךְ הַחֲשֵׁכָה שֶׁל רְצוֹנְכֶם? הִסְתַּכְּלוּ לָדַעַת, וְיִתְגַּלֶּה לָכֶם הָאוֹר הַמֵּאִיר.</p>\n<p>בִּזְמַן שֶׁיַּעֲקֹב הַשָּׁלֵם, מִתּוֹךְ הַצָּרָה שֶׁל הָאָרֶץ וְרָשׁוּת אַחֶרֶת, בְּתוֹךְ דְּרָגוֹת זָרוֹת דָּחָה אֶת כֻּלָּם, וּבָחַר חֵלֶק גּוֹרָלוֹ וְנַחֲלָתוֹ, הָאוֹר מִתּוֹךְ הַחֲשֵׁכָה, חָכְמָה מִתּוֹךְ הַטִּפְּשׁוּת, וְכִבֵּד אֶת רִבּוֹנוֹ, כְּשֶׁהָיָה עוֹמֵד בְּתוֹךְ הָרָשׁוּת שֶׁל אֵל זָר. עַל כֵּן כָּתוּב (ישעיה כט) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ.</p>\n<p>הַקֶּשֶׁר שֶׁל הַקֶּשֶׁר הַטָּהוֹר הָיָה עוֹלֶה לִפְנַי וְלִפְנִים טֶרֶם שֶׁמָּצָא מָקוֹם לְבֵית מוֹשָׁבוֹ. אוֹתוֹ מָקוֹם אֵינוֹ מָקוֹם, לֹא נִמְצָא לְמַעְלָה וּלְמַטָּה, נֶאֱבָד מִן הַכֹּל. אֲבַדּוֹן הוּא מִן הַכֹּל, אֲבַדּוֹן זָכָר. סמא\"ל שֶׁיָּצָא מֵהִתּוּךְ שֶׁל הַחֹזֶק שֶׁל יִצְחָק, אֲבַדּוֹן וּמָוֶת הִיא הַנְּקֵבָה שֶׁלּוֹ, הַנָּחָשׁ הַקַּדְמוֹנִי, אֵשֶׁת זְנוּנִים, שֶׁכָּתוּב (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת. וְאֵלּוּ שְׁנַיִם - אֲבַדּוֹן וּמָוֶת - שִׁמְעוּ אֶת תֹּקֶף רְצוֹן הַמֶּלֶךְ.</p>\n<p>הַסּוֹד וְהַסֵּתֶר (הסתום) הַנִּסְתָּר הָעֶלְיוֹן נֶאֱבָד (הטמיר) מֵהַכֹּל, טָמִיר מֵרַעְיוֹנוֹת (מעינים) וְהִרְהוּרִים. (מי שנמשך אחר אלו, נאבד מן הכל, הכל בהפוך זה מזה, אשריו של איש שלום, כיעקב שעולה ולא נחשכו העינים בעשן הזה, וזכה להתקרב באמת חותם המלך הקדוש, בא ראה, הטמיר העליון מהכל) מִמֶּנּוּ יָצְאָה הָאוֹת י', הַנְּקֻדָּה הָעֶלְיוֹנָה. מֵהַנְּקֻדָּה הָעֶלְיוֹנָה הַזּוֹ יָצָא הַכֹּל, הִמְשִׁיךְ וְהוֹצִיא ה', הָאֵם הָעֶלְיוֹנָה שֶׁמַּשְׁקָה אֶת הַכֹּל. מִזֶּה יָצָא ו', הַסּוֹד שֶׁל שֵׁשׁ שֶׁאוֹחֵז אֶת כָּל הַצְּדָדִים, שֶׁהוּא מַקַּל לִבְנֶה לַח וְלוּז וְעַרְמוֹן.</p>\n<p>שְׁתֵּי הַזְּרוֹעוֹת שֶׁאוֹחֲזוֹת בּוֹ, אֵלּוּ יוֹצְאוֹת וְאוֹחֲזוֹת בַּהֵ\"א הַתַּחְתּוֹנָה לְחַבֵּר הַמַּשְׁכּוֹן יַחַד וְלִהְיוֹת אֶחָד. וְאָז שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת נִהְיוֹת אַחַת. וְהַלָּבָן נֶחְקָק עַל הַגְּוָנִים וְעוֹלֶה עַל הַגְּוָנִים כֻּלָּם. זֶהוּ שֶׁכָּתוּב מַחְשּׁף הַלָּבָן, וְאָז נִקְרָא (זכריה כ) ה' אֶחָד וּשְׁמוֹ אֶחָד. וְאָז (תהלים כג) ה' רֹעִי לֹא אֶחְסָר, וְכָתוּב בִּנְאוֹת דֶּשֶׁא יַרְבִּיצֵנִי עַל מֵי מְנֻחוֹת יְנַהֲלֵנִי נַפְשִׁי יְשׁוֹבֵב וְגוֹ'. ע\"כ תוספתא.</p>\n<p>וַיִּקַּח לוֹ יַעֲקֹב (בראשית ל), בָּחַר לוֹ לְחֶלְקוֹ וּלְגוֹרָלוֹ, מַקַּל לִבְנֶה לַח, צַד יָמִין, גָּוֶן לָבָן. לַח, הוּא צַד שֶׁל הַמַּיִם. וְלוּז, זֶה צַד שֶׁל הַשְּׂמֹאל, אָדם כְּוָרֹד. וְעַרְמוֹן, כָּלוּל זֶה בָּזֶה. וְכֻלָּם אוֹחֵז הַיָּמִין הַלָּבָן בְּצִבְעוֹ וְעוֹלֶה בָהֶם, שֶׁכָּתוּב מַחְשּף הַלָּבָן, שֶׁאַף עַל גַּב שֶׁאוֹחֵז לִשְׁנֵי הַצְּדָדִים, לוֹקֵחַ (נוטה) חֶלְקוֹ לְצַד יָמִין, וְנֶחְקָק בְּכֻלָּם, בְּצַד זֶה וּבְצַד זֶה, אָז נִקְרָא גֶבֶר שָׁלֵם, שָׁלֵם בַּכֹּל.</p>\n<p>מַה כָּתוּב אַחֲרָיו? (שם) וְהָיָה בְּכָל יַחֵם הַצּאן הַמְקֻשָּׁרוֹת וְשָׂם יַעֲקֹב אֶת הַמַּקְלוֹת וְגוֹ'. סֵתֶר הַסְּתָרִים לְחַכְמֵי לֵב נִמְסָר. בְּתוֹךְ מַחֲנוֹת עֶלְיוֹנִים קְדוֹשִׁים יֵשׁ מַדְרֵגוֹת עֶלְיוֹנוֹת אֵלּוּ עַל אֵלּוּ, אֵלּוּ פְּנִימִיִּים וְאֵלּוּ לְבַחוּץ. אֵלּוּ הַפְּנִימִיִּים מִתְחַבְּרִים בַּמֶּלֶךְ הַקָּדוֹשׁ, וּמִתְחַבְּרִים בְּיִשְׂרָאֵל, בָּנִים קְדוֹשִׁים לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֵלּוּ נִקְרָאוֹת הַצּאן הַמְקֻשָּׁרוֹת, מַחֲנוֹת שֶׁל אֵלּוּ מִקֻשָּׁרוֹת, מַעְלָה וּמַטָּה.</p>\n<p>בְּשָׁעָֹה שֶׁהַתְּשׁוּקָה שֶׁלָּהֶם לְגַבֵּי הַזֹּהַר הָעֶלְיוֹן שֶׁלְּמַעְלָה, עַמּוּד הָאֶמְצָעִי, יַעֲקֹב הַשָּׁלֵם לָקַח אוֹתָם הַמַּקְלוֹת, תְּפִלִּין שֶׁל רֹאשׁ, בָּרְהָטִים, מָקוֹם וּמוֹשָׁב, לַהֲנָחַת הַתְּפִלִּין. וּמִכָּאן לוֹקְחִים אוֹר וְזִיו כָּל הַחֲיָלוֹת וּמַחֲנוֹת הָעֶלְיוֹנִים, אֵלּוּ שֶׁמִּתְקַשְּׁרִים לְמַעְלָה וּמִתְקַשְּׁרִים לְמַטָּה. כֵּיוָן שֶׁאֵלּוּ לוֹקְחִים מִתּוֹךְ הָרְהָטִים שִׁקְתוֹת הַמַּיִם, אָז אֵלּוּ הָיוּ מְקוֹרוֹת וּנְבִיעוֹת לְהוֹרִיד לְמַטָּה וְלָתֵת לְכֻלָּם.</p>\n<p>וּמִשּׁוּם כָּךְ הִפְרִישׁ יַעֲקֹב בֵּין הַמַּדְרֵגוֹת הָעֶלְיוֹנוֹת הַקְּדוֹשׁוֹת לַמַּדְרֵגוֹת הָאֲחֵרוֹת שֶׁל שְׁאָר הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ל) וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ וְלֹא שָׁתָם עַל צֹאן לָבָן. (אלו) עֲדָרִים הִפְרִיד לוֹ לְעַצְמוֹ, שֶׁלֹּא יִהְיֶה לוֹ חֵלֶק בִּשְׁאָר הָאֻמּוֹת, וּכְמוֹ שֶׁהִפְרִישׁ לוֹ מַדְרֵגוֹת הָאֱמוּנָה לְמַעְלָה לְחֶלְקוֹ וּלְגוֹרָלוֹ, כָּךְ צָרִיךְ לְהַפְרִישׁ מַדְרֵגוֹת שֶׁל מַחֲנוֹת קְדוֹשִׁים לְמַטָּה, לִקְשֹׁר אוֹתָם עִמּוֹ בְּאֵלּוּ הַהֵיכָלוֹת שֶׁל הַגְּבִירָה.</p>\n<p>וְכֻלָּם רְשׁוּמִים בַּסִּימָן שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן, כְּמוֹ שֶׁיִּשְׂרָאֵל רְשׁוּמִים לְמַטָּה בֵּין כָּל שְׁאָר הָאֻמּוֹת, אֲף מַדְרֵגוֹת שֶׁל מַחֲנוֹת עֶלְיוֹנִים רְשׁוּמִים הֵם לְחֶלְקוֹ (של הקדשה) שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּין כָּל שְׁאָר הַחֲיָלוֹת וּמַחֲנוֹת עֶלְיוֹנִים. וְעַל זֶה בֵּרַר יַעֲקֹב אֶת אֵלּוּ לְחֶלְקוֹ וְגוֹרָלוֹ, רְשׁוּמִים לַחֵלֶק (בסוד) שֶׁל הָאֱמוּנָה, (משום כך כתוב כי י קב בחר לו יה ישראל לסגלתו, יה עליון הוא, ברר חלקו וגורלו סוד האמונה) אַף כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַר לוֹ מִכָּל שְׁאָר צְבָאוֹת וּמַחֲנוֹת שֶׁל הָעוֹלָם.</p>\n<p>וּמַחֲנוֹת עֶלְיוֹנִים נִפְרָדִים אֵלּוּ מֵאֵלּוּ. בְּשָׁעָה שֶׁזֹּהַר שֶׁל אֵשׁ בְּהֶאָרַת הַשְּׁכִינָה מִתְגַּלֶּה, כָּל הַמַּדְרֵגוֹת הָאֲחֵרוֹת הָאֵלּוּ מִתְבַּיְּשׁוֹת, וּמִתְכַּסּוֹת מֵהַזֹּהַר הַהוּא, וְלֹא יָכְלוּ לְהִתְקָרֵב אֵלָיו. וְכָל אֵלּוּ הַתִּקּוּנִים (מדרגות) הַקְּדוֹשִׁים, שֶׁהֵם תִּקּוּנִים שֶׁלּוֹ. בְּשָׁעָה שֶׁמִּתְגַּלֶּה הַזֹּהַר הַהוּא, מִיָּד שְׂמֵחִים וְעוֹלִים לְהִתְקָרֵב עִמּוֹ וּלְהִתְקַשֵּׁר אֶצְלוֹ, וְהוּא בָהֶם נִתְקָן, וְסוֹד זֶה - (בראשית ל) וְהָיָה הָעֲטֻפִים לְלָבָן וְהַקְּשֻׁרִים לְיַעֲקֹב.</p>\n<p>וְצָרִיךָ לְבָרֵר (לברך) וּלְהַבְדִּיל מַדְרֵגוֹת קְדוֹשׁוֹת (ס\"א לחלקו) שֶׁל חֶלְקוֹ מֵאֵלּוּ הַמַּדְרֵגוֹת שֶׁל שְׁאָר הָעַמִּים, וּבְכֻלָּם צָרִיךְ יַעֲקֹב הַקָּדוֹשׁ (בכור של הקדוש ברוך הוא להתקרב), וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא כָּתַב בַּתּוֹרָה, אֱמוּנָה שֶׁלּוֹ, בְּתוֹךְ צִדְדֵי (ס\"א סתרי) מִלִּים אֵלּוּ. אַשְׁרֵי חֶלְקוֹ.</p>"],[9522011330,"<p>רַבִּי יֵיסָא הַקָּטָן הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, זֶה שֶׁכָּתוּב (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק, הָיָה צָרִיךְ לִהְיוֹת לַצַּדִּיק, מַה זֶּה לְרֹאשׁ צַדִּיק? אָמַר לוֹ, רֹאשׁ צַדִּיק זוֹ הִיא הָעֲטָרָה הַקְּדוֹשָׁה, וּבֵאֲרוּהָ. עוֹד, רֹאשׁ צַדִּיק זֶה יַעֲקֹב, שֶׁנָּטַל אֶת הַבְּרָכוֹת וְהִשְׁפִּיעַ אוֹתָם לַצַּדִּיק, וּמִשָּׁם נִזְרְקוּ לְכָל עֵבֶר, וְכָל הָעוֹלָמוֹת מִתְבָּרְכִים.</p>\n<p>אֲבָל הִנֵּה בֵּאַרְנוּ, בְּרָכוֹת לְרֹאשׁ צַדִּיק - (ראש) צַדִּיק נִקְרָא אוֹתוֹ הַמָּקוֹם (ראש) שֶׁל הַבְּרִית, שֶׁמִּמֶּנּוּ יוֹצְאִים מַעְיָנוֹת הַחוּצָה. הַנֶּקֶב שֶׁל הַכַּד שֶׁיּוֹצֵא מִמֶּנּוּ הַיַּיִן הוּא הָרֹאשׁ, כָּךְ רֹאשׁ צַדִּיק, אוֹתוֹ מָקוֹם, כְּשֶׁזּוֹרֵק מַעְיָנוֹת לַנְּקֵבָה, נִקְרָא רֹאשׁ צַדִּיק. הַצַּדִּיק הוּא רֹאשׁ (ראש לכל הברכות) מִשּׁוּם שֶׁכָּל הַבְּרָכוֹת שְׁרוּיוֹת בּוֹ.</p>\n<p>עוֹד, אוֹתוֹ הָאָדָם שֶׁזּוֹכֶה לִשְׁמֹר אֶת אוֹת בְּרִית הַקֹּדֶשׁ וְעוֹשֶׂה אֶת מִצְווֹת הַתּוֹרָה נִקְרָא צַדִּיק, וּמֵרֹאשׁוֹ וְעַד רַגְלוֹ כָּךְ נִקְרָא. וּכְשֶׁהַבְּרָכוֹת שׁוֹפְעוֹת לָעוֹלָם, הֵן שׁוֹרוֹת עַל רֹאשׁוֹ, וּמִמֶּנּוּ עוֹמְדוֹת הַבְּרָכוֹת לָעוֹלָם בַּבָּנִים הַקְּדוֹשִׁים הַצַּדִּיקִים שֶׁהֵקִים.</p>\n<p>עוֹד שָׁאַל רַבִּי יֵיסָא וְאָמַר, כָּתוּב (תהלים לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי וְגוֹ'. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ שֶׁשָּׂרוֹ שֶׁל עוֹלָם אָמַר אוֹתוֹ. הוּא אָמַר אוֹתוֹ בְּחָכְמָה יוֹתֵר מִמַּה שֶּׁחוֹשְׁבִים בְּנֵי אָדָם. אָמַר לוֹ, בְּנִי, יָפֶה הוּא, שֶׁהֲרֵי בַּיִּחוּד הַקָּדוֹשׁ נֶאֱמַר נַעַר הָיִיתִי גַּם זָקַנְתִּי.</p>"],[9522011331,"<p>וְכָךְ הוּא, וְלֹא רָאִיתִי צַדִּיק נֶעֱזָב - זֶה הַשֶּׁבַח שֶׁל הַיִּחוּד שֶׁלֹּא נִמְצָא יוֹם לְלֹא לַיְלָה, שֶׁהִנֵּה הַלַּיְלָה תָּמִיד נִמְצָא בּוֹ, וְהַצַּדִּיק אָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה.</p>\n<p>וְזַרְעוֹ מְבַקֶּשׁ לָחֶם, מַה הוּא? אֶלָּא בְּשָׁעָה שֶׁזּוֹרֵק וְנִשְׁפָּע הַזֶּרַע, אֵינוֹ תוֹבֵעַ אֶת הַנְּקֵבָה, שֶׁהֲרֵי הִיא שׁוֹרָה עִמּוֹ, שֶׁאֵין נִפְרֶדֶת מִמֶּנּוּ לְעוֹלָמִים וּזְמִינָה הִיא אֶצְלוֹ, שֶׁהֲרֵי אֵין זֶרַע שׁוֹפֵעַ אֶלָּא בְּשָׁעָה שֶׁהַנְּקֵבָה זְמִינָה, וּתְשׁוּקַת שְׁנֵיהֶם יַחַד בְּדִבּוּק אֶחָד, שֶׁאֵין נִפְרָדִים, וְלָכֵן לֹא צָרִיךְ לִתְבֹּעַ אוֹתָהּ.</p>\n<p>אָמַר לוֹ, וּבִזְמַן הַגָּלוּת לֹא כָּךְ? אָמַר לוֹ, כָּתוּב זַרְעוֹ, וְאֵינוֹ. מָתַי יוֹצֵא? כְּשֶׁהַנְּקֵבָה בְּדִבּוּק אֶחָד עִם הַזָּכָר. וְאִם תֹּאמַר, לֹא רָאִיתִי צַדִּיק נֶעֱזָב - בִּזְמַן שֶׁל הַגָּלוּת מַה הִיא?</p>\n<p>אֶלָּא זֶה אָחוּז לְמַעְלָה וְלֹא נֶעֱזָב לְעוֹלָמִים. בִּזְמַן אַחֵר לֹא נֶעֱזָב מֵהַנְּקֵבָה, אָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה. אָחוּז לְמַעְלָה - בַּזְּמַן שֶׁל הַגָּלוּת. בִּזְמַן אַחֵר אוֹחֵז אֶת שְׁנֵי הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה, וּלְעוֹלָם אֵינוֹ נֶעֱזָב.</p>"],[9522011332,"<p>כָּתוּב (בראשית א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם, זֶה צַדִּיק, וְאַף עַל גַּב שֶׁנֶּאֱמַר בִּרְקִיעַ הַשָּׁמַיִם, אֶלָּא בִּרְקִיעַ הַשָּׁמַיִם וַדַּאי, שֶׁהוּא סִיּוּם הַגּוּף.</p>"],[9522011333,"<p>בֹּא רְאֵה, שְׁנֵי רְקִיעִים הֵם, וְהֵם הָרֵאשִׁית וְהַסִּיּוּם, זֶה כְּמוֹ זֶה. רֵאשִׁית הָרָקִיעַ הַשְּׁמִינִי בּוֹ שְׁקוּעִים כָּל הַכּוֹכָבִים, קְטַנִּים וּגְדוֹלִים, וְזֶהוּ הָרָקִיעַ הָעֶלְיוֹן הַנִּסְתָּר שֶׁמְּקַיֵּם הַכֹּל, וּמִמֶּנּוּ יוֹצֵא הַכֹּל, וְהוּא הַשְּׁמִינִי מִמַּטָּה לְמַעְלָה, וְהוּא הָרֵאשִׁית לְהוֹצִיא מִמֶּנּוּ הַכֹּל.</p>\n<p>כָּךָ הוּא הָרָקִיעַ הַשְּׁמִינִי מִמַּעְלָה לְמַטָּה, שֶׁבּוֹ שְׁקוּעִים כָּל הַכּוֹכָבִים, כָּל הָאוֹרוֹת וְהַמְּאוֹרוֹת, וְהוּא נוֹטֵל אֶת הַכֹּל, וְזֶה הַסִּיּוּם שֶׁל הַכֹּל. כְּמוֹ שֶׁאוֹתוֹ הָרָקִיעַ הַשְּׁמִינִי, שֶׁהוּא רֵאשִׁית הַכֹּל, תְּלוּיִים בּוֹ כָּל הָאוֹרוֹת, וְנוֹטֵל אוֹתָם, וּמִמֶּנּוּ יוֹצְאִים - כָּךְ גַּם זֶה, אוֹתוֹ רָקִיעַ הַשְּׁמִינִי תְּלוּיִים בּוֹ כָּל הָאוֹרוֹת וְנוֹטֵל אוֹתָם, וּמִמֶּנּוּ יָצְאוּ לְכָל הָעוֹלָמוֹת.</p>\n<p>הָרֵאשִׁית וְהַסִּיּוּם עוֹמְדִים כְּגָוֶן אֶחָד, וְעַל כֵּן הוּא הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא וְלֹא פוֹסְקִים מֵימָיו לְעוֹלָמִים, הַכֹּל שֶׁיִּהְיֶה הַסִּיּוּם כְּמוֹ הָרֵאשִׁית, וּמִשּׁוּם כָּךְ וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם, וִלָמָּה? לְהָאִיר עַל הָאָרֶץ.</p>\n<p>וְאַףֹ עַל גַּב שֶׁנֶּאֱמַר, הַכֹּל עוֹמְדִים כְּגָוֶן אֶחָד, וְזֶהוּ בֵּרוּר הַדָּבָר. מַה בֵּין זֶה לָזֶה? אֶלָּא זֶה מֵקִים וְזָן אֶת הָעוֹלָם הָעֶלְיוֹן שֶׁהוּא בּוֹ וְאֶת כָּל אוֹתָם הַצְּדָדִים הָעֶלְיוֹנִים, וְזֶה מֵקִים וְזָן אֶת הָעוֹלָם הַתַּחְתּוֹן וְאֶת כָּל אוֹתָם הַצְּדָדִים הַתַּחְתּוֹנִים.</p>\n<p>וְאִם תֹּאמַר, הָעוֹלָם שֶׁלְּמַעְלָה מִי הוּא? וַהֲרֵי (הוא) אוֹתוֹ הָרָקִיעַ הַשְּׁמִינִי הָעֶלְיוֹן הַנִּסְתָּר הוּא הָעוֹלָם שֶׁלְּמַעְלָה, וְכָךְ נִקְרָא, שֶׁהֲרֵי שְׁנֵי עוֹלָמוֹת הֵם, כְּמוֹ שֶׁנִּתְבָּאֵר. אֶלָּא הוּא עוֹלָם עֶלְיוֹן, וְכָל אוֹתָם שֶׁיּוֹצְאִים מִמֶּנּוּ נִקְרָאִים עַל שְׁמוֹ, וְאוֹתָם שֶׁיּוֹצְאִים מִן הָעוֹלָם הַתַּחְתּוֹן נִקְרָאִים עַל שְׁמוֹ, וְכָל זֶה וָזֶה הַכֹּל אֶחָד, בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>"],[9522011334,"<p>בֹּא רְאֵה, (תהלים קד) יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. מִי הַלְּבָנוֹן? הֲרֵי פֵּרְשׁוּהוּ וְנִתְבָּאֵר. הַפָּסוּק הַזֶּה, אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ - אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ, בְּאֵיזֶה מָקוֹם? בַּלְּבָנוֹן. וְאֵלּוּ הֵן שְׁתֵּי הַצִּפֳּרִים שֶׁאָמַרְנוּ בְּכַמָּה מְקוֹמוֹת, וּמֵאֵלּוּ נִפְרָדוֹת כַּמָּה צִפֳּרִים אֲחֵרוֹת. אֲבָל אֵלּוּ עֶלְיוֹנוֹת, וְיוֹצֵאת מִן לְבָנוֹן, שֶׁהוּא (סתום) לְמַעְלָה, וְסוֹד הַדָּבָר - וּלְלָבָן שְׁתֵּי בָנוֹת וְגוֹ'.</p>\n<p>חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ, (זו לאה) בְּאוֹתָם שִׁשָּׁה בָנִים עֶלְיוֹנִים, שֵׁשֶׁת צִדְדֵי הָעוֹלָם, כְּמוֹ שֶׁנִּתְבָּאֵר. לָמָּה נִקְרָא חֲסִידָה? אֶלָּא הָעוֹלָם הָעֶלְיוֹן הַזֶּה, אַף עַל גַּב שֶׁהוּא נְקֵבָה, קוֹרְאִים לוֹ זָכָר. שֶׁכַּאֲשֶׁר מִתְפַּשֵּׁט, כָּל טוֹב וְכָל הָאוֹר יוֹצֵא מִמֶּנּוּ.</p>\n<p>וּמִשּׁוּם שֶׁהִיא חֲסִידָה, יוֹצֵא (משם) מִמֶּנָּה חֶסֶד, שֶׁהוּא הָאוֹר הָרִאשׁוֹן, שֶׁכָּתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר. וְעַל זֶה בְּרוֹשִׁים בֵּיתָהּ. בְּרוֹשִׁים - אַל תִּקְרֵי בְּרוֹשִׁים אֶלָּא בְּרָאשִׁים, שֶׁהֲרֵי הָעוֹלָם הָאַחֵר בַּתַּחְתּוֹנִים בֵּיתָהּ, וְהִיא בֵּית הַדִּין שֶׁל הָעוֹלָם, וְלִפְעָמִים נִקְרָא כְּמוֹ שֶׁלְּמַעְלָה בְּכָל אוֹתָם הַשֵּׁמוֹת.</p>\n<p>וְעַל הַמָּקוֹם הַזֶּה כָּתוּב, וַיִּנָּחֶם ה', וַיִּתְעַצֵּב אֶל לִבּוֹ. חֲרוֹן אַף ה'. שֶׁהֲרֵי בַּמָּקוֹם הַזֶּה תָּלוּי. שֶׁהֲרֵי כָּל מַה שֶּׁלְּמַעְלָה, הַכֹּל הוּא בְּאוֹר, חַיִּים לְכָל הַצְּדָדִים, וְעַל כֵּן שָׁנִינוּ, אֵין עַצְבוּת לִפְנֵי הַמָּקוֹם, בְּדִיּוּק לִפְנֵי, וְעַל זֶה כָּתוּב (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה בּאוּ לְפָנָיו בִּרְנָנָה. עִבְדוּ אֶת ה' בְּשִׂמְחָה - כְּנֶגֶד הָעוֹלָם הָעֶלְיוֹן. בֹּאוּ לְפָנָיו בִּרְנָנָה - כְּנֶגֶד הָעוֹלָם הַתַּחְתּוֹן. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, מִשּׁוּם כָּךְ כָּתוּב (דברים לג) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךְ עַם נוֹשַׁע בַּה' מָגֵן עֶזְרֶךְ וַאֲשֶׁר חֶרֶב גַּאֲוָתֶךְ וְיִכָּחֲשׁוּ וְגוֹ'.</p>"],[9522011335,"<p>וַיַּצֵג אֶת הַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים וְגוֹ'. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (משלי ט) אִם חָכַמְתָּ חָכַמְתָּ לָּךְ וְלַצְתָּ לְבַדְּךְ תִשָּׂא. אִם חָכַמְתָּ חָכַמְתָּ לָּךְ - בּא רְאֵה, אוֹי לְאוֹתָם רִשְׁעֵי הָעוֹלָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּדִבְרֵי תוֹרָה. וּכְשֶׁהֵם מַשְׁגִּיחִים בָּהּ - מִשּׁוּם שֶׁאֵין לָהֶם שֵׂכֶל, דִּבְרֵי הַתּוֹרָה נִרְאִים בְּעֵינֵיהֶם כְּאִלּוּ כֻּלָּם מְלֵאִים רֵיקָנוּת וְאֵין בָּהֶם תּוֹעֶלֶת, וְהַכֹּל מִשּׁוּם שֶׁהֵם רֵיקָנִים מִדַּעַת וְשֵׂכֶל, שֶׁהֲרֵי כָּל דִּבְרֵי הַתּוֹרָה, כֻּלָּם דְּבָרִים עֶלְיוֹנִים וְנִכְבָּדִים, וְכָל דָּבָר וְדָבָר שֶׁכָּתוּב בָּהּ יְקָרָה הִיא מִפְּנִינִים וְכָל חֲפָצִים לֹא יִשְׁווּ בָהּ (בתורה).</p>\n<p>וְכָל אוֹתָם הַטִּפְּשִׁים אֲטוּמֵי הַלֵּב, כְּשֶׁרוֹאִים דִּבְרֵי תוֹרָה, לֹא דַי לָהֶם שֶׁלֹּא יוֹדְעִים, אֶלָּא שֶׁהֵם אוֹמְרִים שֶׁהֵם דְּבָרִים פְּגוּמִים, דְּבָרִים שֶׁאֵין בָּהֶם תּוֹעֶלֶת. אוֹי לָהֶם כְּשֶׁיִּתְבַּע אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עֶלְבּוֹן הַתּוֹרָה, וְיֵעָנְשׁוּ עֹנֶשׁ שֶׁמּוֹרְדִים בְּרִבּוֹנָם.</p>\n<p>מַה כָּתוּב בַּתּוֹרָה? כִּי לֹא דָבָר רֵק הוּא מִכֶּם. וְאִם הוּא רֵק - הוּא מִכֶּם, שֶׁהֲרֵי כָּל הַתּוֹרָה מְלֵאָה מִכָּל אֲבָנִים טוֹבוֹת וּמַרְגָּלִיּוֹת יְקָרוֹת מִכָּל הַטּוֹבוֹת שֶׁל הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר וְכָל חֲפָצִים לֹא יִשְׁווּ בָהּ, וְאֵיךְ יֹאמְרוּ שֶׁהִיא רֵיקָה?!</p>\n<p>וּשְׁלֹמֹה הַמֶּלֶךְ אָמַר, אִם חָכַמְתָּ חָכַמְתָּ לָּךְ. שֶׁכַּאֲשֶׁר יִתְחַכֵּם אָדָם בַּתּוֹרָה, זוֹהִי תּוֹעֶלֶת לוֹ, שֶׁהֲרֵי בַּתּוֹרָה לֹא יָכוֹל לְהוֹסִיף אֲפִלּוּ אוֹת אַחַת. וְלַצְתָּ לְבַדְּךְ תִשָּׂא, שֶׁהֲרֵי הַתּוֹרָה לֹא יִגָּרַע כְּלוּם מֵהַשֶּׁבַח שֶׁלָּהּ, וְהַלֵּיצָנוּת הִיא שֶׁלּוֹ וְנִשְׁאֶרֶת בּוֹ לְהַאֲבִיד אוֹתוֹ מִן הָעוֹלָם הַזֶּה וּמִן הָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, כַּאֲשֶׁר הָאוֹתִיּוֹת הָעֶלְיוֹנוֹת כֻּלָּן מִתְחַבְּרוֹת בַּדַּרְגָּה הַזּוֹ, הַסּוֹף שֶׁל כָּל הַדְּרָגוֹת הַקְּדוֹשׁוֹת הָעֶלְיוֹנוֹת, וּמִתְמַלֵּאת מֵהֶם וּמִתְבָּרֶכֶת מִן הָעוֹלָם הָעֶלְיוֹן, אָז הַדַּרְגָּה הַזּוֹ עוֹמֶדֶת לְהַשְׁקוֹת אֶת כָּל הָעֲדָרִים, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְכָל אֶחָד וְאֶחָד נִשְׁקָה מִדִּין וְרַחֲמִים.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיַּצֵּג אֶת הַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים וְגוֹ'. שֶׁיַּעֲקֹב רָצָה לְתַקֵּן תְּפִלַּת עַרְבִית, וּלְהָאִיר לַלְּבָנָה וּלְהַשְׁקוֹת וּלְבָרֵךְ אוֹתָהּ מִכָּל הַצְּדָדִים, שֶׁכָּתוּב וַיַּצֵּג אֶת הַמַּקְלוֹת, אֵלּוּ דִּינִים וּגְבוּרוֹת שֶׁיּוֹצְאִים מִן הַגְּבוּרָה שֶׁלְּמַעְלָה.</p>\n<p>וְכַאֲשֶׁר יַעֲקֹב רָצָה לְתַקֵּן אֶת הַדַּרְגָּה הַזּוֹ, סִלֵּק אֶת כָּל אוֹתָם הַדִּינִים וְהַגְּבוּרוֹת מִמֶּנָּה, וְהֵקִים אוֹתָם בָּרְהָטִים, בְּאוֹתָם אַרְבַּעַת הָרְהָטִים שֶׁעוֹמְדִים תַּחַת זוֹ בְּאֵר חֲפָרוּהָ שָׂרִים, שֶׁמִּתְמַלֵּאת מֵאוֹתָם הַנְּחָלִים וְהַמַּעְיָנוֹת הָעֶלְיוֹנִים. מִשּׁוּם שֶׁכַּאֲשֶׁר הַמַּיִם יוֹצְאִים מֵהַבְּאֵר הַקְּדוֹשָׁה הַזּוֹ, אֵלּוּ הָאַרְבָּעָה נוֹטְלִים הַכֹּל, וְעַל כֵּן נִקְרָאִים רְהָטִים, וּמִשָּׁם כֻּלָּם בָּאִים לִשְׁתּוֹת. וְאוֹתָם דִּינִים וּגְבוּרוֹת, כֻּלָּם עוֹמְדִים שָׁם לִטֹּל אֶת כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ.</p>\n<p>אֲשֶׁר תָּבאנָה הַצֹּאן לִשְׁתּוֹת לְנֹכַח הַצֹאן, אֵלּוּ כְּנֶגֶד אֵלּוּ. וַיֵּחַמְנָה, מַה זֶּה וַיֵּחַמְנָה? שֶׁכַּאֲשֶׁר מִתְעַטְּרִים בְּדִין, מִתְחַמְּמִים בְּאוֹתוֹ הַדִּין, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וּמְעַיְּנִים בְּדַרְכֵי בְּנֵי הָאָדָם, הֵן לְטוֹב הֵן לְרַע.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב אַחֲרָיו, וַיֶּחֱמוּ הַצּאן אֶל הַמַּקְלוֹת. מִשּׁוּם שֶׁאוֹתָם הַמַּקְלוֹת הָיוּ מִתְחַמְּמִים וּמַשְׁגִּיחִים בְּדִינֵי הָעוֹלָם, וְנִפְקָדִים עָלָיו, וְנִדּוֹנִים אֲנָשִׁים עֲלֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ד) בִּגְזֵרַת מַלְאָכִים הַדָּבָר וּבִפְקֻדַּת קְדוֹשִׁים הַגְּזֵרָה וְגוֹ'.</p>\n<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים סג) דָּבְקָה נַפְשִׁי אַחֲרֶיךְ בִּי תָּמְכָה יְמִינֶךְ. בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל, דָּבְקָה נַפְשִׁי אַחֲרֶיךְ - מִשּׁוּם שֶׁדָּוִד הַמֶּלֶךְ הָיָה מַדְבִּיק תָּמִיד אֶת נַפְשׁוֹ אַחֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא חָשַׁשׁ לִדְבָרִים אֲחֵרִים שֶׁל הָעוֹלָם, אֶלָּא לְהַדְבִּיק נַפְשׁוֹ וּרְצוֹנוֹ בּוֹ. וְכֵיוָן שֶׁהוּא הָיָה נִדְבָּק בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, הָיָה תּוֹמֵךְ בּוֹ וְלֹא עוֹזֵב אוֹתוֹ. מִכָּאן שֶׁכַּאֲשֶׁר אָדָם בָּא לְהִדָּבֵק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹחֵז בּוֹ וְלֹא עוֹזֵב אוֹתוֹ.</p>\n<p>דָּבָר אַחֵר דָּבְקָה נַפְשִׁי אַחֲרֶיךְ - לְהִתְעַטֵּר דַּרְגָּתוֹ לְמַעְלָה. שֶׁהֲרֵי כַּאֲשֶׁר נִדְבֶּקֶת הַדַּרְגָה הַהִיא (שלו נתברכה, וכשהתגלתה) בַּדְּרָגוֹת הָעֶלְיוֹנוֹת לַעֲלוֹת אַחֲרֵיהֶן, אָז הַיָּמִין אוֹחֵז בָּהּ לְהַעֲלוֹתָהּ וּלְחַבְּרָהּ בְּחִבּוּר אֶחָד כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר וְתֹאחֲזֵנִי יְמִינֶךְ, וְכָתוּב וִימִינוֹ תְחַבְּקֵנִי, וְעַל כֵּן בִּי תָּמְכָה יְמִינֶךְ.</p>\n<p>וּכְשֶׁאוֹחֵז בּוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, אָז כָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְחַבְּקֵנִי. וְהוּא יִחוּד אֶחָד וְחִבּוּר אֶחָד. וּכְשֶׁהוּא חִבּוּר אֶחָד, אָז מִתְמַלֵּאת אוֹתָהּ דַּרְגָּה שֶׁלּוֹ וּמִתְבָּרֶכֶת.</p>\n<p>וּכְשֶׁמִּתְמַלְּאִים כָּל אוֹתָם הָרְהָטִים, מִתְמַלְּאִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְכָל הָעֲדָרִים מֻשְׁקִים, כָּל אֶחָד וְאֶחָד לְצִדּוֹ. וּכְשֶׁבָּא יַעֲקֹב לְתַקֵּן אֶת הַדַּרְגָּה הַזּוֹ, בָּחַר לוֹ צַד הַיָּמִין שֶׁרָאוּי לוֹ, וְהַצַּד הָאַחֵר שֶׁלֹּא רָאוּי לוֹ נִפְרַד מִמֶּנּוּ, כְּמוֹ שֶׁכָּתוּב וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ וְלֹא שָׁתָם עַל צֹאן לָבָן. לְבַדּוֹ - הָיָה לְבַדּוֹ שֶׁלֹּא יִשְׁתַּמֵּשׁ בַּתּוֹעֵבוֹת הָאֲחֵרוֹת שֶׁבַּצְּדָדִים הָאֲחֵרִים. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁעֲלֵיהֶם כָּתוּב (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ וּבְךְ בָּחַר ה' וְגוֹ'.</p>\n<p>וּבֹא וּרְאֵה, יַעֲקֹב הוּא הַמְשֻׁבָּח שֶׁל הָאָבוֹת וְהוּא הַכְּלָל שֶׁל כֻּלָּם, וּמִשּׁוּם שֶׁהוּא הַכְּלָל שֶׁל הַכֹּל, מִשּׁוּם כָּךְ הוּא עוֹמֵד לְהָאִיר לַלְּבָנָה, שֶׁיַּעֲקֹב הוּא עוֹמֵד לְתַקֵּן אֶת תְּפִלַּת עַרְבִית.</p>\n<p>וְכָל הַתִּקּוּן הַהוּא הוּא כָּרָאוּי לוֹ. כָּל אוֹתָם הַצְּדָדִים הַקְּדוֹשִׁים, כֻּלָּם בְּתִקּוּן הִתְקִין בְּצִדּוֹ, וְהִפְרִיד חֶלְקוֹ מֵחֶלְקָם שֶׁל שְׁאָר הָעַמִּים. אֵלּוּ הַצְּדָדִים הָעֶלְיוֹנִים הַקְּדוֹשִׁים בִּקְדֻשָּׁה עֶלְיוֹנָה, וְאֵלּוּ צְדָדִים טְמֵאִים בְּטֻמְאוֹת הַטֻּמְאָה.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ, שֶׁכָּתוּב וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ. וַיָּשֶׁת לוֹ - שֶׁהִתְקִין תִּקּוּנִים לָאֱמוּנָה. לְבַדּוֹ - כְּמוֹ שֶׁנֶּאֱמַר וּבְךְ בָּחַר ה' לִהְיוֹת לוֹ לְעַם סְגֻלָּה מִכָּל הָעַמִּים. וְלֹא שָׁתָם עַל צֹאן לָבָן - שֶׁלֹּא שָׂם חֶלְקוֹ וְגוֹרָלוֹ עִמָּהֶם.</p>\n<p>וְעַל כֵּן יַעֲקֹב, שְׁלֵמוּת הָאָבוֹת, הִתְקִין סוֹד הָאֱמוּנָה, וְהִפְרִיד חֶלְקוֹ וְגוֹרָלוֹ מֵהַחֵלֶק וְהַגּוֹרָל שֶׁל שְׁאָר הָעַמִּים. וְעַל זֶה כָּתוּב וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>\n<p>רַבִּי אַבָּא אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהֵם עֶלְיוֹנִים עַל הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מִשּׁוּם שֶׁדַּרְגָּתָם לְמַעְלָה, וְהַדְּרָגוֹת שֶׁל הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לְמַטָּה. אֵלּוּ בְּצַד הַקְּדֻשָּׁה, וְאֵלּוּ בְּצַד הַטֻּמְאָה. אֵלּוּ לְיָמִין, וְאֵלּוּ לִשְׂמֹאל.</p>\n<p>כֵּיוָן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ מַה כָּתוּב? (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב. וּמִשּׁוּם כָּךְ כָּתוּב הוֹשִׁיעָה יְמִינְךְ וַעֲנֵנִי. וְהַשְּׂמֹאל מִתְגַּבֵּר וְהַטֻּמְאָה מִתְחַזֶּקֶת, עַד שֶׁיִּבְנֶה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בֵּית הַמִּקְדָּשׁ וִיתַקֵּן אֶת הָעוֹלָם עַל תִּקּוּנוֹ, וְיַחְזְרוּ דְבָרָיו כָּרָאוּי, וְיַעֲבֹר צַד הַטֻּמְאָה מִן הָעוֹלָם. וְהִנֵּה נֶאֱמַר, שֶׁכָּתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ וְגוֹ', וְכָתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'.</p>\n<p>וְיִשָּׁאֵר הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, כְּמוֹ שֶׁכָּתוּב וְהָאֱלִילִים כָּלִיל יַחֲלֹף, וְכָתוּב וְנִשְׂגָּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא. הוּא לְבַדּוֹ, כְּמוֹ שֶׁכָּתוּב (דברים לב) וְאֵין עִמּוֹ אֵל נֵכָר, מִשּׁוּם שֶׁיִּכְלֶה כֹּחַ הַטֻּמְאָה מִן הָעוֹלָם, וְלֹא יִשָּׁאֵר לְמַעְלָה וּלְמַטָּה אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, וְיִשְׂרָאֵל לַעֲבוֹדָתוֹ, עַם קָדוֹשׁ. וְיִקָּרֵא קָדוֹשׁ, שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לַחַיִּים בִּירוּשָׁלם. וְאָז יִהְיֶה מֶלֶךְ יְחִידִי לְמַעְלָה וּלְמַטָּה, וְעַם יְחִידִי לַעֲבוֹדָתוֹ, כְּמוֹ שֶׁכָּתוּב וּמִי כְּעַמְּךְ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ.</p>"],[9522011336,"<p>רַבִּי יִצְחָק וְרַבִּי יֵיסָא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יֵיסָא, הִנֵּה שְׁכִינָה אֶצְלֵנוּ, נִתְעַסֵּק בְּדִבְרֵי תוֹרָה, שֶׁכָּל מִי שֶׁעוֹסֵק בְּדִבְרֵי תוֹרָה וּמִשְׁתַּדֵּל בָּהּ, זוֹכֶה לְהַמְשִׁיךְ אוֹתָהּ עִמּוֹ.</p>\n<p>פָּתַח רַבִּי יִצְחָק וְאָמַר, (תהלים יח) חַי ה' וּבָרוּךְ צוּרִי וְיָרוּם אֱלוֹהֵי יִשְׁעִי. הַפָּסוּק הַזֶּה הוּא סוֹד. חַי ה', וְכִי לֹא יָדַעְנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא חַי? אֶלָּא אֲפִלּוּ צַדִּיק גָּמוּר, הוּא נִקְרָא חַי, שֶׁהֲרֵי חַי - צַדִּיק הוּא לְמַעְלָה וְצַדִּיק הוּא לְמַטָּה. לְמַעְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא חַי - לְמַטָּה הַצַּדִּיק נִקְרָא חַי, שֶׁכָּתוּב (שמואל ב כג) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי. לָמָּה נִקְרָא חַי? מִשּׁוּם שֶׁהוּא צַדִּיק, שֶׁהֲרֵי צַדִּיק נִקְרָא חַי, חֵי הָעוֹלָמִים. וּבָרוּךְ צוּרִי - הַכֹּל אֶחָד. חַי וּבָרוּךְ - שֶׁלֹּא נִפְרָדִים זֶה מִזֶּה. שֶׁכַּאֲשֶׁר מִתְחַבְּרִים יַחַד נִקְרָא בְּאֵר מַיִם חַיִּים. זֶה נוֹבֵעַ הַחוּצָה, וְזֶה מִתְמַלֵּא מִמֶּנּוּ.</p>\n<p>וְיָרוּם אֱלוֹהֵי יִשְׁעִי - זֶה הָעוֹלָם הָעֶלְיוֹן, שֶׁהוּא רָם וְנִשָּׂא, רָם עַל הַכֹּל, שֶׁהֲרֵי מִמֶּנּוּ יוֹצֵא הַכֹּל, (מקור שלא פוסק) וְכָל הַנְּבִיעָה שֶׁנּוֹבֵעַ לְמַלֵּא הַבְּאֵר כָּרָאוּי, וּמִשָּׁם מִתְבָּרֶכֶת לְהָאִיר לְכָל אוֹתָם שֶׁלְּמַטָּה. וּכְשֶׁמִּתְמַלֵּאת (זו) הַכֹּל כָּרָאוּי, אָז וְיָרוּם אֱלוֹהֵי יִשְׁעִי.</p>"],[9522011337,"<p>פָּתַח רַבִּי יֵיסָא וְאָמַר, (איוב לו) לֹא יִגְרַע מִצַּדִּיק עֵינָיו וְאֶת מְלָכִים לַכִּסֵּא וַיֹּשִׁיבֵם לָנֶצַח וַיִּגְבָּהוּ. בֹּא רְאֵה, כְּשֶׁרְשָׁעִים לֹא שׁוֹלְטִים בָּעוֹלָם וְנֶאֱבָדִים מִמֶּנּוּ (מהעולם), אָז הַצַּדִּיק שׁוֹלֵט בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב לֹא יְחַיֶּה רָשָׁע וּמִשְׁפַּט עֲנִיִּים יִתֵּן. מַה כָּתוּב אַחֲרָיו? לֹא יִגְרַע מִצַּדִּיק עֵינָיו. מַה זֶּה עֵינָיו? כְּמוֹ שֶׁנֶּאֱמַר (תהלים לד) עֵינֵי ה' אֶל צַדִּיקִים.</p>\n<p>וְאֶת מְלָכִים לַכִּסֵּא - אֵלּוּ הֵם הַמְּלָכִים הַשּׁוֹלְטִים שֶׁנֶּאֱחָזִים בַּכִּסֵּא. וַיֹּשִׁיבֵם לָנֶצַח - שֶׁהִתְקַיְּמוּ בַּכִּסֵּא בְּקִיּוּם שָׁלֵם. וַיִּגְבָּהוּ - לָמָּה וַיִּגְבָּהוּ? לִשְׁלֹט בָּעוֹלָם, וְיִתְקַיֵּם הַכִּסֵּא עַל עַמּוּדָיו. דָּבָר אַחֵר וַיִּגְבָּהוּ - שֶׁנּוֹטְלִים אֶת הַכִּסֵּא וּמַעֲמִידִים אוֹתוֹ לְמַעְלָה לְהֵאָחֵז בִּמְקוֹמוֹ כָּרָאוּי, וְאָז הַכֹּל יִחוּד אֶחָד.</p>\n<p>בְּעוֹדָם הוֹלְכִים רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא, וְעֶלֶם אֶחָד עִמּוֹ רוֹכֵב עַל כְּתֵפוֹ. אָמַר רַבִּי יִצְחָק, וַדַּאי שֶׁהָאִישׁ הַזֶּה הוּא יְהוּדִי, וּכְדֵי לְזַכּוֹת אֲנָשִׁים הוּא בָּא. אָמַר רַבִּי יֵיסָא, נִזְכֶּה אָנוּ בּוֹ בָּרִאשׁוֹנָה.</p>\n<p>כְּשֶׁהִגִּיעַ אֲלֵיהֶם, אָמַר רַבִּי יֵיסָא, אֵיפֹה הַכְּלִי (המדה של העמיר) עִם מַאַכְלֵי הַדֶּרֶךְ? אָמַר, כְּדֵי שֶׁיִּזְכּוּ (בו) אֲנָשִׁים, שֶׁהֲרֵי יֵשׁ לִי שְׁנֵי בָנִים, וְהִגִּיעַ הַצָּבָא לָעִיר וְנִשְׁבּוּ, וְכָעֵת אֲנִי הוֹלֵךְ כְּדֵי שֶׁיִּזְכּוּ בָהֶם בְּנֵי אָדָם. זָכוּ עִמּוֹ וְנָתְנוּ לוֹ לֶאֱכֹל.</p>"],[9522011338,"<p>בֵּינְתַיִם פָּתַח אוֹתוֹ יְהוּדִי וְאָמַר, (במדבר כח) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי וְגוֹ'. הַקָּרְבָּן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם כְּדֵי לָזוּן אֶת הָעוֹלָם וְלָתֵת כַּלְכָּלָה לְמַעְלָה וּלְמַטָּה, שֶׁהֲרֵי בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה מִתְעוֹרֵר לְמַעְלָה, וּבָזֶה מִתְכַּלְכְּלִים כָּל אֶחָד וְאֶחָד כָּרָאוּי.</p>\n<p>אֶת קָרְבָּנִי לַחְמִי - זֶהוּ שֶׁכָּתוּב (שיר ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי. לְאִשַּׁי - זֶהוּ שֶׁכָּתוּב אִכְלוּ רֵעִים וְגוֹ'. וּמָה הַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה לְעוֹרֵר מָזוֹן לְמַעְלָה (למטה) כְּדֵי לְעוֹרֵר מָזוֹן (למעלה) לְמַטָּה מֵהַמָּזוֹן הַהוּא - מִי שֶׁנּוֹתֵן לְקַיֵּם נֶפֶשׁ עַל אַחַת כַּמָּה וְכַמָּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרֵךְ אוֹתוֹ, וְיָעִיר לוֹ מָזוֹן שֶׁלְּמַעְלָה, וְיִתְבָּרֵךְ הָעוֹלָם בִּשְׁבִילוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַדַּאי זֶה הַסּוֹד כָּרָאוּי, וְיָפֶה אָמַר. אָמַר רַבִּי יֵיסָא, וַדַּאי עַל זֶה אָמַר אוֹתוֹ, שֶׁלֹּא יְזַלְזֵל אָדָם בְּשׁוּם אָדָם אֶחָד בָּעוֹלָם, בִּשְׁתֵּי צוּרוֹת זָכִינוּ לָאִישׁ הַזֶּה.</p>\n<p>פָּתַח וְאָמַר, הַפָּסוּק הַזֶּה אָמַר רַבִּי אֶלְעָזָר, אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. אֶת קָרְבָּנִי - הַסּוֹד שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב אֶת, אֶת דַּוְקָא. קָרְבָּנִי - זֶהוּ קָרְבָּן וְקֶשֶׁר לְהִתְקַשֵּׁר. לַחְמִי - זֶה הַמָּזוֹן שֶׁבָּא מִלְמַעְלָה בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה. לְאִשַּׁי - לְהַכְלִיל שְׁאָר הַחֲיָלוֹת הָאֲחֵרִים שֶׁהִצְטָרְכוּ לְהִזּוֹן כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. רֵיחַ נִיחֹחִי - זֶה הָרָצוֹן וְהַקֶּשֶׁר שֶׁאוֹחֵז אֶת הַכֹּל בְּסוֹד הָעוֹלָם הָעֶלְיוֹן.</p>\n<p>תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ, מִי הוּא מוֹעֲדוֹ? בַּזְּמַן שֶׁמִּתְעוֹרֵר אַבְרָהָם לַעֲשׂוֹת רְצוֹנוֹ, שֶׁכָּתוּב (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר, וּבַזְּמַן שֶׁנֶּעֱקַד יִצְחָק עַל גַּבֵּי הַמִּזְבֵּחַ, שֶׁאוֹתָהּ הַשָּׁעָה הָיְתָה בֵּין הָעַרְבַּיִם. וְאָמַר רַבִּי (חייא) יֵיסָא, אִם כָּךְ, זֶה שֶׁכָּתוּב בְּמוֹעֲדוֹ הָיָה צָרִיךְ לִהְיוֹת בְּמוֹעֲדִים! אָמַר לוֹ, אוֹתָהּ הַשָּׁעָה נִכְלַל אֵשׁ בְּמַיִם וּמַיִם בְּאֵשׁ, וּמִשּׁוּם כָּךְ כָּתוּב בְּמוֹעֲדוֹ.</p>\n<p>בֹּא רְאֵה, בְּכָל הַקָּרְבָּנוֹת לֹא כָתוּב כְּמוֹ שֶׁכָּתוּב כָּאן תִּשְׁמְרוּ לְהַקְרִיב לִי. תִּשְׁמְרוּ - הַסּוֹד שֶׁל שָׁמוֹר, שֶׁהוּא צָרִיךְ לְהַקְרִיב לְמַעְלָה, שֶׁכָּתוּב תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ, בְּיָמִין וּבִשְׂמֹאל, כְּמוֹ שֶׁנֶּאֱמַר בְּאַבְרָהָם וְיִצְחָק, וְהַכֹּל בְּסוֹד עֶלְיוֹן.</p>\n<p>אָמַר רַבִּי יֵיסָא, אִלְמָלֵא לֹא בָאתִי לְכָאן אֶלָּא לִשְׁמֹעַ הַדְּבָרִים הַלָּלוּ - דַּי לִי. אַשְׁרֵיהֵם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עַל זֶה כָּתוּב (ישעיה ה) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר.</p>"],[9522011339,"<p>וְלָבָן הָלַךְ לִגְזז אֶת צֹאנוֹ וְגוֹ'. אָמַר רַבִּי יוֹסֵי, מַה זֶּה תְּרָפִים? אֶלָּא עֲבוֹדָה זָרָה. וְלָמָּה נִקְרָאִים תְּרָפִים? לִגְנַאי הָיָה, כְּמוֹ שֶׁשָּׁנִינוּ בִּמְקוֹם הַתֹּרֶף. וּמִנַּיִן לָנוּ שֶׁהָיוּ עֲבוֹדָה זָרָה? שֶׁכָּתוּב לָמָּה גָנַבְתָּ אֶת אֱלֹהָי וְכָתוּב עִם אֲשֶׁר תִּמְצָא אֶת אֱלֹהֶיךְ וְגוֹ'. וְלָבָן הַמְכַשֵּׁף שֶׁל כָּל הַמְכַשְּׁפִים שֶׁל הָעוֹלָם הָיָה, וּבָזֶה הָיָה יוֹדֵעַ אֶת כָּל מַה שֶּׁרוֹצֶה לָדַעַת.</p>\n<p>אָמַר רַבִּי חִיָּיא, בְּקֶסֶם נַעֲשָׂה. רַבִּי יוֹסֵי אוֹמֵר, בְּנַחַשׁ. אָמַר רַבִּי יְהוּדָה, לֹא נַעֲשׂוּ אֶלָּא בְּשָׁעוֹת יְדוּעוֹת. וְלָמָּה נִקְרָאִים תְּרָפִים? מִשּׁוּם שֶׁמַּכִּים אֶת הַשָּׁעָה הַזּוֹ, וְהַשָּׁעָה מַרְפָּה הַיָּד, כְּמוֹ שֶׁנֶּאֱמַר רַב עַתָּה הֶרֶף יָדֶךְ.</p>\n<p>כְּשֶׁהָאֻמָּן עוֹשֶׂה אוֹתוֹ, אוֹתוֹ שֶׁיּוֹדֵעַ רְגָעִים וְשָׁעוֹת עוֹמֵד עָלָיו וְאוֹמֵר: כָּעֵת הַרְפֵּה וְכָעֵת עֲשֵׂה. וְלֹא תִמְצָא מַעֲשֶׂה שֶׁצָּרִיךְ שֶׁיַּרְפּוּ מִמֶּנּוּ אֶלָּא זֶה. וְהוּא מְדַבֵּר תָּמִיד וְנוֹתֵן עֵצוֹת רָעוֹת לְהָרַע לְנֶפֶשׁ הָאָדָם.</p>\n<p>וְרָחֵל פָּחֲדָה, מִשּׁוּם שֶׁנָּתַן עֵצָה לְהָרַע לְיַעֲקֹב, וּבִשְׁבִיל בִּזְיוֹן עֲבוֹדָה זָרָה שָׂמָה אוֹתָם תַּחְתֶּיהָ עַד שֶׁאֵין יְכוֹלִים לְדַבֵּר. שֶׁהֲרֵי כְּשֶׁהוּא מְתֻקָּן לְדַבֵּר, מְכַבְּדִים וּמַרְבִּיצִים לְפָנָיו. וְכָעֵת מַה כָּתוּב? וַתֵּשֶׁב עֲלֵיהֶם. זָכָר וּנְקֵבָה הָיוּ, וַעֲבוֹדוֹת רַבּוֹת עוֹשִׂים טֶרֶם מְדַבְּרִים. וּמִשּׁוּם כָּךְ הִתְעַכֵּב לָבָן שְׁלֹשָׁה יָמִים, שֶׁלֹּא יָדַע שֶׁבָּרַח יַעֲקֹב, שֶׁכָּתוּב וַיֵּגּד לְלָבָן בַּיּוֹם הַשְּׁלִישִׁי כִּי בָרַח יַעֲקֹב.</p>\n<p>וְאָמַר רַבִּי יְהוּדָה, הִזְמִין עַצְמוֹ בִּשְׁלֹשָׁה דְבָרִים: הִזְדָּרֵז בְּכָל הַכְּשָׁפִים שֶׁהָיוּ לוֹ, וְהִזְדָּרֵז בִּכְלֵי זַיִן כְּדֵי לְאַבֵּד אוֹתוֹ מִן הָעוֹלָם, שֶׁכָּתוּב (דברים כו) אֲרַמִּי אֹבֵד אָבִי. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁרָצָה לְאַבֵּד אֶת יַעֲקֹב, מַה כָּתוּב? הִשָּׁמֶר לְךְ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב עַד רָע. וְהַיְנוּ שֶׁכָּתוּב יֶשׁ לְאֵל יָדִי לַעֲשׂוֹת עִמָּכֶם רָע. בַּמֶּה בָּטַח? בַּכְּשָׁפִים שֶׁהָיוּ בְיָדוֹ.</p>\n<p>בֹּא רְאֵה, לָבָן הָלַךְ בְּיוֹם אֶחָד הַדֶּרֶךְ שֶׁהָלַךְ יַעֲקֹב שִׁבְעָה יָמִים כְּדֵי לַעֲקֹר אוֹתוֹ מִן הָעוֹלָם. אֶחָד עַל שֶׁהָלַךְ, וְאֶחָד עַל אוֹתָם הַתְּרָפִים. וְאַף עַל גַּב שֶׁרָחֵל הִיא שֶׁעָשְׂתָה כְּדֵי לַעֲקֹר אֶת אָבִיהָ מֵאַחֲרֵי עֲבוֹדָה זָרָה - נֶעֶנְשָׁה שֶׁלֹּא גִדְּלָה אֶת בִּנְיָמִין, וְלֹא עָמְדָה עִמּוֹ שָׁעָה אַחַת בִּשְׁבִיל הַצַּעַר שֶׁל אָבִיהָ, אַף עַל גַּב שֶׁהִתְכַּוְּנָה לְטוֹב.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּל אוֹתָהּ הַתּוֹכָחָה שֶׁהָיְתָה לְיַעֲקֹב עִם לָבָן, הֶחֱזִיר לוֹ לְלָבָן לְהוֹדוֹת לַקָּדוֹשׁ- בָּרוּךְ-הוּא, שֶׁכָּתוּב רְאֵה אֱלֹהִים עֵד בֵּינִי וּבֵינֶיךְ. בֹּא רְאֵה, כָּתוּב אֱלֹהֵי אַבְרָהָם וֵאלֹהֵי נָחוֹר יִשְׁפְּטוּ בֵינֵינוּ. חָזַר אוֹתוֹ הָרָשָׁע לְתַקָּלָתוֹ. כֵּיוָן שֶׁאָמַר אֱלֹהֵי אַבְרָהָם, חָזַר וְאָמַר וֵאלֹהֵי נָחוֹר.</p>\n<p>וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. מָה הַטַּעַם בְּפַחַד יִצְחָק וְלֹא בֵּאלֹהֵי אַבְרָהָם? אֶלָּא שֶׁלֹּא רָצָה לְהַטְרִיחַ אֶת הַיָּמִין בִּשְׁבִיל לָבָן, וְלֹא עוֹד, אֶלָּא שֶׁלֹּא צָרִיךְ לָאָדָם - אַף עַל גַּב שֶׁנִּשְׁבָּע בֶּאֱמֶת - לְהִשָּׁבַע בַּמָּקוֹם הָעֶלְיוֹן שֶׁל הַכֹּל.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וַדַּאי לְקִיּוּם (לשבועה) כָּרָאוּי נִשְׁבַּע כָּךְ יַעֲקֹב, וְכָךְ רָאוּי. וְיַעֲקֹב הִשְׁגִּיחַ בַּדָּבָר. אָמַר, הֲרֵי הוּא אָמַר אֱלֹהֵי אַבְרָהָם, וְעָזַב אֶת אַבָּא. אֲנִי אַשְׁלִים אֶת הַכֹּל. מִיָּד - וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. דָּבָר אַחֵר, לְהִכָּלֵל בַּדִּין, לַעֲמֹד עַל לָבָן.</p>"],[9522011340,"<p>וְיַעָקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. רַבִּי אַבָּא פָּתַח וְאָמַר, (בראשית ה) זָכָר וּנְקֵבָה בְּרָאָם וְגוֹ'. כַּמָּה יֵשׁ לָנוּ לְהִסְתַּכֵּל בְּדִבְרֵי הַתּוֹרָה. אוֹי לָהֶם לְאוֹתָם אֲטוּמֵי הַלֵּב וּסְתוּמֵי הָעֵינַיִם. הִנֵּה הַתּוֹרָה קוֹרֵאת לִפְנֵיהֶם, (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. מִי פֶתִי יָסֻר הֵנָּה. חֲסַר לֵב אָמְרָה לוֹ, וְאֵין מִי שֶׁיַּשְׁגִּיחַ.</p>\n<p>בֹּא רְאֵה, בַּפָּסוּק הַזֶּה יֵשׁ סוֹדוֹת עֶלְיוֹנִים, הוּא בִּפְנִים וְהוּא בַּחוּץ. זָכָר וּנְקֵבָה בְּרָאָם, נִשְׁמָע לַצּוּרָה הַזּוֹ וְנִשְׁמָע לַצּוּרָה הַזּוֹ, וְנִשְׁמָע שֶׁהַשֶּׁמֶשׁ וְהַלְּבָנָה הֵם בְּחִבּוּר אֶחָד, שֶׁכָּתוּב בְּרָאָם, כְּמוֹ שֶׁנֶּאֱמַר (חבקוק ג) שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה. וְנִשְׁמָע שֶׁאָדָם וְחַוָּה נִבְרְאוּ יַחַד בְּזִוּוּג אֶחָד, וְכֵיוָן שֶׁנִּמְצְאוּ בְּזִוּוּג אֶחָד, מִיָּד וַיְבָרֶךְ אֹתָם, שֶׁאֵין הַבְּרָכָה שׁוֹרָה אֶלָּא בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה.</p>\n<p>בֹּא רְאֵה, כְּשֶׁיָּצָא יַעֲקֹב לָלֶכֶת לְחָרָן, הָיָה לְבַדּוֹ, שֶׁלֹּא נִשָּׂא, מַה כָּתוּב? וַיִּפְגַּע בַּמָּקוֹם וְגוֹ', וְלֹא הֵשִׁיבוּ לוֹ אֶלָּא בַחֲלוֹם. כָּעֵת שֶׁנִּשָּׂא, וְהָיָה בָּא עִם כָּל הַשְּׁבָטִים, כִּבְיָכוֹל הַמַּחֲנוֹת הָעֶלְיוֹנִים פָּגְשׁוּ בוֹ וְהִתְחַנְּנוּ לוֹ, שֶׁכָּתוּב וַיִּפְגְּעוּ בוֹ. הֵם חָזְרוּ לְהִפָּגֵשׁ בּוֹ. בָּרִאשׁוֹנָה - וַיִּפְגַּע הוּא בַּמָּקוֹם, וְכָעֵת הֵם - וַיִּפְגְּעוּ בוֹ.</p>\n<p>מִשּׁוּם שֶׁבִּשְׁבִיל יַעֲקֹב וּבְאוֹתָם הַשְּׁבָטִים הֵם מֻשְׁקִים, מִן הַמַּיִם שֶׁל הַיָּם הַגָּדוֹל. וְלֹא עוֹד, אֶלָּא בָּרִאשׁוֹנָה בַּלַּיְלָה בַּחֲלוֹם, וְכָעֵת בְּמַרְאֵה הָעַיִן וּבַיּוֹם. זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה וְגוֹ'.</p>\n<p>בַּמָּה הִכִּיר אוֹתָם? אֶלָּא רָאָה שֶׁהֵם הָיוּ אוֹתָם שֶׁרָאָה בַּחֲלוֹם, מִשּׁוּם כָּךְ קָרָא לָהֶם מַחֲנָיִם, מַחֲנוֹת שֶׁנִּרְאוּ לְמַעְלָה וּמַחֲנוֹת שֶׁנִּרְאוּ לְמַטָּה.</p>\n<p>לָמָּה נִתְגַּלּוּ לִפְגֹּשׁ אוֹתוֹ? אֶלָּא הַשְּׁכִינָה הָלְכָה אֵלָיו לִטֹּל אֶת בֵּיתוֹ, וּמְצַפָּה לְבִנְיָמִין לִטֹּל אֶת הַבַּיִת עִם יַעֲקֹב כָּרָאוּי, וְאָז כָּתוּב וְשָׁב יַעֲקֹב וְשָׁקַט וְשַׁאֲנַן וְאֵין מַחֲרִיד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>\n<p>וְיַעָקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. מִשְׁנָה. חָזְקֵי הַשָּׂרִים זְקוּפִים מִלְמַעְלָה, וְלַהַט הַחֶרֶב הַשְּׁנוּנָה מְמֻנָּה עַל כָּל (כמה) הַצְּבָאוֹת וְהַמַּחֲנוֹת.</p>\n<p>אוֹתָהּ הַחֶרֶב הַלּוֹהֶטֶת הִיא חֶרֶב אֲדֻמָּה, שֶׁכָּתוּב (ישעיה לד) חֶרֶב לַה' מָלְאָה דָם. הַחֶרֶב הַ את שֶׁתְּלוּיָה בָּהּ הַהִפּוּךְ, הֵם שֶׁמִּתְהַפְּכִים לְכַמָּה צוּרוֹת. הוּא נָשִׁים, הוּא גְבָרִים, בִּצְדָדִים רַבִּים, נִפְרָדוֹת הַצּוּרוֹת הָאֲחֵרוֹת לְכַמָּה דְרָגוֹת.</p>\n<p>מֵהַצַד שֶׁל עֵץ הַחַיִּים הֵם יוֹצְאִים, שֶׁמִּתְיַחֲדִים בְּיִחוּד בְּקֶשֶׁר. אֵלּוּ הַקְּדוֹשִׁים נִשְׁאָבִים תָּמִיד מִטַּל הַשָּׁמַיִם. הַשֵּׁם שֶׁל אֱלֹהִים מִתְתַּקֵּן בָּהֶם. (ועל זה אמר משמני הארץ ונתקן) בְּאַרְבָּעָה הַצְּדָדִים שֶׁל הָעוֹלָם נַעֲשׂוּ לְעַמּוּדֵי הַכִּסֵּא. כֻּלָּם מַרְגָּלִיּוֹת וְאֵיבָרִים וְעַמּוּדִים, לֹא נִפְרָדִים לְעוֹלָם מִתּוֹךְ הַשֵּׁם הַזֶּה, הֵם הַקְּשָׁרִים שֶׁל יַעֲקֹב שֶׁבָּחַר לְחֶלְקוֹ וְנִקְשָׁרִים בַּשֵּׁם הַזֶּה, כֻּלָּם יָצְאוּ (בערב).</p>\n<p>וְיַעָקֹב, כְּשֶׁיָּצָא לָלֶכֶת לְדַרְכּוֹ, הִקִּיפוּ אוֹתוֹ לְאַרְבָּעָה צְדָדִים. לְאַרְבַּע הַזָּוִיּוֹת שֶׁל הָעוֹלָם שָׁמְרוּ אוֹתוֹ. בְּשָׁעָה קַלָּה הִתְרַגֵּשׁ מֵהָעֵץ (מהמקום) שֶׁלְּמַעְלָה לִשְׁמֹר אֶת הָעֵץ שֶׁלְּמַטָּה, וְאָז וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה. אָז וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה אֶת שְׁלֵמוּתוֹ שֶׁל יַעֲקֹב שֶׁלֹּא רָצָה לָלֶכֶת אֶלָּא בִּרְשׁוּתוֹ שֶׁל לָבָן. וְאִם תֹּאמַר, בְּפַעַם אַחֶרֶת לָמָּה לֹא? אֶלָּא מִשּׁוּם שֶׁיַּעֲקֹב פָּחַד שֶׁלֹּא יַעֲזב אוֹתוֹ, וְיִשְׁתַּלְּמוּ שְׁנֵים עָשָׂר הַשְּׁבָטִים בְּאֶרֶץ אַחֶרֶת. וְעַל כֵּן, כֵּיוָן שֶׁרָאָה שֶׁהִגִּיעָה הַשָּׁעָה שֶׁל בִּנְיָמִין, בָּרַח, כְּמוֹ שֶׁנֶּאֱמַר וַיִּבְרַח הוּא וְכָל אֲשֶׁר לוֹ. כֵּיוָן שֶׁנּוֹלַד בִּנְיָמִין, נִקְשְׁרָה הַשְּׁכִינָה עִם כָּל הַשְּׁבָטִים, וְנָטְלָה אֶת הַבַּיִת עִמָּם. וְיַעֲקֹב הָיָה יוֹדֵעַ בְּרוּחַ הַחָכְמָה, שֶׁכַּאֲשֶׁר יִשְׁתַּלְּמוּ שְׁנֵים עָשָׂר הַשְּׁבָטִים, שֶׁהַשְּׁכִינָה תִּתְקַשֵּׁר עִמָּהֶם וְרָחֵל תָּמוּת, וְהִיא נוֹטֶלֶת אֶת הַבַּיִת.</p>\n<p>וּבֹא וּרְאֵה, כָּךְ לָמַדְנוּ, הָעוֹלָם הַתַּחְתּוֹן רָאוּי לוֹ לְיַעֲקֹב כְּמוֹ שֶׁרָאוּי לְמֹשֶׁה, אֶלָּא שֶׁלֹּא יָכְלָה עַד שֶׁהָיוּ שְׁנֵים עָשָׂר שְׁבָטִים בַּבַּיִת לְהִתְקַשֵּׁר עִמָּהֶם, וְאָז נִדְחֲתָה רָחֵל, וְהִיא נָטְלָה אֶת הַבַּיִת עִם כָּל הַשְּׁבָטִים וְהָיְתָה עִקַּר הַבַּיִת, וְאָז (תהלים קיג) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת. אָמַר יַעֲקֹב, הִנֵּה הִגִּיעַ הַזְּמַן שֶׁיִּשְׁתַּלְּמוּ שְׁנֵים עָשָׂר הַשְּׁבָטִים, וּוַדַּאי שֶׁהָעוֹלָם שֶׁלְּמַעְלָה יָרַד לוֹ לַבַּיִת וְיִתְקַשֵּׁר (העולם שלמעלה ירד לו בביתו והתקשר) בָּהֶם, וְהָעֲנִיָּה הַ את נִדְחֵית לְפָנָיו. אִם תָּמוּת כָּאן, לֹא אֵצֵא מִכָּאן לְעוֹלָמִים. וְלֹא עוֹד, אֶלָּא בָּאָרֶץ הַזּוֹ לֹא רָאוּי לְהַשְׁלִים אֶת הַבַּיִת. מִשּׁוּם כָּךְ, (בראשית ל) וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף, טֶרֶם שֶׁיִּשְׁתַּלְּמוּ הַשְּׁבָטִים.</p>\n<p>שָׁמַע רַבִּי שִׁמְעוֹן, אָמַר, וַדַּאי שֶׁכָּל דִּבְרֵי רַבִּי יְהוּדָה יָפִים, וְזֶה עוֹלֶה עַל הַכֹּל. וְאִם תֹּאמַר, לָמָּה לֹא הָלַךְ לוֹ לְדַרְכּוֹ מִיָּד? אֶלָּא כָּל זְמַן שֶׁרָחֵל לֹא הִתְעַבְּרָה מִבִּנְיָמִין, הִתְעַכֵּב שָׁם. כֵּיוָן שֶׁהִגִּיעַ הַזְּמַן שֶׁל בִּנְיָמִין, בָּרַח, וְלֹא בִקֵּשׁ רְשׁוּת, כְּדֵי שֶׁלֹּא יִתְעַכֵּב שָׁם, וְהִתְחַבֵּר יַעֲקֹב עִם כָּל הַשְּׁבָטִים בַּמָּקוֹם שֶׁצָּרִיךְ. ע\"כ סתרי תורה</p>"],[9522011341,"<p>וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (תהלים צא) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ לִשְׁמָרְךְ בְּכָל דְּרָכֶיךְ. פָּסוּק זֶה בֵּאֲרוּהוּ הַחֲבֵרִים, שֶׁהֲרֵי בְּשָׁעָה שֶׁאָדָם בָּא לָעוֹלָם, מִיָּד מִזְדַּמֵּן עִמּוֹ יֵצֶר הָרָע שֶׁהוּא מְקַטְרֵג לָאָדָם תָּמִיד, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ד) לַפֶּתַח חַטָּאת רֹבֵץ. מִי זֶה חַטָּאת רֹבֵץ? זֶה יֵצֶר הָרָע.</p>\n<p>וְכָךָ גַּם דָּוִד קָרָא לוֹ חַטָּאת, (תהלים נא) וְחַטָּאתִי נֶגְדִּי תָמִיד, מִשּׁוּם שֶׁהוּא עוֹשֶׂה כָּל יוֹם לָאָדָם לַחֲטֹא לִפְנֵי רִבּוֹנוֹ, וְיֵצֶר הָרָע הַזֶּה לֹא זָז מִבֶּן הָאָדָם מִיּוֹם שֶׁנּוֹלָד הָאָדָם לְעוֹלָמִים, וְיֵצֶר הַטּוֹב בָּא לָאָדָם מִיּוֹם שֶׁבָּא לְהִטָּהֵר.</p>\n<p>וּמָתַי בָּא אָדָם לְהִטָּהֵר? כְּשֶׁהוּא בֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנִים, אָז מִזְדַּוֵּג הָאָדָם בִּשְׁנֵיהֶם, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. יֵצֶר טוֹב לְיָמִין, וְיֵצֶר הָרָע לִשְׂמֹאל. וְאֵלֶּה הֵם שְׁנֵי מַלְאָכִים מַמָּשׁ מְמֻנִּים, וְהֵם נִמְצָאִים תָּמִיד עִם הָאָדָם.</p>\n<p>בָּא בֶּן אָדָם לְהִטַּהֵר - אוֹתוֹ יֵצֶר הָרָע נִכְפֶּה לְפָנָיו, וְשׁוֹלֵט הַיָּמִין עַל הַשְּׂמֹאל. וּשְׁנֵיהֶם מִזְדַּוְּגִים לִשְׁמֹר אֶת הָאָדָם בְּכָל דְּרָכָיו שֶׁהוּא עוֹשֶׂה. זֶהוּ שֶׁכָּתוּב כִּי מַלְאָכָיו יְצַוֶּה לָּךְ לִשְׁמָרְךְ בְּכָל דְּרָכֶיךְ.</p>\n<p>רַבִּי אֶלְעָזָר מְבָאֵר אֶת הַפָּסוּק הַזֶּה בְּיַעֲקֹב, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִזְמִין עִמּוֹ מַלְאָכִים מַחֲנוֹת מְמֻנִּים, מִשּׁוּם שֶׁהֲרֵי הוּא בָּא שָׁלֵם בִּשְׁבָטִים עֶלְיוֹנִים כֻּלָּם שְׁלֵמִים כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים, וְנִתְבָּאֵר. וְכָאן, כֵּיוָן שֶׁנִּצּוֹל מִלָּבָן וַהֲרֵי נִפְרַד מִמֶּנּוּ, אָז הִזְדַּוְּגָה עִמּוֹ שְׁכִינָה, וּבָאוּ מַחֲנוֹת קְדוֹשִׁים לְהַקִּיף אוֹתוֹ, וְאָז וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם וְגוֹ', וּמֵאוֹתָם מַלְאָכִים שָׁלַח לְעֵשָׂו, זֶהוּ שֶׁכָּתוּב וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים. מַלְאָכִים מַמָּשׁ הָיוּ וַדַּאי.</p>\n<p>פָּתַח רַבִּי יִצְחָק וְאָמַר, כָּתוּב (תהלים לד) חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם. הֲרֵי פֵּרְשׁוּהָ. אֲבָל בְּמָקוֹם אֶחָד כָּתוּב כִּי מַלְאָכָיו יְצַוֶּה לָּךְ, מַלְאָכָיו רַבִּים, וְכָאן אֶחָד, שֶׁכָּתוּב חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם. אֶלָּא כִּי מַלְאָכָיו יְצַוֶּה לָּךְ - אֵלּוּ שְׁאָר מַלְאָכִים. מַלְאַךְ ה' סָבִיב - זוֹ שְׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר (שמות ג) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. וְלָכֵן חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו, לְהַקִּיפוֹ בְּכָל הַצְּדָדִים כְּדֵי לְהַצִּיל אוֹתוֹ, וּכְשֶׁהַשְּׁכִינָה שׁוֹרָה בְּתוֹךְ הָאָדָם, כַּמָּה מַחֲנוֹת קְדוֹשִׁים כֻּלָּם מִזְדַּמְּנִים לְשָׁם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁדָּוִד הַמֶּלֶךְ נִצַּל מֵאָכִישׁ מֶלֶךְ גַּת, אָז אָמַר אֶת זֶה, מִשּׁוּם שֶׁהַשְּׁכִינָה הִקִּיפָה אוֹתוֹ וְנִצַּל מֵהֶם מֵאָכִישׁ וּמֵעַמּוֹ, כָּל אוֹתָם שֶׁהִתְקִיפוּ (שהקיפו) אוֹתוֹ. מַה כָּתוּב? (שמואל א כא) וַיִּתְהֹלֵל בְּיָדָם, לָמָּה וַיִּתְהֹלֵל? הָיָה צָרִיךְ לִכְתֹּב וַיִּשְׁתַּגַּע, כְּמוֹ שֶׁנֶּאֱמַר (שם) כִּי הֲבֵאתֶם אֶת זֶה לְהִשְׁתַּגֵּעַ עָלָי.</p>\n<p>אֶלָּא חָזַר עַל אוֹתוֹ דָּבָר שֶׁאָמַר דָּוִד בַּתְּחִלָּה, שֶׁכָּתוּב (תהלים עג) כִּי קִנֵּאתִי בַּהוֹלְלִים וְגוֹ'. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: חַיֶּיךְ עֲדַיִן אַתָּה צָרִיךְ אֶת זֶה. כֵּיוָן שֶׁנִּכְנַס לְבֵית אָכִישׁ וְהֶחֱזִיקוּ בוֹ, מַה כָּתוּב? וַיִּתְהֹלֵל בְּיָדָם, כְּאוֹתָם הוֹלְלִים שֶׁקִּנֵּא בָהֶם בַּהַתְחָלָה. וְאָז בָּאָה שְׁכִינָה וְשָׁרְתָה סְבִיב דָּוִד.</p>\n<p>וְאִם תֹּאמַר שֶׁהַשְּׁכִינָה לֹא שׁוֹרָה כִּי אִם בְּנַחֲלָתָהּ, שֶׁהִיא הָאָרֶץ הַקְּדוֹשָׁה - וַדַּאי לֹא שׁוֹרָה בַּעֲבוּר (שיונקים) לִינֹק מִמֶּנָּה, אֲבָל שׁוֹרָה כְּדֵי לְהָגֵן. וְכָאן כְּשֶׁבָּא יַעֲקֹב מִבֵּית לָבָן, כָּל הַמַּחֲנוֹת הַקְּדוֹשִׁים הִקִּיפוּ אוֹתוֹ, וְלֹא נִשְׁאַר לְבַדּוֹ.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, אִם כָּךְ (ס\"א שכל המחנות הקדושים באו יחד עמו והשכינה עמו), לָמָּה כָּתוּב וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וְגוֹ'? אָמַר רַבִּי יְהוּדָה, מִשּׁוּם שֶׁהִכְנִיס עַצְמוֹ לְסַכָּנָה וְהָיָה רוֹאֶה אוֹתָהּ סַכָּנָה בְּעֵינָיו, הֵם פָּרְשׁוּ מִמֶּנּוּ, וְאָז אָמַר, קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת, אֵלּוּ הֵם הַמַּחֲנוֹת הַקְּדוֹשִׁים שֶׁנִּפְרְדוּ מִמֶּנּוּ.</p>\n<p>רַבִּי יִצְחָק אָמַר, כְּדֵי לְהַשְׁאִירוֹ עִם אוֹתוֹ מְמֻנֶּה שֶׁל עֵשָׂו שֶׁהָיָה בָּא בִּרְשׁוּת עֶלְיוֹנָה, וְאֵלֶּה הָלְכוּ לוֹמַר שִׁירָה, שֶׁהִגִּיעַ זְמַנָּם לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ שָׁעָה, וְאַחַר כָּךְ חָזְרוּ. זֶהוּ שֶׁכָּתוּב קָ נְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת אֲשֶׁר עָשִׂיתָ אֶת עַבְדֶּךְ וְגוֹ', וְעַתָּה הָיִיתִי לִשְׁנֵי מַחֲנוֹת. מַחֲנֵה שְׁכִינָה, וְכָל בֵּיתוֹ. (ס\"א מחנה אחד היה, שכתוב מחנה אלהים זה). לִשְׁנֵי מַחֲנוֹת - שֶׁהָיָה שָׁלֵם מִכָּל הַצְּדָדִים מִשְּׁנֵי חֲלָקִים, לָבָן וְאָדם.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, הֲרֵי נִתְבָּאֵר אוֹתוֹ לַיְלָה שִׁלְטוֹן שֶׁל צַד שֶׁל עֵשָׂו הָיָה בְּאוֹתָהּ שָׁעָה, שֶׁהֲרֵי כָּתוּב (בראשית א) יְהִי מְאֹרֹת חָסֵר, וּמִשּׁוּם כָּךְ וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, שֶׁנִּשְׁאַר יַעֲקֹב, שֶׁהוּא שֶׁמֶשׁ לְבַדּוֹ, שֶׁהִתְכַּסְּתָה הַלְּבָנָה מִן הַשֶּׁמֶשׁ. וְאַף עַל גַּב שֶׁשְּׁמִירַת (ועם כל זה השמירה של) הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא זָזָה מִמֶּנּוּ מִכֹּל וָכֹל, וְעַל זֶה לֹא יָכֹל לוֹ, שֶׁכָּתוּב וַיַּרְא כִּי לֹא יָכֹל לוֹ.</p>\n<p>הִסְתַּכֵּל יָמִינָה וְרָאָה אֶת אַבְרָהָם, הִסְתַּכֵּל שְׂמֹאלָה וְרָאָה אֶת יִצְחָק, הִסְתַּכֵּל בַּגּוּף וְרָאָה שֶׁנִּכְלָל מִצַּד זֶה וְנִכְלָל מִצַּד זֶה, וְאָז וַיִּגַּע בְּכַף יְרֵכוֹ, בְּעַמּוּד אֶחָד הַסָּמוּךְ לַגּוּף, שֶׁהוּא מִחוּץ לַגּוּף.</p>\n<p>וְלָכֵן חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם, הִקִּיפוֹ בְּכָל צְדָדָיו כְּדֵי לְהַצִּילוֹ. וּכְשֶׁשָּׁרְתָה שְׁכִינָה בְּתוֹכוֹ (ס\"א אליו), כַּמָּה חֲיָלוֹת וּמַחֲנוֹת בָּאוּ עִמָּהּ, וּמֵאוֹתָם מַלְאָכִים שָׁלַח לְעֵשָׂו.</p>\n<p>וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים. אָמַר רַבִּי אַבָּא, וְכִי מַה הוּא הִתְעוֹרֵר אֶל עֵשָׂו? וְטוֹב הָיָה לוֹ לִשְׁתֹּק מִמֶּנּוּ. אֶלָּא, אָמַר יַעֲקֹב, יוֹדֵעַ אֲנִי שֶׁעֵשָׂו חוֹשֵׁשׁ לִכְבוֹד אַבָּא וּלְעוֹלָם לֹא הִרְגִּיז אוֹתוֹ, וַהֲרֵינִי יוֹדֵעַ, שׁהוֹאִיל וְאַבָּא קַיָּם, אֵינִי פּוֹחֵד מִמֶּנּוּ, אֲבָל עַכְשָׁו שֶׁאַבָּא קַיָּם, אֲנִי רוֹצֶה לְהִתְפַּיֵּס עִמּוֹ. מִיָּד - וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים לְפָנָיו.</p>\n<p>וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים, רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי יב) טוֹב נִקְלֶה וְעֶבֶד לוֹ מִמִּתְכַּבֵּד וַחֲסַר לָחֶם. פָּסוּק זֶה נֶאֱמַר עַל יֵצֶר הָרָע, מִשּׁוּם שֶׁהוּא תָמִיד מְקַטְרֵג לִבְנֵי אָדָם, וְיֵצֶר הָרָע מֵרִים לִבּוֹ וּרְצוֹנוֹ שֶׁל הָאָדָם בְּגַאֲוָה, וְהוֹלֵךְ אַחֲרָיו, מְסַלְסֵל בִּשְׂעָרוֹ וּבְרֹאשׁוֹ, עַד שֶׁמִּתְגָּאֶה עָלָיו וּמוֹשֵׁךְ אוֹתוֹ לַגֵּיהִנֹּם.</p>\n<p>אֲבָל טוֹב נִקְלֶה - אוֹתוֹ שֶׁלֹּא הוֹלֵךְ אַחַר יֵצֶר הָרָע וְלֹא מִתְגָּאֶה כְּלָל וּמַנְמִיךְ רוּחוֹ וְלִבּוֹ וּרְצוֹנוֹ אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז אוֹתוֹ יֵצֶר הָרָע מִתְהַפֵּךְ לוֹ לְעֶבֶד, שֶׁלֹּא יָכוֹל לִשְׁלֹט עָלָיו, וְאוֹתוֹ אִישׁ שׁוֹלֵט עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ד) וְאַתָּה תִּמְשָׁל בּוֹ.</p>\n<p>מִמִּתְכַּבֵּד - כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהוּא מְכַבֵּד עַצְמוֹ, מְסַלְסֵל בִּשְׂעָרוֹ, מִתְגָּאֶה בְרוּחוֹ, וְהוּא חֲסַר לָחֶם - חֲסַר אֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כא) לֶחֶם אֱלֹהָיו וְגוֹ', (שם) לֶחֶם אֱלֹהֵיהֶם הֵם מַקְרִיבִם וְגוֹ'.</p>\n<p>דָּבָר אַחֵר טוֹב נִקְלֶה וְעֶבֶד לוֹ - זֶה יַעֲקֹב שֶׁהִנְמִיךְ רוּחוֹ לְעֵשָׂו כְּדֵי שֶׁאַחַר כָּךְ יִהְיֶה לוֹ עֶבֶד וְיִשְׁלֹט עָלָיו וְיִתְקַיֵּם בּוֹ (בראשית כז) יַעַבְדוּךְ עַמִּים וְיִשְׁתַּחֲוֻ לְךְ לְאֻמִּים וְגוֹ', וַעֲדַיִן לֹא הָיָה זְמַנּוֹ כְּלָל, אֶלָּא מִשּׁוּם שֶׁהֶעֱבִירוֹ יַעֲקֹב לְסוֹף הַיָּמִים. וְעַל זֶה הָיָה מִיָּד נִקְלֶה, וְאַחַר כָּךְ אוֹתוֹ שֶׁמִּתְכַּבֵּד יִהְיֶה עֶבֶד לוֹ. אוֹתוֹ שֶׁהוּא חֲסַר לָחֶם יִהְיֶה עֶבֶד לְאוֹתוֹ שֶׁנָּתְנוּ לוֹ רֹב דָּגָן וְתִירוֹשׁ.</p>\n<p>בֹּא רְאֵה, עַל זֶה, מִשּׁוּם שֶׁיָּדַע יַעֲקֹב שֶׁהִצְטָרֵךְ לוֹ, עַכְשָׁו הִתְהַפֵּךְ לוֹ לְנִקְלֶה, וְיוֹתֵר חָכְמָה וְעַקְמוּמִיּוּת עָשָׂה בָּזֶה מִכָּל מַה שֶּׁעָשָׂה לְעֵשָׂו. שֶׁאִלּוּ הָיָה יוֹדֵעַ עֵשָׂו חָכְמָה זוֹ, יַהֲרֹג אֶת עַצְמוֹ וְלֹא יָבא לִידֵי זֶה, אֲבָל הַכֹּל עָשָׂה בְּחָכְמָה, וְעָלָיו אָמְרָה חַנָּה (שמואל אב) ה' יֵחַתּוּ מְרִיבָו וְגוֹ' וְיִתֶּן עֹז לְמַלְכּוֹ וְגוֹ'.</p>"],[9522011342,"<p>וַיְצַו אֹתָם לֵאמֹר כֹּה תֹאמְרוּן לַאדנִי לְעֵשָׂו כֹּה אָמַר עַבְדְּךְ יַעֲקֹב עִם לָבָן גַּרְתִּי וָאֵחַר עַד עָתָּה. מִיָּד פָּתַח יַעֲקֹב לְהִתְהַפֵּךְ לוֹ לְעֶבֶד כְּדֵי שֶׁלֹּא יִסְתַּכֵּל עֵשָׂו בְּאוֹתָן בְּרָכוֹת שֶׁבֵּרְכוֹ אָבִיו, שֶׁהֲרֵי יַעֲקֹב הֶעֱבִיר אוֹתָן לַסּוֹף, כְּפִי שֶׁאָמַרְנוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מָה רָאָה יַעֲקֹב שֶׁשָּׁלַח לְעֵשָׂו וְאָמַר עִם לָבָן גַּרְתִּי, וְכִי מֶה עָשָׂה בִּשְׁלִיחוּתוֹ שֶׁל עֵשָׂו (שאמר) דָּבָר זֶה? אֶלָּא לָבָן הָאֲרַמִּי, קוֹלוֹ הָלַךְ בָּעוֹלָם, שֶׁלֹּא הָיָה אָדָם שֶׁיִּנָּצֵל מִמֶּנּוּ, וְהוּא הָיָה מְכַשֵּׁף בִּכְשָׁפִים וְגָדוֹל בַּקּוֹסְמִים, וַאֲבִי בְּעוֹר הָיָה, וּבְעוֹר אֲבִי בִּלְעָם, שֶׁכָּתוּב (יהושע יג) בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם, וְלָבָן חָכָם בַּמְּכַשְּׁפִים וּבַקּוֹסְמִים יוֹתֵר מִכֻּלָּם, וְעִם כָּל זֶה לֹא יָכֹל לְיַעֲקֹב, וְרָצָה לְאַבֵּד אֶת יַעֲקֹב בְּכַמָּה כְּלֵי זַיִן. זֶהוּ שֶׁכָּתוּב (דברים כו) אֲרַמִּי אֹבֵד אָבִי.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּל הָעוֹלָם הָיוּ יוֹדְעִים שֶׁלָּבָן הָיָה גְּדוֹל הַחֲכָמִים וְהַמְּכַשְּׁפִים וְהַקּוֹסְמִים, וּמִי שֶׁרָצָה לְאַבֵּד אוֹתוֹ בִּכְשָׁפָיו, לֹא נִצַּל מִמֶּנּוּ, וְכָל מַה שֶּׁיָּדַע בִּלְעָם - מִמֶּנּוּ הָיָה, וְכָתוּב בְּבִלְעָם (במדבר כב) כִּי יָדַעְתִּי אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ וַאֲשֶׁר תָּאֹר יוּאָר, וְכָל הָעוֹלָם הָיוּ פוֹחֲדִים מִלָּבָן וּמִכְּשָׁפָיו. וְדָבָר רִאשׁוֹן שֶׁשָּׁלַח יַעֲקֹב לְעֵשָׂו - אָמַר עִם לָבָן גַּרְתִּי. וְאִם תֹּאמַר שֶׁמְּעַט הָיָה, חֹדֶשׁ אוֹ שָׁנָה - לֹא כָּךְ, אֶלָּא וָאֵחַר עַד עָתָּה, עֶשְׂרִים שָׁנָה הִתְאַחַרְתִּי עִמּוֹ.</p>\n<p>וְאִם תֹּאמַר שֶׁלֹּא עָלָה בְיָדִי כְּלוּם - וַיְהִי לִי שׁוֹר וַחֲמוֹר. אוֹתָם שְׁנֵי גִּזְרֵי דִין, שֶׁכְּשֶׁשְּׁנֵיהֶם מִתְחַבְּרִים יַחַד, לֹא מִתְחַבְּרִים אֶלָּא לְהָרַע לָעוֹלָם, וְלָכֵן כָּתוּב (דברים כב) לֹא תַחֲר!שׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו.</p>\n<p>צֹאן וְעֶבֶד וְשִׁפְחָה - אֵלּוּ הֵם כְּתָרִים תַּחְתּוֹנִים שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, (שמות יב) בְּכוֹר בְּהֵמָה, (שם) בְּכוֹר הַשְּׁבִי, (שם יא) בְּכוֹר הַשִּׁפְחָה. זֶהוּ שֶׁכָּתוּב צֹאן וְעֶבֶד וְשִׁפְחָה. מִיָּד הָיָה עֵשָׂו פּוֹחֵד וְיָצָא כְּנֶגְדּוֹ, וּפַחַד הָיָה לוֹ מִיַּעֲקֹב כְּמוֹ שֶׁהָיָה לְיַעֲקֹב מֵעֵשָׂו.</p>\n<p>לְאִישׁ שֶׁהָיָה הוֹלֵךְ בַּדֶּרֶךְ. עַד שֶׁהָיָה הוֹלֵךְ, שָׁמַע עַל לִסְטִים אֶחָד שֶׁהָיָה אוֹרֵב בַּדֶּרֶךְ. פָּגַשׁ אוֹתוֹ אִישׁ אַחֵר, אָמַר לוֹ: מִמִּי אַתָּה? אָמַר לוֹ: אֲנִי מִלִּגְיוֹן פְּלוֹנִי. אָמַר לוֹ: סְטֵה לְךְ מִלְּפָנַי, שֶׁכָּל מִי שֶׁקָּרֵב אֵלַי, אֲנִי מֵבִיא נָחָשׁ אֶחָד שֶׁהוֹרֵג אוֹתוֹ. הָלַךְ אוֹתוֹ הָאִישׁ לְאוֹתוֹ הַלִּגְיוֹן. אָמַר לוֹ: אִישׁ אֶחָד בָּא, וְכָל מִי שֶׁקָּרֵב אֵלָיו, נוֹשֵׁךְ אוֹתוֹ נָחָשׁ אֶחָד שֶׁהוּא מֵבִיא, וּמֵת.</p>\n<p>שָׁמַע אוֹתוֹ לִגְיוֹן וּפָחַד. אָמַר: יָפֶה שֶׁאֵלֵךְ עִמּוֹ וְאֶתְפַּיֵּס עִמּוֹ. עַד שֶׁרָאָה אוֹתוֹ אוֹתוֹ הָאִישׁ, אָמַר: אוֹי וַאֲבוֹי שֶׁעַכְשָׁו יַהֲרֹג אוֹתוֹ אוֹתוֹ הַלִּגְיוֹן. הִתְחִיל לְהִשְׁתַּחֲווֹת וְלִכְרֹעַ כְּנֶגְדּוֹ. אָמַר אוֹתוֹ לִגְיוֹן: אִלְמָלֵא הָיָה לוֹ בְּיָדוֹ נָחָשׁ לַהֲרֹג, לֹא הָיָה מִשְׁתַּחֲוֶה כָּל זֶה כְּנֶגְדִּי. הִתְחִיל הַלִּגְיוֹן לְהִתְגָּאוֹת. אָמַר: הוֹאִיל וְכָל כָּךְ כָּרַע לְנֶגְדִּי, לֹא אֶהֱרֹג אוֹתוֹ.</p>\n<p>כָּךָ אָמַר יַעֲקֹב, עִם לָבָן גַּרְתִּי וָאַחֵר עַד עָתָּה. עֶשְׂרִים שָׁנָה הִתְאַחַרְתִּי עִמּוֹ, וַאֲנִי מֵבִיא נָחָשׁ לַהֲרֹג בְּנֵי אָדָם. שָׁמַע עֵשָׂו, אָמַר, אוֹי מִי יָקוּם לְפָנָיו, שֶׁעַכְשָׁו יַהֲרֹג אוֹתוֹ יַעֲקֹב בְּפִיו. הִתְחִיל לָצֵאת כְּנֶגְדּוֹ לְהִתְפַּיֵּס עִמּוֹ.</p>\n<p>כֵּיוָן שֶׁרָאָה אוֹתוֹ מַה כָּתוּב? וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ. כֵּיוָן שֶׁקָּרַב אֵלָיו, הִתְחִיל לִכְרֹעַ וְלִסְגֹּד לְפָנָיו, זֶהוּ שֶׁכָּתוּב וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו. אָמַר עֵשָׂו, אִלְמָלֵא כָּל כָּךְ הָיָה עִמּוֹ, לֹא יִשְׁתַּחֲוֶה כְּנֶגְדִּי. הִתְחִיל לְהִתְגָּאוֹת.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב בְּבִלְעָם, (במדבר כב) וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם לַיְלָה. בְּלָבָן כָּתוּב (בראשית לא) וַיָּבא אֱלֹהִים אֶל לָבָן הָאֲרַמִּי בַּחֲלוֹם הַלַּיְלָה וַיֹּאמֶר לוֹ הִשָּׁמֶר לְךְ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב וְגוֹ'. פֶּן תְּדַבֵּר? פֶּן תַּעֲשֶׂה לְיַעֲקֹב רָעָה צָרִיךְ לִכְתֹּב! אֶלָּא לָבָן לֹא רָדַף אַחֲרֵי יַעֲקֹב בְּכֹחַ גִּבּוֹרִים לַעֲרֹךְ בּוֹ קְרָב, שֶׁהֲרֵי חֵיל יַעֲקֹב וּבָנָיו גָּדוֹל מִמֶּנּוּ, אֶלָּא לְהָרְגוֹ בְּפִיו וּלְהַשְׁמִידוֹ אֶת הַכֹּל. זֶהוּ שֶׁכָּתוּב אֲרַמִּי אֹבֵד אָבִי. וְלָכֵן כָּתוּב פֶּן תְּדַבֵּר וְלֹא פֶּן תַּעֲשֶׂה. וְכָתוּב יֶשׁ לְאֵל יָדִי לַעֲשׂוֹת. מִנַּיִן הָיָה יוֹדֵעַ שֶׁיְּכֹלֶת הָיְתָה בְּיָדוֹ? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר אֱלֹהֵי אֲבִיכֶם אֶמֶשׁ אָמַר אֵלַי.</p>\n<p>וְזוֹהִי הָעֵדוּת שֶׁצִּוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָעִיד, שֶׁכָּתוּב (דברים כו) וְעָנִיתָ וְאָמַרְתָּ לִפְנֵי ה' אֱלֹהֶיךְ אֲרַמִּי אֹבֵד אָבִי וְגוֹ'. וְעָנִיתָ - כְּמוֹ שֶׁנֶּאֱמַר (שמות כ) לֹא תַעֲנֶה בְרֵעֲךְ, (דברים יט) עָנָה בְאָחִיו.</p>\n<p>כָּתוּב בְּבִלְעָם (במדבר כד) וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים, שֶׁכָּךְ הוּא דַּרְכּוֹ - שֶׁהוּא הָיָה מְנַחֵשׁ. בְּלָבָן כָּתוּב (בראשית ל) נִחַשְׁתִּי, שֶׁהִשְׁגִּיחַ בִּכְשָׁפָיו וּבִקְסָמָיו בָּעֵסֶק שֶׁל יַעֲקֹב, וּכְשֶׁרָצָה לְהַאֲבִיד אֶת יַעֲקֹב בַּנְּחָשִׁים וּבַכִּשּׁוּפִים שֶׁלּוֹ, רָצָה לְאַבְּדוֹ, וְלֹא עֲזָבוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְהַיְנוּ שֶׁאָמַר בִּלְעָם בֶּן בְּנוֹ, כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. מִי יָכוֹל לָהֶם? שֶׁהֲרֵי סָבִי רָצָה לְאַבֵּד אֶת אֲבִיהֶם בַּנְּחָשִׁים וּבַקְּסָמִים שֶׁלּוֹ וְלֹא עָלָה בְיָדוֹ, שֶׁלֹּא הִשְׁאִירוֹ לְקַלֵּל. זֶהוּ שֶׁכָּתוּב כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל.</p>\n<p>וּבְכָל עֲשֶׂרֶת מִינֵי כְשָׁפִים וּקְסָמִים מֵהֶאָרַת הַכְּתָרִים הַתַּחְתּוֹנִים עָשָׂה לָבָן כְּנֶגֶד יַעֲקֹב, וְלֹא יָכֹל. זֶהוּ שֶׁכָּתוּב (בראשית לא) וַתַּחֲלֵף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מֹנִים. שֶׁכֻּלָּם עָשָׂה לָבָן כְּנֶגְדּוֹ וְלֹא עָלָה בְיָדוֹ לְהָרַע לוֹ, שֶׁכָּתוּב (שם) וְהֶחֱלִף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מֹנִים וְלֹא נְתָנוֹ אֱלֹהִים לְהָרַע עִמָּדִי. מַה זֶּה מֹנִים? כְּתַרְגּוּם מִינִים, וְכָתוּב (ויקרא יז) לַשְּׂעִירִם אֲשֶׁר הֵם זנִים אַחֲרֵיהֶם. מוֹנִים - מִינִים כְּמַשְׁמָעוֹ. וַעֲשָׂרָה מִינִים הֵם שֶׁל כְּשָׁפִים וּקְסָמִים בַּכְּתָרִים הַתַּחְתּוֹנִים, וְכֻלָּם עָשָׂה כְּנֶגְדּוֹ.</p>\n<p>עָשָׂרָה מִינִים הֵם, שֶׁכָּתוּב (דברים יח) קֹסֵם קְסָמִים מְעוֹנֵן וּמְנַחֵשׁ וּמְכַשֵּׂף וְחֹבֵר חָבֶר וְשֹׁאֵל אוֹב וְיִדְּעֹנִי וְדֹרֵשׁ אֶל הַמֵּתִים. הֲרֵי הֵם עֲשָׂרָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, נַחַשׁ וְקֶסֶם הֵם שְׁנֵי מִינִים, וּבְדַרְגָּה אַחַת עוֹלִים, וּכְשֶׁבָּא בִּלְעָם, בְּקֶסֶם עָשָׂה כְּנֶגֶד יִשְׂרָאֵל, וְהַיְנוּ שֶׁכָּתוּב (במדבר כב) וּקְסָמִים בְּיָדָם. וּכְנֶגֶד יַעֲקֹב בָּא לָבָן בְּנַחַשׁ. זֶה וָזֶה לֹא עָלָה בְיָדָם. זֶהוּ שֶׁכָּתוּב (שם כג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. כִּי לֹא נַחַשׁ בְּיַעֲקֹב - בַּתְּחִלָּה בִּימֵי לָבָן. וְלֹא קֶסֶם בְּיִשְׂרָאֵל - אַחַר כָּךְ בִּימֵי בִלְעָם.</p>\n<p>אָמַר בִּלְעָם לְבָלָק, בֹּא רְאֵה מִי יָכוֹל לָהֶם, שֶׁכָּל הַקְּסָמִים וְהַכְּשָׁפִים שֶׁבַּכְּתָרִים שֶׁלָּנוּ מֵהֶאָרַת הַמַּלְכוּת שֶׁלְּמַעְלָה (ומטה) מִתְעַטְּרִים, (שהרי) וְהוּא הִתְקַשֵּׁר בָּהֶם, שֶׁכָּתוּב ה' אֱלֹהָיו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, חַס וְחָלִילָה שֶׁהָיָה יוֹדֵעַ בִּלְעָם בַּקְּדֻשָּׁה שֶׁלְּמַעְלָה כְּלָל, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הִתְרַצָּה בְעַם וְלָשׁוֹן אַחֵר שֶׁיִּשְׁתַּמֵּשׁ בִּכְבוֹדוֹ אֶלָּא בָּנָיו הַקְּדוֹשִׁים, וְאָמַר (ויקרא יא) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים. מִי שֶׁהֵם קְדוֹשִׁים יִשְׁתַּמְּשׁוּ בַּקְּדֻשָּׁה. יִשְׂרָאֵל הֵם קְדוֹשִׁים, שֶׁכָּתוּב (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה. אַתָּה קָדוֹשׁ וְלֹא עַם אַחֵר.</p>\n<p>מִי שֶׁהֵם טְמֵאִים, טֻמְאָה מִזְדַּמֶּנֶת לָהֶם לְהִטָּמֵא עָלָיו. כָּתוּב (ויקרא יג) טָמֵא הוּא בָּדָד יֵשֵׁב מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ, וְטָמֵא לְטָמֵא קוֹרֵא, שֶׁכָּתוּב (שם) וְטָמֵא טָמֵא יִקְרָא. מִי שֶׁהוּא טָמֵא לְטָמֵא יִקְרָא, הַכֹּל הוֹלֵךְ אַחַר מִינוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, נָאֶה הוּא לְיַעֲקֹב, שֶׁהָיָה קָדוֹשׁ, לוֹמַר שֶׁנִּטְמָא בְּלָבָן וּבִכְשָׁפָיו, אוֹ שֶׁבַח הוּא שֶׁלּוֹ? אָמַר לוֹ רַבִּי יוֹסֵי, אַף עַל גַּב שֶׁאָמַר רַבִּי יְהוּדָה - אֲנִי מְסַיֵּעַ לְךְ, שֶׁהֲרֵי כָּתוּב (בראשית כז) אָנֹכִי עֵשָׂו בְּכֹרֶךְ. וְכִי יָפֶה הוּא לְצַדִּיק כְּיַעֲקֹב לְהַחֲלִיף שְׁמוֹ בְּשֵׁם טֻמְאָה? אֶלָּא אָנֹכִי, פּוֹסֵק טַעַם, וְאוֹמֵר אָנֹכִי מִי שֶׁאֲנִי, אֲבָל עֵשָׂו בְּכֹרֶךְ, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>אַף כָּאן. וַיְהִי לוֹ שׁוֹר וַחֲמֹר. לוֹמַר, אַל תָּשִׂים לִבְּךְ וּרְצוֹנְךְ לְאוֹתָהּ בְּרָכָה שֶׁבֵּרְכַנִי אַבָּא שֶׁהִתְקַיְּמָה בִּי. הוּא בֵּרַךְ אוֹתִי הֱוֵה גְבִיר לְאַחֶיךְ וְיִשְׁתַּחֲווּ לְךְ בְּנֵי אִמֶּךְ - מִשּׁוּם כָּךְ עַבְדְּךְ יַעֲקֹב לַאדנִי לְעֵשָׂו. הוּא בֵּרַךְ אוֹתִי בְּרֹב דָּגָן וְתִירוֹשׁ - הֲרֵי לֹא הִתְקַיֵּם בִּי, שֶׁלֹּא אָצַרְתִּי אוֹתָם, אֶלָּא וַיְהִי לִי שׁוֹר וַחֲמוֹר צֹאן וְעֶבֶד, רוֹעֵה צֹאן בַּשָּׂדֶה. הוּא בֵּרַךְ אוֹתִי מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ - הֲרֵי לֹא הִתְקַיֵּם בִּי, מִשּׁוּם שֶׁהֲרֵי עִם לָבָן גַּרְתִּי, כְּגֵר, שֶׁלֹּא הָיָה לִי בַּיִת אֶחָד, כָּל שֶׁכֵּן מִשְׁמַנֵּי הָאָרֶץ. וְכָל זֶה כְּדֵי שֶׁלֹּא יִסְתַּכֵּל בְּיַעֲקֹב עַל אוֹתָן בְּרָכוֹת וִיקַטְרֵג עִמּוֹ.</p>\n<p>רַבִּי אַבָּא אָמַר, כָּתוּב בְּיַעֲקֹב (שם כה) אִישׁ תָּם יֹשֵׁב אֹהָלִים, גֶּבֶר שָׁלֵם, מִשּׁוּם שֶׁהוּשׂ יוֹשֵׁב בִּשְׁנֵי מִשְׁכָּנִים עֶלְיוֹנִים, וְהִשְׁלִים לְצַד זֶה וּלְצַד זֶה. וְהוּא לֹא אָמַר שֶׁנִּטְמָא בִּכְשָׁפָיו. אֲבָל עַל מַה שֶׁאָמַר רַבִּי יְהוּדָה, מִשּׁוּם שֶׁלִּבּוֹ שָׁלֵם עַל טוֹב וֶאֱמֶת שֶׁעָשָׂה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל הָעוֹלָם יוֹדְעִים מַעֲשֵׂי לָבָן מַה הֵם וּמִי יָכוֹל לְהִנָּצֵל (ס\"א ממנו, כל עשרים השנים שהייתי עמו) מִקִּטְרוּגוֹ, וְרָצָה לְאַבֵּד אוֹתִי (ס\"א ואני ישבתי ועשיתי עמו עשרים שנה) וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִצִּילַנִי מִמֶּנּוּ. וְהַכֹּל הָיָה כְּדֵי שֶׁלֹּא יִסְתַּכֵּל בּוֹ עֵשָׂו שֶׁהִתְקַיְּמוּ בוֹ אוֹתָן בְּרָכוֹת וְלֹא יִשְׁמֹר לוֹ טִינָה. וְעַל זֶה כָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ', וְכָתוּב (דברים יח) תָּמִים תִּהְיֶה עִם ה' אֱ לֹהֶיךְ.</p>"],[9522011343,"<p>וַיָּשֻׁבוּ הַמַּלְאָכִים אֶל יַעֲקֹב לֵאמֹר בָּאנוּ אֶל אָחִיךְ אֶל עֵשָׂו וְגַם הֹלֵךְ לִקְרָאתְךְ וְאַרְבַּע מֵאוֹת אִישׁ עִמּוֹ. כֵּיוָן שֶׁאָמַר בָּאנוּ אֶל אָחִיךְ, לֹא יָדַעְנוּ שֶׁהוּא עֵשָׂו? וְכִי אַחִים אֲחֵרִים הָיוּ לְיַעֲקֹב? אֶלָּא בָּאנוּ אֶל אָחִיךְ. וְאִם תֹּאמַר שֶׁחָזַר בִּתְשׁוּבָה וְהוֹלֵךְ בְּדֶרֶךְ תְּקִינָה - לֹא כָּךְ, אֶלָּא עֵשָׂו הָרָשָׁע כְּמוֹ מֵעִקָּרוֹ. וְגַם הֹלֵךְ לִקְרָאתְךְ. וְאִם תֹּאמַר שֶׁהוּא הוֹלֵךְ לְבַדּוֹ - לֹא, אֶלָּא אַרְבַּע מֵאוֹת אִישׁ עִמּוֹ.</p>\n<p>וְכָל כָּךְ לָמָּה? (אלא הם) אָמְרוּ לוֹ, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד מְרֻצֶּה בִּתְפִלּוֹת הַצַּדִּיקִים וּמִתְעַטֵּר בִּתְפִלּוֹתֵיהֶם, כְּמוֹ שֶׁאָמַרְנוּ שֶׁאוֹתוֹ הַמַּלְאָךְ הַמְמֻנֶּה עַל תְּפִלּוֹת יִשְׂרָאֵל, סַנְדַּלְפוֹ\"ן שְׁמוֹ, נוֹטֵל כָּל אוֹתָן תְּפִלּוֹת וְעוֹשֶׂה מֵהֶם עֲטָרָה לְחַי הָעוֹלָמִים וּבֵאֲרוּהָ, וְכָל שֶׁכֵּן תְּפִלּוֹת הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶן, וְנַעֲשׂוֹת עֲטָרָה לְהִתְעַטֵּר בְּאוֹתָן תְּפִלּוֹת לַקָּדוֹשׁ- בָּרוּךְ-הוּא. וְאִם תֹּאמַר, מַחֲנוֹת קְדוֹשִׁים הָיוּ בָאִים עִמּוֹ, אָז לָמָּה פָּחַד? אֶלָּא צַדִּיקִים לֹא סוֹמְכִים עַל זְכֻיּוֹתֵיהֶם, אֶלָּא עַל תְּפִלּוֹתֵיהֶם וּבַקָּשׁוֹתֵיהֶם לְרִבּוֹנָם.</p>\n<p>וּבֹא וּרְאֵה שֶׁאָמַר רַבִּי שִׁמְעוֹן, תְּפִלַּת רַבִּים עוֹלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִתְעַטֵּר בְּאוֹתָהּ תְּפִלָּה, מִשּׁוּם שֶׁעוֹלָה בִּגְוָנִים רַבִּים וְנִכְלֶלֶת מִכַּמָּה צְדָדִים, וּמִשּׁוּם שֶׁנִּכְלֶלֶת מִכַּמָּה גְוָנִים, נַעֲשֵׂית עֲטָרָה, וּמֻנַּחַת עַל רֹאשׁ צַדִּיק חַי הָעוֹלָמִים. וּתְפִלַּת הַיָּחִיד אֵינָהּ כְּלוּלָה וְאֵינָה אֶלָּא בְּגָוֶן אֶחָד, וְעַל כֵּן תְּפִלַּת יָחִיד אֵינָהּ מְתֻקֶּנֶת לְהִתְקַבֵּל (אלא בתפלה) כִּתְפִלַּת רַבִּים. וּבא וּרְאֵה, יַעֲקֹב הָיָה כָּלוּל, וְעַל כָּךְ תְּפִלָּתוֹ הִשְׁתּוֹקֵק לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה כָּתוּב? וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ.</p>\n<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (משלי כח) אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד וּמַקְשֶׁה לִבּוֹ יִפּוֹל בְּרָעָה. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם וְנָתַן לָהֶם תּוֹרַת אֱמֶת כְּדֵי לִזְכּוֹת בָּהּ לְחַיֵּי עוֹלָם, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ עָלָיו חַיִּים עֶלְיוֹנִים וּמַכְנִיסוֹ לְחַיֵּי הָעוֹלָם הַבָּא, שֶׁכָּתוּב (דברים ל) כִּי הִיא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ, וְכָתוּב (שם לב) וּבַדָּבָר הַזֶּה תַּאֲרִיכוּ יָמִים. חַיִּים בָּעוֹלָם הַזֶּה, וְחַיִּים בָּעוֹלָם הַבָּא.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אֵין מִיתָתוֹ עַל יְדֵי יֵצֶר הָרָע, מִשּׁוּם (שהוא נחש, והוא מלאך המות, אלא מיתתם בנשיקה, שכתוב (שיר א) ישקני מנשיקות פיהו, כלומר על פי ה', והיא הנשיקה שהיא דבקות של הנפש בעקר, ואותו שמשתדל בתורה) שֶׁהִתְחַזֵּק בְּעֵץ הַחַיִּים וְלֹא הִרְפָּה מִמֶּנּוּ, וְלָכֵן צַדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה לֹא נִטְמָא גוּפָם (אלא הוא טהור, כמו אליהו בבית הקברות שמצאו אותו רבנן ושאלו אותו, ולא כהן הוא מר? אמר להם, צדיקים לא טמאים במיתתם, כמו ששנינו, ביום שמת רבי בטלה כהנה, כלומר שהתעסקו בו) שֶׁלֹּא שָׁרְתָה עֲלֵיהֶם רוּחַ טֻמְאָה.</p>\n<p>יַעָקֹב הָיָה עֵץ הַחַיִּים, לָמָּה פָּחַד, שֶׁהֲרֵי לֹא יָכוֹל לִשְׁלֹט עָלָיו? וְעוֹד, שֶׁהֲרֵי כָּתוּב וְהִנֵּה אָנֹכִי עִמָּךְ וְגוֹ', לָמָּה הָיָה פּוֹחֵד? וְעוֹד, שֶׁהֲרֵי כָּתוּב וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים, אִם מַחֲנוֹת קְדוֹשִׁים הָיוּ עִמּוֹ, לָמָּה הָיָה פּוֹחֵד?</p>\n<p>אֶלָּא הַכֹּל הָיָה נָאֶה, וְיַעֲקֹב לֹא הָיָה רוֹצֶה לִסְמֹךְ עַל נֵס שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁחָשַׁב שֶׁאֵינוֹ כְּדַאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲשֶׂה לוֹ נֵס, מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא עָבַד אֶת אָבִיו וְאִמּוֹ כָּרָאוּי וְלֹא הִשְׁתַּדֵּל בַּתּוֹרָה וְנָשָׂא שְׁתֵּי אֲחָיוֹת, וְאַף עַל גַּב שֶׁהַכֹּל נִתְבָּאֵר. וְעִם כָּל זֶה צָרִיךְ לָאָדָם לִפְחֹד תָּמִיד וּלְהִתְפַּלֵּל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְפִלָּה, שֶׁכָּתוּב אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד (ולפחד תמיד מלפני הקדוש ברוך הוא), וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, תְּפִלַּת הָאָבוֹת הֶעֱמִידוּ עוֹלָם, וְכָל בְּנֵי הָעוֹלָם עֲלֵיהֶם עוֹמְדִים וּסְמוּכִים, וּלְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים לֹא נִשְׁכַּחַת זְכוּת הָאָבוֹת, מִשּׁוּם שֶׁזְּכוּת הָאָבוֹת הִיא קִיּוּם שֶׁל מַעְלָה וּמַטָּה, וְקִיּוּם שֶׁל יַעֲקֹב הוּא קִיּוּם שָׁלֵם יוֹתֵר מִכֻּלָּם. וְלָכֵן בְּשָׁעָה שֶׁצָּרָה לִבְנֵי יַעֲקֹב, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אֶת דְּמוּת יַעֲקֹב וְחָס עַל הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. יַעֲקוֹ\"ב בְּוָא\"ו, לָמָּה בְּוָא\"ו? מִשּׁוּם שֶׁהוּא דְּמוּת שֶׁל יַעֲקֹב מַמָּשׁ.</p>\n<p>בֹּא רְאֵה, כָּל מִי שֶׁרוֹאֶה אֶת יַעֲקֹב, כְּמִי שֶׁמִּסְתַּכֵּל בְּאַסְפַּקְלַרְיָה הַמְּאִירָה (תפארת), וַהֲרֵי נֶאֱמַר שֶׁיָּפְיוֹ שֶׁל יַעֲקֹב כְּיָפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן. אָמַר רַבִּי יֵיסָא, אֲנִי שָׁמַעְתִּי, שֶׁכָּל מִי שֶׁמִּסְתַּכֵּל בַּחֲלוֹמוֹ וְרוֹאֶה אֶת יַעֲקֹב מְעֻטָּף בְּמַלְבּוּשָׁיו, מִתּוֹסְפִים לוֹ חַיִּים.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, הֲרֵי נֶאֱמַר שֶׁדָּוִד הַמֶּלֶךְ, עַד שֶׁלֹּא הָיָה, לֹא הָיוּ לוֹ חַיִּים כְּלָל, פְּרָט לְזֶה שֶׁאָדָם הָרִאשׁוֹן נָתַן לוֹ שִׁבְעִים שָׁנָה מִשֶּׁלּוֹ, וְכָךְ הָיָה קִיּוּמוֹ שֶׁל דָּוִד הַמֶּלֶךְ שִׁבְעִים שָׁנָה הָיוּ, וְקִיּוּם שֶׁל אָדָם הָרִאשׁוֹן אֶלֶף שָׁנָה חָסֵר שִׁבְעִים. נִמְצְאוּ בְּאֵלֶּה אֶלֶף שָׁנִים רִאשׁוֹנוֹת אָדָם הָרִאשׁוֹן וְדָוִד הַמֶּלֶךְ.</p>\n<p>פָּתַח וְאָמַר, (תהלים כא) חַיִּים שָׁאַל מִמְּךְ נָתַתָּה לּוֹ אֹרֶךְ יָמִים עוֹלָם וָעֶד. חַיִּים שָׁאַל מִמְּךְ - זֶה דָּוִד הַמֶּלֶךְ. שֶׁהֲרֵי כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא גַּן עֵדֶן, הִטִּיל בּוֹ נִשְׁמַת דָּוִד הַמֶּלֶךְ, וְהִסְתַּכֵּל בּוֹ וּרְאֵה שֶׁאֵין לוֹ חַיִּים מִשֶּׁלּוֹ כְּלוּם וְעוֹמֵד לְפָנָיו כָּל הַיּוֹם. כֵּיוָן שֶׁנִּבְרָא אָדָם הָרִאשׁוֹן, אָמַר, הֲרֵי וַדַּאי קִיּוּמוֹ. וּמֵאָדָם הָרִאשׁוֹן הָיוּ שִׁבְעִים שָׁנים שֶׁהִתְקַיֵּם דָּוִד הַמֶּלֶךְ בָּעוֹלָם.</p>\n<p>עוֹד הָאָבוֹת הִשְׁאִירוּ לוֹ מֵחַיֵּיהֶם כָּל אֶחָד וְאֶחָד. אַבְרָהָם הִשְׁאִיר לוֹ, וְכָךְ יַעֲקֹב וְיוֹסֵף. יִצְחָק לוֹ הִשְׁאִיר לוֹ כְּלוּם, מִשּׁוּם שֶׁדָּוִד הַמֶּלֶךְ בָּא מִצִּדּוֹ.</p>\n<p>וַדַּאי אַבְרָהָם הִשְׁאִיר לוֹ חָמֵשׁ שָׁנִים, שֶׁהָיָה לוֹ לְהִתְקַיֵּם מֵאָה וּשְׁמוֹנִים שָׁנִים, וְהִתְקַיֵּם מֵאָה וְשִׁבְעִין וְחָמֵשׁ שָׁנִים, חֲסֵרִים חָמֵשׁ. יַעֲקֹב הָיָה לוֹ לְהִתְקַיֵּם בָּעוֹלָם כִּימֵי אַבְרָהָם, וְלֹא הִתְקַיֵּם אֶלָּא מֵאָה וְאַרְבָּעִים וְשֶׁבַע שָׁנִים. חֲסֵרִים עֶשְׂרִים וּשְׁמוֹנֶה. נִמְצָא שֶׁאַבְרָהָם וְיַנֲקֹב הִשְׁאִירוּ לוֹ מֵחַיֵּיהֶם שְׁלֹשִׁים וְשָׁלֹשׁ שָׁנִים. יוֹסֵף שֶׁהִתְקַיֵּם מֵאָה וְעֶשֶׂר שָׁנִים, הָיָה לוֹ לְהִתְקַיֵּם מֵאָה וְאַרְבָּעִים וְשֶׁבַע שָׁנִים כִּימֵי יַעֲקֹב, וְחָסֵר מֵהֶם שְׁלֹשִׁים וְשֶׁבַע שָׁנִים. הֲרֵי שִׁבְעִים שָׁנִים שֶׁהִשְׁאִירוּ לְדָוִד הַמֶּלֶךְ לְהִתְקַיֵּם בָּהֶם, וּבָהֶם הִתְקַיֵּם דָּוִד בְּכָל אוֹתָם הַשָּׁנִים שֶׁהִשְׁאִירוּ לוֹ הָאָבוֹת.</p>\n<p>וְאִם תֹּאמַר, לָמָּה יִצְחָק לֹא הִשְׁאִיר לוֹ כְּלוּם כְּאֵלֶּה? מִשּׁוּם שֶׁהוּא חֹשֶׁךְ, וְדָוִד בָּא מִצַּד הַחֹשֶׁךְ, וּמִי שֶׁהוּא בְּחֹשֶׁךְ אֵין לוֹ אוֹר כְּלָל וְאֵין לוֹ חַיִּים, וְלָכֵן לֹא הָיוּ לְדָוִד חַיִּים כְּלָל. אֲבָל אֵלֶּה שֶׁהָיָה לָהֶם אוֹר, הֵאִירוּ לְדָוִד הַמֶּלֶךְ, וּמֵהֶם הִצְטָרֵךְ לְהָאִיר וְלִהְיוֹת לוֹ חַיִּים, שֶׁהֲרֵי מִצַּד הַחֹשֶׁךְ אֵין לוֹ חַיִּים כְּלָל, וְעַל זֶה בָּא יִצְחָק בְּחֶשְׁבּוֹן.</p>\n<p>וְאִם תֹּאמַר, לָמָּה יוֹסֵף יוֹתֵר מִכֻּלָּם? אֶלָּא וַדַּאי יוֹסֵף בִּלְבַדּוֹ כְּמוֹ כֻּלָּם, מִשּׁוּם שֶׁנִּקְרָא צַדִּיק, וְזֶהוּ שֶׁמֵּאִיר לַלְּבָנָה יוֹתֵר מִכֻּלָּם, וְלָכֵן זֶה הִשְׁאִיר לְדָוִד הַמֶּלֶךְ יוֹתֵר מִכֻּלָּם חַיִּים, שֶׁכָּתוּב (בראשית א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמַיִם לְהָאִיר עַל הָאָרֶץ.</p>\n<p>בֹּא רְאֵה, יַעֲקֹב, תְּפִלָּתוֹ הֵגֵנָּה עָלָיו מֵעֵשָׂו מִשּׁוּם שֶׁרָצָה לְהַעֲבִיר זְכוּתוֹ לְבָנָיו אַחֲרָיו וְלֹא לְהוֹצִיא אוֹתָהּ עַכְשָׁו אֵצֶל עֵשָׂו, וְעַל זֶה הִתְפַּלֵּל תְּפִלָּתוֹ לַקָּדוֹשׁ- בָּרוּךְ-הוּא וְלֹא סָמַךְ עַל זְכוּתוֹ לְהַצִּילוֹ בִּגְלָלָהּ.</p>\n<p>וַיֹּאמֶר אִם יָבוֹא עֵשָׂו אֶל הַמַּחֲנֶה הָאַחַת וְהִכָּהוּ וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה. בּא רְאֵה מַה כָּתוּב, וַיַּחַץ אֶת הָעָם אֲשֶׁר אִתּוֹ וְאֶת הַצֹּאן וְאֶת הַבָּקָר וְהַגְּמַלִּים לִשְׁנֵי מַחֲנוֹת. לָמָּה לִשְׁנֵי מַחֲנוֹת? מִשּׁוּם שֶׁאָמַר, אִם יָבוֹא עֵשָׂו אֶל הַמַּחֲנֶה הָאַחַת וְהִכָּהוּ וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה.</p>\n<p>בֹּא רְאֵה שֶׁשְּׁכִינָה לֹא זָזָה מֵאֹהֶל לֵאָה וּמֵאֹהֶל רָחֵל. אָמַר יַעֲקֹב, יָדַעְתִּי שֶׁהֲרֵי שְׁמִירָה לְאֵלֶּה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. מֶה עָשָׂה? וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשֹׁנָה. אָמַר, אִם יַהֲרֹג עֵשָׂו - יַהֲרֹג אֶת אֵלֶּה, אֲבָל אֵלֶּה אֵינִי פוֹחֵד מֵהֶם, מִשּׁוּם שֶׁשְּׁכִינָה עִמָּהֶם, וְעַל זֶה - וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה. כֵּיוָן שֶׁעָשָׂה אֶת זֶה, תִּקֵּן תְּפִלָּתוֹ עֲלֵיהֶם, מַה כָּתוּב? וַיֹּאמֶר יַעֲקֹב אֱלֹהֵי אָבִי אַבְרָהָם וֵאלֹהֵי אָבִי יִצְחָק ה' הָאֹמֵר אֵלַי שׁוּב לְאַרְצְךְ וּלְמוֹלַדְתְּךְ וְאֵיטִיבָה עִמָּךְ.</p>\n<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (תהלים קב) תְּפִלָּה לְעָנִי כִי יַעֲטֹף וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ. פָּסוּק זֶה בֵּאֲרוּהוּ בְּכַמָּה מְקוֹמוֹת. אֶלָּא דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה כְּשֶׁהִסְתַּכֵּל וְרָאָה בְּדִבְרֵי הֶעָנִי, וְהִסְתַּכֵּל בּוֹ כְּשֶׁהָיָה הוֹלֵךְ וּבוֹרֵחַ מִלִּפְנֵי חָמִיו אָמַר זֶה. תְּפִלָּה לְעָנִי - זוֹהִי תְפִלָּה שֶׁמְּבַקֵּשׁ הֶעָנִי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזוֹ הַתְּפִלָּה שֶׁמַּקְדִּימָה אֶת כָּל תְּפִלּוֹת הָעוֹלָם.</p>\n<p>כָּתוּב כָּאן תְּפִלָּה לְעָנִי, וְכָתוּב שָׁם (שם צ) תְּפִלָּה לְמֹשֶׁה אִישׁ הָאֱלֹהִים. מַה בֵּין זֶה לָזֶה? אֶלָּא זוֹ תְּפִלָּה שֶׁל יָד, וְזוֹ תְּפִלָּה שֶׁל רֹאשׁ, וְאֵין לְהַפְרִיד בֵּין הַתְּפִלָּה לְעָנִי הַזּוֹ וּבֵין תְּפִלָּה לְמֹשֶׁה אִישׁ הָאֱלֹהִים, וּשְׁתֵּיהֶן שְׁקוּלוֹת כְּאַחַת.</p>\n<p>וְעַל זֶה תְּפִלַּת הֶעָנִי מַקְדִּימָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל תְּפִלּוֹת הָעוֹלָם, מִשּׁוּם שֶׁכָּתוּב (שם כב) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי וְגוֹ'. בֹּא רְאֵה, תְּפִלָּה לְעָנִי זוֹ תְּפִלָּה שֶׁל יָד, שֶׁהֶעָנִי דָּבוּק בְּעָנְיוֹ כְּמִי שֶׁאֵין לוֹ מֵעַצְמוֹ כְּלוּם.</p>\n<p>דָּבָר אַחֵר, תְּפִלָּה - זֶה מֹשֶׁה, לְעָנִי - זֶה דָּוִד, כִי יַעֲטֹף - כְּשֶׁמִּתְכַּסָּה הַלְּבָנָה וּמִתְכַּסָּה הַשֶּׁמֶשׁ מִמֶּנָּה, וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ - כְּדֵי לְהִתְחַבֵּר עִם הַשֶּׁמֶשׁ.</p>\n<p>בֹּא רְאֵה, הַתְּפִלָּה שֶׁל כָּל בְּנֵי אָדָם תְּפִלָּה, וּתְפִלַּת הֶעָנִי הִיא תְפִלָּה שֶׁעוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹבֶרֶת שְׁעָרִים וּפְתָחִים וְנִכְנֶסֶת לְהִתְקַבֵּל לְפָנָיו. זֶהוּ שֶׁכָּתוּב (שמות כב) וְהָיָה כִּי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי, וְכָתוּב שָׁמֹעַ אֶשְׁמַע צַעֲקָתוֹ. וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ - כְּמִי שֶׁמִּתְרַעֵם עַל דִּין הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, תְּפִלּוֹת הַצַּדִּיקִים חֶדְוָה לִכְנֶסֶת יִשְׂרָאֵל לְהִתְעַטֵּר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. מִשּׁוּם זֶה חֲבִיבָה הִיא יוֹתֵר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא תָּאֵב לִתְפִלּוֹת הַצַּדִּיקִים בְּשָׁעָה שֶׁצָּרִיךְ לָהֶם, מִשּׁוּם שֶׁיּוֹדְעִים לְרַצּוֹת אֶת רִבּוֹנָם.</p>\n<p>מַה כָּתוּב בְּיַעֲקֹב? אֱלֹהֵי אָבִי אַבְרָהָם וֵאלֹהֵי אָבִי יִצְחָק ה' הָאֹמֵר אֵלַי שׁוּב וְגוֹ'. הִתְעַטֵּר וְנִקְשַׁר קֶשֶׁר בְּקֶשֶׁר אֶחָד כָּרָאוּי. אֱלֹהֵי אָבִי אַבְרָהָם לְיָמִין, וֵאלֹהֵי אָבִי יִצְחָק לִשְׂמֹאל. הָאֹמֵר אֵלַי - כָּאן תָּלָה הַדָּבָר לְהִתְעַטֵּר לִמְקוֹמוֹ בֵּינֵיהֶם. שׁוּב לְאַרְצְךְ וּלְמוֹלַדְתְּךְ וְאֵיטִיבָה עִמָּךְ.</p>\n<p>קָטֹנְתּי מִכֹּל הַחֲסָדִים. לָמָּה הָיָה צָרִיךְ זֶה עִם זֶה? אֶלָּא, אָמַר יַעֲקֹב, אַתָּה הִבְטַחְתָּ לִי לְהֵיטִיב עִמִּי, וַאֲנִי יָדַעְתִּי שֶׁכָּל מַעֲשֶׂיךְ כֻּלָּם הֵם עַל תְּנַאי, הֲרֵי אֲנִי אֵין בִּי זְכוּת, שֶׁהֲרֵי קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת אֲשֶׁר עָשִׂיתָ אֶת עַבְדֶּךְ. וְכָל מַה שֶּׁעָשִׂיתָ לִי עַד הַיּוֹם, לֹא בִּשְׁבִיל זְכוּתִי הָיָה, אֶלָּא בִּגְלָלְךְ הוּא שֶׁעָשִׂיתָ לִי. וְאוֹתוֹ טוֹב וֶאֱמֶת בִּגְלָלְךְ הָיוּ, שֶׁהֲרֵי כְּשֶׁעָבַרְתִּי בַּתְּחִלָּה, שֶׁהָיִיתִי הוֹלֵךְ מִלִּפְנֵי עֵשָׂו, יְחִידִי עָבַרְתִּי אֶת אוֹתוֹ נָהָר, וְאַתָּה עָשִׂיתָ עִמִּי טוֹב וֶאֱמֶת, וַהֲרֵי אֲנִי עַכְשָׁו עוֹבֵר אוֹתוֹ בִּשְׁנֵי מַחֲנוֹת, הֵם שְׁנֵי הַמַּחֲנוֹת שֶׁחִלֵּק.</p>\n<p>עַד כָּאן סִדּוּר הַשֶּׁבַח שֶׁל רִבּוֹנוֹ. מִכָּאן וּלְהַבָּא בִּקֵּשׁ מַה שֶּׁצָּרִיךְ לוֹ, לְהַרְאוֹת לְכָל בְּנֵי הָעוֹלָם שֶׁצָּרִיךְ לוֹ לָאָדָם לְסַדֵּר שֶׁבַח שֶׁל אֲדוֹנוֹ בַּתְּחִלָּה, וְאַחַר יְבַקֵּשׁ בַּקָּשׁוֹתָיו. שֶׁכָּךְ עָשָׂה יַעֲקֹב - בַּתְּחִלָּה סִדֵּר שְׁבָחָיו שֶׁל קוֹנוֹ, וְאַחַר שֶׁסִּדֵּר הַשֶּׁבַח, אָמַר בַּקָּשָׁתוֹ שֶׁהִצְטָרֵךְ לָהּ.</p>\n<p>זֶהוּ שֶׁכָּתוּב: הַצִּילֵנִי נָא מִיַּד אָחִי מִיַּד עֵשָׂו כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבוֹא וְהִכַּנִי אֵם עַל בָּנִים. מִכָּאן, מִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ שֶׁצָּרִיךְ לְפָרֵשׁ דְּבָרָיו כָּרָאוּי. הַצִּילֵנִי נָא. וְאִם תֹּאמַר שֶׁהֲרֵי הִצַּלְתַּנִי מִלָּבָן - מִיַּד אָחִי. וְאִם תֹּאמַר קְרוֹבִים אֲחֵרִים סְתָם נִקְרָאִים אַחִים - מִיַּד עֵשָׂו. מָה הַטַּעַם? בִּשְׁבִיל לְפָרֵשׁ הַדָּבָר כָּרָאוּי. וְאִם תֹּאמַר, אֲנִי לָמָּה אֶצְטָרֵךְ? כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבוֹא וְהִכַּנִי. כְּדֵי לְהִוָּדַע דָּבָר לְמַעְלָה וּלְפָרְשׁוֹ כָּרָאוּי, וְלֹא יַסְתִּיר הַדָּבָר.</p>\n<p>וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב עִמָּךְ וְגוֹ'. וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב, מַה זֶּה וְאַתָּה? כְּמוֹ שֶׁנֶּאֱמַר (נחמיה ט) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. אַף כָּאן וְאַתָּה אָמַרְתָּ.</p>\n<p>בֹּא רְאֵה, דָּוִד הַמֶּלֶךְ אָמַר, (תהלים יט) יִהְיוּ לְרָצוֹן אִמְרֵי פִי, אֵלּוּ דְּבָרִים שֶׁהִתְפָּרְשׁוּ. וְהֶגְיוֹן לִבִּי - אֵלּוּ דְּבָרִים נִסְתָּרִים שֶׁלֹּא יָכוֹל בֶּן אָדָם לְפָרְשָׁם בְּפִיו, זֶהוּ הִגָּיוֹן, שֶׁהוּא בַּלֵּב, שֶׁלֹּא יָכוֹל לְהִתְפָּרֵשׁ.</p>\n<p>וְעַל זֶה צָרִיךְ הַדָּבָר לְהִתְפָּרֵשׁ בַּפֶּה, וְדָבָר שֶׁתָּלוּי בַּלֵּב, וְהַכֹּל סוֹד הוּא. אֶחָד כְּנֶגֶד דַּרְגָּה תַּחְתּוֹנָה, וְאֶחָד כְּנֶגֶד דַּרְגָּה עֶלְיוֹנָה. דָּבָר שֶׁהִתְפָּרֵשׁ, כְּנֶגֶד דַּרְגָּה תַּחְתּוֹנָה שֶׁהִצְטָרֵךְ לְהִתְפָּרֵשׁ. אוֹתוֹ שֶׁתָּלוּי בַּלֵּב הוּא כְּנֶגֶד דַּרְגָּה פְּנִימִית יוֹתֵר, וְהַכֹּל הוּא כְּאֶחָד. וְעַל זֶה אָמַר יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךְ וְגוֹ'.</p>\n<p>כְּמוֹ זֶה אָמַר יַעֲקֹב. בַּתְּחִלָּה פֵּרַשׁ הַדָּבָר כָּרָאוּי, וְאַחַר כָּךְ הִסְתִּיר הַדָּבָר שֶׁתָּלוּי בְּהֶגְיוֹן הַלֵּב שֶׁלֹּא צָרִיךְ לְפָרֵשׁ, שֶׁכָּתוּב (בראשית לב) וְשַׂמְתִּי אֶת זַרְעֲךְ כְּחוֹל הַיָּם אֲשֶׁר לֹא יִסָּפֵר מֵרֹב. כָּאן הוּא דָבָר הַתָּלוּי בַּלֵּב שֶׁלֹּא צָרִיךְ לְפָרֵשׁ, וְכֵן צָרִיךְ כְּמוֹ שֶׁאָמַרְנוּ, כְּדֵי לְיַחֵד יִחוּד שָׁלֵם כָּרָאוּי. אַשְׁרֵי הַצַּדִּיקִים שֶׁיּוֹדְעִים לְסַדֵּר שֶׁבַח רִבּוֹנָם כָּרָאוּי וּלְבַקֵּשׁ בַּקָּשָׁתָם, וְלָכֵן כָּתוּב (ישעיה מט) וַיּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. (ס\"א כתוב גם את השני גם את השלישי וגו', שלש פעמים גם, רמז (ג\"ם ראשי תבות, ' גואל משה, גואל מרדכי, גואל משיח) לשלש גאלות על ידי שלשה צדיקים, משה מרדכי משיח, שעתיד לגאלנו בקרוב).</p>"],[9522011344,"<p>וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים צא) לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה בְּכָל יוֹם וָיוֹם מַעֲשֵׂהוּ הָרָאוּי לוֹ, וַהֲרֵי פֵּרְשׁוּהָ. וְנִתְבָּאֵר, (ואם תאמר) בַּיּוֹם הָרְבִיעִי עָשָׂה מְאוֹרוֹת, וְאָז נִבְרְאָה הַלְּבָנָה חֲסֵרָה, אוֹר שֶׁהִקְטִינָה עַצְמָהּ, וּמִשּׁוּם שֶׁהִיא מְאֹרֹת חָסֵר וָא\"ו, נִתַּן מָקוֹם לִשְׁלֹט כָּל הָרוּחוֹת וְהַשֵּׁדִים וְרוּחוֹת סְעָרָה וּמַזִּיקִים וְכָל רוּחוֹת הַטֻּמְאָה.</p>\n<p>כֻּלָּם עוֹלִים וּמְשׁוֹטְטִים בָּעוֹלָם לְהַסְטוֹת, וְנִתְמַנּוּ בִּמְקוֹמוֹת חֲרֵבִים וּבְשָׂדוֹת חֲזָקִים וּבְמִדְבָּרוֹת חֲרֵבִים, וְכֻלָּם מִצַּד רוּחַ הַטֻּמְאָה. וַהֲרֵי נִתְבָּאֵר שֶׁהֲרֵי רוּחַ הַטֻּמְאָה בָּאָה שֶׁבָּאָה מִנָּחָשׁ הָעֲקַלָּתוֹן, הוּא רוּחַ טֻמְאָה מַמָּשׁ, וְהוּא הִתְמַנָּה בָּעוֹלָם לְהַסְטוֹת בֶּן אָדָם אֵלָיו, וְעַל זֶה יֵצֶר הָרָע שׁוֹלֵט בָּעוֹלָם.</p>\n<p>וְהוּא הִתְמַנָּה אֵצֶל בְּנֵי אָדָם וְנִמְצָא עִמָּם, וּבְעַקְמוּמִיּוֹת וּבְתַחְבּוּלוֹת בָּא אֲלֵיהֶם לְהַסְטוֹתָם מִדַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כְּמוֹ שֶׁהִסְטָה אֶת אָדָם הָרִאשׁוֹן וְגָרַם מָוֶת לְכָל הָעוֹלָם, כָּךְ גַּם מַסְטֶה בְּנֵי אָדָם וְגוֹרֵם לָהֶם לְהִטָּמֵא.</p>\n<p>וּמִי שֶׁבָּא לְהִטָּמֵא, מוֹשֵׁךְ עָלָיו אוֹתוֹ רוּחַ טֻמְאָה וְנִדְבָּק עִמּוֹ. וְכַמָּה הֵם שֶׁמְּזֻמָּנִים לְטַמֵּא אוֹתוֹ, וּמְטַמְּאִים אוֹתוֹ וְהוּא טָמֵא, וּמְטַמְּאִים אוֹתוֹ בָּעוֹלָם הַזֶּה וּבְאוֹתוֹ עוֹלָם, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>וּבְשָׁעָה שֶׁבָּא בֶּן אָדָם לְהִטָּהֵר, אוֹתוֹ רוּחַ טֻמְאָה נִכְפֶּה לְפָנָיו וְלֹא יָכוֹל לִשְׁלֹט עָלָיו, וְאָז כָּתוּב לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. אָמַר (כשאמר) רַבִּי יוֹסֵי, לֹא תְאֻנֶּה אֵלֶיךְ רָעָה - זוֹ לִילִית. וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ - אֵלּוּ שְׁאָר מַזִּיקִים, וַהֲרֵי פֵּרְשׁוּהָ וְנִתְבָּאֵר.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, הֲרֵי אָמַרְנוּ שֶׁלֹּא יֵצֵא אָדָם יְחִידִי בַּלַּיְלָה, וְכָל שֶׁכֵּן כְּשֶׁהַלְּבָנָה נִבְרְאָה וְהָיְתָה חֲסֵרָה, וּבֵאֲרוּהָ שֶׁהֲרֵי אָז רוּחַ טֻמְאָה שׁוֹלֶטֶת, וְזוֹהִי רוּחַ רָעָה. מִי רָעָה? זֶה נָחָשׁ הָרָע, וְנֶגַע זֶהוּ מִי שֶׁרוֹכֵב עַל הַנָּחָשׁ. רָעָה וְנֶגַע הֵם כְּאֶחָד.</p>\n<p>וְאַף עַל גַּב שֶׁשָּׁנִינוּ שֶׁנֶּגַע אֵלּוּ נִגְעֵי בְּנֵי אָדָם שֶׁיָּצְאוּ מֵאָדָם, שֶׁהֲרֵי כָּל אוֹתָן שָׁנִים שֶׁלֹּא קָרַב אָדָם לְאִשְׁתּוֹ, רוּחוֹת טֻמְאָה הָיוּ בָּאוֹת וּמִתְחַמְּמוֹת מִמֶּנּוּ וּמוֹלִידוֹת מִמֶּנּוּ, וְאֵלֶּה נִקְרָאִים נִגְעֵי בְּנֵי אָדָם.</p>\n<p>וַהֲרֵי נֶאֱמַר, שֶׁכְּשֶׁבֶּן אָדָם בַּחֲלוֹמוֹ וְלֹא שׁוֹלֵט בְּגוּפוֹ וְהַגּוּף שׁוֹכֵךְ, רוּחַ טֻמְאָה בָּאָה וְשׁוֹרָה עָלָיו, וְלִפְעָמִים רוּחוֹת נְקֵבוֹת טְמֵאוֹת בָּאוֹת וּקְרֵבוֹת אֵלָיו וּמוֹשְׁכוֹת אוֹתוֹ אֲלֵיהֶן וּמִתְחַמְּמוֹת מִמֶּנּוּ, וּמוֹלִידוֹת אַחַר כָּךְ רוּחוֹת וּמַזִּיקִים (נגעי בני אדם, כמו בני אדם), וְלִפְעָמִים נִרְאִים כְּמַרְאֵה בְּנֵי אָדָם, פְּרָט לְזֶה שֶׁאֵין לָהֶם שְׂעָרוֹת בָּרֹאשׁ.</p>\n<p>וּבַכֹּל יֵשׁ לָאָדָם לְהִשָּׁמֵר מִלִּפְנֵיהֶם כְּדֵי שֶׁיֵּלֵךְ בְּדַרְכֵי הַתּוֹרָה וְלֹא יִטָּמָא עִמָּם, שֶׁהֲרֵי אֵין לְךְ מִי שֶׁיָּשֵׁן בַּלַּיְלָה בְּמִטָּתוֹ וְלֹא טוֹעֵם טַעַם מָוֶת וְיוֹצֵאת נִשְׁמָתוֹ מִמֶּנּוּ, וְכֵיוָן שֶׁנִּשְׁאָר הַגּוּף בְּלִי נְשָׁמָה קְדוֹשָׁה, רוּחַ טֻמְאָה זְמִינָה וְשׁוֹרָה עָלָיו וְנִטְמָא. וַהֲרֵי בֵּאַרְנוּ דָבָר, שֶׁאֵין לָאָדָם לְהַעֲבִיר יָדָיו עַל עֵינָיו בַּבּקֶר, מִשּׁוּם שֶׁהֲרֵי רוּחַ טֻמְאָה שׁוֹרָה עֲלֵיהֶם, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה שֶׁהֲרֵי יַעֲקֹב, אַף עַל גַּב שֶׁנֶּאֱהַב עַל יְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁנִּשְׁאַר לְבַדּוֹ, רוּחַ אַחֶרֶת נוֹעֲדָה לְהִזְדַּוֵּג עִמּוֹ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בּא רְאֵה מַה כָּתוּב בּוֹ בְּבִלְעָם הָרָשָׁע, וַיֵּלֶךְ שֶׁפִי. מַהוּ שֶׁפִי? יְחִידִי, כְּמוֹ שֶׁנֶּאֱמַר שְׁפִיפוֹן עֲלֵי אֹרַח. כַּנָּחָשׁ הַזֶּה שֶׁהוֹלֵךְ יְחִידִי וְאוֹרֵב עַל דְּרָכִים וּשְׁבִילִים, כָּךְ גַּם בִּלְעָם הָיָה הוֹלֵךְ יְחִידִי. מָה הַטַּעַם? כְּדֵי לְהַמְשִׁיךְ עָלָיו רוּחַ טֻמְאָה. שֶׁכָּל מִי שֶׁהוֹלֵךְ יְחִידִי בִּזְמַנִּים יְדוּעִים אֲפִלּוּ בָּעִיר בִּמְקוֹמוֹת יְדוּעִים, מוֹשֵׁךְ עָלָיו רוּחַ טֻמְאָה.</p>\n<p>לָכֵן בְּכָל זְמַן לֹא יֵלֵךְ אָדָם יְחִידִי בַּדֶּרֶךְ וּבָעִיר, אֶלָּא בְּמָקוֹם שֶׁבְּנֵי אָדָם הוֹלְכִים וְשָׁבִים וְנִמְצָאִים שָׁם, וְעַל כֵּן לֹא יֵלֵךְ אָדָם יְחִידִי בַּלַּיְלָה, הוֹאִיל וּבְנֵי אָדָם לֹא נִמְצָאִים, וְהַיְנוּ הַטַּעַם שֶׁלֹּא תָלִין נִבְלָתוֹ, שֶׁלֹּא לְהַחֲזִיק גּוּף מֵת בְּלִי רוּחַ עַל הָאָרֶץ בַּלַּיְלָה. מִשּׁוּם כָּךְ אוֹתוֹ בִּלְעָם הָרָשָׁע הָיָה הוֹלֵךְ יְחִידִי כַּנָּחָשׁ הַזֶּה, כְּמוֹ שֶׁבֵּאֲרוּהוּ.</p>"],[9522011345,"<p>וַיֵּאָבֵק אִישׁ עִמּוֹ. מַה זֶּה וַיֵּאָבֵק? (שאמר רבי יהושע בן לוי, מלמד שהעלו אבק ברגליהם עד כסא הכבוד, כתוב כאן בהאבקו עמו, וכתוב (נחום א) אבק רגליו, ואותו מלאך שרו של עשו היה, והוא סמא\"ל, לכן דינו הוא שיעלה אבק רגליו עד כסא הכבוד, שהוא מקום המשפט). רַבִּי שִׁמְעוֹן אָמַר, מִן אָבָק. אָבָק טָפֵל לֶעָפָר. מַה בֵּין עָפָר לְאָבָק? זֶה אָבָק שֶׁנִּשְׁאָר מֵהָאֵשׁ וְלֹא עוֹשֶׂה פֵּרוֹת (בעולם) לְעוֹלָמִים, עָפָר שֶׁכָּל הַפֵּרוֹת יוֹצְאִים מִמֶּנּוּ, וְהוּא כְּלָל שֶׁלְּמַעְלָה וּמַטָּה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, מַה זֶּה מֵקִים מֵעָפָר דָּל? אָמַר לוֹ, כְּמַשְׁמָעוֹ, אֲבָל בְּגָוֶן זֶה מֵקִים מֵעָפָר דַּל מִשּׁוּם שֶׁאֵין לוֹ מֵעַצְמוֹ כְּלוּם, וּמֵאוֹתוֹ עָפָר יָצָא דַל שֶׁאֵין בּוֹ כְּלוּם, וּמֵאוֹתוֹ עָפָר כָּל הַפֵּרוֹת וְכָל טוּב הָעוֹלָם יוֹצְאִים מִמֶּנּוּ וּבוֹ נַעֲשִׂים כָּל מַעֲשֵׂי הָעוֹלָם, כְּמוֹ שֶׁכָּתוּב (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. וְשָׁנִינוּ, הַכֹּל הָיָה מִן הֶעָפָר - אֲפִלּוּ גַּלְגַּל חַמָּה, אֲבָל אָבָק לֹא עוֹשֶׂה פֵּרוֹת וְנִצָּנִים (לעולם) לְעוֹלָמִים, וּמִשּׁוּם כָּךְ וַיֵּאָבֵק אִישׁ, שֶׁבָּא בְּאוֹתוֹ אָבָק וְרָכַב עָלָיו כְּדֵי לְקַטְרֵג לְיַעֲקֹב.</p>\n<p>עַד עֲלוֹת הַשָּׁחַר, שֶׁנֶּעֱבַר שִׁלְטוֹנוֹ וְהִתְחַלֵּף. וְכָךְ הוּא לֶעָתִיד לָבֹא, מִשּׁוּם שֶׁהַגָּלוּת עַכְשָׁו דּוֹמָה לְלַיְלָה, וְהִיא לַיְלָה, וְשׁוֹלֵט אוֹתוֹ אָבָק עַל יִשְׂרָאֵל וְהֵם שׁוֹכְבִים לֶעָפָר (אחר), עַד שֶׁיַּעֲלֶה הָאוֹר וְיָאִיר הַיּוֹם, וְאָז יִשְׁלְטוּ יִשְׂרָאֵל, וְלָהֶם תִּנָּתֵן הַמַּלְכוּת, שֶׁהֵם קְדוֹשִׁים עֶלְיוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ז) וּמַלְכוּת וְשִׁלְטוֹן וּגְדֻלָּה שֶׁמּוֹלֶכֶת תַּחַת כָּל הַשָּׁמַיִם תִּנָּתֵן לְעַם קְדוֹשִׁים עֶלְיוֹנִים. מַלְכוּתוֹ מַלְכוּת עוֹלָם, וְכָל הַשַּׁלִּיטִים לוֹ יַעַבְדוּ וְיִשְׁמְעוּ.</p>"],[9522011346,"<p>וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךְ כִּי אִם בֵּרַכְתָּנִי. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר ו) מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר יָפָה כַלְּבָנָה בָּרָה כַּחַמָּה יָפָה כַּנִּדְגָּלוֹת. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר. אֲבָל מִי זֹאת הַנִּשְׁקָפָה - אֵלּוּ הֵם יִשְׂרָאֵל, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָקִים אוֹתָם וְיוֹצִיאֵם מִן הַגָּלוּת, אָז יִפְתַּח לָהֶם פֶּתַח שֶׁל אוֹר (שהוא) דַּקִּיק קָטָן, וְאַחַר כָּךְ פֶּתַח אַחֵר שֶׁהוּא גָדוֹל מִמֶּנּוּ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִפְתַּח לָהֶם שְׁעָרִים עֶלְיוֹנִים פְּתוּחִים לְאַרְבַּע רוּחוֹת הָעוֹלָם.</p>\n<p>וְכֵן כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל וְלַצַּדִּיקִים שֶׁבָּהֶם, כָּךְ כֻּלָּם וְלֹא בִּזְמַן אֶחָד. לְאָדָם שֶׁנִּתָּן בַּחֹשֶׁךְ וְדִיּוּרוֹ הָיָה תָּמִיד בַּחֹשֶׁךְ, כְּשֶׁיִּרְצוּ לְהָאִיר לוֹ, צְרִיכִים לִפְתֹּחַ לוֹ אוֹר קָטָן כְּעֵין הַמַּחַט, וְאַחַר כָּךְ גָּדוֹל מִמֶּנּוּ, וְכָךְ בְּכָל פַּעַם עַד שֶׁיָּאִירוּ לוֹ כָּל הָאוֹר כָּרָאוּי.</p>\n<p>כָּךָ הֵם יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (שמות כג) מְעַט מְעַט אֲגָרֲשֶׁנּוּ מִפָּנֶיךְ עַד אֲשֶׁר תִּפְרֶה וְגוֹ'. וְכֵן לְמִי שֶׁהוּא בָּא לְהֵרָפֵא, אֵינוֹ בְּשָׁעָה אַחַת, אֶלָּא מְעַט מְעַט עַד שֶׁיִּתְחַזֵּק. אֲבָל לְעֵשָׂו לֹא כָּךְ, אֶלָּא בְּפַעַם אַחַת מֵאִיר לוֹ, וְנֶאֱבָד מִמֶּנּוּ מְעַט מְעַט (ולעתיד לבא לאמות עובדי עבודה זרה (ישעיה מב) ה' כגבור יצא) עַד שֶׁיִּתְחַזְּקוּ יִשְׂרָאֵל וְיַשְׁמִידוּ (וישבו) אוֹתוֹ מֵהַכֹּל, מֵהָעוֹלָם הַזֶּה וּמֵהָעוֹלָם הַבָּא. וּמִשּׁוּם שֶׁמֵּאִיר בְּשָׁעָה אַחַת, יִהְיֶה לוֹ הַשְׁמָדָה מֵהַכֹּל. אֲבָל יִשְׂרָאֵל, אוֹר שֶׁלָּהֶם מְעַט מְעַט, עַד שֶׁיִּתְחַזְּקוּ, וְיָאִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים.</p>\n<p>וְכֻלָּם שׁוֹאֲלִים אוֹתָם וְאוֹמְרִים, מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר, זוֹהִי קַדְרוּת הַבּקֶר, וְזֶהוּ אוֹר דַּקִּיק. וְאַחַר יָפָה כַלְּבָנָה, מִשּׁוּם שֶׁהַלְּבָנָה, הָאוֹר שֶׁלָּהּ מֵאִיר יוֹתֵר מִשַּׁחַר. וְאַחַר בָּרָה כַּחַמָּה, מִשּׁוּם שֶׁאוֹרָהּ חָזָק וּמֵאִיר יוֹתֵר מֵהַלְּבָנָה. וְאַחַר כָּךְ אֲיֻמָּה כַּנִּדְגָּלוֹת, חֲזָקָה בְּאוֹר חָזָק כָּרָאוּי.</p>\n<p>בֹּא רְאֵה, בְּעוֹד שֶׁנֶּחְשָׁךְ הַיּוֹם וּמִתְכַּסֶּה הָאוֹר וּבָא הַבֹּקֶר, יוּאַר בַּתְּחִלָּה מְעַט מְעַט עַד שֶׁיִּתְרַבֶּה הָאוֹר כָּרָאוּי. שֶׁהֲרֵי כֵּיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְעוֹרֵר לְהָאִיר לָהּ לִכְנֶסֶת יִשְׂרָאֵל, יָאִיר בַּתְּחִלָּה כְּמוֹ שָׁחַר, שֶׁהוּא שָׁחֹר, וְאַחַר כָּךְ יָפָה כַלְּבָנָה, וְאַחַר כָּךְ בָּרָה כַּחַמָּה, וְאַחַר כָּךְ אֲיֻמָּה כַּנִּדְגָּלוֹת, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וּבֹא רְאֵה, כֵּיוָן שֶׁעוֹלֶה הַבֹּקֶר, שֶׁהֲרֵי לֹא כָתוּב כִּי בָא הַשַּׁחַר, אֶלָּא כִּי עָלָה, שֶׁהֲרֵי בִּזְמַן כִּי בָא הַשַּׁחַר, אָז הִתְחַזֵּק אוֹתוֹ מְמֻנֶּה וְהִכִּישׁ אֶת יַעֲקֹב, מִשּׁוּם שֶׁאוֹתוֹ מְמֻנֶּה הִכִּישׁ אֶת יַעֲקֹב לָתֵת כֹּחַ לְהִתְחַזֵּק לְעֵשָׂו.</p>\n<p>וּכְשֶׁעָלָה אוֹתוֹ שָׁחֹר שֶׁל שַׁחַר וְנִרְאָה, בָּא הָאוֹר וְהִתְחַזֵּק יַעֲקֹב, שֶׁהֲרֵי אָז הִגִּיעַ זְמַנּוֹ לִהְיוֹת מוּאָר, מַה כָּתוּב? וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ כַּאֲשֶׁר עָבַר אֶת פְּנוּאֵל וְהוּא צֹלֵעַ עַל יְרֵכוֹ. וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ, שֶׁהֲרֵי אָז הַזְּמַן לִהְיוֹת מוּאָר.</p>\n<p>וְהוּא צֹלֵעַ עַל יְרֵכוֹ. אָז הוּא רֶמֶז, שֶׁהֲרֵי בְּעוֹד שֶׁיִּשְׂרָאֵל בַּגָּלוּת וְסוֹבְלִים כְּאֵבִים וְצַעַר וְכַמָּה רָעוֹת, כְּשֶׁמֵּאִיר לָהֶם הַיּוֹם וְיָבִיא לָהֶם מְנוּחָה, אָז יִסְתַּכְּלוּ וְיִכְאֲבוּ בְּעַצְמוֹתֵיהֶם מִכַּמָּה רָעוֹת וְצַעַר שֶׁסָּבְלוּ וְיִתְמְהוּ עֲלֵיהֶם, מִשּׁוּם כָּךְ וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ. שֶׁאוֹתוֹ זְמַן הַמְּנוּחָה, וְאָז הוּא צֹלֵעַ עַל יְרֵכוֹ, כּוֹאֵב וּמְצַעֵר עַצְמוֹ עַל מַה שֶּׁעָבַר.</p>\n<p>וְהוּא, כְּשֶׁעוֹלֶה קַדְרוּת הַשַּׁחַר, אָז מִתְחַזֵּק וְנֶאֱחָז בּוֹ, שֶׁהֲרֵי נֶחֱלָשׁ כֹּחוֹ, שֶׁאֵין לוֹ שִׁלְטוֹן אֶלָּא בַּלַּיְלָה, וְיַעֲקֹב שִׁלְטוֹנוֹ בַּיּוֹם. וְעַל זֶה אָמַר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר, שֶׁהֲרֵי אֲנִי בִּרְשׁוּתְךְ עוֹמֵד, וַהֲרֵי נִתְבָּאֵר וּפֵרְשׁוּהוּ.</p>"],[9522011347,"<p>(על כן לא יאכלו בני ישראל את גיד הנשה וגו', כי נגע בכף ירך י קב בגיד הנשה, שאפלו בהנאה אסור, ואפלו לתת אותו לכלב, ולמה נקרא גיד הנשה? כלומר, גיד שהוא משכיח את בני האדם מעבודת רבונם, ושם רובץ היצר הרע</p>\n<p>וכיון שנדבק עם יעקב, לא מצא מקום שיכול להתגבר על יעקב, משום שכל איברי הגוף סיעו ליעקב, וכלם היו חזקים ולא היתה בהם חלשה, מה עשה? ויגע בכף ירכו בגיד הנשה, במינו של יצר הרע שהוא מינו למקומו, ומשם בא יצר הרע על בני האדם,</p>\n<p>ולכן אמרה תורה לא יאכלו בני ישראל את גיד הנשה, כמו שאמרו החברים באיברי האדם שרמוז למעלה, אם טוב טוב, ואם רע רע, ולכן כל איבר מחזק איבר, ודאי גיד הנשה מחזק את יצר הרע שהוא מינו, ובני ישראל לא יאכלו אותו, שאינם מצדו וממינו, אבל עמים עובדי עבודה זרה יאכלו אותו, שהוא מצד וממין המלאך שלהם, שהוא סמא\"ל, כדי לחזק לבם,</p>\n<p>משום שיש באדם מאתים ארבעים ושמונה איברים כנגד מאתים ארבעים ושמונה מצוות התורה שהם נתנו להעשות, וכנגד מאתים ארבעים ושמונה מלאכים שהתלבשה בהם שכינה והשם שלהם כשם רבונם,</p>\n<p>ויש באדם שלש מאות ששים וחמשה גידים, וכנגדם שלש מאות ששים וחמש מצוות שלא נתנו להעשות וכנגד שלש מאות ששים וחמשה ימות השנה, והרי תשעה באב אחד מהם, שהוא כנגד סמא\"ל, שהוא אחד מאותם שלש מאות ששים וחמשה מלאכים (ימים), ולכן אמרה תורה לא יאכלו בני ישראל את גיד הנשה, א\"ת לרבות תשעה באב שלא אוכלים בו ולא שותים,</p>\n<p>ולכן ראה הקדוש ברוך הוא הכל, ונרמז בהם רמז ליעקב, ויאבק איש עמו, בכל ימות השנה ובכל איברי י קב, ולא נמצא פרט לאותו גיד הנשה, מיד תשש כח יעקב, ובימות השנה מצא יום תשעה באב שבו התחזק ונגזר דין עלינו ונחרב בית המקדש, וכל מי שאוכל בתשעה באב כאלו אכל את גיד הנשה). רבי חייא אמר, אלמלא לא נחלש כח (של מקום) זה של יעקב, היה מתקים יעקב אליו, ונשבר כח של עשו למעלה ולמטה.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (יחזקאל לא) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב הוּא מַרְאֵה דְּמוּת כְּבוֹד ה' וָאֶרְאֶה וָאֶפֹּל עַל פָּנַי וְגוֹ'. פָּסוּק זֶה נִתְבָּאֵר. אֲבָל בּא רְאֵה, שֶׁהֲרֵי כָּתוּב (דברים לד) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. מַה בֵּין מֹשֶׁה לִשְׁאָר נְבִיאֵי הָעוֹלָם? מֹשֶׁה הִסְתַּכֵּל בְּאַסְפַּקְלַרְיָה הַמְּאִירָה - שְׁאָר הַנְּבִיאִים לֹא הָיוּ מִסְתַּכְּלִים אֶלָּא בְּאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה. מֹשֶׁה הָיָה שׁוֹמֵעַ וְעוֹמֵד עַל רַגְלָיו וְכֹחוֹ מִתְחַזֵּק וְהָיָה יוֹדֵעַ דָּבָר עַל בֻּרְיוֹ, כְּמוֹ שֶׁכָּתוּב (במדבר יב) וּמַרְאֶה וְלֹא בְחִידוֹת - שְׁאָר הַנְּבִיאִים הָיוּ נוֹפְלִים עַל פְּנֵיהֶם וְנֶחֱלַשׁ כֹּחָם וְלֹא הָיוּ יְכוֹלִים לַעֲמֹד עַל בֻּרְיוֹ שֶׁל דָּבָר. מִי גָרַם לָהֶם אֶת זֶה? מִשּׁוּם שֶׁכָּתוּב כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב וְהוּא צֹלֵעַ עַל יְרֵכוֹ.</p>\n<p>וְכָל אוֹתָם נְבִיאִים לֹא יָכְלוּ לַעֲמֹד עַל מַה שֶּׁעָתִיד לַעֲשׂוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא לְעֵשָׂו, פְּרָט לְעוֹבַדְיָה הַנָּבִיא שֶׁהָיָה גֵר, שֶׁבָּא מִצַּד שֶׁל עֵשָׂו - זֶה עָמַד בְּקִיּוּמוֹ עַל עֵשָׂו וְלֹא נֶחֱלַשׁ כֹּחוֹ. וְעַל זֶה כָּל שְׁאָר הַנְּבִיאִים נֶחֱלַשׁ כֹּחָם וְלֹא הָיוּ יְכוֹלִים לַעֲמֹד לְקַבֵּל דָּבָר עַל בֻּרְיוֹ כָּרָאוּי. מָה הַטַּעַם? מִשּׁוּם כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב בְּגִיד הַנָּשֶׁה. שֶׁלָּקַח וְשָׁאַב כָּל כֹּחַ הַיָּרֵךְ, וְעַל זֶה נִשְׁבַּר כֹּחַ הַיָּרֵךְ וְנִשְׁאַר צוֹלֵעַ עַל יְרֵכוֹ, שֶׁהֲרֵי כָּל נְבִיאֵי הָעוֹלָם לֹא יָכְלוּ לְהִדָּבֵק וְלַעֲמֹד בּוֹ.</p>\n<p>בֹּא רְאֵה, כָּל הַנְּבִיאִים פְּרָט לְמֹשֶׁה לֹא עָמְדוּ בְּכֹחָם כָּרָאוּי, וּמִי שֶׁעוֹסֵק בַּתּוֹרָה וְאֵין מִי שֶׁתּוֹמֵךְ בּוֹ, לֹא נִמְצָא מִי שֶׁמַּטִּיל מְלַאי לְכִיסוֹ לְהִתְחַזֵּק. עַל זֶה הַתּוֹרָה מִשְׁתַּכַּחַת בְּכָל דּוֹר וָדוֹר וְנֶחֱלָשׁ כֹּחַ הַתּוֹרָה כָּל יוֹם וָיוֹם, מִשּׁוּם שֶׁאֵין לָהֶם לְאֵלּוּ שֶׁעוֹסְקִים בַּתּוֹרָה עַל מַה שֶּׁסּוֹמְכִים, וּמַלְכוּת הָרִשְׁעָה מִתְחַזֶּקֶת בְּכָל יוֹם וָיוֹם.</p>\n<p>בֹּא רְאֵה כַּמָּה גָרַם חֵטְא זֶה, וּמִשּׁוּם שֶׁאֵין (לו) מִי שֶׁיִּתְמֹךְ בַּתּוֹרָה כָּרָאוּי, אוֹתָם עַמּוּדִים חַלָּשִׁים, וְגוֹרְמִים לְהִתְחַזֵּק אֶת אוֹתוֹ שֶׁאֵין לוֹ שׁוֹקַיִם וְרַגְלַיִם לַעֲמֹד עֲלֵיהֶם.</p>\n<p>פָּתַח וְאָמַר, (בראשית ב) וַיֹּאמֶר ה' אֱלֹהִים אֶל הַנָּחָשׁ כִּי עָשִׂיתָ זֹאת אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגוֹ' עַל גְּחֹנְךְ תֵלֵךְ. מַה זֶּה עַל גְּחֹנְךְ תֵלֵךְ? שֶׁנִּשְׁבְּרוּ הַתּוֹמְכִים שֶׁלּוֹ וְקִצְּצוּ אֶת רַגְלָיו וְאֵין לוֹ עַל מַה שֶּׁיַּעֲמֹד. כְּשֶׁיִּשְׂרָאֵל לֹא רוֹצִים לִתְמֹךְ בַּתּוֹרָה, הֵם נוֹתְנִים לוֹ תּוֹמְכִים וְשׁוֹקַיִם לַעֲמֹד וּלְהִתְחַזֵּק בָּהֶם.</p>\n<p>בֹּא רְאֵה כַּמָּה עֲקִימוּת וְהִתְחַכְּמוּת הִתְחַכֵּם בְּאוֹתוֹ לַיְלָה אוֹתוֹ הָרוֹכֵב עַל הַנָּחָשׁ כְּנֶגֶד יַעֲקֹב, שֶׁהֲרֵי הוּא הָיָה יוֹדֵעַ שֶׁכָּתוּב (שם כז) הַקֹּל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו, וְאִם פּוֹסֵק קוֹל יַעֲב, אָז וְהַיָּדַיִם יְדֵי עֵשָׂו. לָכֵן הִסְתַּכֵּל לְכָל הַצְּדָדִים לְהָרַע לְיַעֲקֹב וּלְהַפְסִיק קוֹלוֹ.</p>\n<p>וְרָאָה אוֹתוֹ חָזָק בַּכֹּל; זְרוֹעוֹת מִצַּד זֶה וּמִצַּד זֶה שֶׁהֵם חָזְקֵי הַגּוּף שֶׁמִּתְחַזֵּק בֵּינֵיהֶם, וְרָאָה כֹּחַ הַתּוֹרָה שֶׁהִתְחַזֵּק בַּכֹּל, אָז וַיַּרְא כִּי לֹא יָכֹל לוֹ. מֶה עָשָׂה? מִיָּד - וַיִּגַּע בְּכַף יְרֵכוֹ, שֶׁהִתְחַכֵּם כְּנֶגְדּוֹ. אָמַר, כֵּיוָן שֶׁנִּשְׁבְּרוּ עַמּוּדֵי וְתוֹמְכֵי הַתּוֹרָה, מִיָּד הַתּוֹרָה לֹא מִתְחַזֶּקֶת, אָז יִתְקַיֵּם מַה שֶּׁאָמַר אֲבִיהֶם הַקֹּל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו, (שם) וְהָיָה כַּאֲשֶׁר תָּרִיד וּפָרַקְתָּ עֻלּוֹ מֵעַל צַוָּארֶךְ.</p>\n<p>וּבָזֶה הִתְחַכֵּם כְּנֶגֶד יַעֲקֹב. שֶׁהֲרֵי מִשּׁוּם שֶׁנִּשְׁבַּר כֹּחַ הַתּוֹרָה, הָלַךְ וְהִתְחַזֵּק עֵשָׂו. וּכְשֶׁרָאָה שֶׁלֹּא יָכֹל לַתּוֹרָה, אָז הֶחֱלִישׁ כֹּחַ אוֹתָם הַתּוֹמְכִים אוֹתָהּ. וּכְשֶׁלֹּא נִמְצָא מִי שֶׁסּוֹמֵךְ אֶת הַתּוֹרָה, אָז לֹא יִהְיֶה קוֹל קוֹל יַעֲקֹב, וְיִהְיוּ הַיָּדַיִם יְדֵי עֵשָׂו.</p>\n<p>וּכְשֶׁרָאָה יַעֲקֹב כָּךְ כְּשֶׁעָלָה הַבֹּקֶר, הֶחֱזִיק (יעקב) בּוֹ וְהִתְגַּבֵּר עָלָיו, עַד שֶׁהוּא בֵּרַךְ אוֹתוֹ וְהוֹדָה לוֹ עַל אוֹתָן בְּרָכוֹת, וְאָמַר לוֹ, לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךְ כִּי אִם יִשְׂרָאֵל. לֹא יַעֲקֹב בַּעֲקִימוּת, אֶלָּא בְּגַאֲוָה וְכֹחַ, שֶׁאֵין מִי שֶׁיּוּכַל לְךְ.</p>\n<p>וּבֹא וּרְאֵה, מֵהַנָּחָשׁ הַזֶּה כַּמָּה כֹחוֹת נִפְרָדִים לְכָל צַד וְנִמְצָאִים בָּעוֹלָם אֵצֶל בְּנֵי אָדָם, וְרוֹצִים לְקַיֵּם אוֹתוֹ גִּיד הַנָּשֶׁה. שֶׁאַף עַל גַּב שֶׁקָּרַב אֵלָיו אוֹתוֹ רוֹכֵב עַל נָחָשׁ, עוֹמֵד הוּא וְהִתְקַיֵּם בְּצוּרָה וְלֹא נִשְׁבָּר.</p>\n<p>וְכֹחַ צְרִיכִים לְהִתְחַזֵּק בָּעוֹלָם וּלְהֵרָאוֹת, כִּי שָׂרִיתָ עִם אֱלֹהִים וְעִם אֲנָשִׁים וַתּוּכָל. וּכְשֶׁרָאָה שֶׁהֲרֵי לֹא נִשְׁבַּר וְלֹא נֶאֱכַל אוֹתוֹ מָקוֹם, אָז נִשְׁבַּר כֹּחוֹ וְחָזְקוֹ וְלֹא יָכֹל לְהָרַע לִבְנֵי יַעֲקֹב, וְעַל זֶה לֹא צְרִיכִים לָתֵת מָקוֹם לִבְרִיּוֹת הָעוֹלָם לֶאֱכֹל אוֹתוֹ וְלֹא לֵהָנוֹת מִמֶּנּוּ כְּלָל.</p>\n<p>רַבִּי יֵיסָא הַזָּקֵן דָּרַשׁ, כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב - כָּתוּב כָּאן כִּי נָגַע בְּכַף, וְכָתוּב שָׁם (במדבר יט) כָּל הַנֹּגֵעַ בְּמֵת בְּנֶפֶשׁ הָאָדָם (יטמא). מַה לְּהַלָּן טֻמְאָה - אַף כָּאן גַּם טֻמְאָה, שֶׁטִּמֵּא אוֹתוֹ מָקוֹם, וּמִמָּקוֹם טָמֵא אֵין לָנוּ (להתתקן) לֵהָנוֹת מִמֶּנּוּ כְּלָל. כָּל שֶׁכֵּן בְּמָקוֹם שֶׁקָּרַב אוֹתוֹ צַד הַטֻּמְאָה, וְהַתּוֹרָה לֹא אָמְרָה אֶלָּא כִּי נָגַע, וְכָתוּב וַיִּגַּע בְּכַף יְרֵכוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שם) וְכֹל אֲשֶׁר יִגַּע בּוֹ הַטָּמֵא יִטְמָא. בָּרוּךְ הָרַחֲמָן שֶׁנָּתַן תּוֹרָה לְיִשְׂרָאֵל לִזְכּוֹת בָּהּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (משלי ג) אֹרֶךְ חַיִּים בִּימִינָהּ בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד.</p>"]]});
